-- 0038_apply_form_simplify.sql
-- Seller application form, simpler and wider:
--   * Maisha Card is accepted as an ID type next to National ID and Passport.
--   * "Year established" is optional, so a seller is not blocked on a detail that is never used to decide.
-- Existing rows are untouched; both changes only widen what the table accepts.
-- Safe to run more than once, and safe whatever the old check constraint was called.

do $$
declare
  c record;
begin
  for c in
    select conname
      from pg_constraint
     where conrelid = 'public.applications'::regclass
       and contype = 'c'
       and pg_get_constraintdef(oid) ilike '%owner_id_type%'
  loop
    execute format('alter table public.applications drop constraint %I', c.conname);
  end loop;
end $$;

alter table public.applications
  add constraint applications_owner_id_type_check
  check (owner_id_type in ('national_id', 'maisha_card', 'passport'));

alter table public.applications
  alter column year_established drop not null;

$m_0038_apply_form_simplify$),
    ('0039_live_top_searches', $m_0039_live_top_searches$
create table if not exists public.search_salt (
  id boolean primary key default true check (id),
  salt text not null default gen_random_uuid()::text
);
insert into public.search_salt (id) values (true) on conflict do nothing;

create table if not exists public.search_blocklist (
  term text primary key check (term = lower(btrim(term)) and char_length(term) >= 2)
);

create table if not exists public.search_events (
  id bigint generated always as identity primary key,
  term text not null check (char_length(term) between 2 and 60),
  client_hash text not null,
  bucket bigint not null,
  at timestamptz not null default now(),
  unique (term, client_hash, bucket)
);

create index if not exists search_events_at_idx on public.search_events (at desc);
create index if not exists search_events_client_at_idx on public.search_events (client_hash, at desc);

alter table public.search_salt enable row level security;
alter table public.search_blocklist enable row level security;
alter table public.search_events enable row level security;
revoke all on public.search_salt, public.search_blocklist, public.search_events from public, anon, authenticated;
grant all on public.search_salt, public.search_blocklist, public.search_events to service_role;

create or replace function public.log_search(p_term text) returns void
language plpgsql volatile security definer set search_path = public, extensions set statement_timeout = '2s' as
$$
declare
  v_term text := lower(regexp_replace(btrim(coalesce(p_term, '')), '\s+', ' ', 'g'));
  v_headers jsonb;
  v_ip text;
  v_client text;
begin
  if char_length(v_term) < 2 or char_length(v_term) > 60
    or cardinality(string_to_array(v_term, ' ')) > 6
    or v_term !~ '^[[:alnum:] ''&-]+$'
    or v_term !~ '[[:alpha:]]' then
    return;
  end if;

  v_headers := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb;
  v_ip := coalesce(nullif(btrim(v_headers ->> 'cf-connecting-ip'), ''), nullif(btrim(v_headers ->> 'x-real-ip'), ''));
  if v_ip is null then
    return;
  end if;

  v_client := encode(digest((select salt from public.search_salt limit 1) || ':' || current_date::text || ':' || v_ip, 'sha256'), 'hex');

  if (select count(*) from public.search_events where client_hash = v_client and at > now() - interval '1 minute') >= 12 then
    return;
  end if;
  if (select count(*) from public.search_events where at > now() - interval '1 minute') >= 300 then
    return;
  end if;

  insert into public.search_events (term, client_hash, bucket)
  values (v_term, v_client, floor(extract(epoch from now()) / 3600)::bigint)
  on conflict do nothing;

  if random() < 0.01 then
    delete from public.search_events
    where id in (select id from public.search_events where at < now() - interval '2 days' order by at limit 5000);
  end if;
exception when others then
  return;
end $$;
revoke all on function public.log_search(text) from public;
grant execute on function public.log_search(text) to anon, authenticated, service_role;

create or replace function public.top_searches(p_limit integer default 10)
returns table (term text, count integer, hot boolean)
language sql stable security definer set search_path = public set statement_timeout = '3s' as
$$
  select
    e.term,
    count(distinct e.client_hash)::integer as count,
    (count(distinct e.client_hash) filter (where e.at > now() - interval '3 hours') >= 3
      and count(distinct e.client_hash) filter (where e.at > now() - interval '3 hours') * 4 >= count(distinct e.client_hash)) as hot
  from public.search_events e
  where e.at > now() - interval '24 hours'
    and not exists (select 1 from public.search_blocklist b where position(b.term in e.term) > 0)
  group by e.term
  having count(distinct e.client_hash) >= 3
  order by 2 desc, e.term
  limit greatest(1, least(coalesce(p_limit, 10), 20))
$$;
revoke all on function public.top_searches(integer) from public;
grant execute on function public.top_searches(integer) to anon, authenticated, service_role;

$m_0039_live_top_searches$),
    ('0040_public_offers', $m_0040_public_offers$
-- 0040_public_offers.sql
-- Business cards show an "Offer" chip when a shop has an offer running. Customers (anon) cannot read public.offers
-- directly (row level security), so this view exposes only the offers that are public right now: the business is live,
-- the offer is active, inside its start/end window, and not hidden or removed by an admin. Same rules as public_items.
-- Only fields a customer may see leave the database; admin columns stay behind.

create or replace view public.public_offers with (security_barrier = true) as
select
  o.id, o.business_id, o.title, o.description, o.starts_at, o.ends_at, o.created_at
from public.offers o
join public.businesses b on b.id = o.business_id
where public.business_is_visible(b)
  and o.active
  and not o.hidden_by_admin
  and not o.removed_by_admin
  and (o.starts_at is null or o.starts_at <= now())
  and (o.ends_at is null or o.ends_at > now());
revoke all on public.public_offers from public;
grant select on public.public_offers to anon, authenticated, service_role;

$m_0040_public_offers$),
    ('0041_product_ids', $m_0041_product_ids$
-- One id per product, made by the database and never changed.
--
-- Every row in public.items already gets a uuid primary key, so two products can never share an id. Two gaps remained:
--   * a seller can insert into items directly through row security (the "seller inserts own items" policy), and that
--     insert could name its own id. An id the caller chose is not an id the system made, and a chosen id can be
--     guessed or reused, so an insert from a seller or a visitor now always gets a fresh id from the database.
--   * nothing stopped an update from rewriting an id, which would break every link, flash sale, offer and history
--     row that traces the product by it. An id can no longer change.
--
-- Code that runs as the database owner (the seller_save_item, seller_duplicate_item and seller_import_items
-- functions, migrations, seed data) already takes the default, so nothing there changes.

create or replace function public.items_assign_id() returns trigger
language plpgsql as $$
begin
  if current_user in ('anon', 'authenticated') then
    new.id := gen_random_uuid();
  end if;
  return new;
end $$;

drop trigger if exists t_items_assign_id on public.items;
create trigger t_items_assign_id before insert on public.items for each row execute function public.items_assign_id();

create or replace function public.items_id_immutable() returns trigger
language plpgsql as $$
begin
  if new.id is distinct from old.id then
    raise exception 'item_id_immutable' using errcode = 'P0001';
  end if;
  return new;
end $$;

drop trigger if exists t_items_id_immutable on public.items;
create trigger t_items_id_immutable before update of id on public.items for each row execute function public.items_id_immutable();

$m_0041_product_ids$),
    ('004200_browse_snapshot', $m_004200_browse_snapshot$
-- 004200_browse_snapshot.sql
-- The browse endpoint (client/api/browse.js) needs the whole public catalog once, not once per visitor.
-- Before this, building that snapshot meant paging through public_businesses (select *), public_items, public_flash_sales
-- and public_offers, up to 20 requests of 1,000 rows each. This function returns the same information in ONE round trip
-- and only the columns browsing uses: the heavy ones (socials, amenities, payment methods, delivery area, address) stay out,
-- and the per-item rows collapse into one lowest price per business.
--
-- It reads only the public views, as the caller (anon), so it can show nothing a visitor could not already read.
-- Nothing is written. The endpoint falls back to paging the views if this function is missing or too slow.

create or replace function public.browse_snapshot() returns jsonb
language sql stable set search_path = public as $$
  select jsonb_build_object(
    'businesses', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.id)
      from (
        select id, slug, name, category_id, plan_key, verification_level, tagline, description,
               phone, whatsapp, county, town, lat, lng, logo_path, cover_path, tags, hours, created_at, exceptions
        from public.public_businesses
      ) x), '[]'::jsonb),
    'prices', coalesce((
      select jsonb_object_agg(q.business_id, q.lowest)
      from (
        select business_id, min(price) as lowest
        from public.public_items
        where price is not null and price_type in ('fixed', 'from', 'range')
        group by business_id
      ) q), '{}'::jsonb),
    'flash', coalesce((
      select jsonb_object_agg(q.business_id, q.ends)
      from (select business_id, jsonb_agg(ends_at) as ends from public.public_flash_sales group by business_id) q), '{}'::jsonb),
    -- An offer with no end date runs until the seller turns it off: its end is null here.
    'offers', coalesce((
      select jsonb_object_agg(q.business_id, q.ends)
      from (select business_id, jsonb_agg(ends_at) as ends from public.public_offers group by business_id) q), '{}'::jsonb),
    'categories', coalesce((
      select jsonb_agg(to_jsonb(c) order by c.sort)
      from (select id, name, icon, sort, active from public.categories where active) c), '[]'::jsonb)
  );
$$;

revoke all on function public.browse_snapshot() from public;
grant execute on function public.browse_snapshot() to anon, authenticated, service_role;

$m_004200_browse_snapshot$),
    ('004201_search_postgis', $m_004201_search_postgis$
create extension if not exists postgis with schema extensions;
create extension if not exists unaccent with schema extensions;

alter table public.businesses
  add column if not exists geo extensions.geography(Point, 4326)
  generated always as (
    case when lat between -90 and 90 and lng between -180 and 180
      then extensions.st_setsrid(extensions.st_makepoint(lng, lat), 4326)::extensions.geography
    end
  ) stored;
create index if not exists businesses_geo_idx on public.businesses using gist (geo);

create or replace function public.search_norm(p_text text) returns text
language sql stable set search_path = public, extensions as $$
  select btrim(regexp_replace(regexp_replace(lower(extensions.unaccent(coalesce(p_text, ''))), '[^a-z0-9_[:space:]]', ' ', 'g'), '[[:space:]]+', ' ', 'g'))
$$;

create or replace function public.search_tokens(p_query text) returns text[]
language sql stable set search_path = public, extensions as $$
  select coalesce((string_to_array(public.search_norm(left(coalesce(p_query, ''), 200)), ' '))[1:8], '{}'::text[])
$$;

create or replace function public.hours_interval_ok(p jsonb) returns boolean
language sql immutable as $$
  select case
    when jsonb_typeof(p) = 'array' and jsonb_array_length(p) = 2 and jsonb_typeof(p -> 0) = 'string' and jsonb_typeof(p -> 1) = 'string'
      then (p ->> 0) ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' and (p ->> 1) ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    else false
  end
$$;

create or replace function public.hours_exception_on(p_exceptions jsonb, p_date date) returns jsonb
language sql immutable as $$
  select e
  from jsonb_array_elements(case when jsonb_typeof(p_exceptions) = 'array' then p_exceptions else '[]'::jsonb end) with ordinality t(e, i)
  where jsonb_typeof(e) = 'object' and e ->> 'date' = p_date::text and e ->> 'kind' in ('closed', 'special')
  order by i
  limit 1
$$;

create or replace function public.hours_intervals_on(p_hours jsonb, p_exceptions jsonb, p_date date) returns jsonb
language plpgsql immutable as $$
declare
  v_ex jsonb := public.hours_exception_on(p_exceptions, p_date);
  v_slot jsonb;
begin
  if v_ex is not null then
    if v_ex ->> 'kind' = 'special' and jsonb_typeof(v_ex -> 'intervals') = 'array' then
      return coalesce((select jsonb_agg(iv) from jsonb_array_elements(v_ex -> 'intervals') iv where public.hours_interval_ok(iv)), '[]'::jsonb);
    end if;
    return '[]'::jsonb;
  end if;
  v_slot := case when jsonb_typeof(p_hours) = 'object' then p_hours -> (array['sun','mon','tue','wed','thu','fri','sat'])[extract(dow from p_date)::int + 1] end;
  if v_slot is not null and public.hours_interval_ok(v_slot) then
    return jsonb_build_array(v_slot);
  end if;
  return '[]'::jsonb;
end $$;

create or replace function public.hours_open(p_hours jsonb, p_exceptions jsonb, p_at timestamptz default now()) returns boolean
language plpgsql immutable as $$
declare
  v_local timestamp := p_at at time zone 'Africa/Nairobi';
  v_date date := v_local::date;
  v_min integer := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_iv jsonb;
  v_start integer;
  v_end integer;
begin
  for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date)) loop
    v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
    v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
    if v_end > v_start then
      if v_min >= v_start and v_min < v_end then return true; end if;
    elsif v_min >= v_start then
      return true;
    end if;
  end loop;
  if coalesce(public.hours_exception_on(p_exceptions, v_date) ->> 'kind', '') <> 'closed' then
    for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date - 1)) loop
      v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
      v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
      if v_end <= v_start and v_end > 0 and v_min < v_end then return true; end if;
    end loop;
  end if;
  return false;
end $$;

create or replace function public.search_businesses(
  p_query text default '',
  p_category text default null,
  p_county text default null,
  p_town text default null,
  p_open_now boolean default false,
  p_verified boolean default false,
  p_featured boolean default false,
  p_lat double precision default null,
  p_lng double precision default null,
  p_radius_km double precision default null,
  p_min_price numeric default null,
  p_max_price numeric default null,
  p_sort text default 'relevance',
  p_seed text default '',
  p_page integer default 1,
  p_page_size integer default 12
) returns jsonb
language plpgsql stable security definer set search_path = public, extensions set statement_timeout = '3s' as $$
declare
  v_tokens text[] := public.search_tokens(p_query);
  v_size integer := least(100, greatest(1, coalesce(p_page_size, 12)));
  v_page integer := greatest(1, coalesce(p_page, 1));
  v_sort text := case when p_sort in ('relevance', 'distance', 'newest', 'price_asc', 'price_desc') then p_sort when p_sort = 'rating' then 'newest' else 'relevance' end;
  v_origin extensions.geography := case when p_lat between -90 and 90 and p_lng between -180 and 180
    then extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326)::extensions.geography end;
  v_now timestamptz := now();
  v_seed text := left(coalesce(p_seed, ''), 40);
  v_out jsonb;
begin
  with base as (
    select
      to_jsonb(pb) as doc,
      pb.id,
      pb.created_at,
      (pb.plan_key = 'premium') as premium,
      case when v_origin is not null and b.geo is not null then extensions.st_distance(b.geo, v_origin) / 1000.0 end as dist,
      pr.from_price,
      pb.hours,
      pb.exceptions,
      n.name_text, n.tag_text, n.cat_text, n.area_text, n.body_text
    from public.public_businesses pb
    join public.businesses b on b.id = pb.id
    left join public.categories c on c.id = pb.category_id
    cross join lateral (
      select
        public.search_norm(pb.name) as name_text,
        public.search_norm(array_to_string(pb.tags, ' ')) as tag_text,
        public.search_norm(c.name) as cat_text,
        public.search_norm(coalesce(pb.town, '') || ' ' || coalesce(pb.county, '')) as area_text,
        public.search_norm(coalesce(pb.tagline, '') || ' ' || coalesce(pb.description, '')) as body_text
    ) n
    left join lateral (
      select min(i.price) as from_price
      from public.public_items i
      where i.business_id = pb.id and i.price_type in ('fixed', 'from', 'range') and i.price is not null
    ) pr on true
    where (p_category is null or pb.category_id = p_category)
      and (p_county is null or pb.county = p_county)
      and (p_town is null or replace(public.search_norm(pb.town), ' ', '-') = p_town)
      and (not coalesce(p_verified, false) or pb.verification_level = 'verified')
      and (not coalesce(p_featured, false) or pb.plan_key = 'premium')
      and (v_origin is null or p_radius_km is null or p_radius_km <= 0
           or (b.geo is not null and extensions.st_dwithin(b.geo, v_origin, p_radius_km * 1000.0)))
      and (not coalesce(p_open_now, false) or public.hours_open(pb.hours, pb.exceptions, v_now))
  ),
  scored as (
    select base.*,
      coalesce((
        select case when bool_or(w is null) then -1 else sum(w) end
        from (
          select greatest(
            case when strpos(base.name_text, t) > 0 then 5 end,
            case when strpos(base.tag_text, t) > 0 then 4 end,
            case when strpos(base.cat_text, t) > 0 then 3 end,
            case when strpos(base.area_text, t) > 0 then 2 end,
            case when strpos(base.body_text, t) > 0 then 1 end
          ) as w
          from unnest(v_tokens) t
        ) x
      ), 0) as score
    from base
  ),
  matched as (
    select * from scored
    where score >= 0
      and (p_min_price is null or (from_price is not null and from_price >= p_min_price))
      and (p_max_price is null or (from_price is not null and from_price <= p_max_price))
  ),
  ranked as (
    select m.*,
      count(*) over () as total,
      row_number() over (
        order by
          (v_sort = 'relevance' and not premium)::int,
          case when v_sort = 'relevance' then score end desc,
          case when v_sort = 'relevance' and premium then md5(v_seed || ':' || id::text) end,
          case when v_sort = 'distance' or (v_sort = 'relevance' and not premium) then dist end nulls last,
          case when v_sort = 'price_asc' then from_price end nulls last,
          case when v_sort = 'price_desc' then from_price end desc nulls last,
          created_at desc,
          id
      ) as rn
    from matched m
  )
  select jsonb_build_object(
    'total', coalesce((select max(total) from ranked), 0),
    'items', coalesce((
      select jsonb_agg(
        doc || jsonb_build_object('distance_km', dist, 'is_open', public.hours_open(hours, exceptions, v_now), 'from_price', from_price)
        order by rn
      )
      from ranked
      where rn > (v_page - 1) * v_size and rn <= v_page * v_size
    ), '[]'::jsonb)
  )
  into v_out;

  return v_out || jsonb_build_object('page', v_page, 'page_size', v_size);
end $$;

create or replace function public.search_facets(p_query text default '', p_category text default null) returns jsonb
language sql stable security definer set search_path = public, extensions set statement_timeout = '3s' as $$
  with tokens as (select public.search_tokens(p_query) as t),
  scored as (
    select pb.id, pb.category_id, pb.town, pb.county, pr.from_price,
      coalesce((
        select case when bool_or(w is null) then -1 else sum(w) end
        from (
          select greatest(
            case when strpos(public.search_norm(pb.name), t) > 0 then 5 end,
            case when strpos(public.search_norm(array_to_string(pb.tags, ' ')), t) > 0 then 4 end,
            case when strpos(public.search_norm(c.name), t) > 0 then 3 end,
            case when strpos(public.search_norm(coalesce(pb.town, '') || ' ' || coalesce(pb.county, '')), t) > 0 then 2 end,
            case when strpos(public.search_norm(coalesce(pb.tagline, '') || ' ' || coalesce(pb.description, '')), t) > 0 then 1 end
          ) as w
          from unnest((select tokens.t from tokens)) t
        ) x
      ), 0) as score
    from public.public_businesses pb
    left join public.categories c on c.id = pb.category_id
    left join lateral (
      select min(i.price) as from_price from public.public_items i
      where i.business_id = pb.id and i.price_type in ('fixed', 'from', 'range') and i.price is not null
    ) pr on true
    where p_category is null or pb.category_id = p_category
  ),
  matched as (select * from scored where score >= 0)
  select jsonb_build_object(
    'towns', coalesce((
      select jsonb_agg(jsonb_build_object('slug', slug, 'name', name, 'county', county, 'count', n) order by lower(name), slug)
      from (
        select replace(public.search_norm(town), ' ', '-') as slug, min(town) as name, min(county) as county, count(*) as n
        from matched where public.search_norm(town) <> '' group by 1
      ) tw
    ), '[]'::jsonb),
    'price', (select case when count(from_price) > 0 then jsonb_build_object('min', min(from_price), 'max', max(from_price)) end from matched),
    'category_ids', coalesce((select jsonb_agg(distinct category_id) from matched), '[]'::jsonb)
  )
$$;

create or replace function public.search_suggestions(p_prefix text, p_limit integer default 6) returns jsonb
language sql stable security definer set search_path = public, extensions set statement_timeout = '2s' as $$
  with q as (select public.search_norm(left(coalesce(p_prefix, ''), 60)) as t),
  cats as (
    select 1 as grp, 'category' as type, c.name as label, c.id as ref
    from public.categories c, q where c.active and char_length(q.t) >= 2 and strpos(public.search_norm(c.name), q.t) > 0
  ),
  biz as (
    select 2, 'business', pb.name, pb.slug
    from public.public_businesses pb, q where char_length(q.t) >= 2 and strpos(public.search_norm(pb.name), q.t) > 0
  ),
  terms as (
    select distinct on (lower(tag)) 3, 'term', tag, null::text
    from public.public_businesses pb, q, unnest(pb.tags) tag
    where char_length(q.t) >= 2 and strpos(public.search_norm(tag), q.t) > 0
    order by lower(tag), tag
  ),
  allrows as (
    select * from cats union all select * from biz union all select * from terms
  ),
  deduped as (
    select distinct on (type, lower(label)) * from allrows order by type, lower(label), ref
  ),
  ordered as (
    select * from deduped order by grp, lower(label), label limit least(20, greatest(1, coalesce(p_limit, 6)))
  )
  select coalesce(jsonb_agg(
    case type
      when 'category' then jsonb_build_object('type', type, 'label', label, 'categoryId', ref)
      when 'business' then jsonb_build_object('type', type, 'label', label, 'slug', ref)
      else jsonb_build_object('type', type, 'label', label)
    end order by grp, lower(label), label
  ), '[]'::jsonb)
  from ordered
$$;

revoke all on function public.search_businesses(text, text, text, text, boolean, boolean, boolean, double precision, double precision, double precision, numeric, numeric, text, text, integer, integer) from public;
revoke all on function public.search_facets(text, text) from public;
revoke all on function public.search_suggestions(text, integer) from public;
grant execute on function public.search_businesses(text, text, text, text, boolean, boolean, boolean, double precision, double precision, double precision, numeric, numeric, text, text, integer, integer) to anon, authenticated, service_role;
grant execute on function public.search_facets(text, text) to anon, authenticated, service_role;
grant execute on function public.search_suggestions(text, integer) to anon, authenticated, service_role;
grant execute on function public.hours_open(jsonb, jsonb, timestamptz) to anon, authenticated, service_role;

$m_004201_search_postgis$),
    ('0043_products_snapshot', $m_0043_products_snapshot$
-- 0043_products_snapshot.sql
-- The home page "all products" grid (client/api/products.js) needs the public product list once per cache window, not
-- once per visitor. Before this, every visitor's browser paged through public_items with select * (up to 20 requests of
-- 1,000 rows, with every image path and video path of every item) plus public_businesses.
--
-- This function returns the same information in ONE round trip and only what the grid and its filters use:
--   * per item: id, store, name, a 160 character description (search only), section, price, price type, unit,
--     availability, created_at, the FIRST image path, and the running flash sale (if any), already priced by the database;
--   * per store: only the columns the card, the filters and the open/closed status need.
-- Items are newest first and capped, so one runaway seller can never make the snapshot unbounded. 'truncated' says so.
--
-- It reads only the public views as the caller (anon): it can show nothing a visitor could not already read.
-- Nothing is written. The endpoint falls back to paging the views if this function is missing or too slow.

create or replace function public.products_snapshot(p_limit int default 10000) returns jsonb
language sql stable set search_path = public as $$
  with capped as (
    select i.id, i.business_id, i.name, left(i.description, 160) as description, i.section, i.price, i.price_type,
           i.unit, i.availability, i.created_at, i.image_paths ->> 0 as image_path
    from public.public_items i
    order by i.created_at desc, i.id
    limit least(greatest(coalesce(p_limit, 10000), 1), 50000) + 1
  ), kept as (
    select * from capped order by created_at desc, id limit least(greatest(coalesce(p_limit, 10000), 1), 50000)
  )
  select jsonb_build_object(
    'truncated', (select count(*) from capped) > least(greatest(coalesce(p_limit, 10000), 1), 50000),
    'items', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc, x.id)
      from (
        select k.id, k.business_id, k.name, k.description, k.section, k.price, k.price_type, k.unit, k.availability,
               k.created_at, k.image_path,
               f.id as sale_id, f.sale_price, f.starts_at as sale_starts_at, f.ends_at as sale_ends_at, f.headline as sale_headline
        from kept k
        left join lateral (
          select s.id, s.sale_price, s.starts_at, s.ends_at, s.headline
          from public.public_flash_sales s
          where s.item_id = k.id
          order by s.sale_price asc, s.id
          limit 1
        ) f on true
      ) x), '[]'::jsonb),
    'businesses', coalesce((
      select jsonb_agg(to_jsonb(b))
      from (
        select id, slug, name, plan_key, verification_level, category_id, town, county, hours, exceptions
        from public.public_businesses
        where id in (select business_id from kept)
      ) b), '[]'::jsonb)
  );
$$;

revoke all on function public.products_snapshot(int) from public;
grant execute on function public.products_snapshot(int) to anon, authenticated, service_role;

-- Supports the newest-first scan above on the table behind the public view.
create index if not exists items_created_at_id_idx on public.items (created_at desc, id);

$m_0043_products_snapshot$),
    ('0044_seller_sign_in', $m_0044_seller_sign_in$
-- 0044: seller sign-in details.
--
-- A seller is created with only a Seller ID and a temporary password (must_change_password = true). From the
-- Account page they then add and verify their own email, and choose their own password. After that they can sign
-- in with either their Seller ID or their email.
--
-- The Supabase auth user keeps its internal address (<seller id>@sellers.epicmkt.app). The seller's real email
-- lives here on the business row, so changing it never touches auth and the Seller ID keeps working.
--
--   login_email              lower-cased; unique among live businesses; only ever set by an edge function after a code
--                            sent to that address was entered (sellers cannot write businesses directly)
--   login_email_verified_at  when the seller proved they own it
--   password_changed_at      when the seller last chose a password themselves (null = still on the one we sent)
--
-- OTP codes can now go to SMS (Africa's Talking) or email (Resend). seller_otps records which channel was used and,
-- for 'verify_email', which address the code was sent to, so a code for one address can never confirm another.

alter table public.businesses
  add column if not exists login_email text,
  add column if not exists login_email_verified_at timestamptz,
  add column if not exists password_changed_at timestamptz;

do $$
begin
  alter table public.businesses add constraint businesses_login_email_format
    check (login_email is null or (login_email = lower(login_email) and login_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'));
exception when duplicate_object then null;
end $$;

create unique index if not exists businesses_login_email_key
  on public.businesses (login_email) where login_email is not null and status <> 'deleted';

alter table public.seller_otps drop constraint if exists seller_otps_purpose_check;
alter table public.seller_otps add constraint seller_otps_purpose_check
  check (purpose in ('forgot_password', 'change_password', 'verify_email'));
alter table public.seller_otps add column if not exists channel text not null default 'sms';
alter table public.seller_otps drop constraint if exists seller_otps_channel_check;
alter table public.seller_otps add constraint seller_otps_channel_check check (channel in ('sms', 'email'));
alter table public.seller_otps add column if not exists target text;

drop function if exists public.seller_otp_issue(uuid, text, text);

create or replace function public.seller_otp_issue(p_business uuid, p_purpose text, p_code text, p_channel text default 'sms', p_target text default null)
returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_last timestamptz;
  v_hour integer;
  v_id uuid := gen_random_uuid();
begin
  p_channel := coalesce(p_channel, 'sms'); -- an explicit null means the default, not "no channel"
  if p_purpose not in ('forgot_password', 'change_password', 'verify_email') or p_code !~ '^[0-9]{6}$' or p_channel not in ('sms', 'email') then
    raise exception 'invalid_otp_request';
  end if;
  if p_purpose = 'verify_email' and (p_channel <> 'email' or p_target is null) then raise exception 'invalid_otp_request'; end if;
  perform pg_advisory_xact_lock(hashtext(p_business::text || 'otp:' || p_purpose));
  select max(o.created_at), count(*) filter (where o.created_at > now() - interval '1 hour')
    into v_last, v_hour from public.seller_otps o where o.business_id = p_business and o.purpose = p_purpose;
  if v_last is not null and v_last > now() - interval '60 seconds' then
    return jsonb_build_object('ok', false, 'reason', 'resend_wait', 'retry_after', ceil(extract(epoch from (v_last + interval '60 seconds' - now())))::integer);
  end if;
  if v_hour >= 5 then
    return jsonb_build_object('ok', false, 'reason', 'hour_limit', 'retry_after', 3600);
  end if;
  update public.seller_otps o set used = true where o.business_id = p_business and o.purpose = p_purpose and not o.used;
  insert into public.seller_otps (id, business_id, purpose, channel, target, code_hash, expires_at)
  values (v_id, p_business, p_purpose, p_channel, lower(p_target), encode(digest(v_id::text || ':' || p_code, 'sha256'), 'hex'), now() + interval '10 minutes');
  return jsonb_build_object('ok', true);
end $$;

-- On success also returns the channel and target the code was issued for.
create or replace function public.seller_otp_verify(p_business uuid, p_purpose text, p_code text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare r public.seller_otps;
begin
  select * into r from public.seller_otps o
  where o.business_id = p_business and o.purpose = p_purpose and not o.used and o.expires_at > now()
  order by o.created_at desc limit 1 for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'invalid'); end if;
  if r.attempts >= 5 then return jsonb_build_object('ok', false, 'reason', 'attempts'); end if;
  update public.seller_otps o set attempts = o.attempts + 1 where o.id = r.id;
  if r.code_hash = encode(digest(r.id::text || ':' || coalesce(p_code, ''), 'sha256'), 'hex') then
    update public.seller_otps o set used = true where o.id = r.id;
    return jsonb_build_object('ok', true, 'channel', r.channel, 'target', r.target);
  end if;
  return jsonb_build_object('ok', false, 'reason', 'invalid');
end $$;

do $$
declare fn text;
begin
  foreach fn in array array['seller_otp_issue(uuid, text, text, text, text)', 'seller_otp_verify(uuid, text, text)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', fn);
    execute format('grant execute on function public.%s to service_role', fn);
  end loop;
end $$;

$m_0044_seller_sign_in$),
    ('0045_product_offers', $m_0045_product_offers$
-- 0045_product_offers.sql
-- Offers belong to PRODUCTS. A store card shows an Offer chip because at least one of its products has a running offer;
-- a product card, the store page's product list and the product page show the offer only on the products that are in it.
-- The offer never changes a product's price: items.price (and any flash sale price) stays the truth, the deal is
-- explained beside it.
--
--   * offers gets a kind (percent off, buy X get Y, multi-buy, bundle, volume, free gift), its settings, who and when
--     it applies to (days, hours, new customers, minimum spend), an optional chip text, code and terms.
--   * offer_items says which products an offer is on. A bundle has main products and companion ("with") products.
--   * offer_config_valid() / offer_conditions_valid() are the rules of shared/src/offers.js, enforced on every write
--     path by a trigger. A test keeps the two sides equal.
--   * public_offers (customers) now lists only offers on at least one public product, with those products. Offers
--     written before this migration have no product and no kind, so they stop showing until the seller attaches
--     products. Nothing is deleted.
--   * The plan's active-offer limit stops counting offers whose end time has passed.
--   * seller_save_offer / seller_set_offer_active / seller_end_offer are the seller's write path.

alter table public.offers
  add column if not exists kind text check (kind is null or kind in ('percent_off','amount_off','buy_x_get_y','multi_buy','bundle','volume','free_gift')),
  add column if not exists config jsonb not null default '{}',
  add column if not exists conditions jsonb not null default '{}',
  add column if not exists chip_text text check (chip_text is null or char_length(chip_text) between 2 and 22),
  add column if not exists code text check (code is null or code ~ '^[A-Z0-9]{3,16}$'),
  add column if not exists terms text check (terms is null or char_length(terms) <= 280);
alter table public.offers drop constraint if exists offers_config_object;
alter table public.offers add constraint offers_config_object
  check (jsonb_typeof(config) = 'object' and jsonb_typeof(conditions) = 'object' and octet_length(config::text) <= 1500 and octet_length(conditions::text) <= 500);

create index if not exists offers_business_window_idx on public.offers (business_id, ends_at) where active;

-- ---------------------------------------------------------------------------
-- Rules (same as shared/src/offers.js)
-- ---------------------------------------------------------------------------
create or replace function public.offer_int(v jsonb) returns integer
language sql immutable as $$
  select case when jsonb_typeof(v) = 'number' and (v #>> '{}')::numeric = trunc((v #>> '{}')::numeric) and abs((v #>> '{}')::numeric) < 1000000000
    then (v #>> '{}')::numeric::integer end
$$;

create or replace function public.offer_num(v jsonb) returns numeric
language sql immutable as $$
  select case when jsonb_typeof(v) = 'number' then (v #>> '{}')::numeric end
$$;

create or replace function public.offer_text_ok(v jsonb, p_min integer, p_max integer) returns boolean
language sql immutable as $$
  select coalesce(jsonb_typeof(v) = 'string' and char_length(btrim(v #>> '{}')) between p_min and p_max and (v #>> '{}') !~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]', false)
$$;

create or replace function public.offer_config_valid(p_kind text, p_config jsonb) returns boolean
language plpgsql immutable set search_path = public as $$
declare
  c jsonb := coalesce(p_config, '{}'::jsonb);
  t jsonb;
  q integer;
  pc integer;
  prev_q integer := 0;
  prev_p integer := 0;
begin
  if jsonb_typeof(c) <> 'object' then return false; end if;
  if p_kind = 'percent_off' then
    return coalesce(public.offer_int(c -> 'percent') between 1 and 99, false);
  elsif p_kind = 'amount_off' then
    return coalesce(public.offer_num(c -> 'amount') > 0 and public.offer_num(c -> 'amount') <= 10000000, false);
  elsif p_kind = 'buy_x_get_y' then
    return coalesce(public.offer_int(c -> 'buy') between 1 and 50 and public.offer_int(c -> 'get') between 1 and 50
      and public.offer_int(c -> 'discountPercent') between 1 and 100, false);
  elsif p_kind = 'multi_buy' then
    return coalesce(public.offer_int(c -> 'qty') between 2 and 100 and public.offer_num(c -> 'price') > 0 and public.offer_num(c -> 'price') <= 100000000, false);
  elsif p_kind = 'bundle' then
    case c ->> 'rewardType'
      when 'free_gift' then return public.offer_text_ok(c -> 'gift', 2, 48);
      when 'percent_off' then return coalesce(public.offer_int(c -> 'rewardValue') between 1 and 99, false);
      when 'amount_off' then return coalesce(public.offer_num(c -> 'rewardValue') > 0 and public.offer_num(c -> 'rewardValue') <= 10000000, false);
      when 'bundle_price' then return coalesce(public.offer_num(c -> 'rewardValue') > 0 and public.offer_num(c -> 'rewardValue') <= 100000000, false);
      else return false;
    end case;
  elsif p_kind = 'volume' then
    if jsonb_typeof(c -> 'tiers') <> 'array' or jsonb_array_length(c -> 'tiers') not between 1 and 4 then return false; end if;
    for t in select * from jsonb_array_elements(c -> 'tiers') loop
      q := public.offer_int(t -> 'qty');
      pc := public.offer_int(t -> 'percent');
      if q is null or pc is null or q < 2 or q > 1000 or pc < 1 or pc > 99 or q <= prev_q or pc <= prev_p then return false; end if;
      prev_q := q;
      prev_p := pc;
    end loop;
    return true;
  elsif p_kind = 'free_gift' then
    if not public.offer_text_ok(c -> 'gift', 2, 48) then return false; end if;
    if c ? 'minQty' and not coalesce(public.offer_int(c -> 'minQty') between 1 and 1000, false) then return false; end if;
    return true;
  end if;
  return false;
end $$;

create or replace function public.offer_conditions_valid(p_conditions jsonb) returns boolean
language plpgsql immutable set search_path = public as $$
declare
  c jsonb := coalesce(p_conditions, '{}'::jsonb);
  d text;
  seen text[] := '{}';
begin
  if jsonb_typeof(c) <> 'object' then return false; end if;
  if c ? 'daysOfWeek' then
    if jsonb_typeof(c -> 'daysOfWeek') <> 'array' or jsonb_array_length(c -> 'daysOfWeek') > 6 then return false; end if;
    for d in select jsonb_array_elements_text(c -> 'daysOfWeek') loop
      if d not in ('mon','tue','wed','thu','fri','sat','sun') or d = any (seen) then return false; end if;
      seen := seen || d;
    end loop;
  end if;
  if c ? 'hours' then
    if jsonb_typeof(c -> 'hours') <> 'object'
       or coalesce(c -> 'hours' ->> 'from', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or coalesce(c -> 'hours' ->> 'to', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       or (c -> 'hours' ->> 'from') = (c -> 'hours' ->> 'to') then return false; end if;
  end if;
  if c ? 'newCustomersOnly' and jsonb_typeof(c -> 'newCustomersOnly') <> 'boolean' then return false; end if;
  if c ? 'minSpend' and not coalesce(public.offer_num(c -> 'minSpend') > 0 and public.offer_num(c -> 'minSpend') <= 10000000, false) then return false; end if;
  return true;
end $$;
grant execute on function public.offer_int(jsonb), public.offer_num(jsonb), public.offer_text_ok(jsonb, integer, integer),
  public.offer_config_valid(text, jsonb), public.offer_conditions_valid(jsonb) to anon, authenticated, service_role;

create or replace function public.offers_check_rules() returns trigger
language plpgsql set search_path = public as $$
begin
  -- Offers from before products were attached have no kind: they stay as they are and show nothing.
  if new.kind is null then
    if tg_op = 'INSERT' and public.actor_role() = 'seller' and new.config <> '{}'::jsonb then raise exception 'invalid_offer_config' using errcode = 'P0001'; end if;
    return new;
  end if;
  if not public.offer_config_valid(new.kind, new.config) then raise exception 'invalid_offer_config' using errcode = 'P0001'; end if;
  if not public.offer_conditions_valid(new.conditions) then raise exception 'invalid_offer_conditions' using errcode = 'P0001'; end if;
  if new.starts_at is not null and new.ends_at is not null and new.ends_at <= new.starts_at then raise exception 'invalid_window' using errcode = 'P0001'; end if;
  if new.ends_at is not null and new.ends_at - coalesce(new.starts_at, new.created_at, now()) > interval '365 days' then raise exception 'duration_too_long' using errcode = 'P0001'; end if;
  return new;
end $$;
drop trigger if exists t_offers_rules on public.offers;
create trigger t_offers_rules before insert or update on public.offers for each row execute function public.offers_check_rules();

-- The plan's active-offer limit counts offers that are on, not ones whose end time has passed.
create or replace function public.enforce_limit() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_cat text;
  v_plan text;
  v_limit integer;
  v_count integer;
  v_tbl text := tg_table_name;
begin
  if public.actor_role() <> 'seller' then return new; end if;
  if v_tbl = 'offers' then
    if not new.active then return new; end if;
    if tg_op = 'UPDATE' and old.active then return new; end if;
  end if;
  perform pg_advisory_xact_lock(hashtext(new.business_id::text || v_tbl));
  select b.category_id, b.plan_key into v_cat, v_plan from public.businesses b where b.id = new.business_id;
  if v_tbl = 'items' then
    select p.items_limit into v_limit from public.plans p where p.category_id = v_cat and p.plan_key = v_plan;
    if not found then v_limit := 0; end if;
    select count(*) into v_count from public.items i where i.business_id = new.business_id;
  elsif v_tbl = 'faqs' then
    select (case v_plan when 'premium' then g.premium else g.standard end ->> 'faqs')::integer into v_limit
      from public.global_limits g where g.id = 1;
    select count(*) into v_count from public.faqs f where f.business_id = new.business_id;
  else
    select (case v_plan when 'premium' then g.premium else g.standard end ->> 'activeOffers')::integer into v_limit
      from public.global_limits g where g.id = 1;
    select count(*) into v_count from public.offers o where o.business_id = new.business_id and o.active and (o.ends_at is null or o.ends_at > now());
  end if;
  if v_limit is not null and v_count >= v_limit then
    raise exception 'limit_reached:%', v_tbl using errcode = 'P0001';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Which products an offer is on
-- ---------------------------------------------------------------------------
create table if not exists public.offer_items (
  offer_id uuid not null references public.offers(id) on delete cascade,
  item_id uuid not null references public.items(id) on delete cascade,
  business_id uuid not null references public.businesses(id) on delete cascade,
  role text not null default 'main' check (role in ('main','with')),
  sort integer not null default 0,
  primary key (offer_id, item_id)
);
create index if not exists offer_items_item_idx on public.offer_items (item_id);
create index if not exists offer_items_business_idx on public.offer_items (business_id);

create or replace function public.offer_items_check() returns trigger
language plpgsql set search_path = public as $$
begin
  if not exists (select 1 from public.offers o where o.id = new.offer_id and o.business_id = new.business_id) then
    raise exception 'offer_item_mismatch' using errcode = '42501';
  end if;
  if not exists (select 1 from public.items i where i.id = new.item_id and i.business_id = new.business_id) then
    raise exception 'offer_item_mismatch' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' and (select count(*) from public.offer_items x where x.offer_id = new.offer_id) >= 12 then
    raise exception 'too_many_items' using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists t_offer_items_check on public.offer_items;
create trigger t_offer_items_check before insert or update on public.offer_items for each row execute function public.offer_items_check();

alter table public.offer_items enable row level security;
drop policy if exists "admin all offer_items" on public.offer_items;
create policy "admin all offer_items" on public.offer_items for all to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists "seller reads own offer_items" on public.offer_items;
create policy "seller reads own offer_items" on public.offer_items for select to authenticated using (business_id = public.my_business_id());
drop policy if exists "seller inserts own offer_items" on public.offer_items;
create policy "seller inserts own offer_items" on public.offer_items for insert to authenticated with check (business_id = public.my_business_id());
drop policy if exists "seller updates own offer_items" on public.offer_items;
create policy "seller updates own offer_items" on public.offer_items for update to authenticated using (business_id = public.my_business_id()) with check (business_id = public.my_business_id());
drop policy if exists "seller deletes own offer_items" on public.offer_items;
create policy "seller deletes own offer_items" on public.offer_items for delete to authenticated using (business_id = public.my_business_id());

do $$
declare cmd text;
begin
  foreach cmd in array array['insert', 'update', 'delete'] loop
    execute format('drop policy if exists %I on public.offer_items', 'suspended cannot ' || cmd || ' offer_items');
  end loop;
  create policy "suspended cannot insert offer_items" on public.offer_items as restrictive for insert to authenticated with check (public.is_admin() or not public.my_business_suspended());
  create policy "suspended cannot update offer_items" on public.offer_items as restrictive for update to authenticated using (public.is_admin() or not public.my_business_suspended()) with check (public.is_admin() or not public.my_business_suspended());
  create policy "suspended cannot delete offer_items" on public.offer_items as restrictive for delete to authenticated using (public.is_admin() or not public.my_business_suspended());
end $$;

revoke all on public.offer_items from public, anon;
grant select, insert, update, delete on public.offer_items to authenticated;
grant all on public.offer_items to service_role;

-- ---------------------------------------------------------------------------
-- What customers can see
-- ---------------------------------------------------------------------------
-- A product is public when customers can see it (the same rule as public_items). An offer is public when its store is
-- live, it is switched on, inside its window, not hidden or removed by an admin, has a kind, and is on at least one
-- public product (a bundle needs a public main product and a public companion). New columns go last so the view
-- definition stays valid.
create or replace view public.public_offers with (security_barrier = true) as
select
  o.id, o.business_id, o.title, o.description, o.starts_at, o.ends_at, o.created_at,
  o.kind, o.config, o.conditions, o.chip_text, o.code, o.terms,
  p.items
from public.offers o
join public.businesses b on b.id = o.business_id
cross join lateral (
  select
    coalesce(jsonb_agg(jsonb_build_object('item_id', oi.item_id, 'role', oi.role) order by oi.sort, oi.role, oi.item_id), '[]'::jsonb) as items,
    count(*) filter (where oi.role = 'main') as mains,
    count(*) filter (where oi.role = 'with') as withs
  from public.offer_items oi
  join public.items i on i.id = oi.item_id
  where oi.offer_id = o.id and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
) p
where public.business_is_visible(b)
  and o.kind is not null
  and o.active
  and not o.hidden_by_admin
  and not o.removed_by_admin
  and (o.starts_at is null or o.starts_at <= now())
  and (o.ends_at is null or o.ends_at > now())
  and (p.mains + p.withs) > 0
  and (o.kind <> 'bundle' or (p.mains > 0 and p.withs > 0));
revoke all on public.public_offers from public;
grant select on public.public_offers to anon, authenticated, service_role;

-- One row per product that has a running offer. This is what a store card's Offer chip counts.
create or replace view public.public_offer_items with (security_barrier = true) as
select
  oi.offer_id, oi.item_id, oi.business_id, oi.role, po.starts_at, po.ends_at
from public.offer_items oi
join public.public_offers po on po.id = oi.offer_id
join public.items i on i.id = oi.item_id
where i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin;
revoke all on public.public_offer_items from public;
grant select on public.public_offer_items to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Seller write path
-- ---------------------------------------------------------------------------
create or replace function public.seller_save_offer(p_id uuid, p_fields jsonb, p_items jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_kind text := f ->> 'kind';
  v_config jsonb := coalesce(f -> 'config', '{}'::jsonb);
  v_conditions jsonb := coalesce(f -> 'conditions', '{}'::jsonb);
  v_title text := nullif(btrim(coalesce(f ->> 'title', '')), '');
  v_desc text := nullif(btrim(coalesce(f ->> 'description', '')), '');
  v_chip text := nullif(btrim(coalesce(f ->> 'chip_text', '')), '');
  v_code text := nullif(upper(btrim(coalesce(f ->> 'code', ''))), '');
  v_terms text := nullif(btrim(coalesce(f ->> 'terms', '')), '');
  v_starts timestamptz;
  v_ends timestamptz;
  v_old public.offers;
  v_id uuid;
  v_mains integer := 0;
  v_withs integer := 0;
  v_n integer := 0;
  e jsonb;
  v_item uuid;
  v_role text;
  v_seen uuid[] := '{}';
  v_pos integer := 0;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  if v_kind is null or v_kind not in ('percent_off','amount_off','buy_x_get_y','multi_buy','bundle','volume','free_gift') then
    raise exception 'invalid_kind' using errcode = 'P0001';
  end if;
  if not public.offer_config_valid(v_kind, v_config) then raise exception 'invalid_config' using errcode = 'P0001'; end if;
  if not public.offer_conditions_valid(v_conditions) then raise exception 'invalid_conditions' using errcode = 'P0001'; end if;
  if v_title is not null and char_length(v_title) not between 3 and 80 then raise exception 'invalid_title' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_desc, '')) > 200 then raise exception 'invalid_description' using errcode = 'P0001'; end if;
  if v_chip is not null and char_length(v_chip) not between 2 and 22 then raise exception 'invalid_chip_text' using errcode = 'P0001'; end if;
  if v_code is not null and v_code !~ '^[A-Z0-9]{3,16}$' then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_terms, '')) > 280 then raise exception 'invalid_terms' using errcode = 'P0001'; end if;
  if coalesce(v_title, '') ~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' or coalesce(v_desc, '') ~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]'
     or coalesce(v_chip, '') ~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' or coalesce(v_terms, '') ~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' then
    raise exception 'invalid_text' using errcode = 'P0001';
  end if;

  if jsonb_typeof(p_items) is distinct from 'array' then raise exception 'no_items' using errcode = 'P0001'; end if;
  for e in select * from jsonb_array_elements(p_items) loop
    begin
      v_item := (e ->> 'item_id')::uuid;
    exception when others then
      raise exception 'item_not_found' using errcode = 'P0001';
    end;
    if v_item = any (v_seen) then continue; end if;
    v_seen := v_seen || v_item;
    v_role := case when v_kind = 'bundle' and e ->> 'role' = 'with' then 'with' else 'main' end;
    if not exists (select 1 from public.items i where i.id = v_item and i.business_id = v_biz and not i.removed_by_admin) then
      raise exception 'item_not_found' using errcode = 'P0001';
    end if;
    v_n := v_n + 1;
    if v_role = 'with' then v_withs := v_withs + 1; else v_mains := v_mains + 1; end if;
  end loop;
  if v_n = 0 then raise exception 'no_items' using errcode = 'P0001'; end if;
  if v_n > 12 then raise exception 'too_many_items' using errcode = 'P0001'; end if;
  if v_kind = 'bundle' and (v_mains < 1 or v_withs < 1) then raise exception 'bundle_needs_two' using errcode = 'P0001'; end if;

  if p_id is not null then
    select * into v_old from public.offers o where o.id = p_id and o.business_id = v_biz for update;
    if not found then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
    if v_old.removed_by_admin then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
  end if;

  v_starts := coalesce(nullif(f ->> 'starts_at', '')::timestamptz, case when p_id is null then now() else v_old.starts_at end);
  v_ends := nullif(f ->> 'ends_at', '')::timestamptz;
  if p_id is null and v_starts < now() then v_starts := now(); end if;
  if v_ends is not null and v_ends <= now() then raise exception 'ends_in_past' using errcode = 'P0001'; end if;
  if v_ends is not null and v_starts is not null and v_ends <= v_starts then raise exception 'invalid_window' using errcode = 'P0001'; end if;
  if v_ends is not null and v_ends - coalesce(v_starts, now()) > interval '365 days' then raise exception 'duration_too_long' using errcode = 'P0001'; end if;

  if p_id is null then
    insert into public.offers (business_id, title, description, kind, config, conditions, chip_text, code, terms, starts_at, ends_at)
    values (v_biz, coalesce(v_title, 'Special offer'), v_desc, v_kind, v_config, v_conditions, v_chip, v_code, v_terms, v_starts, v_ends)
    returning id into v_id;
  else
    v_id := p_id;
    update public.offers set
      title = coalesce(v_title, title), description = v_desc, kind = v_kind, config = v_config, conditions = v_conditions,
      chip_text = v_chip, code = v_code, terms = v_terms, starts_at = v_starts, ends_at = v_ends
    where id = v_id;
    delete from public.offer_items where offer_id = v_id;
  end if;

  v_seen := '{}';
  for e in select * from jsonb_array_elements(p_items) loop
    v_item := (e ->> 'item_id')::uuid;
    if v_item = any (v_seen) then continue; end if;
    v_seen := v_seen || v_item;
    v_pos := v_pos + 1;
    insert into public.offer_items (offer_id, item_id, business_id, role, sort)
    values (v_id, v_item, v_biz, case when v_kind = 'bundle' and e ->> 'role' = 'with' then 'with' else 'main' end, v_pos);
  end loop;
  return v_id;
end $$;
revoke all on function public.seller_save_offer(uuid, jsonb, jsonb) from public, anon;
grant execute on function public.seller_save_offer(uuid, jsonb, jsonb) to authenticated, service_role;

create or replace function public.seller_set_offer_active(p_id uuid, p_active boolean) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  update public.offers set active = coalesce(p_active, false)
  where id = p_id and business_id = v_biz and not removed_by_admin;
  if not found then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
  return true;
end $$;
revoke all on function public.seller_set_offer_active(uuid, boolean) from public, anon;
grant execute on function public.seller_set_offer_active(uuid, boolean) to authenticated, service_role;

-- Ending a running offer stamps its end now, so it stays in the seller's history. One that has not started yet is just removed.
create or replace function public.seller_end_offer(p_id uuid) returns text
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_o public.offers;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into v_o from public.offers o where o.id = p_id and o.business_id = v_biz and not o.removed_by_admin for update;
  if not found then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
  if v_o.starts_at is not null and v_o.starts_at > now() then
    delete from public.offers where id = p_id;
    return 'removed';
  end if;
  update public.offers set ends_at = now() where id = p_id and (ends_at is null or ends_at > now());
  return 'ended';
end $$;
revoke all on function public.seller_end_offer(uuid) from public, anon;
grant execute on function public.seller_end_offer(uuid) to authenticated, service_role;

grant all on public.offers to service_role;

do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['offers', 'offer_items'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

$m_0045_product_offers$),
    ('004600_item_availability', $m_004600_item_availability$
-- 004600_item_availability.sql
-- Availability for a business directory (see docs/availability.md).
--
--   * Available / by appointment  -> listed, no marker.
--   * Low stock                   -> listed, with a "Low stock" tag (and "Only N left" when the seller allows it).
--   * Out of stock / unavailable  -> NOT listed to customers. The seller keeps the item and can list it again.
--
-- Stock counting already existed in the database (track_stock, stock_count, low_stock_threshold, show_stock_count and the
-- t_items_stock trigger) but sellers had no way to set it. This migration:
--   1. makes public_items (and the offer views that repeat its rule) leave out sold-out items, and exposes stock_left,
--   2. lets seller_save_item write the stock fields,
--   3. adds seller_item_stock: "mark out of stock" and "back in stock" as one guarded call,
--   4. stops the bulk availability action from silently failing on counted items,
--   5. carries stock_left through products_snapshot.
-- No data is changed and no availability value is added or removed.

-- The one definition of "customers can be shown this". 'unavailable' is the older word for out of stock.
create or replace function public.item_is_listed(p_availability text) returns boolean
language sql immutable parallel safe as
$$ select coalesce(p_availability, 'available') not in ('out_of_stock', 'unavailable') $$;
revoke all on function public.item_is_listed(text) from public;
grant execute on function public.item_is_listed(text) to anon, authenticated, service_role;

-- New columns go last so the existing view definition stays valid.
create or replace view public.public_items with (security_barrier = true) as
select
  i.id, i.business_id, i.name, i.description, i.section, i.price, i.price_max, i.price_type, i.unit,
  i.availability, i.sort, i.created_at,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at) from public.item_media m where m.item_id = i.id and m.kind = 'image'), '[]'::jsonb) as image_paths,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at) from public.item_media m where m.item_id = i.id and m.kind = 'video'), '[]'::jsonb) as video_paths,
  -- Only when the seller counts stock, the item is running low, and they chose to tell customers the number.
  case when i.track_stock and i.show_stock_count and i.availability = 'limited_stock' and i.stock_count > 0 then i.stock_count end as stock_left
from public.items i
join public.businesses b on b.id = i.business_id
where public.business_is_visible(b) and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
  and public.item_is_listed(i.availability);
revoke all on public.public_items from public;
grant select on public.public_items to anon, authenticated, service_role;

-- The offer views repeat the "public product" rule, so a sold-out product must not keep an offer chip alive.
create or replace view public.public_offers with (security_barrier = true) as
select
  o.id, o.business_id, o.title, o.description, o.starts_at, o.ends_at, o.created_at,
  o.kind, o.config, o.conditions, o.chip_text, o.code, o.terms,
  p.items
from public.offers o
join public.businesses b on b.id = o.business_id
cross join lateral (
  select
    coalesce(jsonb_agg(jsonb_build_object('item_id', oi.item_id, 'role', oi.role) order by oi.sort, oi.role, oi.item_id), '[]'::jsonb) as items,
    count(*) filter (where oi.role = 'main') as mains,
    count(*) filter (where oi.role = 'with') as withs
  from public.offer_items oi
  join public.items i on i.id = oi.item_id
  where oi.offer_id = o.id and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
    and public.item_is_listed(i.availability)
) p
where public.business_is_visible(b)
  and o.kind is not null
  and o.active
  and not o.hidden_by_admin
  and not o.removed_by_admin
  and (o.starts_at is null or o.starts_at <= now())
  and (o.ends_at is null or o.ends_at > now())
  and (p.mains + p.withs) > 0
  and (o.kind <> 'bundle' or (p.mains > 0 and p.withs > 0));
revoke all on public.public_offers from public;
grant select on public.public_offers to anon, authenticated, service_role;

create or replace view public.public_offer_items with (security_barrier = true) as
select
  oi.offer_id, oi.item_id, oi.business_id, oi.role, po.starts_at, po.ends_at
from public.offer_items oi
join public.public_offers po on po.id = oi.offer_id
join public.items i on i.id = oi.item_id
where i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
  and public.item_is_listed(i.availability);
revoke all on public.public_offer_items from public;
grant select on public.public_offer_items to anon, authenticated, service_role;

-- Seller save: stock fields are optional. Sending none leaves the item's stock settings alone.
create or replace function public.seller_save_item(p_id uuid, p_fields jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_old public.items;
  v_name text := btrim(coalesce(f ->> 'name', ''));
  v_desc text := nullif(btrim(coalesce(f ->> 'description', '')), '');
  v_section text := nullif(btrim(coalesce(f ->> 'section', '')), '');
  v_unit text := nullif(btrim(coalesce(f ->> 'unit', '')), '');
  v_type text := f ->> 'price_type';
  v_avail text := f ->> 'availability';
  v_old_item public.items;
  v_track boolean;
  v_count integer;
  v_low integer;
  v_show boolean;
  v_price numeric;
  v_max numeric;
  v_sale numeric;
  v_sort integer;
  v_new uuid;
  c_money constant text := '^\d{1,10}(\.\d{1,2})?$';
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  if char_length(v_name) < 2 or char_length(v_name) > 120 then raise exception 'invalid_name' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_desc, '')) > 2000 or char_length(coalesce(v_section, '')) > 60 or char_length(coalesce(v_unit, '')) > 30 then
    raise exception 'invalid_text' using errcode = 'P0001';
  end if;
  if v_avail is null or v_avail not in ('available','limited_stock','out_of_stock','unavailable','by_appointment') then
    raise exception 'invalid_availability' using errcode = 'P0001';
  end if;
  if v_type is null or v_type not in ('fixed','from','range','free','contact') then raise exception 'invalid_price' using errcode = 'P0001'; end if;

  -- Stock counting is optional. A caller that sends none of these fields leaves the item's stock settings as they are.
  if p_id is not null then
    select * into v_old_item from public.items i where i.id = p_id and i.business_id = v_id;
  end if;
  if (f ? 'low_stock_threshold' and coalesce(f ->> 'low_stock_threshold', '') !~ '^\d{1,4}$')
     or (f ? 'track_stock' and coalesce(f ->> 'track_stock', '') not in ('true', 'false'))
     or (f ? 'show_stock_count' and coalesce(f ->> 'show_stock_count', '') not in ('true', 'false')) then
    raise exception 'invalid_stock' using errcode = 'P0001';
  end if;
  v_track := case when f ? 'track_stock' then coalesce((f ->> 'track_stock')::boolean, false) else coalesce(v_old_item.track_stock, false) end;
  v_low := case when f ? 'low_stock_threshold' then (f ->> 'low_stock_threshold')::integer else coalesce(v_old_item.low_stock_threshold, 3) end;
  v_show := case when f ? 'show_stock_count' then coalesce((f ->> 'show_stock_count')::boolean, false) else coalesce(v_old_item.show_stock_count, false) end;
  if f ? 'stock_count' and coalesce(f ->> 'stock_count', '') <> '' then
    if (f ->> 'stock_count') !~ '^\d{1,6}$' then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
    v_count := (f ->> 'stock_count')::integer;
  elsif f ? 'stock_count' then
    v_count := null;
  else
    v_count := v_old_item.stock_count;
  end if;
  if v_low is null or v_low < 0 or v_low > 9999 then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
  if v_track and v_count is null then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
  -- A counted item takes its availability from the count (trigger t_items_stock), so start from the neutral value.
  if v_track then v_avail := 'available'; end if;

  if v_type in ('fixed','from','range') then
    if coalesce(f ->> 'price', '') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    v_price := (f ->> 'price')::numeric;
    if v_type = 'range' then
      if coalesce(f ->> 'price_max', '') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
      v_max := (f ->> 'price_max')::numeric;
      if v_max < v_price then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    end if;
    if coalesce(f ->> 'sale_price', '') <> '' then
      if (f ->> 'sale_price') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
      v_sale := (f ->> 'sale_price')::numeric;
      if v_sale >= v_price then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    end if;
  end if;

  if p_id is null then
    select coalesce(max(sort), 0) + 1 into v_sort from public.items where business_id = v_id;
    insert into public.items (business_id, name, description, section, price_type, price, price_max, sale_price, unit, availability, track_stock, stock_count, low_stock_threshold, show_stock_count, visible, draft, sort)
    values (v_id, v_name, v_desc, v_section, v_type, v_price, v_max, v_sale, v_unit, v_avail, v_track, v_count, v_low, v_show, false, true, v_sort)
    returning id into v_new;
    return v_new;
  end if;

  select * into v_old from public.items i where i.id = p_id and i.business_id = v_id and not i.removed_by_admin for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;

  if (v_old.price, v_old.price_max, v_old.price_type, v_old.sale_price) is distinct from (v_price, v_max, v_type, v_sale)
     and exists (select 1 from public.flash_sales s where s.item_id = p_id and s.status in ('scheduled','live')) then
    raise exception 'item_in_flash_sale' using errcode = 'P0001';
  end if;

  update public.items set
    name = v_name, description = v_desc, section = v_section, price_type = v_type, price = v_price, price_max = v_max,
    sale_price = v_sale, unit = v_unit, availability = v_avail,
    track_stock = v_track, stock_count = v_count, low_stock_threshold = v_low, show_stock_count = v_show
  where id = p_id;
  return p_id;
end $$;

-- Mark out of stock / back in stock, for one of the seller's own items.
--   sold_out : a counted item goes to 0 (the trigger delists it); any other item is set to out_of_stock.
--   restock  : a counted item needs the new count (a count of 0 would put it straight back out); any other item is
--              set to available.
create or replace function public.seller_item_stock(p_id uuid, p_action text, p_count integer default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_item public.items;
  v_after public.items;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if p_action is null or p_action not in ('sold_out', 'restock') then raise exception 'invalid_action' using errcode = 'P0001'; end if;

  select * into v_item from public.items i where i.id = p_id and i.business_id = v_id and not i.removed_by_admin for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;

  if p_action = 'sold_out' then
    if v_item.track_stock then
      update public.items set stock_count = 0 where id = p_id;
    else
      update public.items set availability = 'out_of_stock' where id = p_id;
    end if;
  elsif v_item.track_stock then
    if p_count is null or p_count < 1 or p_count > 999999 then raise exception 'stock_count_required' using errcode = 'P0001'; end if;
    update public.items set stock_count = p_count where id = p_id;
  else
    update public.items set availability = 'available' where id = p_id;
  end if;

  select * into v_after from public.items where id = p_id;
  perform public.write_audit(v_id, 'item_stock_' || p_action, 'item', p_id::text, jsonb_build_object('availability', v_after.availability, 'stock_count', v_after.stock_count));
  return jsonb_build_object('availability', v_after.availability, 'stock_count', v_after.stock_count);
end $$;
revoke all on function public.seller_item_stock(uuid, text, integer) from public, anon;
grant execute on function public.seller_item_stock(uuid, text, integer) to authenticated, service_role;

-- Bulk actions: the availability action no longer silently fails on counted items.
create or replace function public.seller_bulk_items(p_action text, p_ids uuid[], p_args jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_ids uuid[];
  v_n integer := 0;
  v_skipped integer := 0;
  v_tenths integer;
  v_section text;
  v_avail text;
  v_blocked integer := 0;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if p_action is null or p_action not in ('hide','show','delete','move_section','set_availability','price_percent','confirm_prices') then
    raise exception 'invalid_action' using errcode = 'P0001';
  end if;
  if p_ids is null or cardinality(p_ids) = 0 then raise exception 'no_items' using errcode = 'P0001'; end if;
  if cardinality(p_ids) > 500 then raise exception 'too_many_items' using errcode = 'P0001'; end if;

  perform 1 from public.items i where i.business_id = v_id and i.id = any (p_ids) and not i.removed_by_admin order by i.id for update;
  select coalesce(array_agg(i.id order by i.id), '{}') into v_ids
    from public.items i
    where i.business_id = v_id and i.id = any (p_ids) and not i.removed_by_admin;
  v_skipped := cardinality(p_ids) - cardinality(v_ids);

  if p_action = 'hide' then
    update public.items set visible = false where id = any (v_ids) and visible;
    get diagnostics v_n = row_count;
  elsif p_action = 'show' then
    update public.items set visible = true, draft = false where id = any (v_ids) and (not visible or draft);
    get diagnostics v_n = row_count;
  elsif p_action = 'delete' then
    delete from public.items where id = any (v_ids);
    get diagnostics v_n = row_count;
  elsif p_action = 'move_section' then
    v_section := nullif(btrim(coalesce(p_args ->> 'section', '')), '');
    if v_section is not null and char_length(v_section) > 60 then raise exception 'invalid_section' using errcode = 'P0001'; end if;
    update public.items set section = v_section where id = any (v_ids) and section is distinct from v_section;
    get diagnostics v_n = row_count;
  elsif p_action = 'set_availability' then
    v_avail := p_args ->> 'availability';
    if v_avail is null or v_avail not in ('available','limited_stock','out_of_stock','unavailable','by_appointment') then
      raise exception 'invalid_availability' using errcode = 'P0001';
    end if;
    -- A counted item takes its availability from its count, so a status alone cannot relist it: with no stock in hand it
    -- would flip straight back out. Those are skipped, and the seller is told to give them a count (Back in stock).
    select count(*) into v_blocked from public.items i
      where i.id = any (v_ids) and i.track_stock and v_avail in ('available','limited_stock') and coalesce(i.stock_count, 0) <= 0;
    update public.items set
      availability = v_avail,
      stock_count = case when track_stock and v_avail in ('out_of_stock','unavailable') then 0 else stock_count end
    where id = any (v_ids) and availability <> v_avail
      and not (track_stock and v_avail in ('available','limited_stock') and coalesce(stock_count, 0) <= 0);
    get diagnostics v_n = row_count;
    v_skipped := v_skipped + v_blocked;
  elsif p_action = 'price_percent' then
    begin
      v_tenths := round((p_args ->> 'percent')::numeric * 10)::integer;
    exception when others then
      raise exception 'invalid_percent' using errcode = 'P0001';
    end;
    if v_tenths = 0 or v_tenths < -900 or v_tenths > 3000 then raise exception 'invalid_percent' using errcode = 'P0001'; end if;
    if exists (
      select 1 from public.items i
      where i.id = any (v_ids) and i.price_type in ('fixed','from','range') and not exists (select 1 from public.flash_sales s where s.item_id = i.id and s.status in ('scheduled','live'))
        and greatest(public.seller_scale_price(i.price, v_tenths), coalesce(public.seller_scale_price(i.price_max, v_tenths), 0)) > 9999999999.99
    ) then raise exception 'price_too_large' using errcode = 'P0001'; end if;
    update public.items i set
      price = public.seller_scale_price(i.price, v_tenths),
      price_max = public.seller_scale_price(i.price_max, v_tenths),
      sale_price = case
        when i.sale_price is null then null
        when public.seller_scale_price(i.sale_price, v_tenths) < public.seller_scale_price(i.price, v_tenths) then public.seller_scale_price(i.sale_price, v_tenths)
        when public.seller_scale_price(i.price, v_tenths) > 1 then public.seller_scale_price(i.price, v_tenths) - 1
        else null end
    where i.id = any (v_ids) and i.price_type in ('fixed','from','range') and i.price is not null
      and not exists (select 1 from public.flash_sales s where s.item_id = i.id and s.status in ('scheduled','live'));
    get diagnostics v_n = row_count;
    v_skipped := v_skipped + (cardinality(v_ids) - v_n);
  else
    update public.items set price_confirmed_at = now() where id = any (v_ids);
    get diagnostics v_n = row_count;
  end if;

  perform public.write_audit(v_id, 'items_bulk_' || p_action, 'item', null, jsonb_build_object('count', v_n, 'skipped', v_skipped, 'args', coalesce(p_args, '{}')));
  return jsonb_build_object('affected', v_n, 'skipped', v_skipped);
end $$;

-- The home grid snapshot carries stock_left so the card can say "Only 3 left".
create or replace function public.products_snapshot(p_limit int default 10000) returns jsonb
language sql stable set search_path = public as $$
  with capped as (
    select i.id, i.business_id, i.name, left(i.description, 160) as description, i.section, i.price, i.price_type,
           i.unit, i.availability, i.stock_left, i.created_at, i.image_paths ->> 0 as image_path
    from public.public_items i
    order by i.created_at desc, i.id
    limit least(greatest(coalesce(p_limit, 10000), 1), 50000) + 1
  ), kept as (
    select * from capped order by created_at desc, id limit least(greatest(coalesce(p_limit, 10000), 1), 50000)
  )
  select jsonb_build_object(
    'truncated', (select count(*) from capped) > least(greatest(coalesce(p_limit, 10000), 1), 50000),
    'items', coalesce((
      select jsonb_agg(to_jsonb(x) order by x.created_at desc, x.id)
      from (
        select k.id, k.business_id, k.name, k.description, k.section, k.price, k.price_type, k.unit, k.availability, k.stock_left,
               k.created_at, k.image_path,
               f.id as sale_id, f.sale_price, f.starts_at as sale_starts_at, f.ends_at as sale_ends_at, f.headline as sale_headline
        from kept k
        left join lateral (
          select s.id, s.sale_price, s.starts_at, s.ends_at, s.headline
          from public.public_flash_sales s
          where s.item_id = k.id
          order by s.sale_price asc, s.id
          limit 1
        ) f on true
      ) x), '[]'::jsonb),
    'businesses', coalesce((
      select jsonb_agg(to_jsonb(b))
      from (
        select id, slug, name, plan_key, verification_level, category_id, town, county, hours, exceptions
        from public.public_businesses
        where id in (select business_id from kept)
      ) b), '[]'::jsonb)
  );
$$;
revoke all on function public.products_snapshot(int) from public;
grant execute on function public.products_snapshot(int) to anon, authenticated, service_role;

$m_004600_item_availability$),
    ('004601_store_offers', $m_004601_store_offers$
-- 004601_store_offers.sql
-- Two kinds of offer, both controlled by the seller:
--   product  an offer on chosen products (0045). Shows on those products and counts toward the store card's Offer chip.
--   store    an offer on the whole shop: percent off, amount off or a free perk with the order, with its own settings
--            (minimum spend, days, hours, new customers). It has no products. Shows on the store page and the store chip.
-- Sellers can edit, pause, end and now DELETE any offer, including ended ones and ones made before 0045.
--
--   * offers.scope: 'product' (default) or 'store'.
--   * Offers made before 0045 were whole-store promotions with no kind: they become scope 'store' and stay hidden from
--     customers until the seller opens them, picks a type and saves.
--   * public_offers lists a store offer without needing products.
--   * seller_save_offer takes scope from p_fields; seller_delete_offer removes an offer for good.

alter table public.offers
  add column if not exists scope text not null default 'product' check (scope in ('product', 'store'));

update public.offers set scope = 'store' where kind is null and scope <> 'store';

create or replace function public.offers_check_rules() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.kind is null then
    if tg_op = 'INSERT' and public.actor_role() = 'seller' and new.config <> '{}'::jsonb then raise exception 'invalid_offer_config' using errcode = 'P0001'; end if;
    return new;
  end if;
  if new.scope = 'store' and (new.kind not in ('percent_off', 'amount_off', 'free_gift') or (new.kind = 'free_gift' and new.config ? 'minQty')) then
    raise exception 'invalid_offer_config' using errcode = 'P0001';
  end if;
  if not public.offer_config_valid(new.kind, new.config) then raise exception 'invalid_offer_config' using errcode = 'P0001'; end if;
  if not public.offer_conditions_valid(new.conditions) then raise exception 'invalid_offer_conditions' using errcode = 'P0001'; end if;
  if new.starts_at is not null and new.ends_at is not null and new.ends_at <= new.starts_at then raise exception 'invalid_window' using errcode = 'P0001'; end if;
  if new.ends_at is not null and new.ends_at - coalesce(new.starts_at, new.created_at, now()) > interval '365 days' then raise exception 'duration_too_long' using errcode = 'P0001'; end if;
  return new;
end $$;

create or replace function public.offer_items_check() returns trigger
language plpgsql set search_path = public as $$
begin
  if not exists (select 1 from public.offers o where o.id = new.offer_id and o.business_id = new.business_id and o.scope = 'product') then
    raise exception 'offer_item_mismatch' using errcode = '42501';
  end if;
  if not exists (select 1 from public.items i where i.id = new.item_id and i.business_id = new.business_id) then
    raise exception 'offer_item_mismatch' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' and (select count(*) from public.offer_items x where x.offer_id = new.offer_id) >= 12 then
    raise exception 'too_many_items' using errcode = 'P0001';
  end if;
  return new;
end $$;

-- A store offer is public on its own. A product offer still needs a public product (a bundle needs a main and a companion).
-- scope goes last so the view definition stays valid.
create or replace view public.public_offers with (security_barrier = true) as
select
  o.id, o.business_id, o.title, o.description, o.starts_at, o.ends_at, o.created_at,
  o.kind, o.config, o.conditions, o.chip_text, o.code, o.terms,
  p.items,
  o.scope
from public.offers o
join public.businesses b on b.id = o.business_id
cross join lateral (
  select
    coalesce(jsonb_agg(jsonb_build_object('item_id', oi.item_id, 'role', oi.role) order by oi.sort, oi.role, oi.item_id), '[]'::jsonb) as items,
    count(*) filter (where oi.role = 'main') as mains,
    count(*) filter (where oi.role = 'with') as withs
  from public.offer_items oi
  join public.items i on i.id = oi.item_id
  where oi.offer_id = o.id and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
) p
where public.business_is_visible(b)
  and o.kind is not null
  and o.active
  and not o.hidden_by_admin
  and not o.removed_by_admin
  and (o.starts_at is null or o.starts_at <= now())
  and (o.ends_at is null or o.ends_at > now())
  and (
    o.scope = 'store'
    or ((p.mains + p.withs) > 0 and (o.kind <> 'bundle' or (p.mains > 0 and p.withs > 0)))
  );
revoke all on public.public_offers from public;
grant select on public.public_offers to anon, authenticated, service_role;

create or replace function public.seller_save_offer(p_id uuid, p_fields jsonb, p_items jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_scope text := case when f ->> 'scope' = 'store' then 'store' else 'product' end;
  v_kind text := f ->> 'kind';
  v_config jsonb := coalesce(f -> 'config', '{}'::jsonb);
  v_conditions jsonb := coalesce(f -> 'conditions', '{}'::jsonb);
  v_title text := nullif(btrim(coalesce(f ->> 'title', '')), '');
  v_desc text := nullif(btrim(coalesce(f ->> 'description', '')), '');
  v_chip text := nullif(btrim(coalesce(f ->> 'chip_text', '')), '');
  v_code text := nullif(upper(btrim(coalesce(f ->> 'code', ''))), '');
  v_terms text := nullif(btrim(coalesce(f ->> 'terms', '')), '');
  v_starts timestamptz;
  v_ends timestamptz;
  v_old public.offers;
  v_id uuid;
  v_mains integer := 0;
  v_withs integer := 0;
  v_n integer := 0;
  e jsonb;
  v_item uuid;
  v_role text;
  v_seen uuid[] := '{}';
  v_pos integer := 0;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  if v_kind is null
     or (v_scope = 'product' and v_kind not in ('percent_off','amount_off','buy_x_get_y','multi_buy','bundle','volume','free_gift'))
     or (v_scope = 'store' and v_kind not in ('percent_off','amount_off','free_gift')) then
    raise exception 'invalid_kind' using errcode = 'P0001';
  end if;
  if not public.offer_config_valid(v_kind, v_config) or (v_scope = 'store' and v_kind = 'free_gift' and v_config ? 'minQty') then
    raise exception 'invalid_config' using errcode = 'P0001';
  end if;
  if not public.offer_conditions_valid(v_conditions) then raise exception 'invalid_conditions' using errcode = 'P0001'; end if;
  if v_title is not null and char_length(v_title) not between 3 and 80 then raise exception 'invalid_title' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_desc, '')) > 200 then raise exception 'invalid_description' using errcode = 'P0001'; end if;
  if v_chip is not null and char_length(v_chip) not between 2 and 22 then raise exception 'invalid_chip_text' using errcode = 'P0001'; end if;
  if v_code is not null and v_code !~ '^[A-Z0-9]{3,16}$' then raise exception 'invalid_code' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_terms, '')) > 280 then raise exception 'invalid_terms' using errcode = 'P0001'; end if;
  if coalesce(v_title, '') ~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' or coalesce(v_desc, '') ~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]'
     or coalesce(v_chip, '') ~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' or coalesce(v_terms, '') ~ '[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' then
    raise exception 'invalid_text' using errcode = 'P0001';
  end if;

  if v_scope = 'product' then
    if jsonb_typeof(p_items) is distinct from 'array' then raise exception 'no_items' using errcode = 'P0001'; end if;
    for e in select * from jsonb_array_elements(p_items) loop
      begin
        v_item := (e ->> 'item_id')::uuid;
      exception when others then
        raise exception 'item_not_found' using errcode = 'P0001';
      end;
      if v_item = any (v_seen) then continue; end if;
      v_seen := v_seen || v_item;
      v_role := case when v_kind = 'bundle' and e ->> 'role' = 'with' then 'with' else 'main' end;
      if not exists (select 1 from public.items i where i.id = v_item and i.business_id = v_biz and not i.removed_by_admin) then
        raise exception 'item_not_found' using errcode = 'P0001';
      end if;
      v_n := v_n + 1;
      if v_role = 'with' then v_withs := v_withs + 1; else v_mains := v_mains + 1; end if;
    end loop;
    if v_n = 0 then raise exception 'no_items' using errcode = 'P0001'; end if;
    if v_n > 12 then raise exception 'too_many_items' using errcode = 'P0001'; end if;
    if v_kind = 'bundle' and (v_mains < 1 or v_withs < 1) then raise exception 'bundle_needs_two' using errcode = 'P0001'; end if;
  end if;

  if p_id is not null then
    select * into v_old from public.offers o where o.id = p_id and o.business_id = v_biz for update;
    if not found then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
    if v_old.removed_by_admin then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
    if v_old.kind is not null and v_old.scope <> v_scope then raise exception 'scope_locked' using errcode = 'P0001'; end if;
  end if;

  v_starts := coalesce(nullif(f ->> 'starts_at', '')::timestamptz, case when p_id is null then now() else v_old.starts_at end);
  v_ends := nullif(f ->> 'ends_at', '')::timestamptz;
  if p_id is null and v_starts < now() then v_starts := now(); end if;
  if v_ends is not null and v_ends <= now() then raise exception 'ends_in_past' using errcode = 'P0001'; end if;
  if v_ends is not null and v_starts is not null and v_ends <= v_starts then raise exception 'invalid_window' using errcode = 'P0001'; end if;
  if v_ends is not null and v_ends - coalesce(v_starts, now()) > interval '365 days' then raise exception 'duration_too_long' using errcode = 'P0001'; end if;

  if p_id is null then
    insert into public.offers (business_id, scope, title, description, kind, config, conditions, chip_text, code, terms, starts_at, ends_at)
    values (v_biz, v_scope, coalesce(v_title, 'Special offer'), v_desc, v_kind, v_config, v_conditions, v_chip, v_code, v_terms, v_starts, v_ends)
    returning id into v_id;
  else
    v_id := p_id;
    delete from public.offer_items where offer_id = v_id;
    update public.offers set
      scope = v_scope, title = coalesce(v_title, title), description = v_desc, kind = v_kind, config = v_config, conditions = v_conditions,
      chip_text = v_chip, code = v_code, terms = v_terms, starts_at = v_starts, ends_at = v_ends
    where id = v_id;
  end if;

  if v_scope = 'product' then
    v_seen := '{}';
    for e in select * from jsonb_array_elements(p_items) loop
      v_item := (e ->> 'item_id')::uuid;
      if v_item = any (v_seen) then continue; end if;
      v_seen := v_seen || v_item;
      v_pos := v_pos + 1;
      insert into public.offer_items (offer_id, item_id, business_id, role, sort)
      values (v_id, v_item, v_biz, case when v_kind = 'bundle' and e ->> 'role' = 'with' then 'with' else 'main' end, v_pos);
    end loop;
  end if;
  return v_id;
end $$;
revoke all on function public.seller_save_offer(uuid, jsonb, jsonb) from public, anon;
grant execute on function public.seller_save_offer(uuid, jsonb, jsonb) to authenticated, service_role;

-- Deletes the offer and, by cascade, its product list. Works on running, scheduled, paused and ended offers alike.
create or replace function public.seller_delete_offer(p_id uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  delete from public.offers where id = p_id and business_id = v_biz and not removed_by_admin;
  if not found then raise exception 'offer_not_found' using errcode = 'P0001'; end if;
  return true;
end $$;
revoke all on function public.seller_delete_offer(uuid) from public, anon;
grant execute on function public.seller_delete_offer(uuid) to authenticated, service_role;

$m_004601_store_offers$),
    ('0047_cloudinary_media', $m_0047_cloudinary_media$
-- Pictures move to Cloudinary. Supabase keeps the data (messages, payments, listings) and the paths that point at pictures.
--
-- A stored picture value is now one of two things (see shared/src/seller/images.js):
--   Cloudinary public id   "<businessId>/<itemId>/<uuid>"        no file extension
--   legacy Supabase path   "<businessId>/<itemId>/<uuid>.jpg"    always has one
-- Nothing about item_media.path, businesses.logo_path or the public views changes shape, so every existing query,
-- index, snapshot and policy keeps working. This migration adds only what Cloudinary needs around them:
--
--   media_uploads  one row per signed upload, written BEFORE the browser sends the file. It binds a public id to a business,
--                  an item and a purpose, so finalize can refuse an id the server never issued.
--   media_gc       a queue of Cloudinary files nobody points at any more (a deleted photo, a replaced logo, an upload that was
--                  never finished). A trigger fills it in the same transaction as the change, so a crash cannot leave a file
--                  behind; the media-gc function drains it. Same idea as a transactional outbox.
--
-- Both tables are reachable only by the service role (the edge functions). RLS is on with no policies, and no grants.

create or replace function public.is_cloudinary_id(p text) returns boolean
language sql immutable as $$
  select p is not null
    and p <> ''
    and char_length(p) <= 300
    and p !~* '^(blob:|data:|https?:)'
    and position('..' in p) = 0
    and p !~ '\.[A-Za-z0-9]{2,5}$'
$$;

create table if not exists public.media_uploads (
  public_id text primary key,
  business_id uuid not null,
  item_id uuid,
  purpose text not null check (purpose in ('item_photo', 'logo', 'cover')),
  created_at timestamptz not null default now(),
  finalized_at timestamptz,
  check (public.is_cloudinary_id(public_id)),
  check (public_id like business_id::text || '/%'),
  check ((purpose = 'item_photo') = (item_id is not null))
);
-- The sweep looks only at old rows; the partial index keeps that cheap however many finished uploads there are.
create index if not exists media_uploads_created_idx on public.media_uploads (created_at);
create index if not exists media_uploads_pending_idx on public.media_uploads (created_at) where finalized_at is null;
create index if not exists media_uploads_business_idx on public.media_uploads (business_id, created_at desc);

create table if not exists public.media_gc (
  public_id text primary key,
  reason text not null,
  queued_at timestamptz not null default now(),
  attempts integer not null default 0,
  next_try_at timestamptz not null default now(),
  last_error text
);
create index if not exists media_gc_due_idx on public.media_gc (next_try_at);

alter table public.media_uploads enable row level security;
alter table public.media_gc enable row level security;
revoke all on public.media_uploads, public.media_gc from public, anon, authenticated;
grant select, insert, update, delete on public.media_uploads, public.media_gc to service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- Outbox triggers: whatever stops pointing at a Cloudinary file queues that file for deletion, in the same transaction.
-- SECURITY DEFINER so a seller deleting their own photo (row level security lets them) can still write the queue.
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.media_gc_from_item_media() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.kind = 'image' and public.is_cloudinary_id(old.path) then
    insert into public.media_gc (public_id, reason) values (old.path, 'photo_removed') on conflict (public_id) do nothing;
  end if;
  return null;
end $$;

drop trigger if exists item_media_gc on public.item_media;
create trigger item_media_gc after delete on public.item_media
  for each row execute function public.media_gc_from_item_media();

create or replace function public.media_gc_from_business() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    insert into public.media_gc (public_id, reason)
    select x, 'business_deleted' from unnest(array[old.logo_path, old.cover_path]) as x
    where public.is_cloudinary_id(x)
    on conflict (public_id) do nothing;
    return null;
  end if;
  insert into public.media_gc (public_id, reason)
  select x, 'shop_image_replaced'
  from unnest(array[
    case when old.logo_path is distinct from new.logo_path then old.logo_path end,
    case when old.cover_path is distinct from new.cover_path then old.cover_path end
  ]) as x
  where public.is_cloudinary_id(x)
  on conflict (public_id) do nothing;
  return null;
end $$;

drop trigger if exists businesses_media_gc_update on public.businesses;
create trigger businesses_media_gc_update after update of logo_path, cover_path on public.businesses
  for each row execute function public.media_gc_from_business();
drop trigger if exists businesses_media_gc_delete on public.businesses;
create trigger businesses_media_gc_delete after delete on public.businesses
  for each row execute function public.media_gc_from_business();

-- ---------------------------------------------------------------------------------------------------------------------
-- Service-only RPCs used by the edge functions.
-- ---------------------------------------------------------------------------------------------------------------------

-- Called by seller-media-sign BEFORE the browser gets its signature. The id must sit under the business's own prefix, and an
-- item photo must belong to an item of that business, so a seller can never be signed an id inside someone else's folder.
create or replace function public.media_register_upload(p_business uuid, p_item uuid, p_purpose text, p_public_id text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_purpose not in ('item_photo', 'logo', 'cover') then raise exception 'invalid_purpose'; end if;
  if not public.is_cloudinary_id(p_public_id) or p_public_id not like p_business::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
  if p_purpose = 'item_photo' then
    if p_item is null or not exists (select 1 from public.items i where i.id = p_item and i.business_id = p_business) then raise exception 'item_not_found'; end if;
  elsif p_item is not null then
    raise exception 'invalid_purpose';
  end if;
  insert into public.media_uploads (public_id, business_id, item_id, purpose) values (p_public_id, p_business, p_item, p_purpose);
end $$;

-- Called by seller-media-finalize once Cloudinary's own signature on the upload response has been checked.
-- Returns the purpose and item the id was issued for; raises upload_not_found for an id this business was never signed.
create or replace function public.media_confirm_upload(p_business uuid, p_public_id text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare u public.media_uploads;
begin
  select * into u from public.media_uploads m where m.public_id = p_public_id and m.business_id = p_business for update;
  if not found then raise exception 'upload_not_found'; end if;
  update public.media_uploads m set finalized_at = coalesce(m.finalized_at, now()) where m.public_id = p_public_id;
  return jsonb_build_object('purpose', u.purpose, 'item_id', u.item_id);
end $$;

-- Hands the worker the files that are due, and leases them for ten minutes so two workers never take the same file.
-- Anything that something still points at is dropped from the queue instead of being handed out: the queue can be wrong, a delete cannot.
create or replace function public.media_gc_claim(p_limit integer default 50) returns table (public_id text)
language plpgsql security definer set search_path = public as $$
begin
  delete from public.media_gc g
  where g.next_try_at <= now()
    and (exists (select 1 from public.item_media m where m.path = g.public_id)
      or exists (select 1 from public.businesses b where b.logo_path = g.public_id or b.cover_path = g.public_id));
  return query
  update public.media_gc g set attempts = g.attempts + 1, next_try_at = now() + interval '10 minutes'
  where g.public_id in (select q.public_id from public.media_gc q where q.next_try_at <= now() order by q.next_try_at, q.queued_at limit greatest(1, least(coalesce(p_limit, 50), 100)) for update skip locked)
  returning g.public_id;
end $$;

create or replace function public.media_gc_done(p_ids text[]) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  delete from public.media_gc where public_id = any (p_ids);
  get diagnostics n = row_count;
  return n;
end $$;

-- A failed delete is retried with a growing pause: 2, 4, 8 ... minutes, never more than six hours.
create or replace function public.media_gc_fail(p_ids text[], p_error text) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  update public.media_gc g
  set next_try_at = now() + least(interval '6 hours', make_interval(mins => power(2, least(g.attempts, 10))::integer)),
      last_error = left(coalesce(p_error, ''), 300)
  where g.public_id = any (p_ids);
  get diagnostics n = row_count;
  return n;
end $$;

-- Queues files for deletion by hand (the migration script uses it for pictures it has copied and verified).
create or replace function public.media_gc_enqueue(p_ids text[], p_reason text) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  insert into public.media_gc (public_id, reason)
  select x, left(coalesce(p_reason, 'manual'), 60) from unnest(p_ids) as x where public.is_cloudinary_id(x)
  on conflict (public_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- Uploads older than the grace period (an hour) are settled: one that nothing points at is queued for deletion, one that
-- something points at is simply forgotten (the triggers above own its deletion from then on). Either way the row goes, which
-- keeps this table small however many photos are uploaded. Returns how many orphans were queued.
create or replace function public.media_sweep_orphans(p_grace interval default interval '1 hour') returns integer
language plpgsql security definer set search_path = public as $$
declare queued integer;
begin
  with put as (
    insert into public.media_gc (public_id, reason)
    select u.public_id, 'unattached_upload' from public.media_uploads u
    where u.created_at < now() - p_grace
      and not exists (select 1 from public.item_media m where m.path = u.public_id)
      and not exists (select 1 from public.businesses b where b.logo_path = u.public_id or b.cover_path = u.public_id)
    on conflict (public_id) do nothing
    returning 1
  )
  select count(*) into queued from put;
  delete from public.media_uploads where created_at < now() - p_grace;
  return queued;
end $$;

do $$
declare fn text;
begin
  foreach fn in array array[
    'media_register_upload(uuid, uuid, text, text)', 'media_confirm_upload(uuid, text)', 'media_gc_claim(integer)',
    'media_gc_done(text[])', 'media_gc_fail(text[], text)', 'media_gc_enqueue(text[], text)', 'media_sweep_orphans(interval)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', fn);
    execute format('grant execute on function public.%s to service_role', fn);
  end loop;
end $$;

$m_0047_cloudinary_media$),
    ('0048_utc_timezone', $m_0048_utc_timezone$
-- 0048_utc_timezone.sql
-- The time contract (see docs/timezones.md and shared/src/time.js):
--   * Every instant is stored as timestamptz. Postgres keeps it as UTC internally whatever the session zone is.
--   * Every instant leaves the API as ISO 8601 in UTC. The database never formats a time for a viewer; the
--     browser converts to the viewer's zone when it draws the value.
--   * Business calendar days (paid until, opening hours, exception dates, quiet hours) are read in
--     'Africa/Nairobi' with an EXPLICIT zone (public.nairobi_day and friends), so they do not depend on the session zone.
--
-- This migration closes the two remaining ways a session zone could leak into a result.

-- 1. New sessions start in UTC, so timestamptz serialises as "2026-10-25T04:51:00+00:00" for every client.
--    Wrapped so a host that does not let us change database settings does not fail the whole migration run.
do $$
begin
  execute format('alter database %I set timezone to %L', current_database(), 'UTC');
exception when insufficient_privilege then
  raise notice 'Could not set the database time zone. Set it to UTC by hand: alter database % set timezone to ''UTC'';', current_database();
end $$;

-- 2. PostgREST lets a client choose the session zone for a request ("Prefer: timezone=..."). Two functions read the
--    session zone without naming one, so pin it for the length of those calls:
--      admin_analytics  builds a day series with generate_series(date, date, interval) and then casts back with d::date.
--                       That round trip goes through the session zone and can land on the wrong day in a zone whose
--                       daylight saving starts at midnight.
--      log_search       keys its per-client rate limit on current_date.
--    Everything else that turns an instant into a day already names 'Africa/Nairobi'.
alter function public.admin_analytics(integer) set timezone to 'UTC';
alter function public.log_search(text) set timezone to 'UTC';

$m_0048_utc_timezone$),
    ('0049_media_purge_for_business', $m_0049_media_purge_for_business$
-- A seller who removes a photo should not have to wait for the cron job: the seller site asks seller-media-purge to delete that
-- seller's queued Cloudinary files right away. This is the same claim as media_gc_claim, limited to one business's own files
-- (every id starts with "<businessId>/"), so a seller can only ever trigger deletion of their own queue.

create or replace function public.media_gc_claim_for_business(p_business uuid, p_limit integer default 20) returns table (public_id text)
language plpgsql security definer set search_path = public as $$
begin
  delete from public.media_gc g
  where g.next_try_at <= now()
    and g.public_id like p_business::text || '/%'
    and (exists (select 1 from public.item_media m where m.path = g.public_id)
      or exists (select 1 from public.businesses b where b.logo_path = g.public_id or b.cover_path = g.public_id));
  return query
  update public.media_gc g set attempts = g.attempts + 1, next_try_at = now() + interval '10 minutes'
  where g.public_id in (
    select q.public_id from public.media_gc q
    where q.next_try_at <= now() and q.public_id like p_business::text || '/%'
    order by q.next_try_at, q.queued_at
    limit greatest(1, least(coalesce(p_limit, 20), 50))
    for update skip locked)
  returning g.public_id;
end $$;

revoke all on function public.media_gc_claim_for_business(uuid, integer) from public, anon, authenticated;
grant execute on function public.media_gc_claim_for_business(uuid, integer) to service_role;

$m_0049_media_purge_for_business$),
    ('0050_item_details', $m_0050_item_details$
create or replace function public.item_detail_text_ok(p jsonb, p_max integer) returns boolean
language sql immutable parallel safe as
$$ select coalesce(jsonb_typeof(p) = 'string' and btrim(p #>> '{}') <> '' and char_length(p #>> '{}') <= p_max, false) $$;

create or replace function public.item_highlights_valid(p jsonb) returns boolean
language plpgsql immutable parallel safe as $$
declare
  e jsonb;
  k text;
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 8 then return false; end if;
  for e in select jsonb_array_elements(p) loop
    if jsonb_typeof(e) <> 'object' then return false; end if;
    for k in select jsonb_object_keys(e) loop
      if k not in ('title', 'text') then return false; end if;
    end loop;
    if not public.item_detail_text_ok(e -> 'text', 200) then return false; end if;
    if e ? 'title' and not public.item_detail_text_ok(e -> 'title', 40) then return false; end if;
  end loop;
  return true;
end $$;

create or replace function public.item_specs_valid(p jsonb) returns boolean
language plpgsql immutable parallel safe as $$
declare
  e jsonb;
  k text;
  c_groups constant text[] := array['Features & Specs', 'Measurements', 'Additional details', 'User guide', 'Item details'];
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 20 then return false; end if;
  for e in select jsonb_array_elements(p) loop
    if jsonb_typeof(e) <> 'object' then return false; end if;
    for k in select jsonb_object_keys(e) loop
      if k not in ('group', 'label', 'value') then return false; end if;
    end loop;
    if jsonb_typeof(e -> 'group') is distinct from 'string' or (e ->> 'group') <> all (c_groups) then return false; end if;
    if not public.item_detail_text_ok(e -> 'label', 40) or not public.item_detail_text_ok(e -> 'value', 120) then return false; end if;
  end loop;
  return true;
end $$;

create or replace function public.item_includes_valid(p text[]) returns boolean
language plpgsql immutable parallel safe as $$
declare
  t text;
begin
  if p is null or cardinality(p) > 10 or coalesce(array_ndims(p), 1) <> 1 then return false; end if;
  foreach t in array p loop
    if t is null or btrim(t) = '' or char_length(t) > 80 then return false; end if;
  end loop;
  return true;
end $$;

revoke all on function public.item_detail_text_ok(jsonb, integer), public.item_highlights_valid(jsonb), public.item_specs_valid(jsonb), public.item_includes_valid(text[]) from public;
grant execute on function public.item_detail_text_ok(jsonb, integer), public.item_highlights_valid(jsonb), public.item_specs_valid(jsonb), public.item_includes_valid(text[]) to anon, authenticated, service_role;

alter table public.items
  add column if not exists brand text,
  add column if not exists short_description text,
  add column if not exists highlights jsonb not null default '[]'::jsonb,
  add column if not exists specs jsonb not null default '[]'::jsonb,
  add column if not exists includes text[] not null default '{}',
  add column if not exists terms text,
  add column if not exists pack_size text;

alter table public.items
  drop constraint if exists items_brand_len,
  drop constraint if exists items_short_description_len,
  drop constraint if exists items_highlights_shape,
  drop constraint if exists items_specs_shape,
  drop constraint if exists items_includes_shape,
  drop constraint if exists items_terms_len,
  drop constraint if exists items_pack_size_len,
  add constraint items_brand_len check (char_length(brand) <= 60),
  add constraint items_short_description_len check (char_length(short_description) <= 140),
  add constraint items_highlights_shape check (public.item_highlights_valid(highlights)),
  add constraint items_specs_shape check (public.item_specs_valid(specs)),
  add constraint items_includes_shape check (public.item_includes_valid(includes)),
  add constraint items_terms_len check (char_length(terms) <= 500),
  add constraint items_pack_size_len check (char_length(pack_size) <= 40);

-- New columns go last so the existing view definitions stay valid.
create or replace view public.public_items with (security_barrier = true) as
select
  i.id, i.business_id, i.name, i.description, i.section, i.price, i.price_max, i.price_type, i.unit,
  i.availability, i.sort, i.created_at,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at) from public.item_media m where m.item_id = i.id and m.kind = 'image'), '[]'::jsonb) as image_paths,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at) from public.item_media m where m.item_id = i.id and m.kind = 'video'), '[]'::jsonb) as video_paths,
  case when i.track_stock and i.show_stock_count and i.availability = 'limited_stock' and i.stock_count > 0 then i.stock_count end as stock_left,
  i.brand, i.short_description, i.highlights, i.specs, i.includes, i.terms, i.pack_size
from public.items i
join public.businesses b on b.id = i.business_id
where public.business_is_visible(b) and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
  and public.item_is_listed(i.availability);
revoke all on public.public_items from public;
grant select on public.public_items to anon, authenticated, service_role;

create or replace view public.public_businesses with (security_barrier = true) as
select
  b.id, b.slug, b.name, b.category_id, b.plan_key, b.verification_level, b.tagline, b.description,
  b.phone, b.whatsapp, b.socials, b.amenities, b.payment_methods, b.delivery_area,
  b.county, b.town, b.address, b.lat, b.lng, b.logo_path, b.cover_path, b.tags, b.hours, b.created_at,
  public.public_exceptions(b.exceptions) as exceptions,
  (select count(*)::integer from public.items i
    where i.business_id = b.id and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
      and public.item_is_listed(i.availability)) as product_count
from public.businesses b
where public.business_is_visible(b);
revoke all on public.public_businesses from public;
grant select on public.public_businesses to anon, authenticated, service_role;

create or replace function public.log_item_changes() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  o jsonb := to_jsonb(old);
  n jsonb := to_jsonb(new);
  f text;
begin
  foreach f in array array['name','price','price_max','price_type','unit','sale_price','availability','stock_count','visible','hidden_by_admin',
                           'brand','short_description','highlights','specs','includes','terms','pack_size'] loop
    if o -> f is distinct from n -> f then
      insert into public.item_history (item_id, business_id, field, old_value, new_value, changed_by, actor_role)
      values (new.id, new.business_id, f, o ->> f, n ->> f, auth.uid(), public.actor_role());
    end if;
  end loop;
  return null;
end $$;

create or replace function public.seller_duplicate_item(p_id uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_src public.items;
  v_new uuid;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into v_src from public.items where id = p_id and business_id = v_id and not removed_by_admin;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  insert into public.items (business_id, name, description, section, price, price_max, price_type, unit, sale_price, availability, stock_count,
    track_stock, low_stock_threshold, show_stock_count, season, tags, badge, variants, visible, draft, sort,
    brand, short_description, highlights, specs, includes, terms, pack_size)
  values (v_id, left(v_src.name, 111) || ' (copy)', v_src.description, v_src.section, v_src.price, v_src.price_max, v_src.price_type, v_src.unit,
    v_src.sale_price, v_src.availability, v_src.stock_count, v_src.track_stock, v_src.low_stock_threshold, v_src.show_stock_count, v_src.season,
    v_src.tags, v_src.badge, v_src.variants, false, true, v_src.sort + 1,
    v_src.brand, v_src.short_description, v_src.highlights, v_src.specs, v_src.includes, v_src.terms, v_src.pack_size)
  returning id into v_new;
  return v_new;
end $$;

create or replace function public.seller_save_item(p_id uuid, p_fields jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_old public.items;
  v_name text := btrim(coalesce(f ->> 'name', ''));
  v_desc text := nullif(btrim(coalesce(f ->> 'description', '')), '');
  v_section text := nullif(btrim(coalesce(f ->> 'section', '')), '');
  v_unit text := nullif(btrim(coalesce(f ->> 'unit', '')), '');
  v_type text := f ->> 'price_type';
  v_avail text := f ->> 'availability';
  v_old_item public.items;
  v_track boolean;
  v_count integer;
  v_low integer;
  v_show boolean;
  v_price numeric;
  v_max numeric;
  v_sale numeric;
  v_sort integer;
  v_new uuid;
  v_brand text;
  v_short text;
  v_terms text;
  v_pack text;
  v_hl jsonb;
  v_specs jsonb;
  v_inc text[];
  c_money constant text := '^\d{1,10}(\.\d{1,2})?$';
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  if char_length(v_name) < 2 or char_length(v_name) > 120 then raise exception 'invalid_name' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_desc, '')) > 2000 or char_length(coalesce(v_section, '')) > 60 or char_length(coalesce(v_unit, '')) > 30 then
    raise exception 'invalid_text' using errcode = 'P0001';
  end if;
  if v_avail is null or v_avail not in ('available','limited_stock','out_of_stock','unavailable','by_appointment') then
    raise exception 'invalid_availability' using errcode = 'P0001';
  end if;
  if v_type is null or v_type not in ('fixed','from','range','free','contact') then raise exception 'invalid_price' using errcode = 'P0001'; end if;

  if p_id is not null then
    select * into v_old_item from public.items i where i.id = p_id and i.business_id = v_id;
  end if;
  if (f ? 'low_stock_threshold' and coalesce(f ->> 'low_stock_threshold', '') !~ '^\d{1,4}$')
     or (f ? 'track_stock' and coalesce(f ->> 'track_stock', '') not in ('true', 'false'))
     or (f ? 'show_stock_count' and coalesce(f ->> 'show_stock_count', '') not in ('true', 'false')) then
    raise exception 'invalid_stock' using errcode = 'P0001';
  end if;
  v_track := case when f ? 'track_stock' then coalesce((f ->> 'track_stock')::boolean, false) else coalesce(v_old_item.track_stock, false) end;
  v_low := case when f ? 'low_stock_threshold' then (f ->> 'low_stock_threshold')::integer else coalesce(v_old_item.low_stock_threshold, 3) end;
  v_show := case when f ? 'show_stock_count' then coalesce((f ->> 'show_stock_count')::boolean, false) else coalesce(v_old_item.show_stock_count, false) end;
  if f ? 'stock_count' and coalesce(f ->> 'stock_count', '') <> '' then
    if (f ->> 'stock_count') !~ '^\d{1,6}$' then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
    v_count := (f ->> 'stock_count')::integer;
  elsif f ? 'stock_count' then
    v_count := null;
  else
    v_count := v_old_item.stock_count;
  end if;
  if v_low is null or v_low < 0 or v_low > 9999 then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
  if v_track and v_count is null then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
  if v_track then v_avail := 'available'; end if;

  if (f ? 'brand' and jsonb_typeof(f -> 'brand') not in ('string', 'null'))
     or (f ? 'short_description' and jsonb_typeof(f -> 'short_description') not in ('string', 'null'))
     or (f ? 'terms' and jsonb_typeof(f -> 'terms') not in ('string', 'null'))
     or (f ? 'pack_size' and jsonb_typeof(f -> 'pack_size') not in ('string', 'null'))
     or (f ? 'highlights' and jsonb_typeof(f -> 'highlights') not in ('array', 'null'))
     or (f ? 'specs' and jsonb_typeof(f -> 'specs') not in ('array', 'null'))
     or (f ? 'includes' and jsonb_typeof(f -> 'includes') not in ('array', 'null')) then
    raise exception 'invalid_details' using errcode = 'P0001';
  end if;
  v_brand := case when f ? 'brand' then nullif(btrim(coalesce(f ->> 'brand', '')), '') else v_old_item.brand end;
  v_short := case when f ? 'short_description' then nullif(btrim(coalesce(f ->> 'short_description', '')), '') else v_old_item.short_description end;
  v_terms := case when f ? 'terms' then nullif(btrim(coalesce(f ->> 'terms', '')), '') else v_old_item.terms end;
  v_pack := case when f ? 'pack_size' then nullif(btrim(coalesce(f ->> 'pack_size', '')), '') else v_old_item.pack_size end;
  v_hl := case when f ? 'highlights' then coalesce(nullif(f -> 'highlights', 'null'::jsonb), '[]'::jsonb) else coalesce(v_old_item.highlights, '[]'::jsonb) end;
  v_specs := case when f ? 'specs' then coalesce(nullif(f -> 'specs', 'null'::jsonb), '[]'::jsonb) else coalesce(v_old_item.specs, '[]'::jsonb) end;
  if f ? 'specs' then
    select coalesce(jsonb_agg(
      case when jsonb_typeof(x.e) = 'object' and (not x.e ? 'group' or jsonb_typeof(x.e -> 'group') = 'null')
        then x.e || jsonb_build_object('group', 'Features & Specs') else x.e end
      order by x.n), '[]'::jsonb) into v_specs
      from jsonb_array_elements(v_specs) with ordinality as x(e, n);
  end if;
  if f ? 'highlights' then
    select coalesce(jsonb_agg(
      case when jsonb_typeof(x.e) = 'object' and (jsonb_typeof(x.e -> 'title') = 'null' or btrim(coalesce(x.e ->> 'title', 'x')) = '') then x.e - 'title' else x.e end
      order by x.n), '[]'::jsonb) into v_hl
      from jsonb_array_elements(v_hl) with ordinality as x(e, n);
  end if;
  if f ? 'includes' then
    if exists (select 1 from jsonb_array_elements(case when jsonb_typeof(f -> 'includes') = 'array' then f -> 'includes' else '[]'::jsonb end) e
               where jsonb_typeof(e) <> 'string') then
      raise exception 'invalid_details' using errcode = 'P0001';
    end if;
    select coalesce(array_agg(btrim(x.t) order by x.n), '{}') into v_inc
      from jsonb_array_elements_text(case when jsonb_typeof(f -> 'includes') = 'array' then f -> 'includes' else '[]'::jsonb end) with ordinality as x(t, n);
  else
    v_inc := coalesce(v_old_item.includes, '{}');
  end if;
  if char_length(coalesce(v_brand, '')) > 60 or char_length(coalesce(v_short, '')) > 140
     or char_length(coalesce(v_terms, '')) > 500 or char_length(coalesce(v_pack, '')) > 40
     or not public.item_highlights_valid(v_hl) or not public.item_specs_valid(v_specs) or not public.item_includes_valid(v_inc) then
    raise exception 'invalid_details' using errcode = 'P0001';
  end if;

  if v_type in ('fixed','from','range') then
    if coalesce(f ->> 'price', '') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    v_price := (f ->> 'price')::numeric;
    if v_type = 'range' then
      if coalesce(f ->> 'price_max', '') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
      v_max := (f ->> 'price_max')::numeric;
      if v_max < v_price then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    end if;
    if coalesce(f ->> 'sale_price', '') <> '' then
      if (f ->> 'sale_price') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
      v_sale := (f ->> 'sale_price')::numeric;
      if v_sale >= v_price then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    end if;
  end if;

  if p_id is null then
    select coalesce(max(sort), 0) + 1 into v_sort from public.items where business_id = v_id;
    insert into public.items (business_id, name, description, section, price_type, price, price_max, sale_price, unit, availability, track_stock, stock_count, low_stock_threshold, show_stock_count, visible, draft, sort,
      brand, short_description, highlights, specs, includes, terms, pack_size)
    values (v_id, v_name, v_desc, v_section, v_type, v_price, v_max, v_sale, v_unit, v_avail, v_track, v_count, v_low, v_show, false, true, v_sort,
      v_brand, v_short, v_hl, v_specs, v_inc, v_terms, v_pack)
    returning id into v_new;
    return v_new;
  end if;

  select * into v_old from public.items i where i.id = p_id and i.business_id = v_id and not i.removed_by_admin for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;

  if (v_old.price, v_old.price_max, v_old.price_type, v_old.sale_price) is distinct from (v_price, v_max, v_type, v_sale)
     and exists (select 1 from public.flash_sales s where s.item_id = p_id and s.status in ('scheduled','live')) then
    raise exception 'item_in_flash_sale' using errcode = 'P0001';
  end if;

  update public.items set
    name = v_name, description = v_desc, section = v_section, price_type = v_type, price = v_price, price_max = v_max,
    sale_price = v_sale, unit = v_unit, availability = v_avail,
    track_stock = v_track, stock_count = v_count, low_stock_threshold = v_low, show_stock_count = v_show,
    brand = v_brand, short_description = v_short, highlights = v_hl, specs = v_specs, includes = v_inc, terms = v_terms, pack_size = v_pack
  where id = p_id;
  return p_id;
end $$;

$m_0050_item_details$),
    ('0051_offers_skip_unlisted', $m_0051_offers_skip_unlisted$
-- 004601_store_offers rebuilt public_offers from the 0045 text and lost the sold-out rule that 004600_item_availability added.
create or replace view public.public_offers with (security_barrier = true) as
select
  o.id, o.business_id, o.title, o.description, o.starts_at, o.ends_at, o.created_at,
  o.kind, o.config, o.conditions, o.chip_text, o.code, o.terms,
  p.items,
  o.scope
from public.offers o
join public.businesses b on b.id = o.business_id
cross join lateral (
  select
    coalesce(jsonb_agg(jsonb_build_object('item_id', oi.item_id, 'role', oi.role) order by oi.sort, oi.role, oi.item_id), '[]'::jsonb) as items,
    count(*) filter (where oi.role = 'main') as mains,
    count(*) filter (where oi.role = 'with') as withs
  from public.offer_items oi
  join public.items i on i.id = oi.item_id
  where oi.offer_id = o.id and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
    and public.item_is_listed(i.availability)
) p
where public.business_is_visible(b)
  and o.kind is not null
  and o.active
  and not o.hidden_by_admin
  and not o.removed_by_admin
  and (o.starts_at is null or o.starts_at <= now())
  and (o.ends_at is null or o.ends_at > now())
  and (
    o.scope = 'store'
    or ((p.mains + p.withs) > 0 and (o.kind <> 'bundle' or (p.mains > 0 and p.withs > 0)))
  );
revoke all on public.public_offers from public;
grant select on public.public_offers to anon, authenticated, service_role;

$m_0051_offers_skip_unlisted$),
    ('0052_import_item_details', $m_0052_import_item_details$
-- seller_import_items (0017) also takes the optional brand, short_description, pack_size, terms and includes of each row.
-- A row without them is stored exactly as before. A bad value stops the whole import with invalid_details.
create or replace function public.seller_import_items(p_rows jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_b public.businesses;
  r jsonb;
  v_sort integer;
  v_n integer := 0;
  v_tags text[];
  v_brand text;
  v_short text;
  v_pack text;
  v_terms text;
  v_inc text[];
  k text;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into v_b from public.businesses where id = v_id;
  if v_b.plan_key <> 'premium' then raise exception 'premium_required' using errcode = 'P0001'; end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'no_rows' using errcode = 'P0001'; end if;
  if jsonb_array_length(p_rows) > 500 then raise exception 'too_many_rows' using errcode = 'P0001'; end if;
  select coalesce(max(sort), 0) into v_sort from public.items where business_id = v_id;
  for r in select * from jsonb_array_elements(p_rows) loop
    if left(coalesce(r ->> 'name', ''), 1) in ('=','+','-','@') or left(coalesce(r ->> 'section', ''), 1) in ('=','+','-','@')
       or left(coalesce(r ->> 'unit', ''), 1) in ('=','+','-','@') then
      raise exception 'formula_rejected' using errcode = 'P0001';
    end if;
    foreach k in array array['brand', 'short_description', 'pack_size', 'terms'] loop
      if r ? k and jsonb_typeof(r -> k) not in ('string', 'null') then raise exception 'invalid_details' using errcode = 'P0001'; end if;
      if left(coalesce(r ->> k, ''), 1) in ('=','+','-','@') then raise exception 'formula_rejected' using errcode = 'P0001'; end if;
    end loop;
    if r ? 'includes' and jsonb_typeof(r -> 'includes') not in ('array', 'null') then raise exception 'invalid_details' using errcode = 'P0001'; end if;
    if exists (select 1 from jsonb_array_elements(case when jsonb_typeof(r -> 'includes') = 'array' then r -> 'includes' else '[]'::jsonb end) e where jsonb_typeof(e) <> 'string') then
      raise exception 'invalid_details' using errcode = 'P0001';
    end if;
    if exists (select 1 from jsonb_array_elements_text(case when jsonb_typeof(r -> 'includes') = 'array' then r -> 'includes' else '[]'::jsonb end) e
               where left(btrim(e), 1) in ('=','+','-','@')) then
      raise exception 'formula_rejected' using errcode = 'P0001';
    end if;

    v_brand := nullif(btrim(coalesce(r ->> 'brand', '')), '');
    v_short := nullif(btrim(coalesce(r ->> 'short_description', '')), '');
    v_pack := nullif(btrim(coalesce(r ->> 'pack_size', '')), '');
    v_terms := nullif(btrim(coalesce(r ->> 'terms', '')), '');
    select coalesce(array_agg(btrim(x.t) order by x.n) filter (where btrim(x.t) <> ''), '{}') into v_inc
      from jsonb_array_elements_text(case when jsonb_typeof(r -> 'includes') = 'array' then r -> 'includes' else '[]'::jsonb end) with ordinality as x(t, n);
    if char_length(coalesce(v_brand, '')) > 60 or char_length(coalesce(v_short, '')) > 140
       or char_length(coalesce(v_pack, '')) > 40 or char_length(coalesce(v_terms, '')) > 500
       or not public.item_includes_valid(v_inc) then
      raise exception 'invalid_details' using errcode = 'P0001';
    end if;

    select coalesce(array_agg(t), '{}') into v_tags from jsonb_array_elements_text(coalesce(r -> 'tags', '[]'::jsonb)) as t;
    v_sort := v_sort + 1;
    insert into public.items (business_id, name, section, price, price_max, price_type, unit, availability, tags, visible, draft, sort,
      brand, short_description, pack_size, terms, includes)
    values (v_id, btrim(r ->> 'name'), nullif(btrim(coalesce(r ->> 'section', '')), ''), (r ->> 'price')::numeric, (r ->> 'price_max')::numeric,
      coalesce(r ->> 'price_type', 'fixed'), nullif(btrim(coalesce(r ->> 'unit', '')), ''), coalesce(r ->> 'availability', 'available'), v_tags, false, true, v_sort,
      v_brand, v_short, v_pack, v_terms, v_inc);
    v_n := v_n + 1;
  end loop;
  perform public.write_audit(v_id, 'items_imported', 'item', null, jsonb_build_object('count', v_n));
  return jsonb_build_object('created', v_n);
end $$;

$m_0052_import_item_details$),
    ('0053_reorder_item_photos', $m_0053_reorder_item_photos$
create or replace function public.seller_reorder_item_photos(p_item uuid, p_paths text[]) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_n integer;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id and not i.removed_by_admin) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  if p_paths is null or cardinality(p_paths) = 0 or cardinality(p_paths) > 50 then raise exception 'no_items' using errcode = 'P0001'; end if;
  update public.item_media m set sort = o.pos
    from (select u.path, u.ord::integer - 1 as pos from unnest(p_paths) with ordinality as u(path, ord)) o
    where m.item_id = p_item and m.business_id = v_id and m.kind = 'image' and m.path = o.path and m.sort <> o.pos;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

revoke all on function public.seller_reorder_item_photos(uuid, text[]) from public, anon;
grant execute on function public.seller_reorder_item_photos(uuid, text[]) to authenticated, service_role;

$m_0053_reorder_item_photos$),
    ('0054_business_timezone', $m_0054_business_timezone$
-- Each shop keeps its opening hours in its own time zone (an IANA name such as Asia/Kolkata). Until now every shop was
-- read as Africa/Nairobi. Existing shops keep that value, so nothing changes for them.
--
--   * businesses.timezone: validated against the database's own zone list on every insert or change of the value.
--   * hours_open_in(hours, exceptions, at, tz): hours_open for any zone. hours_open stays and means Africa/Nairobi.
--   * public_businesses exposes timezone (last column, so the view can be replaced in place).
--   * public_flash_sales, browse_snapshot and products_snapshot carry the shop's timezone next to its hours.
--   * search_businesses reads "open now" and "is_open" in each shop's zone instead of Nairobi's.

alter table public.businesses add column if not exists timezone text not null default 'Africa/Nairobi';

create or replace function public.businesses_check_timezone() returns trigger
language plpgsql as $$
begin
  if new.timezone is null or not exists (select 1 from pg_catalog.pg_timezone_names where name = new.timezone) then
    raise exception 'unknown time zone: %', new.timezone using errcode = '22023';
  end if;
  return new;
end $$;

drop trigger if exists businesses_check_timezone on public.businesses;
create trigger businesses_check_timezone before insert or update of timezone on public.businesses
  for each row execute function public.businesses_check_timezone();

create or replace function public.hours_open_in(p_hours jsonb, p_exceptions jsonb, p_at timestamptz, p_tz text) returns boolean
language plpgsql stable as $$
declare
  v_local timestamp := p_at at time zone coalesce(nullif(p_tz, ''), 'Africa/Nairobi');
  v_date date := v_local::date;
  v_min integer := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_iv jsonb;
  v_start integer;
  v_end integer;
begin
  for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date)) loop
    v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
    v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
    if v_end > v_start then
      if v_min >= v_start and v_min < v_end then return true; end if;
    elsif v_min >= v_start then
      return true;
    end if;
  end loop;
  if coalesce(public.hours_exception_on(p_exceptions, v_date) ->> 'kind', '') <> 'closed' then
    for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date - 1)) loop
      v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
      v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
      if v_end <= v_start and v_end > 0 and v_min < v_end then return true; end if;
    end loop;
  end if;
  return false;
end $$;

grant execute on function public.hours_open_in(jsonb, jsonb, timestamptz, text) to anon, authenticated, service_role;

create or replace view public.public_businesses with (security_barrier = true) as
select
  b.id, b.slug, b.name, b.category_id, b.plan_key, b.verification_level, b.tagline, b.description,
  b.phone, b.whatsapp, b.socials, b.amenities, b.payment_methods, b.delivery_area,
  b.county, b.town, b.address, b.lat, b.lng, b.logo_path, b.cover_path, b.tags, b.hours, b.created_at,
  public.public_exceptions(b.exceptions) as exceptions,
  (select count(*)::integer from public.items i
    where i.business_id = b.id and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
      and public.item_is_listed(i.availability)) as product_count,
  b.timezone
from public.businesses b
where public.business_is_visible(b);
revoke all on public.public_businesses from public;
grant select on public.public_businesses to anon, authenticated, service_role;

-- Patch search_businesses in place: two literal replacements, and the migration fails loudly if either text is not found
-- (rather than silently leaving Nairobi's clock in the search).
do $$
declare
  v_oid oid;
  v_def text;
  v_new text;
begin
  select p.oid into strict v_oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'search_businesses';
  v_def := pg_get_functiondef(v_oid);
  if position('hours_open_in(' in v_def) > 0 then return; end if; -- already patched: the migration can be re-run
  v_new := replace(v_def,
    'public.hours_open(pb.hours, pb.exceptions, v_now)',
    'public.hours_open_in(pb.hours, pb.exceptions, v_now, b.timezone)');
  if v_new = v_def then raise exception 'search_businesses: open-now clause not found'; end if;
  v_def := v_new;
  v_new := replace(v_def,
    'public.hours_open(hours, exceptions, v_now)',
    'public.hours_open_in(hours, exceptions, v_now, (select bb.timezone from public.businesses bb where bb.id = ranked.id))');
  if v_new = v_def then raise exception 'search_businesses: is_open clause not found'; end if;
  execute v_new;
end $$;

-- Flash sale cards show an open/closed chip from the shop's hours, so the view carries the shop's zone too (last column).
create or replace view public.public_flash_sales with (security_barrier = true) as
select
  s.id, s.business_id, s.item_id, s.headline, s.starts_at, s.ends_at,
  s.discount_type, s.discount_value, s.variant_overrides, s.quantity_note,
  i.name as item_name, i.description as item_description, i.section as item_section,
  i.price_type as item_price_type, i.unit as item_unit, i.availability as item_availability,
  (select m.path from public.item_media m where m.item_id = i.id and m.kind = 'image' order by m.sort, m.created_at limit 1) as item_image_path,
  i.price as regular_price,
  d.p as sale_price,
  i.price - d.p as savings,
  case when i.price > 0 then round((i.price - d.p) / i.price * 100) else 0 end as discount_percent,
  b.slug as business_slug, b.name as business_name, b.category_id as business_category_id,
  b.town as business_town, b.county as business_county, b.lat as business_lat, b.lng as business_lng,
  b.phone as business_phone, b.whatsapp as business_whatsapp, b.logo_path as business_logo_path,
  b.verification_level as business_verification_level, b.hours as business_hours,
  now() as server_now,
  floor(extract(epoch from (s.ends_at - now())) * 1000)::bigint as remaining_ms,
  public.public_exceptions(b.exceptions) as business_exceptions,
  b.timezone as business_timezone
from public.flash_sales s
join public.items i on i.id = s.item_id
join public.businesses b on b.id = s.business_id
cross join lateral (select public.flash_discounted_price(s.discount_type, s.discount_value, i.price) as p) d
where s.status in ('scheduled','live')
  and now() >= s.starts_at
  and now() < s.ends_at
  and public.business_is_visible(b)
  and i.visible and not i.hidden_by_admin and not i.removed_by_admin
  and i.availability not in ('out_of_stock','unavailable')
  and i.price is not null and i.price_type in ('fixed','from')
  and d.p > 0 and d.p < i.price;
revoke all on public.public_flash_sales from public;
grant select on public.public_flash_sales to anon, authenticated, service_role;

-- The two snapshot functions list the business columns they return. Add timezone by literal replacement; fail loudly
-- if the text is not found, so a snapshot can never silently go without it.
do $$
declare
  v_def text;
  v_new text;
begin
  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'browse_snapshot';
  if position('exceptions, timezone' in v_def) = 0 then
    v_new := replace(v_def, 'tags, hours, created_at, exceptions', 'tags, hours, created_at, exceptions, timezone');
    if v_new = v_def then raise exception 'browse_snapshot: business column list not found'; end if;
    execute v_new;
  end if;

  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'products_snapshot';
  if position('exceptions, timezone' in v_def) = 0 then
    v_new := replace(v_def, 'category_id, town, county, hours, exceptions', 'category_id, town, county, hours, exceptions, timezone');
    if v_new = v_def then raise exception 'products_snapshot: business column list not found'; end if;
    execute v_new;
  end if;
end $$;

-- A seller sets the zone their shop's clock is in. Hours and exceptions are wall-clock times in this zone, so changing it
-- moves them with the shop; it is audited like any profile change.
create or replace function public.seller_set_timezone(p_timezone text) returns text
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_tz text := btrim(coalesce(p_timezone, ''));
begin
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  perform public.assert_seller_active();
  if v_tz = '' or not exists (select 1 from pg_catalog.pg_timezone_names where name = v_tz) then
    raise exception 'invalid_timezone' using errcode = '22023';
  end if;
  update public.businesses set timezone = v_tz where id = v_id;
  perform public.write_audit(v_id, 'timezone_changed', 'business', v_id::text, jsonb_build_object('timezone', v_tz));
  return v_tz;
end $$;
revoke all on function public.seller_set_timezone(text) from public, anon;
grant execute on function public.seller_set_timezone(text) to authenticated, service_role;

$m_0054_business_timezone$),
    ('0055_reorder_item_photos_once', $m_0055_reorder_item_photos_once$
create or replace function public.seller_reorder_item_photos(p_item uuid, p_paths text[]) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_n integer;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id and not i.removed_by_admin) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  if p_paths is null or cardinality(p_paths) = 0 or cardinality(p_paths) > 50 then raise exception 'no_items' using errcode = 'P0001'; end if;
  update public.item_media m set sort = o.pos
    from (select u.path, (row_number() over (order by min(u.ord)) - 1)::integer as pos from unnest(p_paths) with ordinality as u(path, ord) group by u.path) o
    where m.item_id = p_item and m.business_id = v_id and m.kind = 'image' and m.path = o.path and m.sort <> o.pos;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

revoke all on function public.seller_reorder_item_photos(uuid, text[]) from public, anon;
grant execute on function public.seller_reorder_item_photos(uuid, text[]) to authenticated, service_role;

$m_0055_reorder_item_photos_once$),
    ('0056_import_skips_bad_details', $m_0056_import_skips_bad_details$
-- seller_import_items (0052) now also takes the optional highlights and specs of each row, and a row whose details are not valid
-- is skipped and reported instead of stopping the whole import. The good rows are still created.
--
--   returns { "created": <n>, "skipped": [ { "row": <spreadsheet row>, "error": "invalid_details" | "formula_rejected" } ] }
--
-- "row" is the row number the seller app sends with each row (the line in their file); without it, the position in p_rows.
-- Only the optional details are skipped. A bad name, section, unit, price or price type, a missing Premium plan, too many rows
-- and the plan's item limit still refuse the whole import, as before, and a refused import creates nothing.
create or replace function public.seller_import_items(p_rows jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_b public.businesses;
  r jsonb;
  v_pos integer := 0;
  v_row integer;
  v_sort integer;
  v_n integer := 0;
  v_tags text[];
  v_brand text;
  v_short text;
  v_pack text;
  v_terms text;
  v_inc text[];
  v_hl jsonb;
  v_specs jsonb;
  v_err text;
  v_skipped jsonb := '[]'::jsonb;
  k text;
  c_formula constant text[] := array['=','+','-','@'];
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into v_b from public.businesses where id = v_id;
  if v_b.plan_key <> 'premium' then raise exception 'premium_required' using errcode = 'P0001'; end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'no_rows' using errcode = 'P0001'; end if;
  if jsonb_array_length(p_rows) > 500 then raise exception 'too_many_rows' using errcode = 'P0001'; end if;
  select coalesce(max(sort), 0) into v_sort from public.items where business_id = v_id;
  for r in select * from jsonb_array_elements(p_rows) loop
    v_pos := v_pos + 1;
    v_row := case when coalesce(r ->> 'row', '') ~ '^\d{1,6}$' then (r ->> 'row')::integer else v_pos end;

    if left(coalesce(r ->> 'name', ''), 1) = any (c_formula) or left(coalesce(r ->> 'section', ''), 1) = any (c_formula)
       or left(coalesce(r ->> 'unit', ''), 1) = any (c_formula) then
      raise exception 'formula_rejected' using errcode = 'P0001';
    end if;

    -- The optional details. A problem here marks the row as skipped; v_err keeps the first one found.
    v_err := null;
    foreach k in array array['brand', 'short_description', 'pack_size', 'terms'] loop
      if r ? k and jsonb_typeof(r -> k) not in ('string', 'null') then v_err := coalesce(v_err, 'invalid_details'); end if;
      if left(coalesce(r ->> k, ''), 1) = any (c_formula) then v_err := coalesce(v_err, 'formula_rejected'); end if;
    end loop;
    if (r ? 'includes' and jsonb_typeof(r -> 'includes') not in ('array', 'null'))
       or (r ? 'highlights' and jsonb_typeof(r -> 'highlights') not in ('array', 'null'))
       or (r ? 'specs' and jsonb_typeof(r -> 'specs') not in ('array', 'null')) then
      v_err := coalesce(v_err, 'invalid_details');
    end if;

    v_brand := nullif(btrim(coalesce(r ->> 'brand', '')), '');
    v_short := nullif(btrim(coalesce(r ->> 'short_description', '')), '');
    v_pack := nullif(btrim(coalesce(r ->> 'pack_size', '')), '');
    v_terms := nullif(btrim(coalesce(r ->> 'terms', '')), '');
    v_inc := '{}';
    v_hl := '[]'::jsonb;
    v_specs := '[]'::jsonb;

    if v_err is null then
      if exists (select 1 from jsonb_array_elements(case when jsonb_typeof(r -> 'includes') = 'array' then r -> 'includes' else '[]'::jsonb end) e where jsonb_typeof(e) <> 'string') then
        v_err := 'invalid_details';
      else
        select coalesce(array_agg(btrim(x.t) order by x.n) filter (where btrim(x.t) <> ''), '{}') into v_inc
          from jsonb_array_elements_text(case when jsonb_typeof(r -> 'includes') = 'array' then r -> 'includes' else '[]'::jsonb end) with ordinality as x(t, n);
        if exists (select 1 from unnest(v_inc) e where left(e, 1) = any (c_formula)) then v_err := 'formula_rejected'; end if;
      end if;
    end if;

    -- Highlights and specs are normalised as seller_save_item does: a missing group becomes "Features & Specs", a blank lead is dropped.
    if v_err is null and jsonb_typeof(r -> 'highlights') = 'array' then
      select coalesce(jsonb_agg(
        case when jsonb_typeof(x.e) = 'object' and (jsonb_typeof(x.e -> 'title') = 'null' or btrim(coalesce(x.e ->> 'title', 'x')) = '') then x.e - 'title' else x.e end
        order by x.n), '[]'::jsonb) into v_hl
        from jsonb_array_elements(r -> 'highlights') with ordinality as x(e, n);
      if exists (select 1 from jsonb_array_elements(v_hl) e where left(coalesce(e ->> 'text', ''), 1) = any (c_formula) or left(coalesce(e ->> 'title', ''), 1) = any (c_formula)) then
        v_err := 'formula_rejected';
      end if;
    end if;
    if v_err is null and jsonb_typeof(r -> 'specs') = 'array' then
      select coalesce(jsonb_agg(
        case when jsonb_typeof(x.e) = 'object' and (not x.e ? 'group' or jsonb_typeof(x.e -> 'group') = 'null')
          then x.e || jsonb_build_object('group', 'Features & Specs') else x.e end
        order by x.n), '[]'::jsonb) into v_specs
        from jsonb_array_elements(r -> 'specs') with ordinality as x(e, n);
      if exists (select 1 from jsonb_array_elements(v_specs) e where left(coalesce(e ->> 'label', ''), 1) = any (c_formula) or left(coalesce(e ->> 'value', ''), 1) = any (c_formula)) then
        v_err := 'formula_rejected';
      end if;
    end if;

    if v_err is null and (char_length(coalesce(v_brand, '')) > 60 or char_length(coalesce(v_short, '')) > 140
       or char_length(coalesce(v_pack, '')) > 40 or char_length(coalesce(v_terms, '')) > 500
       or not public.item_includes_valid(v_inc) or not public.item_highlights_valid(v_hl) or not public.item_specs_valid(v_specs)) then
      v_err := 'invalid_details';
    end if;

    if v_err is not null then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('row', v_row, 'error', v_err));
      continue;
    end if;

    select coalesce(array_agg(t), '{}') into v_tags from jsonb_array_elements_text(coalesce(r -> 'tags', '[]'::jsonb)) as t;
    v_sort := v_sort + 1;
    insert into public.items (business_id, name, section, price, price_max, price_type, unit, availability, tags, visible, draft, sort,
      brand, short_description, pack_size, terms, includes, highlights, specs)
    values (v_id, btrim(r ->> 'name'), nullif(btrim(coalesce(r ->> 'section', '')), ''), (r ->> 'price')::numeric, (r ->> 'price_max')::numeric,
      coalesce(r ->> 'price_type', 'fixed'), nullif(btrim(coalesce(r ->> 'unit', '')), ''), coalesce(r ->> 'availability', 'available'), v_tags, false, true, v_sort,
      v_brand, v_short, v_pack, v_terms, v_inc, v_hl, v_specs);
    v_n := v_n + 1;
  end loop;
  perform public.write_audit(v_id, 'items_imported', 'item', null, jsonb_build_object('count', v_n));
  return jsonb_build_object('created', v_n, 'skipped', v_skipped);
end $$;

$m_0056_import_skips_bad_details$),
    ('0057_item_media_sequence', $m_0057_item_media_sequence$
-- 0057_item_media_sequence.sql
-- Photos and videos of an item share ONE ordered sequence (item_media.sort, then created_at, then id).
--
--   * The first kind='image' row in that sequence is the cover. A video can sit anywhere in the sequence but is never the cover;
--     nothing stores the cover, it is always derived, so it cannot drift.
--   * seller_reorder_item_media(item, paths) orders the WHOLE sequence. It refuses a list that is not exactly the item's media.
--   * seller_item_media(item) reads the sequence and the plan limits ({photos:{used,max}, videos:{used,max}}) in one call.
--   * seller_reorder_item_photos (0053/0055) still works and is DEPRECATED: it reorders photos among the slots photos already
--     occupy, so videos keep their place in the sequence.
--   * attach_item_media appends at max(sort)+1. It used count(*), which collides with an existing row after a delete.
--   * public_items gains `media` (the merged sequence); image_paths and video_paths stay, in the same order.
--   * products_snapshot carries video_paths so a grid card no longer drops an item's videos.
--   * Videos live in the Supabase bucket, so an upload that is signed but never finalized, or a video that is deleted, can leave
--     a file behind. Signed video uploads are now recorded in media_uploads, and the sweep and the delete trigger queue the file
--     in media_gc; the media-gc function deletes it from storage.
-- Idempotent: every statement can be run twice.

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. Video paths in the upload and cleanup tables
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.is_storage_video_path(p text) returns boolean
language sql immutable as $$
  select p is not null
    and char_length(p) <= 300
    and p ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(mp4|webm)$'
$$;

do $$
declare c record;
begin
  for c in
    select conname from pg_constraint
    where conrelid = 'public.media_uploads'::regclass and contype = 'c'
      and (pg_get_constraintdef(oid) ~ 'is_cloudinary_id|item_photo|purpose|is_storage_video_path')
  loop
    execute format('alter table public.media_uploads drop constraint %I', c.conname);
  end loop;
end $$;

alter table public.media_uploads
  add constraint media_uploads_purpose_ck check (purpose in ('item_photo', 'item_video', 'logo', 'cover')),
  add constraint media_uploads_id_ck check (
    case when purpose = 'item_video' then public.is_storage_video_path(public_id) else public.is_cloudinary_id(public_id) end),
  add constraint media_uploads_item_ck check ((purpose in ('item_photo', 'item_video')) = (item_id is not null));

create or replace function public.media_register_upload(p_business uuid, p_item uuid, p_purpose text, p_public_id text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_purpose not in ('item_photo', 'item_video', 'logo', 'cover') then raise exception 'invalid_purpose'; end if;
  if p_purpose = 'item_video' then
    if p_item is null or not exists (select 1 from public.items i where i.id = p_item and i.business_id = p_business) then raise exception 'item_not_found'; end if;
    if not public.is_storage_video_path(p_public_id) or p_public_id not like p_business::text || '/' || p_item::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
  else
    if not public.is_cloudinary_id(p_public_id) or p_public_id not like p_business::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
    if p_purpose = 'item_photo' then
      if p_item is null or not exists (select 1 from public.items i where i.id = p_item and i.business_id = p_business) then raise exception 'item_not_found'; end if;
    elsif p_item is not null then
      raise exception 'invalid_purpose';
    end if;
  end if;
  insert into public.media_uploads (public_id, business_id, item_id, purpose) values (p_public_id, p_business, p_item, p_purpose);
end $$;

-- A removed photo (Cloudinary id) or removed video (bucket file) is queued in the same transaction as the delete.
create or replace function public.media_gc_from_item_media() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.kind = 'image' and public.is_cloudinary_id(old.path) then
    insert into public.media_gc (public_id, reason) values (old.path, 'photo_removed') on conflict (public_id) do nothing;
  elsif old.kind = 'video' and public.is_storage_video_path(old.path) then
    insert into public.media_gc (public_id, reason) values (old.path, 'video_removed') on conflict (public_id) do nothing;
  end if;
  return null;
end $$;

create or replace function public.media_gc_enqueue(p_ids text[], p_reason text) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  insert into public.media_gc (public_id, reason)
  select x, left(coalesce(p_reason, 'manual'), 60) from unnest(p_ids) as x where public.is_cloudinary_id(x) or public.is_storage_video_path(x)
  on conflict (public_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

-- A signed video ticket lasts two hours, so a video upload gets three hours before the sweep calls it abandoned.
create or replace function public.media_sweep_orphans(p_grace interval default interval '1 hour') returns integer
language plpgsql security definer set search_path = public as $$
declare queued integer;
begin
  with put as (
    insert into public.media_gc (public_id, reason)
    select u.public_id, 'unattached_upload' from public.media_uploads u
    where u.created_at < now() - (case when u.purpose = 'item_video' then greatest(p_grace, interval '3 hours') else p_grace end)
      and not exists (select 1 from public.item_media m where m.path = u.public_id)
      and not exists (select 1 from public.businesses b where b.logo_path = u.public_id or b.cover_path = u.public_id)
    on conflict (public_id) do nothing
    returning 1
  )
  select count(*) into queued from put;
  delete from public.media_uploads u
  where u.created_at < now() - (case when u.purpose = 'item_video' then greatest(p_grace, interval '3 hours') else p_grace end);
  return queued;
end $$;

revoke all on function public.is_storage_video_path(text) from public, anon, authenticated;
grant execute on function public.is_storage_video_path(text) to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 2. One sequence
-- ---------------------------------------------------------------------------------------------------------------------

-- Dense, per-item sequence from whatever order the rows already have. Same order the views already showed, id breaks exact ties.
update public.item_media m set sort = r.pos
from (select id, (row_number() over (partition by item_id order by sort, created_at, id) - 1)::integer as pos from public.item_media) r
where m.id = r.id and m.sort is distinct from r.pos;

create or replace function public.attach_item_media(
  p_item uuid, p_kind text, p_path text, p_mime text, p_width integer, p_height integer, p_duration numeric, p_size bigint
) returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_bid uuid;
  v_id uuid;
  v_sort integer;
begin
  select i.business_id into v_bid from public.items i where i.id = p_item;
  if v_bid is null then raise exception 'item_not_found'; end if;
  if p_path not like v_bid::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
  -- media_limit_ok takes the per-business advisory lock, so the max() below cannot race another attach.
  if not public.media_limit_ok(p_item, p_kind) then raise exception 'limit_reached:item_media'; end if;
  select coalesce(max(m.sort) + 1, 0) into v_sort from public.item_media m where m.item_id = p_item;
  insert into public.item_media (item_id, business_id, kind, path, mime, sort, width, height, duration_sec, size_bytes)
  values (p_item, v_bid, p_kind, p_path, p_mime, v_sort, p_width, p_height, p_duration, p_size)
  returning id into v_id;
  return v_id;
end $$;
revoke all on function public.attach_item_media(uuid, text, text, text, integer, integer, numeric, bigint) from public, anon, authenticated;
grant execute on function public.attach_item_media(uuid, text, text, text, integer, integer, numeric, bigint) to service_role;

-- Writes sort = position for a COMPLETE ordered list of one item's paths. Internal: callers have already checked ownership.
create or replace function public.media_apply_order(p_item uuid, p_ordered text[]) returns integer
language plpgsql security definer set search_path = public as $$
declare v_n integer;
begin
  update public.item_media m set sort = o.pos
  from (select u.path, (u.ord - 1)::integer as pos from unnest(p_ordered) with ordinality as u(path, ord)) o
  where m.item_id = p_item and m.path = o.path and m.sort is distinct from o.pos;
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function public.media_apply_order(uuid, text[]) from public, anon, authenticated;

create or replace function public.seller_reorder_item_media(p_item uuid, p_paths text[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_have text[];
  v_n integer;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id and not i.removed_by_admin) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  if p_paths is null then raise exception 'no_items' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtext(v_id::text || 'item_media'));
  select coalesce(array_agg(m.path order by m.sort, m.created_at, m.id), '{}') into v_have
  from public.item_media m where m.item_id = p_item and m.business_id = v_id;
  if cardinality(p_paths) <> (select count(distinct p) from unnest(p_paths) as p) then raise exception 'duplicate_path' using errcode = 'P0001'; end if;
  if exists (select 1 from unnest(p_paths) as p where p is null or p <> all (v_have)) then raise exception 'path_not_found' using errcode = 'P0001'; end if;
  if cardinality(p_paths) <> cardinality(v_have) then raise exception 'order_incomplete' using errcode = 'P0001'; end if;
  v_n := public.media_apply_order(p_item, p_paths);
  return jsonb_build_object('updated', v_n,
    'cover', (select m.path from public.item_media m where m.item_id = p_item and m.kind = 'image' order by m.sort, m.created_at, m.id limit 1));
end $$;
revoke all on function public.seller_reorder_item_media(uuid, text[]) from public, anon;
grant execute on function public.seller_reorder_item_media(uuid, text[]) to authenticated, service_role;

-- DEPRECATED: use seller_reorder_item_media. Photos are reordered inside the slots photos already occupy; videos keep their place.
-- Paths that are not this item's photos are ignored and photos left out of the list keep their relative order after the listed ones.
create or replace function public.seller_reorder_item_photos(p_item uuid, p_paths text[]) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_order text[];
  v_n integer;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id and not i.removed_by_admin) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  if p_paths is null or cardinality(p_paths) = 0 or cardinality(p_paths) > 50 then raise exception 'no_items' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtext(v_id::text || 'item_media'));
  with cur as (
    select m.path, m.kind, row_number() over (order by m.sort, m.created_at, m.id) as rn
    from public.item_media m where m.item_id = p_item and m.business_id = v_id
  ), want as (
    select u.path, min(u.ord) as ord from unnest(p_paths) with ordinality as u(path, ord) group by u.path
  ), slots as (
    select rn, row_number() over (order by rn) as idx from cur where kind = 'image'
  ), picks as (
    select c.path, row_number() over (order by coalesce(w.ord, 2147483647), c.rn) as idx
    from cur c left join want w on w.path = c.path where c.kind = 'image'
  ), placed as (
    select c.path, c.rn as pos from cur c where c.kind <> 'image'
    union all
    select p.path, s.rn from picks p join slots s on s.idx = p.idx
  )
  select coalesce(array_agg(path order by pos), '{}') into v_order from placed;
  v_n := public.media_apply_order(p_item, v_order);
  return v_n;
end $$;
revoke all on function public.seller_reorder_item_photos(uuid, text[]) from public, anon;
grant execute on function public.seller_reorder_item_photos(uuid, text[]) to authenticated, service_role;

-- The sequence and the plan limits, for the seller's own item. max is null when the plan has no limit.
create or replace function public.seller_item_media(p_item uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_lim jsonb;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  select case b.plan_key when 'premium' then g.premium else g.standard end into v_lim
  from public.businesses b cross join public.global_limits g where b.id = v_id and g.id = 1;
  return jsonb_build_object(
    'media', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'path', m.path, 'kind', m.kind, 'sort', m.sort, 'duration', m.duration_sec) order by m.sort, m.created_at, m.id)
                       from public.item_media m where m.item_id = p_item), '[]'::jsonb),
    'cover', (select m.path from public.item_media m where m.item_id = p_item and m.kind = 'image' order by m.sort, m.created_at, m.id limit 1),
    'limits', jsonb_build_object(
      'photos', jsonb_build_object('used', (select count(*) from public.item_media m where m.item_id = p_item and m.kind = 'image')::integer, 'max', (v_lim ->> 'photosPerItem')::integer),
      'videos', jsonb_build_object('used', (select count(*) from public.item_media m where m.item_id = p_item and m.kind = 'video')::integer, 'max', (v_lim ->> 'videosPerItem')::integer)));
end $$;
revoke all on function public.seller_item_media(uuid) from public, anon;
grant execute on function public.seller_item_media(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 3. Public read: image_paths, video_paths and the merged media, all in the one sequence
-- ---------------------------------------------------------------------------------------------------------------------

-- New column goes last so the existing definition stays valid.
create or replace view public.public_items with (security_barrier = true) as
select
  i.id, i.business_id, i.name, i.description, i.section, i.price, i.price_max, i.price_type, i.unit,
  i.availability, i.sort, i.created_at,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id and m.kind = 'image'), '[]'::jsonb) as image_paths,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id and m.kind = 'video'), '[]'::jsonb) as video_paths,
  case when i.track_stock and i.show_stock_count and i.availability = 'limited_stock' and i.stock_count > 0 then i.stock_count end as stock_left,
  i.brand, i.short_description, i.highlights, i.specs, i.includes, i.terms, i.pack_size,
  coalesce((select jsonb_agg(jsonb_build_object('path', m.path, 'kind', m.kind, 'duration', m.duration_sec) order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id), '[]'::jsonb) as media
from public.items i
join public.businesses b on b.id = i.business_id
where public.business_is_visible(b) and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
  and public.item_is_listed(i.availability);
revoke all on public.public_items from public;
grant select on public.public_items to anon, authenticated, service_role;

-- The home grid snapshot carries video_paths (null when there are none) so a card keeps the item's videos.
do $$
declare
  v_def text;
  v_new text;
begin
  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'products_snapshot';
  if position('video_paths' in v_def) = 0 then
    v_new := replace(v_def, 'i.image_paths ->> 0 as image_path', 'i.image_paths ->> 0 as image_path, nullif(i.video_paths, ''[]''::jsonb) as video_paths');
    if v_new = v_def then raise exception 'products_snapshot: capped column list not found'; end if;
    v_def := v_new;
    v_new := replace(v_def, 'k.created_at, k.image_path,', 'k.created_at, k.image_path, k.video_paths,');
    if v_new = v_def then raise exception 'products_snapshot: item column list not found'; end if;
    execute v_new;
  end if;
end $$;

$m_0057_item_media_sequence$),
    ('0058_remembered_sessions', $m_0058_remembered_sessions$
alter table public.status_sessions add column if not exists remembered boolean not null default false;

$m_0058_remembered_sessions$),
    ('0059_admin_activity_delete', $m_0059_admin_activity_delete$
-- 0059_admin_activity_delete.sql
-- Delete buttons for the Command Center "Live activity" feed (feeds admin_activity(), migration 0014).
--
--   * Notification rows (id "n:<uuid>") are really deleted from admin_notifications.
--   * Audit rows (id "a:<number>") are NEVER deleted. audit_log stays immutable (0008 revokes UPDATE and DELETE).
--     "Delete" only hides the row from the calling admin's own feed, through admin_activity_dismissals.
--     Other admins still see it, and the Audit page still shows it.
--
-- Additive and safe to re-run.
--
-- ROLLBACK (run by hand, in this order; nothing here touches audit_log):
--   drop function if exists public.admin_delete_activity(text[], text);
--   -- restore the previous feed: re-run the "create or replace function public.admin_activity" statement from 0014_admin_live.sql
--   drop table if exists public.admin_activity_dismissals;
--   -- Notification rows that were deleted through admin_delete_activity() cannot be brought back by a rollback.
--   -- Their removal is recorded in the audit log as action 'activity.delete' (with the reason and the kinds removed).

-- ---------------------------------------------------------------------------
-- Per-admin "hidden from my feed" list. Audit rows only.
-- ---------------------------------------------------------------------------
create table if not exists public.admin_activity_dismissals (
  admin_id     uuid        not null default auth.uid() references auth.users(id) on delete cascade,
  activity_id  text        not null check (activity_id ~ '^a:[0-9]{1,19}$'),
  dismissed_at timestamptz not null default now(),
  primary key (admin_id, activity_id)
);

alter table public.admin_activity_dismissals enable row level security;

drop policy if exists "own dismissals read" on public.admin_activity_dismissals;
drop policy if exists "own dismissals insert" on public.admin_activity_dismissals;
drop policy if exists "own dismissals delete" on public.admin_activity_dismissals;
create policy "own dismissals read" on public.admin_activity_dismissals
  for select to authenticated using (admin_id = auth.uid() and public.is_admin());
create policy "own dismissals insert" on public.admin_activity_dismissals
  for insert to authenticated with check (admin_id = auth.uid() and public.is_admin());
create policy "own dismissals delete" on public.admin_activity_dismissals
  for delete to authenticated using (admin_id = auth.uid() and public.is_admin());

revoke all on public.admin_activity_dismissals from public, anon, authenticated;
grant select, insert, delete on public.admin_activity_dismissals to authenticated;
grant all on public.admin_activity_dismissals to service_role;

-- ---------------------------------------------------------------------------
-- The feed: same as 0014, minus the rows the caller dismissed.
-- The audit row written by admin_delete_activity() ('activity.delete') is kept out of the feed so that clearing the
-- feed does not put a new line in it. It is still in the audit log.
-- ---------------------------------------------------------------------------
create or replace function public.admin_activity(p_limit integer default 15) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_limit integer := least(greatest(coalesce(p_limit, 15), 1), 50);
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.at desc, x.id desc) from (
      select * from (
        select 'n:' || n.id::text as id, n.created_at as at, n.kind, n.business_id,
               coalesce(b.name, n.data->>'business_name') as business_name,
               null::text as actor, n.data
          from public.admin_notifications n
          left join public.businesses b on b.id = n.business_id
         where n.kind <> 'application_submitted' or public.has_role(array['owner', 'reviewer'])
        union all
        select 'a:' || a.id::text, a.created_at, a.action, a.business_id, b.name,
               coalesce(a.actor_email, a.actor_role),
               coalesce(a.data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object('reason', a.reason))
          from public.audit_log a
          left join public.businesses b on b.id = a.business_id
         where a.action not in ('payment_submitted', 'change_requested', 'flag_replied', 'deletion_requested', 'activity.delete')
           and not exists (
             select 1 from public.admin_activity_dismissals d
              where d.admin_id = auth.uid() and d.activity_id = 'a:' || a.id::text)
      ) u
      order by u.at desc, u.id desc
      limit v_limit
    ) x
  ), '[]'::jsonb);
end $$;

revoke all on function public.admin_activity(integer) from public, anon;
grant execute on function public.admin_activity(integer) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- admin_delete_activity(p_ids, p_reason): the one way the feed is cleared.
--   "n:<uuid>"   -> the notification is deleted for everyone
--   "a:<number>" -> the audit row is hidden for the caller only (audit_log is not touched)
-- Owner and reviewer only, the same roles as 'activity.manage' in admin/src/auth/permissions.js.
-- Returns { deleted, dismissed, skipped }: skipped is what was already gone or already hidden.
-- Any id that is not one of the two shapes rejects the whole call (invalid_input), so nothing is half done.
-- ---------------------------------------------------------------------------
create or replace function public.admin_delete_activity(p_ids text[], p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_uid       uuid := auth.uid();
  v_ids       text[];
  v_notif     uuid[];
  v_audit     bigint[];
  v_deleted   integer := 0;
  v_dismissed integer := 0;
  v_kinds     jsonb := '[]'::jsonb;
begin
  if v_uid is null or not public.has_role(array['reviewer']) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select coalesce(array_agg(distinct x), '{}') into v_ids from unnest(p_ids) as t(x) where x is not null;
  if cardinality(v_ids) = 0 then
    raise exception 'invalid_input' using detail = 'no ids';
  end if;
  if cardinality(v_ids) > 200 then
    raise exception 'too_many' using detail = 'at most 200 ids per call';
  end if;
  if exists (
    select 1 from unnest(v_ids) as t(x)
     where x !~ '^n:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       and x !~ '^a:[0-9]{1,18}$'
  ) then
    raise exception 'invalid_input' using detail = 'unknown id';
  end if;

  select coalesce(array_agg(substr(x, 3)::uuid), '{}') into v_notif from unnest(v_ids) as t(x) where x like 'n:%';
  select coalesce(array_agg(substr(x, 3)::bigint), '{}') into v_audit from unnest(v_ids) as t(x) where x like 'a:%';

  -- Notifications: really deleted. The kinds go into the audit entry because the rows cannot be restored.
  with gone as (
    delete from public.admin_notifications n where n.id = any(v_notif) returning n.kind
  )
  select count(*)::integer, coalesce(jsonb_agg(g.kind order by g.kind), '[]'::jsonb) into v_deleted, v_kinds from gone g;

  -- Audit rows: only an entry in the caller's own dismissal list. Ids that are not in audit_log are ignored.
  with hidden as (
    insert into public.admin_activity_dismissals (admin_id, activity_id)
    select v_uid, 'a:' || a.id::text from public.audit_log a where a.id = any(v_audit)
    on conflict (admin_id, activity_id) do nothing
    returning 1
  )
  select count(*)::integer into v_dismissed from hidden;

  if v_deleted > 0 then
    perform public.admin_audit_action('activity.delete', 'admin_notification', null, null,
      jsonb_build_object('deleted', v_deleted, 'kinds', v_kinds), nullif(btrim(coalesce(p_reason, '')), ''));
  end if;

  return jsonb_build_object('deleted', v_deleted, 'dismissed', v_dismissed,
                            'skipped', cardinality(v_ids) - v_deleted - v_dismissed);
end $$;

revoke all on function public.admin_delete_activity(text[], text) from public, anon;
grant execute on function public.admin_delete_activity(text[], text) to authenticated, service_role;

$m_0059_admin_activity_delete$),
    ('0060_clearer_messages', $m_0060_clearer_messages$
-- 0060: clearer, shorter payment and renewal messages (SMS, email and in-app).
-- Wording only. No logic, columns or amounts change.

create or replace function public.mpesa_credit_target(p_tx uuid, p_type text, p_id uuid, p_method text) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  t public.mpesa_transactions;
  a public.applications;
  b public.businesses;
  v_price integer;
  v_body text;
begin
  select * into t from public.mpesa_transactions where id = p_tx for update;
  if not found then raise exception 'tx_not_found'; end if;
  if t.state <> 'needs_assignment' then return jsonb_build_object('outcome', 'skipped', 'state', t.state); end if;

  if p_type = 'application' then
    select * into a from public.applications where id = p_id for update;
    if not found then raise exception 'target_not_found'; end if;
    -- An activated application's money belongs to its business.
    select * into b from public.businesses y where y.application_id = a.id and y.status <> 'deleted';
    if found then return public.mpesa_credit_target(p_tx, 'business', b.id, p_method); end if;
    if a.status in ('rejected', 'draft') then raise exception 'application_not_payable'; end if;

    update public.applications set credit_kes = credit_kes + t.amount_kes where id = a.id returning * into a;
    update public.mpesa_transactions set state = 'credited', target_type = 'application', application_id = a.id, business_id = null,
      match_method = p_method, note = null, candidates = '[]' where id = t.id;
    v_price := public.mpesa_price(a);

    if a.status = 'approved' and a.credit_kes >= v_price then
      update public.applications set status = 'payment_confirming', payment_code = t.trans_id where id = a.id;
      insert into public.application_events (application_id, actor, type, data)
      values (a.id, 'system', 'payment_submitted', jsonb_build_object('code', t.trans_id, 'amount', t.amount_kes, 'auto', true, 'credit', a.credit_kes));
      perform public.notify_admin('payment_received', null, jsonb_build_object('code', t.trans_id, 'amount', t.amount_kes, 'application_id', a.id,
        'business_name', a.business_name, 'ready', true));
      v_body := format('KES %s received for %s. We are confirming it and will send your login shortly.', trim(to_char(t.amount_kes, 'FM999G999G990')), a.business_name);
      perform public.mpesa_queue_sms(null, a.id, a.phone, 'EpicMKT: ' || v_body, 'mpesa:' || t.id || ':sms');
      return jsonb_build_object('outcome', 'ready', 'application_id', a.id, 'reference_no', a.reference_no, 'business_name', a.business_name, 'credit', a.credit_kes);
    elsif a.status = 'payment_confirming' then
      return jsonb_build_object('outcome', 'extra_credit', 'application_id', a.id, 'reference_no', a.reference_no, 'business_name', a.business_name, 'credit', a.credit_kes);
    elsif a.status = 'approved' then
      v_body := format('KES %s received for %s. One month costs KES %s. Balance KES %s. Pay to Paybill %s, Account %s.',
        trim(to_char(t.amount_kes, 'FM999G999G990')), a.business_name, v_price, trim(to_char(v_price - a.credit_kes, 'FM999G999G990')),
        coalesce(public.mpesa_paybill(), '-'), a.reference_no);
      perform public.mpesa_queue_sms(null, a.id, a.phone, 'EpicMKT: ' || v_body, 'mpesa:' || t.id || ':sms');
      return jsonb_build_object('outcome', 'part_paid', 'application_id', a.id, 'reference_no', a.reference_no, 'business_name', a.business_name,
        'credit', a.credit_kes, 'balance', v_price - a.credit_kes);
    end if;
    -- Paid before approval. The money is safe; the approval step moves it forward.
    v_body := format('KES %s received for %s. It will be applied once your application is approved.', trim(to_char(t.amount_kes, 'FM999G999G990')), a.business_name);
    perform public.mpesa_queue_sms(null, a.id, a.phone, 'EpicMKT: ' || v_body, 'mpesa:' || t.id || ':sms');
    return jsonb_build_object('outcome', 'early', 'application_id', a.id, 'reference_no', a.reference_no, 'business_name', a.business_name, 'credit', a.credit_kes);
  elsif p_type = 'business' then
    select * into b from public.businesses where id = p_id for update;
    if not found or b.status = 'deleted' then raise exception 'target_not_found'; end if;
    update public.businesses set credit_kes = credit_kes + t.amount_kes where id = b.id;
    update public.mpesa_transactions set state = 'credited', target_type = 'business', business_id = b.id, application_id = null,
      match_method = p_method, note = null, candidates = '[]' where id = t.id;
    return public.mpesa_settle_business(b.id, t.id);
  end if;
  raise exception 'invalid_target';
end $$;

CREATE OR REPLACE FUNCTION public.payment_apply_confirmation(p_id uuid, p_via text DEFAULT 'admin'::text, p_now timestamp with time zone DEFAULT now())
 RETURNS payments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  p public.payments;
  b public.businesses;
  v_today date := public.nairobi_day(p_now);
  v_paid date;
  v_start date;
  v_end date;
  v_body text;
begin
  if p_via not in ('admin','auto') then raise exception 'invalid_via'; end if;
  select * into p from public.payments x where x.id = p_id for update;
  if not found then raise exception 'payment_not_found'; end if;
  if p.status = 'confirmed' then return p; end if;
  if p.status = 'rejected' then raise exception 'payment_rejected'; end if;
  select * into b from public.businesses x where x.id = p.business_id for update;

  if p.kind in ('first','renewal') then
    v_paid := case when b.paid_until is null then null else public.nairobi_day(b.paid_until) end;
    v_start := case when v_paid is not null and v_today <= v_paid + public.grace_days_of(b.grace_days) then v_paid else v_today end;
    v_end := public.add_calendar_month(v_start);
    update public.businesses x set paid_until = public.nairobi_midnight(v_end),
      status = case when x.status in ('pending','expired') then 'live' else x.status end
    where x.id = b.id;
    v_body := format('KES %s received. Your business page is paid until %s.', p.amount_kes, to_char(v_end, 'DD Mon YYYY'));
  elsif p.kind = 'upgrade' then
    v_start := v_today;
    v_end := public.nairobi_day(b.paid_until);
    update public.businesses x set plan_key = coalesce(p.plan_key, x.plan_key) where x.id = b.id;
    v_body := format('KES %s received. You are now on %s until %s.', p.amount_kes, initcap(coalesce(p.plan_key, b.plan_key)), to_char(v_end, 'DD Mon YYYY'));
  else
    v_start := v_today;
    v_end := case when b.paid_until is null then null else public.nairobi_day(b.paid_until) end;
    v_body := format('KES %s received for your category change. It is now awaiting approval.', p.amount_kes);
  end if;

  update public.payments x set status = 'confirmed', period_start = v_start, period_end = v_end, confirmed_via = p_via, decline_reason = null
  where x.id = p.id returning * into p;
  perform public.post_seller_message(p.business_id, 'payment', 'Payment received', v_body || ' Receipt ' || p.receipt_no || '.',
    jsonb_build_object('payment_id', p.id, 'receipt_no', p.receipt_no), 'payment:' || p.id);
  perform public.write_audit(p.business_id, 'payment_confirmed', 'payment', p.id::text, jsonb_build_object('via', p_via, 'receipt', p.receipt_no));
  return p;
end $function$;

CREATE OR REPLACE FUNCTION public.mpesa_settle_business(p_business uuid, p_tx uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  b public.businesses;
  t public.mpesa_transactions;
  v_price integer;
  v_max integer;
  v_today date := public.nairobi_day(now());
  v_paid date;
  v_start date;
  v_end date;
  v_cap_end date;
  v_months integer;
  v_pay public.payments;
  v_credit numeric;
  v_body text;
  v_ref text;
  v_q jsonb;
  v_need integer;
  v_intent jsonb;
begin
  select * into b from public.businesses where id = p_business for update;
  if not found or b.status = 'deleted' then raise exception 'target_not_found'; end if;
  if p_tx is not null then select * into t from public.mpesa_transactions where id = p_tx; end if;
  v_price := coalesce(b.monthly_price, (select p.price_kes from public.plans p where p.category_id = b.category_id and p.plan_key = b.plan_key));
  if v_price is null or v_price <= 0 then return jsonb_build_object('outcome', 'no_price', 'credit', b.credit_kes); end if;
  v_ref := b.seller_id;

  -- The seller opened an upgrade or category-change payment: that is what this money is for. Apply it when the credit
  -- covers it; until then hold it instead of turning it into a renewal month.
  if b.pay_intent is not null and (b.pay_intent ->> 'set_at')::timestamptz > now() - interval '48 hours' then
    begin
      v_q := public.payment_quote(b, b.pay_intent ->> 'purpose', b.pay_intent ->> 'target_plan', b.pay_intent ->> 'category');
      v_need := (v_q ->> 'amount_kes')::integer;
      if v_need > 0 and b.credit_kes >= v_need then
        v_intent := public.mpesa_apply_purpose(b.id, b.pay_intent ->> 'purpose', b.pay_intent ->> 'target_plan', b.pay_intent ->> 'category', nullif(b.pay_intent ->> 'change_id', '')::uuid);
        select * into b from public.businesses where id = p_business for update;
        -- The upgrade used the money. Anything left over only becomes renewal months if it covers a whole month.
        if b.credit_kes < v_price then
          return v_intent || jsonb_build_object('credit', b.credit_kes, 'business_id', b.id, 'business_name', b.name);
        end if;
      elsif v_need > 0 then
        v_body := format('KES %s received toward your %s. It costs KES %s. Balance KES %s. Pay to Paybill %s, Account %s.',
          trim(to_char(coalesce(t.amount_kes, b.credit_kes), 'FM999G999G990')), case when b.pay_intent ->> 'purpose' = 'upgrade' then 'upgrade' else 'category change' end,
          v_need, trim(to_char(v_need - b.credit_kes, 'FM999G999G990')), coalesce(public.mpesa_paybill(), '-'), v_ref);
        perform public.post_seller_message(b.id, 'payment', 'Payment received, balance due', v_body, jsonb_build_object('credit', b.credit_kes, 'price', v_need),
          'mpesa-hold:' || coalesce(t.id::text, gen_random_uuid()::text));
        perform public.mpesa_queue_sms(b.id, b.application_id, b.phone, 'EpicMKT: ' || v_body, 'mpesa-hold:' || coalesce(t.id::text, gen_random_uuid()::text) || ':sms');
        return jsonb_build_object('outcome', 'held', 'credit', b.credit_kes, 'price', v_need, 'balance', v_need - b.credit_kes, 'business_id', b.id, 'business_name', b.name);
      end if;
    exception when others then
      -- The quote no longer applies (for example the listing expired). Forget the intent and treat the money as a renewal.
      update public.businesses set pay_intent = null where id = b.id;
      select * into b from public.businesses where id = p_business for update;
    end;
  end if;

  v_max := coalesce((select (s.value #>> '{}')::integer from public.site_settings s where s.key = 'max_prepay_months'), 12);
  v_paid := case when b.paid_until is null then null else public.nairobi_day(b.paid_until) end;
  -- Same rule as a manual confirmation: paying on the last day or one day late carries on from the old date.
  v_start := case when v_paid is not null and v_today <= v_paid + public.grace_days_of(b.grace_days) then v_paid else v_today end;
  v_cap_end := (v_today + (v_max || ' months')::interval)::date;
  v_months := floor(b.credit_kes / v_price)::integer;
  v_months := least(v_months, greatest(0, (extract(year from age(v_cap_end, v_start)) * 12 + extract(month from age(v_cap_end, v_start)))::integer));

  if v_months >= 1 then
    v_end := (v_start + (v_months || ' months')::interval)::date;
    insert into public.payments (business_id, application_id, amount_kes, method, reference, mpesa_code, status, kind, plan_key, category_id,
                                 months, period_start, period_end, account_ref, phone, source, confirmed_via, submitted_at, confirmed_at)
    values (b.id, b.application_id, v_months * v_price, 'mpesa', coalesce(t.trans_id, 'CREDIT-' || left(gen_random_uuid()::text, 8)), t.trans_id,
            'confirmed', 'renewal', b.plan_key, b.category_id, v_months, v_start, v_end, t.account, t.payer_phone, 'auto', 'auto',
            coalesce(t.created_at, now()), now())
    returning * into v_pay;
    update public.businesses x set paid_until = public.nairobi_midnight(v_end), credit_kes = x.credit_kes - v_months * v_price,
      status = case when x.status in ('pending', 'expired') then 'live' else x.status end
    where x.id = b.id returning credit_kes into v_credit;
    update public.mpesa_transactions set state = 'applied', payment_id = v_pay.id, applied_at = now()
      where business_id = b.id and state = 'credited';

    v_body := format('Payment received. %s month%s added. Paid until %s.%s Receipt %s.',
      v_months, case when v_months = 1 then '' else 's' end, to_char(v_end, 'DD Mon YYYY'),
      case when v_credit > 0 then format(' KES %s kept as credit.', trim(to_char(v_credit, 'FM999G999G990'))) else '' end,
      v_pay.receipt_no);
    perform public.post_seller_message(b.id, 'payment', 'Payment received', v_body,
      jsonb_build_object('payment_id', v_pay.id, 'receipt_no', v_pay.receipt_no, 'months', v_months), 'payment:' || v_pay.id);
    perform public.mpesa_queue_sms(b.id, b.application_id, b.phone, 'EpicMKT: ' || v_body, 'mpesa:' || v_pay.id || ':sms');
    perform public.write_audit(b.id, 'payment_confirmed', 'payment', v_pay.id::text, jsonb_build_object('via', 'auto', 'months', v_months, 'receipt', v_pay.receipt_no));
    return jsonb_build_object('outcome', 'applied', 'months', v_months, 'paid_until', v_end, 'credit', v_credit, 'receipt_no', v_pay.receipt_no,
      'payment_id', v_pay.id, 'business_id', b.id, 'business_name', b.name);
  end if;

  v_credit := b.credit_kes;
  if v_credit >= v_price then
    v_body := format('Payment received. Your business page is already paid ahead for the maximum of %s months. KES %s is kept as credit and applied when due.',
      v_max, trim(to_char(v_credit, 'FM999G999G990')));
  else
    v_body := format('KES %s received. One month costs KES %s. Balance KES %s. Pay to Paybill %s, Account %s.',
      trim(to_char(coalesce(t.amount_kes, v_credit), 'FM999G999G990')), v_price, trim(to_char(v_price - v_credit, 'FM999G999G990')),
      coalesce(public.mpesa_paybill(), '-'), v_ref);
  end if;
  perform public.post_seller_message(b.id, 'payment', 'Payment received, balance due', v_body,
    jsonb_build_object('credit', v_credit, 'price', v_price), 'mpesa-part:' || coalesce(t.id::text, gen_random_uuid()::text));
  perform public.mpesa_queue_sms(b.id, b.application_id, b.phone, 'EpicMKT: ' || v_body, 'mpesa-part:' || coalesce(t.id::text, gen_random_uuid()::text) || ':sms');
  return jsonb_build_object('outcome', case when v_credit >= v_price then 'capped' else 'part_paid' end, 'credit', v_credit, 'price', v_price,
    'balance', greatest(v_price - v_credit, 0), 'business_id', b.id, 'business_name', b.name);
end $function$;

CREATE OR REPLACE FUNCTION public.queue_billing_notices(p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b record;
  v_left integer;
  v_day text;
  v_kind text;
  v_key text;
  v_subject text;
  v_body text;
  v_name text;
  v_inapp integer;
  v_queued integer := 0;
  v_n integer;
  v_g integer;
begin
  v_inapp := public.generate_billing_notices(p_now);

  for b in
    select x.id, x.name, x.paid_until, x.phone, x.email, x.grace_days
      from public.businesses x
     where x.paid_until is not null and x.status in ('live', 'paused', 'suspended', 'expired')
  loop
    v_left := public.nairobi_day(b.paid_until) - public.nairobi_day(p_now);
    v_day := to_char(public.nairobi_day(b.paid_until), 'YYYY-MM-DD');
    v_g := public.grace_days_of(b.grace_days);
    v_name := left(b.name, 40);
    v_kind := null;

    if v_left in (7, 3, 1) then
      v_kind := 'reminder';
      v_key := format('reminder:%s:%s', v_left, v_day);
      v_subject := format('Your listing expires in %s day%s', v_left, case when v_left = 1 then '' else 's' end);
      v_body := format('EpicMKT: %s expires in %s day%s (%s). Renew to stay visible.',
        v_name, v_left, case when v_left = 1 then '' else 's' end, to_char(public.nairobi_day(b.paid_until), 'DD Mon YYYY'));
    elsif v_left = -1 and v_g > 0 then
      v_kind := 'grace';
      v_key := 'grace:' || v_day;
      v_subject := format('Your subscription has ended: %s day%s of grace', v_g, case when v_g = 1 then '' else 's' end);
      v_body := format('EpicMKT: %s has expired. You have %s day%s of grace. Renew now to stay visible.', v_name, v_g, case when v_g = 1 then '' else 's' end);
    elsif v_left between -(v_g + 3) and -(v_g + 1) then
      -- Only the first days after grace; sellers who lapsed long ago are not texted when this first runs.
      v_kind := 'expiry';
      v_key := 'expiry:' || v_day;
      v_subject := 'Your subscription has expired';
      v_body := format('EpicMKT: %s is now hidden from customers. Renew to bring it back.', v_name);
    end if;

    if v_kind is null then continue; end if;

    insert into public.messages (business_id, channel, kind, template_key, to_address, subject, body, status, transactional, scheduled_at, read_at, dedupe_key, data)
    values (b.id, 'sms', v_kind, 'billing_' || v_kind, b.phone, v_subject, v_body, 'queued', true, p_now, p_now, v_key || ':sms',
            jsonb_build_object('days_left', v_left))
    on conflict (business_id, dedupe_key) where dedupe_key is not null do nothing;
    get diagnostics v_n = row_count;
    v_queued := v_queued + v_n;

    if b.email is not null and b.email <> '' then
      insert into public.messages (business_id, channel, kind, template_key, to_address, subject, body, status, transactional, scheduled_at, read_at, dedupe_key, data)
      values (b.id, 'email', v_kind, 'billing_' || v_kind, b.email, v_subject, v_body, 'queued', true, p_now, p_now, v_key || ':email',
              jsonb_build_object('days_left', v_left))
      on conflict (business_id, dedupe_key) where dedupe_key is not null do nothing;
      get diagnostics v_n = row_count;
      v_queued := v_queued + v_n;
    end if;
  end loop;

  return jsonb_build_object('inApp', v_inapp, 'queued', v_queued);
end $function$;

$m_0060_clearer_messages$),
    ('0061_bulk_unlist_assign_undo', $m_0061_bulk_unlist_assign_undo$
-- 0061_bulk_unlist_assign_undo.sql
-- Bulk actions, part 2: Unlist and Assign agent are real, and bulk actions can be undone.
-- Ported from feature/bulk-unlist-assign-undo (its 0017) onto main. It re-declares the business-list functions as they
-- stand after 0014, 0016 and 0029, so it must run after them. Additive and safe to re-run.
--
--   businesses.agent           the staff member looking after a business (a name from admin_agent_names()).
--   Unlist                     a live business becomes "paused" (the status the seller app calls "Paused (unlisted)").
--   Assign agent               sets or clears businesses.agent. Silent: the seller is not told.
--   admin_bulk_undo            what each undoable bulk action changed, kept for 15 minutes.
--   admin_undo_bulk_business_action(token)
--                              puts back only what is still exactly as the action left it. A business someone
--                              changed in the meantime (a payment moved paid_until, say) is skipped, never overwritten.
--   Payments are not touched: a suspended seller can still see the payment details and pay (seller_payment_instructions and
--   the other payment functions are already open to a suspended seller, see 0016).

alter table public.businesses add column if not exists agent text check (agent is null or char_length(agent) between 1 and 100);

-- Names an admin can pick as an agent: every staff member, by display name (or e-mail when there is none).
create or replace function public.admin_agent_names() returns jsonb
language sql stable security definer set search_path = public as $$
  select case when public.is_admin()
    then coalesce((select jsonb_agg(n order by n) from (
           select distinct coalesce(nullif(btrim(a.display_name), ''), nullif(btrim(a.email), '')) as n from public.admins a) x
          where n is not null), '[]'::jsonb)
    else '[]'::jsonb end
$$;
revoke all on function public.admin_agent_names() from public, anon;
grant execute on function public.admin_agent_names() to authenticated, service_role;

-- The agent is read straight from businesses, so the admin_businesses_v view (0014, changed by 0029) keeps its shape.

create or replace function public.admin_businesses_filtered(p_filters jsonb default '{}', p_search text default null)
returns setof public.admin_businesses_v
language sql stable security invoker set search_path = public as $$
  select v.*
    from public.admin_businesses_v v
   where public.is_admin()
     and (coalesce(p_filters->>'category', '') = '' or v.category = p_filters->>'category')
     and (coalesce(p_filters->>'county', '')   = '' or v.county   = p_filters->>'county')
     and (coalesce(p_filters->>'town', '')     = '' or v.town     = p_filters->>'town')
     and (coalesce(p_filters->>'plan', '')     = '' or v.plan     = p_filters->>'plan')
     and (coalesce(p_filters->>'verified', '') = '' or v.verified = (p_filters->>'verified' = 'yes'))
     and (coalesce(p_filters->>'featured', '') = '' or v.featured = (p_filters->>'featured' = 'yes'))
     and (coalesce(p_filters->>'status', '')   = '' or v.state    = p_filters->>'status')
     and (coalesce(p_filters->>'daysMin', '') = '' or v.days_left >= (p_filters->>'daysMin')::numeric)
     and (coalesce(p_filters->>'daysMax', '') = '' or v.days_left <= (p_filters->>'daysMax')::numeric)
     and (coalesce(p_filters->>'hasFlags', 'false') <> 'true' or v.open_flags > 0)
     and (coalesce(p_filters->>'hasUnconfirmed', 'false') <> 'true' or v.unconfirmed_payment)
     and (coalesce(p_filters->>'agent', '') = ''
          or (p_filters->>'agent' = '__none__' and not exists (select 1 from public.businesses x where x.id = v.id and x.agent is not null))
          or exists (select 1 from public.businesses x where x.id = v.id and x.agent = p_filters->>'agent'))
     and (coalesce(p_filters->>'createdFrom', '') = '' or v.created_day >= (p_filters->>'createdFrom')::date)
     and (coalesce(p_filters->>'createdTo', '')   = '' or v.created_day <= (p_filters->>'createdTo')::date)
     and (btrim(coalesce(p_search, '')) = '' or
          v.name ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
       or v.phone ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
       or v.seller_id ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
       or v.slug ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
       or v.owner_name ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%')
$$;

create or replace function public.admin_businesses_query(
  p_tab text default 'all', p_search text default null, p_sort text default 'paidUntil', p_dir text default 'asc',
  p_filters jsonb default '{}', p_limit integer default 50, p_offset integer default 0
) returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare
  v_order text;
  v_dir text := case when lower(coalesce(p_dir, 'asc')) = 'desc' then 'desc' else 'asc' end;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 5000);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_total bigint;
  v_rows jsonb;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  -- Only these columns can be sorted on: the key is looked up here, never pasted into the query.
  v_order := case p_sort
    when 'name' then 'lower(name)'
    when 'items' then 'items'
    when 'healthScore' then 'health_score'
    when 'lastLogin' then 'last_login_at'
    when 'createdAt' then 'created_at'
    when 'lastEdit' then 'last_edit_at'
    when 'strikes' then 'strikes'
    else 'paid_until'
  end;
  if v_order = 'health_score' then
    v_order := 'round(completeness * 0.35 + greatest(0, least(100, 100 - price_age_days * 2.5)) * 0.25'
            || ' + greatest(0, least(100, 100 - login_age_days * 4)) * 0.25'
            || ' + greatest(0, least(100, 100 - open_reports * 35)) * 0.15)';
  end if;

  select count(*) into v_total
    from public.admin_businesses_filtered(p_filters, p_search) v
   where public.admin_business_in_tab(p_tab, v.state, v.open_flags);

  execute format($q$
    select coalesce(jsonb_agg(r.j order by r.rn), '[]'::jsonb) from (
      select row_number() over (order by %1$s %2$s nulls last, id) as rn,
        jsonb_build_object(
          'id', id, 'sellerId', seller_id, 'slug', slug, 'name', name, 'category', coalesce(category, ''),
          'county', coalesce(county, ''), 'town', coalesce(town, ''), 'ownerName', coalesce(owner_name, ''),
          'phone', coalesce(phone, ''), 'plan', plan, 'verified', verified, 'featured', featured,
          'status', ui_status, 'paidUntil', to_char(paid_day, 'YYYY-MM-DD'), 'items', items,
          'openFlags', open_flags, 'strikes', strikes, 'completeness', completeness,
          'priceAgeDays', price_age_days, 'loginAgeDays', login_age_days, 'openReports', open_reports,
          'healthScore', round(completeness * 0.35 + greatest(0, least(100, 100 - price_age_days * 2.5)) * 0.25
                             + greatest(0, least(100, 100 - login_age_days * 4)) * 0.25
                             + greatest(0, least(100, 100 - open_reports * 35)) * 0.15),
          'lastLogin', last_login_at, 'lastEdit', last_edit_at, 'createdAt', created_at,
          'state', state, 'agent', (select x.agent from public.businesses x where x.id = v.id), 'tags', to_jsonb(tags), 'deleted', deleted, 'unconfirmedPayment', unconfirmed_payment
        ) as j
      from public.admin_businesses_filtered($1, $2) v
      where public.admin_business_in_tab($3, v.state, v.open_flags)
      order by %1$s %2$s nulls last, id
      limit $4 offset $5
    ) r
  $q$, v_order, v_dir)
  into v_rows
  using p_filters, p_search, p_tab, v_limit, v_offset;

  return jsonb_build_object('total', v_total, 'rows', v_rows);
end $$;

create or replace function public.admin_business_filter_options() returns jsonb
language plpgsql stable security invoker set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'categories', coalesce((select jsonb_agg(name order by name) from public.categories where active), '[]'::jsonb),
    'counties', coalesce((
      select jsonb_agg(jsonb_build_object('name', county, 'towns', towns) order by county)
        from (select b.county, jsonb_agg(distinct b.town order by b.town) filter (where b.town is not null) as towns
                from public.businesses b where b.county is not null group by b.county) t
    ), '[]'::jsonb),
    'plans', jsonb_build_array('Standard', 'Premium'),
    'agents', public.admin_agent_names()
  );
end $$;


-- The business tab "unlisted" is the same set as "paused": an unlisted business is a paused one.
create or replace function public.admin_business_in_tab(p_tab text, p_state text, p_open_flags integer)
returns boolean language sql immutable as $$
  select case coalesce(nullif(p_tab, ''), 'all')
    when 'all' then p_state <> 'deleted'
    when 'live' then p_state in ('live', 'expiring', 'grace')
    when 'flagged' then p_open_flags > 0 and p_state <> 'deleted'
    when 'expiring' then p_state = 'expiring'
    when 'grace' then p_state = 'grace'
    when 'expired' then p_state = 'expired'
    when 'paused' then p_state = 'paused'
    when 'unlisted' then p_state = 'paused'
    when 'suspended' then p_state = 'suspended'
    when 'deleted' then p_state = 'deleted'
    else false
  end
$$;

create or replace function public.admin_business_tab_counts(p_filters jsonb default '{}') returns jsonb
language plpgsql stable security invoker set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return (
    select jsonb_build_object(
      'all',       count(*) filter (where public.admin_business_in_tab('all', v.state, v.open_flags)),
      'live',      count(*) filter (where public.admin_business_in_tab('live', v.state, v.open_flags)),
      'expiring',  count(*) filter (where public.admin_business_in_tab('expiring', v.state, v.open_flags)),
      'grace',     count(*) filter (where public.admin_business_in_tab('grace', v.state, v.open_flags)),
      'expired',   count(*) filter (where public.admin_business_in_tab('expired', v.state, v.open_flags)),
      'paused',    count(*) filter (where public.admin_business_in_tab('paused', v.state, v.open_flags)),
      'suspended', count(*) filter (where public.admin_business_in_tab('suspended', v.state, v.open_flags)),
      'unlisted',  count(*) filter (where public.admin_business_in_tab('unlisted', v.state, v.open_flags)),
      'flagged',   count(*) filter (where public.admin_business_in_tab('flagged', v.state, v.open_flags)),
      'deleted',   count(*) filter (where public.admin_business_in_tab('deleted', v.state, v.open_flags))
    )
    from public.admin_businesses_filtered(p_filters, null) v
  );
end $$;

-- ---------------------------------------------------------------------------
-- Undo log. Only the security definer functions below touch it.
-- ---------------------------------------------------------------------------
create table if not exists public.admin_bulk_undo (
  token uuid primary key default gen_random_uuid(),
  actor_id uuid not null,
  action text not null,
  entries jsonb not null,           -- [{ "id": <business id>, "before": {field: value}, "after": {field: value} }]
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '15 minutes',
  undone_at timestamptz
);
alter table public.admin_bulk_undo enable row level security;
revoke all on public.admin_bulk_undo from public, anon, authenticated;
grant all on public.admin_bulk_undo to service_role;

-- Which business columns each action changes (and so what an undo may put back).
create or replace function public.admin_bulk_fields(p_action text) returns text[]
language sql immutable as $$
  select case p_action
    when 'suspend' then array['status', 'status_reason']
    when 'unsuspend' then array['status', 'status_reason']
    when 'unlist' then array['status', 'status_reason']
    when 'strike' then array['strikes']
    when 'tag' then array['tags']
    when 'feature' then array['featured']
    when 'extend' then array['paid_until']
    when 'assign' then array['agent']
    else array[]::text[]
  end
$$;

create or replace function public.admin_pick_fields(p_row public.businesses, p_fields text[]) returns jsonb
language sql immutable as $$
  select coalesce(jsonb_object_agg(k, to_jsonb(p_row) -> k), '{}'::jsonb) from unnest(p_fields) k
$$;

-- ---------------------------------------------------------------------------
-- The bulk action, now with unlist, assign and an undo token
-- ---------------------------------------------------------------------------
create or replace function public.admin_bulk_business_action(p_action text, p_ids uuid[], p_reason text, p_params jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_params jsonb := coalesce(p_params, '{}'::jsonb);
  b public.businesses;
  a public.businesses;
  v_affected integer := 0;
  v_total integer;
  v_channels jsonb;
  v_tag text;
  v_days integer;
  v_hit boolean;
  v_agent text;
  v_fields text[] := public.admin_bulk_fields(p_action);
  v_entries jsonb := '[]'::jsonb;
  v_token uuid;
begin
  if p_action = 'extend' then
    if not public.has_role(array['finance']) then raise exception 'forbidden' using errcode = '42501'; end if;
  elsif not public.has_role(array['reviewer', 'support']) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p_ids is null or cardinality(p_ids) = 0 then raise exception 'invalid_input'; end if;
  if cardinality(p_ids) > 500 then raise exception 'too_many_recipients'; end if;
  if char_length(v_reason) < 5 then raise exception 'reason_required'; end if;
  if p_action not in ('suspend', 'unsuspend', 'strike', 'unlist', 'tag', 'feature', 'extend', 'assign', 'message', 'export') then raise exception 'not_supported'; end if;
  v_total := cardinality(p_ids);

  if p_action = 'tag' then
    v_tag := btrim(coalesce(v_params ->> 'tag', ''));
    if char_length(v_tag) not between 1 and 30 or coalesce(v_params ->> 'mode', '') not in ('add', 'remove') then raise exception 'invalid_input'; end if;
  elsif p_action = 'extend' then
    v_days := coalesce((v_params ->> 'days')::integer, 0);
    if v_days not between 1 and 365 then raise exception 'invalid_input'; end if;
  elsif p_action = 'feature' then
    if jsonb_typeof(v_params -> 'featured') <> 'boolean' then raise exception 'invalid_input'; end if;
  elsif p_action = 'assign' then
    -- "agent": null or "" clears the agent. A name must belong to a staff member.
    if jsonb_typeof(v_params -> 'agent') not in ('string', 'null') and v_params ? 'agent' then raise exception 'invalid_input'; end if;
    v_agent := nullif(btrim(coalesce(v_params ->> 'agent', '')), '');
    if v_agent is not null and not (public.admin_agent_names() ? v_agent) then raise exception 'unknown_agent'; end if;
  end if;

  if p_action = 'export' then
    select count(*) into v_affected from public.businesses x where x.id = any (p_ids);
    return jsonb_build_object('affected', v_affected, 'skipped', v_total - v_affected, 'undoToken', null, 'auditId', null);
  end if;

  if p_action = 'message' then
    v_channels := coalesce(v_params -> 'channels', '["inApp"]'::jsonb);
    if jsonb_typeof(v_channels) <> 'array' or jsonb_array_length(v_channels) = 0 then raise exception 'invalid_input'; end if;
    for b in select * from public.businesses x where x.id = any (p_ids) and x.status <> 'deleted' loop
      v_hit := false;
      if v_channels ? 'inApp' then
        perform public.admin_send_message(array[b.id], v_params ->> 'subject', v_params ->> 'body',
          coalesce((v_params ->> 'needsReply')::boolean, false), coalesce(v_params -> 'attachments', '[]'::jsonb), null, v_reason);
        v_hit := true;
      end if;
      if v_channels ? 'sms' and b.phone is not null then
        insert into public.messages (business_id, channel, sender, subject, body, to_address, status, created_by)
        values (b.id, 'sms', 'admin', null, left(btrim(coalesce(v_params ->> 'body', '')), 4000), b.phone, 'queued', auth.uid());
        v_hit := true;
      end if;
      if v_channels ? 'email' and b.email is not null then
        insert into public.messages (business_id, channel, sender, subject, body, to_address, status, created_by)
        values (b.id, 'email', 'admin', coalesce(nullif(btrim(coalesce(v_params ->> 'subject', '')), ''), 'Message from EpicMKT'),
                left(btrim(coalesce(v_params ->> 'body', '')), 4000), b.email, 'queued', auth.uid());
        v_hit := true;
      end if;
      if v_hit then v_affected := v_affected + 1; end if;
    end loop;
    return jsonb_build_object('affected', v_affected, 'skipped', v_total - v_affected, 'undoToken', null, 'auditId', null);
  end if;

  for b in select * from public.businesses x where x.id = any (p_ids) and x.status <> 'deleted' order by x.id for update loop
    if p_action = 'suspend' then
      continue when b.status = 'suspended';
      update public.businesses set status = 'suspended', status_reason = v_reason where id = b.id;
      perform public.post_seller_message(b.id, 'general', 'Your account has been suspended',
        'EpicMKT suspended your account. Reason: ' || v_reason || ' Your listing is hidden and your account is locked until EpicMKT lifts the suspension. You can still see your payment details and pay.', '{}');
    elsif p_action = 'unsuspend' then
      continue when b.status <> 'suspended';
      update public.businesses set status = 'live', status_reason = null where id = b.id;
      perform public.post_seller_message(b.id, 'general', 'Your account is active again', 'EpicMKT lifted the suspension on your account. Reason: ' || v_reason, '{}');
    elsif p_action = 'unlist' then
      continue when b.status <> 'live';
      update public.businesses set status = 'paused', status_reason = v_reason where id = b.id;
      perform public.post_seller_message(b.id, 'general', 'Your listing has been unlisted',
        'EpicMKT unlisted your listing, so customers cannot see it. Reason: ' || v_reason, '{}');
    elsif p_action = 'strike' then
      update public.businesses set strikes = strikes + 1 where id = b.id;
      perform public.post_seller_message(b.id, 'strike', 'You received a strike',
        v_reason || ' You now have ' || (b.strikes + 1) || ' strike' || case when b.strikes + 1 = 1 then '' else 's' end || '.',
        jsonb_build_object('strikes', b.strikes + 1));
    elsif p_action = 'tag' then
      if v_params ->> 'mode' = 'add' then
        continue when v_tag = any (b.tags);
        update public.businesses set tags = array_append(tags, v_tag) where id = b.id;
      else
        continue when not (v_tag = any (b.tags));
        update public.businesses set tags = array_remove(tags, v_tag) where id = b.id;
      end if;
    elsif p_action = 'feature' then
      continue when b.featured = (v_params ->> 'featured')::boolean;
      update public.businesses set featured = (v_params ->> 'featured')::boolean where id = b.id;
    elsif p_action = 'extend' then
      continue when b.paid_until is null;
      update public.businesses set paid_until = paid_until + make_interval(days => v_days) where id = b.id;
    elsif p_action = 'assign' then
      continue when b.agent is not distinct from v_agent;
      update public.businesses set agent = v_agent where id = b.id;
    end if;
    v_affected := v_affected + 1;
    select * into a from public.businesses where id = b.id;
    v_entries := v_entries || jsonb_build_object('id', b.id, 'before', public.admin_pick_fields(b, v_fields), 'after', public.admin_pick_fields(a, v_fields));
    perform public.admin_audit_action('business.' || p_action, 'business', b.id::text,
      jsonb_build_object('status', b.status, 'strikes', b.strikes, 'tags', to_jsonb(b.tags), 'featured', b.featured, 'paid_until', b.paid_until, 'agent', b.agent),
      v_params, v_reason, b.id);
  end loop;

  if v_affected > 0 then
    insert into public.admin_bulk_undo (actor_id, action, entries) values (auth.uid(), p_action, v_entries) returning token into v_token;
  end if;
  return jsonb_build_object('affected', v_affected, 'skipped', v_total - v_affected,
                            'undoToken', case when v_token is null then null else v_token::text end, 'auditId', null);
end $$;
revoke all on function public.admin_bulk_business_action(text, uuid[], text, jsonb) from public, anon;
grant execute on function public.admin_bulk_business_action(text, uuid[], text, jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Undo. Same person, within 15 minutes, once. Returns { restored, skipped }.
-- ---------------------------------------------------------------------------
create or replace function public.admin_undo_bulk_business_action(p_token uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  u public.admin_bulk_undo;
  e jsonb;
  b public.businesses;
  f text;
  v_fields text[];
  v_restored integer := 0;
  v_skipped integer := 0;
  v_same boolean;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into u from public.admin_bulk_undo where token = p_token for update;
  if not found or u.actor_id is distinct from auth.uid() then raise exception 'nothing_to_undo'; end if;
  if u.undone_at is not null or u.expires_at < now() then raise exception 'nothing_to_undo'; end if;
  if u.action = 'extend' then
    if not public.has_role(array['finance']) then raise exception 'forbidden' using errcode = '42501'; end if;
  elsif not public.has_role(array['reviewer', 'support']) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  v_fields := public.admin_bulk_fields(u.action);

  for e in select * from jsonb_array_elements(u.entries) loop
    select * into b from public.businesses where id = (e ->> 'id')::uuid for update;
    -- Put back only what is still exactly as the action left it.
    v_same := found;
    if v_same then
      foreach f in array v_fields loop
        if (to_jsonb(b) -> f) is distinct from (e -> 'after' -> f) then v_same := false; end if;
      end loop;
    end if;
    if not v_same then v_skipped := v_skipped + 1; continue; end if;

    if u.action in ('suspend', 'unsuspend', 'unlist') then
      update public.businesses set status = e -> 'before' ->> 'status', status_reason = e -> 'before' ->> 'status_reason' where id = b.id;
      if u.action = 'suspend' then
        perform public.post_seller_message(b.id, 'general', 'Your account is active again', 'EpicMKT reversed the suspension.', '{}');
      elsif u.action = 'unsuspend' then
        perform public.post_seller_message(b.id, 'general', 'Your account is suspended', 'EpicMKT reversed lifting the suspension. Reason: ' || coalesce(e -> 'before' ->> 'status_reason', 'see earlier notice') || ' You can still see your payment details and pay.', '{}');
      else
        perform public.post_seller_message(b.id, 'general', 'Your listing is visible again', 'EpicMKT reversed unlisting your listing.', '{}');
      end if;
    elsif u.action = 'strike' then
      update public.businesses set strikes = (e -> 'before' ->> 'strikes')::integer where id = b.id;
      perform public.post_seller_message(b.id, 'general', 'A strike was removed', 'EpicMKT reversed the strike it gave you. You now have ' || (e -> 'before' ->> 'strikes') || '.', '{}');
    elsif u.action = 'tag' then
      update public.businesses set tags = coalesce((select array_agg(t) from jsonb_array_elements_text(e -> 'before' -> 'tags') t), '{}') where id = b.id;
    elsif u.action = 'feature' then
      update public.businesses set featured = (e -> 'before' ->> 'featured')::boolean where id = b.id;
    elsif u.action = 'extend' then
      update public.businesses set paid_until = (e -> 'before' ->> 'paid_until')::timestamptz where id = b.id;
    elsif u.action = 'assign' then
      update public.businesses set agent = e -> 'before' ->> 'agent' where id = b.id;
    end if;
    v_restored := v_restored + 1;
    perform public.admin_audit_action('business.undo', 'business', b.id::text, e -> 'after', e -> 'before', 'Undo of ' || u.action, b.id);
  end loop;

  update public.admin_bulk_undo set undone_at = now() where token = u.token;
  return jsonb_build_object('restored', v_restored, 'skipped', v_skipped);
end $$;
revoke all on function public.admin_undo_bulk_business_action(uuid) from public, anon;
grant execute on function public.admin_undo_bulk_business_action(uuid) to authenticated, service_role;

$m_0061_bulk_unlist_assign_undo$),
    ('0062_seller_settings', $m_0062_seller_settings$
-- 0062_seller_settings.sql
-- Seller settings (S8b), ported from feat/s8b-settings-help-onboarding onto main.
--   * seller_settings (0005) already holds a seller's settings jsonb; this adds the server-side rules for what may be in it
--     (a validation trigger) and seller_save_settings, the only way the portal writes it (a partial patch, merged deeply).
--   * Saved views keep their own functions (seller_save_views, 0017) and are not touched here.
--   * A few settings are mirrored into businesses.profile so the public page can read them without reading seller_settings.
--   * seller_import_items (latest: 0056) now starts imported items from the saved low-stock level and "Only N left" choice.
-- Not ported: the branch's own message_outbox / seller_notify / reminder jobs. main already delivers SMS and email through
-- messages + claim_due_messages (0021), so notification preferences are stored here but not yet enforced on delivery.

create or replace function public.jsonb_deep_merge(a jsonb, b jsonb) returns jsonb
language plpgsql immutable as $$
declare
  k text;
  out jsonb := '{}';
begin
  if jsonb_typeof(a) <> 'object' or jsonb_typeof(b) <> 'object' then return b; end if;
  out := a;
  for k in select jsonb_object_keys(b) loop
    out := jsonb_set(out, array[k], case when out ? k then public.jsonb_deep_merge(out -> k, b -> k) else b -> k end, true);
  end loop;
  return out;
end $$;

-- True when free text carries a link or a phone-like run of seven or more digits.
create or replace function public.settings_text_bad(p text) returns boolean
language sql immutable as $$
  select p ~* '(https?:|www\.|wa\.me|bit\.ly|t\.me|\y[a-z0-9-]+\.(com|co|ke|org|net|io|me|app|link|ly|info|biz|dev)\y|[a-z0-9]/[a-z0-9])'
      or regexp_replace(p, '\{[a-z]+\}', '', 'g') ~ '(\+?[0-9][[:space:]().-]*){7,}'
$$;

create or replace function public.settings_greeting_bad(p text) returns boolean
language sql immutable as $$
  select btrim(p) = '' or char_length(p) > 160 or public.settings_text_bad(p)
      or exists (select 1 from regexp_matches(p, '\{([^{}]*)\}', 'g') m where m[1] not in ('item', 'price'))
      or regexp_replace(p, '\{(item|price)\}', '', 'g') ~ '[{}]'
$$;

create or replace function public.validate_seller_settings() returns trigger
language plpgsql as $$
declare
  s jsonb := new.settings;
  v jsonb;
  e jsonb;
  k text;
  ev text;
  crit text[] := array['expiry', 'payment', 'admin_question', 'suspension'];
  events text[] := array['expiry', 'payment', 'admin_question', 'suspension', 'change_decision', 'customer_report', 'removal', 'closure_reminder'];
  units jsonb;
  u jsonb;
  ids text[] := '{}';
begin
  if s ? 'idle_minutes' and (jsonb_typeof(s -> 'idle_minutes') <> 'number' or (s ->> 'idle_minutes') not in ('15', '30', '60', '120')) then
    raise exception 'invalid_idle_minutes';
  end if;

  if s ? 'appearance' then
    v := s -> 'appearance';
    if jsonb_typeof(v) <> 'object' then raise exception 'invalid_appearance'; end if;
    if v ? 'theme' and coalesce(v ->> 'theme', '') <> all (array['light', 'dark', 'system']) then raise exception 'invalid_appearance'; end if;
    if v ? 'text_size' and coalesce(v ->> 'text_size', '') <> all (array['normal', 'large', 'xlarge']) then raise exception 'invalid_appearance'; end if;
    if v ? 'density' and coalesce(v ->> 'density', '') <> all (array['comfortable', 'compact']) then raise exception 'invalid_appearance'; end if;
    if v ? 'card_view' and coalesce(v ->> 'card_view', '') <> all (array['comfortable', 'compact', 'list']) then raise exception 'invalid_appearance'; end if;
    foreach k in array array['reduce_motion', 'remember_card_view'] loop
      if v ? k and jsonb_typeof(v -> k) <> 'boolean' then raise exception 'invalid_appearance'; end if;
    end loop;
  end if;

  if s ? 'notifications' then
    v := s -> 'notifications';
    if jsonb_typeof(v) <> 'object' then raise exception 'invalid_notifications'; end if;
    if v ? 'events' then
      if jsonb_typeof(v -> 'events') <> 'object' then raise exception 'invalid_notifications'; end if;
      for ev in select jsonb_object_keys(v -> 'events') loop
        if not (ev = any (events)) then raise exception 'invalid_notifications'; end if;
        e := v -> 'events' -> ev;
        if jsonb_typeof(e) <> 'object' then raise exception 'invalid_notifications'; end if;
        foreach k in array array['in_app', 'sms', 'email'] loop
          if e ? k and jsonb_typeof(e -> k) <> 'boolean' then raise exception 'invalid_notifications'; end if;
        end loop;
        if ev = any (crit) and e ? 'in_app' and (e ->> 'in_app') <> 'true' then raise exception 'critical_in_app_required'; end if;
      end loop;
    end if;
    if v ? 'quiet_hours' then
      e := v -> 'quiet_hours';
      if jsonb_typeof(e) <> 'object' then raise exception 'invalid_quiet_hours'; end if;
      if e ? 'enabled' and jsonb_typeof(e -> 'enabled') <> 'boolean' then raise exception 'invalid_quiet_hours'; end if;
      foreach k in array array['start', 'end'] loop
        if e ? k and (jsonb_typeof(e -> k) <> 'string' or (e ->> k) !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$') then raise exception 'invalid_quiet_hours'; end if;
      end loop;
      if e ? 'start' and e ? 'end' and e ->> 'start' = e ->> 'end' then raise exception 'invalid_quiet_hours'; end if;
    end if;
  end if;

  if s ? 'catalog' then
    v := s -> 'catalog';
    if jsonb_typeof(v) <> 'object' then raise exception 'invalid_catalog'; end if;
    if v ? 'default_availability' and coalesce(v ->> 'default_availability', '') <> all (array['available', 'limited_stock', 'out_of_stock', 'unavailable']) then raise exception 'invalid_catalog'; end if;
    if v ? 'low_stock_threshold' and (jsonb_typeof(v -> 'low_stock_threshold') <> 'number' or (v ->> 'low_stock_threshold') !~ '^[0-9]{1,4}$' or (v ->> 'low_stock_threshold')::integer > 1000) then raise exception 'invalid_catalog'; end if;
    if v ? 'price_reminder_days' and coalesce(v ->> 'price_reminder_days', '') <> all (array['14', '30', '60']) then raise exception 'invalid_catalog'; end if;
    foreach k in array array['start_visible', 'show_only_n_left'] loop
      if v ? k and jsonb_typeof(v -> k) <> 'boolean' then raise exception 'invalid_catalog'; end if;
    end loop;
    if v ? 'default_units' then
      units := v -> 'default_units';
      if jsonb_typeof(units) <> 'object' or (select count(*) from jsonb_object_keys(units)) > 60 then raise exception 'invalid_catalog'; end if;
      for k in select jsonb_object_keys(units) loop
        if k !~ '^[A-Za-z0-9_-]{1,40}$' or jsonb_typeof(units -> k) <> 'array' or jsonb_array_length(units -> k) > 12 then raise exception 'invalid_catalog'; end if;
        for u in select value from jsonb_array_elements(units -> k) loop
          if jsonb_typeof(u) <> 'string' or char_length(btrim(u #>> '{}')) not between 1 and 20 then raise exception 'invalid_catalog'; end if;
        end loop;
      end loop;
    end if;
  end if;

  if s ? 'messaging' then
    v := s -> 'messaging';
    if jsonb_typeof(v) <> 'object' then raise exception 'invalid_messaging'; end if;
    if v ? 'whatsapp_greeting' and (jsonb_typeof(v -> 'whatsapp_greeting') <> 'string' or public.settings_greeting_bad(v ->> 'whatsapp_greeting')) then raise exception 'invalid_greeting'; end if;
    if v ? 'closure_reasons' then
      if jsonb_typeof(v -> 'closure_reasons') <> 'array' or jsonb_array_length(v -> 'closure_reasons') > 8 then raise exception 'invalid_closure_reasons'; end if;
      for e in select value from jsonb_array_elements(v -> 'closure_reasons') loop
        if jsonb_typeof(e) <> 'object' or jsonb_typeof(e -> 'id') <> 'string' or jsonb_typeof(e -> 'label') <> 'string'
           or (e ->> 'id') !~ '^[A-Za-z0-9_-]{1,40}$' or (e ->> 'id') = any (ids)
           or char_length(btrim(e ->> 'label')) not between 1 and 40 or public.settings_text_bad(e ->> 'label')
           or (e ? 'message' and (jsonb_typeof(e -> 'message') <> 'string' or char_length(e ->> 'message') > 140 or public.settings_text_bad(e ->> 'message'))) then
          raise exception 'invalid_closure_reasons';
        end if;
        ids := ids || (e ->> 'id');
      end loop;
    end if;
  end if;

  if s ? 'business' then
    v := s -> 'business';
    if jsonb_typeof(v) <> 'object' then raise exception 'invalid_business_prefs'; end if;
    if v ? 'show_closes_chip' and jsonb_typeof(v -> 'show_closes_chip') <> 'boolean' then raise exception 'invalid_business_prefs'; end if;
    if v ? 'partial_closure_message' and (jsonb_typeof(v -> 'partial_closure_message') <> 'string' or char_length(v ->> 'partial_closure_message') > 140 or public.settings_text_bad(v ->> 'partial_closure_message')) then raise exception 'invalid_business_prefs'; end if;
    if v ? 'announcement' then
      e := v -> 'announcement';
      if jsonb_typeof(e) <> 'object'
         or (e ? 'enabled' and jsonb_typeof(e -> 'enabled') <> 'boolean')
         or (e ? 'text' and (jsonb_typeof(e -> 'text') <> 'string' or char_length(e ->> 'text') > 280))
         or (e ? 'days' and (jsonb_typeof(e -> 'days') <> 'number' or (e ->> 'days') !~ '^[0-9]{1,2}$' or (e ->> 'days')::integer not between 1 and 90)) then
        raise exception 'invalid_business_prefs';
      end if;
    end if;
  end if;

  if s ? 'onboarding' then
    v := s -> 'onboarding';
    if jsonb_typeof(v) <> 'object' then raise exception 'invalid_onboarding'; end if;
    if v ? 'status' and coalesce(v ->> 'status', '') <> all (array['active', 'skipped', 'done']) then raise exception 'invalid_onboarding'; end if;
    if v ? 'qr_seen' and jsonb_typeof(v -> 'qr_seen') <> 'boolean' then raise exception 'invalid_onboarding'; end if;
    if v ? 'completed_at' and jsonb_typeof(v -> 'completed_at') not in ('string', 'null') then raise exception 'invalid_onboarding'; end if;
    if v ? 'dismissed_tips' then
      if jsonb_typeof(v -> 'dismissed_tips') <> 'array' or jsonb_array_length(v -> 'dismissed_tips') > 40 then raise exception 'invalid_onboarding'; end if;
      for u in select value from jsonb_array_elements(v -> 'dismissed_tips') loop
        if jsonb_typeof(u) <> 'string' or (u #>> '{}') !~ '^[A-Za-z0-9_-]{1,40}$' then raise exception 'invalid_onboarding'; end if;
      end loop;
    end if;
  end if;
  return new;
end $$;

drop trigger if exists t_seller_settings_validate on public.seller_settings;
create trigger t_seller_settings_validate before insert or update on public.seller_settings for each row execute function public.validate_seller_settings();

-- Saves a partial change. It can only touch seller_settings (and mirror the greeting for the public page);
-- status, plan and visibility rules are never reachable from here.
create or replace function public.seller_save_settings(p_patch jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_plan text;
  k text;
  v_settings jsonb;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then raise exception 'invalid_patch'; end if;
  foreach k in array coalesce((select array_agg(x) from jsonb_object_keys(p_patch) x), '{}') loop
    if k <> all (array['idle_minutes', 'appearance', 'notifications', 'catalog', 'messaging', 'business', 'onboarding']) then
      raise exception 'field_not_allowed:%', k using errcode = '42501';
    end if;
  end loop;
  select b.plan_key into v_plan from public.businesses b where b.id = v_id;
  if (p_patch #>> '{business,announcement,enabled}') = 'true' and v_plan <> 'premium' then
    raise exception 'premium_only' using errcode = '42501';
  end if;
  insert into public.seller_settings as s (business_id, settings) values (v_id, '{}') on conflict (business_id) do nothing;
  update public.seller_settings s set settings = public.jsonb_deep_merge(s.settings, p_patch) where s.business_id = v_id returning s.settings into v_settings;
  -- The customer-facing page reads these three from the public profile, so mirror them there.
  update public.businesses b set profile = coalesce(b.profile, '{}')
    || case when p_patch #>> '{messaging,whatsapp_greeting}' is not null then jsonb_build_object('whatsapp_greeting', p_patch #>> '{messaging,whatsapp_greeting}') else '{}'::jsonb end
    || case when p_patch #>> '{business,show_closes_chip}' is not null then jsonb_build_object('show_closes_chip', (p_patch #>> '{business,show_closes_chip}')::boolean) else '{}'::jsonb end
    || case when p_patch #>> '{business,partial_closure_message}' is not null then jsonb_build_object('partial_closure_message', p_patch #>> '{business,partial_closure_message}') else '{}'::jsonb end
  where b.id = v_id and (p_patch #>> '{messaging,whatsapp_greeting}' is not null or p_patch #>> '{business,show_closes_chip}' is not null or p_patch #>> '{business,partial_closure_message}' is not null);
  perform public.write_audit(v_id, 'settings_updated', 'seller_settings', v_id::text,
    jsonb_build_object('keys', coalesce((select jsonb_agg(x) from jsonb_object_keys(p_patch) x), '[]')));
  return v_settings;
end $$;

revoke all on function public.seller_save_settings(jsonb) from public, anon;
grant execute on function public.seller_save_settings(jsonb) to authenticated, service_role;

-- Used by the validation trigger, which runs as the seller. Pure functions with no table access.
revoke all on function public.settings_text_bad(text), public.settings_greeting_bad(text) from public, anon;
grant execute on function public.settings_text_bad(text), public.settings_greeting_bad(text) to authenticated, service_role;
revoke all on function public.jsonb_deep_merge(jsonb, jsonb) from public, anon;
grant execute on function public.jsonb_deep_merge(jsonb, jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Imports start from the saved catalog defaults
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.seller_import_items(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid := public.my_business_id();
  v_b public.businesses;
  r jsonb;
  v_pos integer := 0;
  v_row integer;
  v_sort integer;
  v_n integer := 0;
  v_tags text[];
  v_brand text;
  v_short text;
  v_pack text;
  v_terms text;
  v_inc text[];
  v_hl jsonb;
  v_specs jsonb;
  v_err text;
  v_thr integer;
  v_show boolean;
  v_skipped jsonb := '[]'::jsonb;
  k text;
  c_formula constant text[] := array['=','+','-','@'];
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into v_b from public.businesses where id = v_id;
  if v_b.plan_key <> 'premium' then raise exception 'premium_required' using errcode = 'P0001'; end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'no_rows' using errcode = 'P0001'; end if;
  if jsonb_array_length(p_rows) > 500 then raise exception 'too_many_rows' using errcode = 'P0001'; end if;
  -- New items start from the seller's saved catalog defaults (settings.catalog).
  select coalesce((st.settings #>> '{catalog,low_stock_threshold}')::integer, 3), coalesce((st.settings #>> '{catalog,show_only_n_left}')::boolean, false)
    into v_thr, v_show from (select 1) x left join public.seller_settings st on st.business_id = v_id;
  v_thr := coalesce(v_thr, 3);
  v_show := coalesce(v_show, false);
  select coalesce(max(sort), 0) into v_sort from public.items where business_id = v_id;
  for r in select * from jsonb_array_elements(p_rows) loop
    v_pos := v_pos + 1;
    v_row := case when coalesce(r ->> 'row', '') ~ '^\d{1,6}$' then (r ->> 'row')::integer else v_pos end;

    if left(coalesce(r ->> 'name', ''), 1) = any (c_formula) or left(coalesce(r ->> 'section', ''), 1) = any (c_formula)
       or left(coalesce(r ->> 'unit', ''), 1) = any (c_formula) then
      raise exception 'formula_rejected' using errcode = 'P0001';
    end if;

    -- The optional details. A problem here marks the row as skipped; v_err keeps the first one found.
    v_err := null;
    foreach k in array array['brand', 'short_description', 'pack_size', 'terms'] loop
      if r ? k and jsonb_typeof(r -> k) not in ('string', 'null') then v_err := coalesce(v_err, 'invalid_details'); end if;
      if left(coalesce(r ->> k, ''), 1) = any (c_formula) then v_err := coalesce(v_err, 'formula_rejected'); end if;
    end loop;
    if (r ? 'includes' and jsonb_typeof(r -> 'includes') not in ('array', 'null'))
       or (r ? 'highlights' and jsonb_typeof(r -> 'highlights') not in ('array', 'null'))
       or (r ? 'specs' and jsonb_typeof(r -> 'specs') not in ('array', 'null')) then
      v_err := coalesce(v_err, 'invalid_details');
    end if;

    v_brand := nullif(btrim(coalesce(r ->> 'brand', '')), '');
    v_short := nullif(btrim(coalesce(r ->> 'short_description', '')), '');
    v_pack := nullif(btrim(coalesce(r ->> 'pack_size', '')), '');
    v_terms := nullif(btrim(coalesce(r ->> 'terms', '')), '');
    v_inc := '{}';
    v_hl := '[]'::jsonb;
    v_specs := '[]'::jsonb;

    if v_err is null then
      if exists (select 1 from jsonb_array_elements(case when jsonb_typeof(r -> 'includes') = 'array' then r -> 'includes' else '[]'::jsonb end) e where jsonb_typeof(e) <> 'string') then
        v_err := 'invalid_details';
      else
        select coalesce(array_agg(btrim(x.t) order by x.n) filter (where btrim(x.t) <> ''), '{}') into v_inc
          from jsonb_array_elements_text(case when jsonb_typeof(r -> 'includes') = 'array' then r -> 'includes' else '[]'::jsonb end) with ordinality as x(t, n);
        if exists (select 1 from unnest(v_inc) e where left(e, 1) = any (c_formula)) then v_err := 'formula_rejected'; end if;
      end if;
    end if;

    -- Highlights and specs are normalised as seller_save_item does: a missing group becomes "Features & Specs", a blank lead is dropped.
    if v_err is null and jsonb_typeof(r -> 'highlights') = 'array' then
      select coalesce(jsonb_agg(
        case when jsonb_typeof(x.e) = 'object' and (jsonb_typeof(x.e -> 'title') = 'null' or btrim(coalesce(x.e ->> 'title', 'x')) = '') then x.e - 'title' else x.e end
        order by x.n), '[]'::jsonb) into v_hl
        from jsonb_array_elements(r -> 'highlights') with ordinality as x(e, n);
      if exists (select 1 from jsonb_array_elements(v_hl) e where left(coalesce(e ->> 'text', ''), 1) = any (c_formula) or left(coalesce(e ->> 'title', ''), 1) = any (c_formula)) then
        v_err := 'formula_rejected';
      end if;
    end if;
    if v_err is null and jsonb_typeof(r -> 'specs') = 'array' then
      select coalesce(jsonb_agg(
        case when jsonb_typeof(x.e) = 'object' and (not x.e ? 'group' or jsonb_typeof(x.e -> 'group') = 'null')
          then x.e || jsonb_build_object('group', 'Features & Specs') else x.e end
        order by x.n), '[]'::jsonb) into v_specs
        from jsonb_array_elements(r -> 'specs') with ordinality as x(e, n);
      if exists (select 1 from jsonb_array_elements(v_specs) e where left(coalesce(e ->> 'label', ''), 1) = any (c_formula) or left(coalesce(e ->> 'value', ''), 1) = any (c_formula)) then
        v_err := 'formula_rejected';
      end if;
    end if;

    if v_err is null and (char_length(coalesce(v_brand, '')) > 60 or char_length(coalesce(v_short, '')) > 140
       or char_length(coalesce(v_pack, '')) > 40 or char_length(coalesce(v_terms, '')) > 500
       or not public.item_includes_valid(v_inc) or not public.item_highlights_valid(v_hl) or not public.item_specs_valid(v_specs)) then
      v_err := 'invalid_details';
    end if;

    if v_err is not null then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('row', v_row, 'error', v_err));
      continue;
    end if;

    select coalesce(array_agg(t), '{}') into v_tags from jsonb_array_elements_text(coalesce(r -> 'tags', '[]'::jsonb)) as t;
    v_sort := v_sort + 1;
    insert into public.items (business_id, name, section, price, price_max, price_type, unit, availability, tags, visible, draft, sort,
      brand, short_description, pack_size, terms, includes, highlights, specs, low_stock_threshold, show_stock_count)
    values (v_id, btrim(r ->> 'name'), nullif(btrim(coalesce(r ->> 'section', '')), ''), (r ->> 'price')::numeric, (r ->> 'price_max')::numeric,
      coalesce(r ->> 'price_type', 'fixed'), nullif(btrim(coalesce(r ->> 'unit', '')), ''), coalesce(r ->> 'availability', 'available'), v_tags, false, true, v_sort,
      v_brand, v_short, v_pack, v_terms, v_inc, v_hl, v_specs, v_thr, v_show);
    v_n := v_n + 1;
  end loop;
  perform public.write_audit(v_id, 'items_imported', 'item', null, jsonb_build_object('count', v_n));
  return jsonb_build_object('created', v_n, 'skipped', v_skipped);
end $function$;

$m_0062_seller_settings$),
    ('0063_gallery_team_schedule', $m_0063_gallery_team_schedule$
-- 0063_gallery_team_schedule.sql
-- Gallery photos, team members (with the services they do) and the weekly class timetable (ported from s7).
-- Offers, flash sales and the QR poster are already on main, so only these three parts are added.
--
--   * Pictures are Cloudinary ids like every other shop picture: "<biz>/gallery/<uuid>" and "<biz>/staff/<uuid>".
--     media_uploads accepts the new purposes 'gallery' and 'staff'; the sweep, the claim and the delete triggers know them.
--   * Gallery photos are soft deleted first (deleted_at, so Undo works) and hard deleted afterwards.
--   * Suspended sellers can read but not write (restrictive policies, same as offer_items).
-- Re-runnable: every statement can be run twice.

create extension if not exists btree_gist with schema extensions;

-- ---------------------------------------------------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------------------------------------------------
create table if not exists public.gallery_photos (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  path text not null unique,
  mime text not null,
  width integer check (width > 0),
  height integer check (height > 0),
  size_bytes bigint check (size_bytes >= 0),
  caption text check (char_length(caption) <= 120),
  sort integer not null default 0,
  pair_id uuid,
  pair_role text check (pair_role in ('before','after')),
  deleted_at timestamptz,
  hidden_by_admin boolean not null default false,
  admin_hide_reason text,
  admin_status text check (admin_status in ('ok','hidden','removed')),
  admin_reason text,
  removed_by_admin boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((pair_id is null) = (pair_role is null))
);
create index if not exists gallery_photos_business_idx on public.gallery_photos (business_id, sort);
create unique index if not exists gallery_photos_pair_idx on public.gallery_photos (business_id, pair_id, pair_role) where pair_id is not null;

create table if not exists public.staff_members (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  name text not null check (char_length(name) between 2 and 80),
  role text check (char_length(role) <= 60),
  specialties text[] not null default '{}' check (cardinality(specialties) <= 10),
  photo_path text,
  sort integer not null default 0,
  hidden_by_admin boolean not null default false,
  admin_hide_reason text,
  admin_status text check (admin_status in ('ok','hidden','removed')),
  admin_reason text,
  removed_by_admin boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists staff_members_business_idx on public.staff_members (business_id, sort);

create table if not exists public.staff_services (
  staff_id uuid not null references public.staff_members(id) on delete cascade,
  item_id uuid not null references public.items(id) on delete cascade,
  business_id uuid not null references public.businesses(id) on delete cascade,
  primary key (staff_id, item_id)
);

create table if not exists public.timetable_slots (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses(id) on delete cascade,
  day_of_week smallint not null check (day_of_week between 1 and 7),
  start_time time not null,
  end_time time not null,
  class_name text not null check (char_length(class_name) between 2 and 80),
  staff_id uuid references public.staff_members(id) on delete set null,
  hidden_by_admin boolean not null default false,
  admin_hide_reason text,
  admin_status text check (admin_status in ('ok','hidden','removed')),
  admin_reason text,
  removed_by_admin boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_time > start_time)
);
create index if not exists timetable_slots_business_idx on public.timetable_slots (business_id, day_of_week, start_time);
alter table public.timetable_slots drop constraint if exists timetable_trainer_no_overlap;
alter table public.timetable_slots add constraint timetable_trainer_no_overlap exclude using gist (
  staff_id with =,
  day_of_week with =,
  tsrange(date '2000-01-01' + start_time, date '2000-01-01' + end_time) with &&
) where (staff_id is not null and coalesce(admin_status, 'ok') = 'ok' and not removed_by_admin and not hidden_by_admin);

do $$
declare t text;
begin
  foreach t in array array['gallery_photos','staff_members','timetable_slots'] loop
    execute format('drop trigger if exists %I on public.%I', 't_' || t || '_touch', t);
    execute format('create trigger %I before update on public.%I for each row execute function public.touch_updated_at()', 't_' || t || '_touch', t);
    execute format('drop trigger if exists %I on public.%I', 't_' || t || '_protect', t);
    execute format('create trigger %I before insert or update on public.%I for each row execute function public.protect_admin_cols()', 't_' || t || '_protect', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------------------------------------------------
-- Rules
-- ---------------------------------------------------------------------------------------------------------------------
create or replace function public.is_counted_gallery(g public.gallery_photos) returns boolean
language sql immutable as
$$ select g.deleted_at is null and coalesce(g.admin_status, 'ok') = 'ok' and not g.removed_by_admin and not g.hidden_by_admin $$;

create or replace function public.validate_gallery_photo() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_cat text;
begin
  if public.actor_role() = 'admin' then return new; end if;
  if tg_op = 'INSERT' then
    if not public.is_cloudinary_id(new.path) or new.path not like new.business_id::text || '/gallery/%' then
      raise exception 'path_not_owned' using errcode = '42501';
    end if;
  elsif public.actor_role() = 'seller' then
    if (new.business_id, new.path, new.mime, new.width, new.height, new.size_bytes)
       is distinct from (old.business_id, old.path, old.mime, old.width, old.height, old.size_bytes) then
      raise exception 'gallery_columns_protected' using errcode = '42501';
    end if;
  end if;
  if new.pair_id is not null then
    select b.category_id into v_cat from public.businesses b where b.id = new.business_id;
    if v_cat not in ('barbershop', 'salon-beauty') then raise exception 'pair_category'; end if;
  end if;
  return new;
end $$;
drop trigger if exists t_gallery_photos_1_validate on public.gallery_photos;
create trigger t_gallery_photos_1_validate before insert or update on public.gallery_photos for each row execute function public.validate_gallery_photo();

create or replace function public.enforce_gallery_limit() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_plan text; v_limit integer; v_count integer;
begin
  if public.actor_role() = 'admin' then return new; end if;
  if not public.is_counted_gallery(new) then return new; end if;
  if tg_op = 'UPDATE' and public.is_counted_gallery(old) then return new; end if;
  perform pg_advisory_xact_lock(hashtext(new.business_id::text || 'gallery_photos'));
  select b.plan_key into v_plan from public.businesses b where b.id = new.business_id;
  select (case v_plan when 'premium' then g.premium else g.standard end ->> 'galleryPhotos')::integer into v_limit
    from public.global_limits g where g.id = 1;
  if v_limit is null then return new; end if;
  select count(*) into v_count from public.gallery_photos p
    where p.business_id = new.business_id and p.id <> new.id and public.is_counted_gallery(p);
  if v_count >= v_limit then raise exception 'limit_reached:gallery_photos' using errcode = 'P0001'; end if;
  return new;
end $$;
drop trigger if exists t_gallery_photos_2_limit on public.gallery_photos;
create trigger t_gallery_photos_2_limit before insert or update on public.gallery_photos for each row execute function public.enforce_gallery_limit();

create or replace function public.validate_staff_member() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if public.actor_role() = 'admin' then return new; end if;
  if new.photo_path is not null and (not public.is_cloudinary_id(new.photo_path) or new.photo_path not like new.business_id::text || '/staff/%') then
    raise exception 'invalid_photo_path';
  end if;
  return new;
end $$;
drop trigger if exists t_staff_members_1_validate on public.staff_members;
create trigger t_staff_members_1_validate before insert or update on public.staff_members for each row execute function public.validate_staff_member();

create or replace function public.validate_staff_service() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_plan text; s public.staff_members; i public.items;
begin
  if public.actor_role() = 'admin' then return new; end if;
  select * into s from public.staff_members where id = new.staff_id;
  select * into i from public.items where id = new.item_id;
  if s.id is null or i.id is null or s.business_id <> new.business_id or i.business_id <> new.business_id then
    raise exception 'item_not_owned';
  end if;
  select b.plan_key into v_plan from public.businesses b where b.id = new.business_id;
  if v_plan <> 'premium' and tg_op = 'INSERT' then raise exception 'premium_only:services'; end if;
  return new;
end $$;
drop trigger if exists t_staff_services_validate on public.staff_services;
create trigger t_staff_services_validate before insert or update on public.staff_services for each row execute function public.validate_staff_service();

create or replace function public.validate_timetable_slot() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_plan text; v_cat text; v_owner uuid;
begin
  if public.actor_role() = 'admin' then return new; end if;
  select b.plan_key, b.category_id into v_plan, v_cat from public.businesses b where b.id = new.business_id;
  if tg_op = 'INSERT' and v_plan <> 'premium' then raise exception 'premium_only:timetable'; end if;
  if v_cat not in ('salon-beauty', 'gym-fitness') then raise exception 'timetable_category'; end if;
  if new.staff_id is not null then
    select s.business_id into v_owner from public.staff_members s where s.id = new.staff_id;
    if v_owner is distinct from new.business_id then raise exception 'trainer_not_owned'; end if;
  end if;
  return new;
end $$;
drop trigger if exists t_timetable_slots_1_validate on public.timetable_slots;
create trigger t_timetable_slots_1_validate before insert or update on public.timetable_slots for each row execute function public.validate_timetable_slot();

do $$
declare fn text;
begin
  foreach fn in array array['validate_gallery_photo()', 'enforce_gallery_limit()', 'validate_staff_member()', 'validate_staff_service()', 'validate_timetable_slot()'] loop
    execute format('revoke all on function public.%s from public, anon', fn);
    execute format('grant execute on function public.%s to authenticated, service_role', fn);
  end loop;
end $$;

-- ---------------------------------------------------------------------------------------------------------------------
-- Row level security
-- ---------------------------------------------------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['gallery_photos','staff_members','staff_services','timetable_slots'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', 'admin all ' || t, t);
    execute format('create policy %I on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())', 'admin all ' || t, t);
    execute format('drop policy if exists %I on public.%I', 'seller reads own ' || t, t);
    execute format('create policy %I on public.%I for select to authenticated using (business_id = public.my_business_id())', 'seller reads own ' || t, t);
    execute format('drop policy if exists %I on public.%I', 'seller inserts own ' || t, t);
    execute format('create policy %I on public.%I for insert to authenticated with check (business_id = public.my_business_id())', 'seller inserts own ' || t, t);
    execute format('drop policy if exists %I on public.%I', 'seller updates own ' || t, t);
    execute format('create policy %I on public.%I for update to authenticated using (business_id = public.my_business_id()) with check (business_id = public.my_business_id())', 'seller updates own ' || t, t);
    execute format('drop policy if exists %I on public.%I', 'seller deletes own ' || t, t);
    execute format('create policy %I on public.%I for delete to authenticated using (business_id = public.my_business_id())', 'seller deletes own ' || t, t);
    execute format('drop policy if exists %I on public.%I', 'suspended cannot insert ' || t, t);
    execute format('create policy %I on public.%I as restrictive for insert to authenticated with check (public.is_admin() or not public.my_business_suspended())', 'suspended cannot insert ' || t, t);
    execute format('drop policy if exists %I on public.%I', 'suspended cannot update ' || t, t);
    execute format('create policy %I on public.%I as restrictive for update to authenticated using (public.is_admin() or not public.my_business_suspended()) with check (public.is_admin() or not public.my_business_suspended())', 'suspended cannot update ' || t, t);
    execute format('drop policy if exists %I on public.%I', 'suspended cannot delete ' || t, t);
    execute format('create policy %I on public.%I as restrictive for delete to authenticated using (public.is_admin() or not public.my_business_suspended())', 'suspended cannot delete ' || t, t);
  end loop;
end $$;
-- A live photo must be soft deleted (Undo window) before the row can be removed.
drop policy if exists "seller deletes own gallery_photos" on public.gallery_photos;
create policy "seller deletes own gallery_photos" on public.gallery_photos for delete to authenticated
  using (business_id = public.my_business_id() and deleted_at is not null);

revoke all on public.gallery_photos, public.staff_members, public.staff_services, public.timetable_slots from public, anon;
grant select, insert, update, delete on public.gallery_photos, public.staff_members, public.staff_services, public.timetable_slots to authenticated;
grant all on public.gallery_photos, public.staff_members, public.staff_services, public.timetable_slots to service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- Pictures: new upload purposes, and cleanup of files nothing points at any more
-- ---------------------------------------------------------------------------------------------------------------------
do $$
declare c record;
begin
  for c in
    select conname from pg_constraint
    where conrelid = 'public.media_uploads'::regclass and contype = 'c' and conname = 'media_uploads_purpose_ck'
  loop
    execute format('alter table public.media_uploads drop constraint %I', c.conname);
  end loop;
end $$;
alter table public.media_uploads add constraint media_uploads_purpose_ck
  check (purpose in ('item_photo', 'item_video', 'logo', 'cover', 'gallery', 'staff'));

create or replace function public.media_register_upload(p_business uuid, p_item uuid, p_purpose text, p_public_id text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_purpose not in ('item_photo', 'item_video', 'logo', 'cover', 'gallery', 'staff') then raise exception 'invalid_purpose'; end if;
  if p_purpose = 'item_video' then
    if p_item is null or not exists (select 1 from public.items i where i.id = p_item and i.business_id = p_business) then raise exception 'item_not_found'; end if;
    if not public.is_storage_video_path(p_public_id) or p_public_id not like p_business::text || '/' || p_item::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
  else
    if not public.is_cloudinary_id(p_public_id) or p_public_id not like p_business::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
    if p_purpose = 'item_photo' then
      if p_item is null or not exists (select 1 from public.items i where i.id = p_item and i.business_id = p_business) then raise exception 'item_not_found'; end if;
    elsif p_item is not null then
      raise exception 'invalid_purpose';
    elsif p_purpose in ('gallery', 'staff') and p_public_id not like p_business::text || '/' || p_purpose || '/%' then
      raise exception 'path_not_owned' using errcode = '42501';
    end if;
  end if;
  insert into public.media_uploads (public_id, business_id, item_id, purpose) values (p_public_id, p_business, p_item, p_purpose);
end $$;

-- Is anything still pointing at this file? One definition for the claim, the per-seller claim and the sweep.
create or replace function public.media_in_use(p_id text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.item_media m where m.path = p_id)
      or exists (select 1 from public.businesses b where b.logo_path = p_id or b.cover_path = p_id)
      or exists (select 1 from public.gallery_photos g where g.path = p_id)
      or exists (select 1 from public.staff_members s where s.photo_path = p_id)
$$;
revoke all on function public.media_in_use(text) from public, anon, authenticated;
grant execute on function public.media_in_use(text) to service_role;

create or replace function public.media_gc_claim(p_limit integer default 50) returns table (public_id text)
language plpgsql security definer set search_path = public as $$
begin
  delete from public.media_gc g where g.next_try_at <= now() and public.media_in_use(g.public_id);
  return query
  update public.media_gc g set attempts = g.attempts + 1, next_try_at = now() + interval '10 minutes'
  where g.public_id in (select q.public_id from public.media_gc q where q.next_try_at <= now() order by q.next_try_at, q.queued_at limit greatest(1, least(coalesce(p_limit, 50), 100)) for update skip locked)
  returning g.public_id;
end $$;

create or replace function public.media_gc_claim_for_business(p_business uuid, p_limit integer default 20) returns table (public_id text)
language plpgsql security definer set search_path = public as $$
begin
  delete from public.media_gc g
  where g.next_try_at <= now() and g.public_id like p_business::text || '/%' and public.media_in_use(g.public_id);
  return query
  update public.media_gc g set attempts = g.attempts + 1, next_try_at = now() + interval '10 minutes'
  where g.public_id in (
    select q.public_id from public.media_gc q
    where q.next_try_at <= now() and q.public_id like p_business::text || '/%'
    order by q.next_try_at, q.queued_at
    limit greatest(1, least(coalesce(p_limit, 20), 50))
    for update skip locked)
  returning g.public_id;
end $$;

create or replace function public.media_sweep_orphans(p_grace interval default interval '1 hour') returns integer
language plpgsql security definer set search_path = public as $$
declare queued integer;
begin
  with put as (
    insert into public.media_gc (public_id, reason)
    select u.public_id, 'unattached_upload' from public.media_uploads u
    where u.created_at < now() - (case when u.purpose = 'item_video' then greatest(p_grace, interval '3 hours') else p_grace end)
      and not public.media_in_use(u.public_id)
    on conflict (public_id) do nothing
    returning 1
  )
  select count(*) into queued from put;
  delete from public.media_uploads u
  where u.created_at < now() - (case when u.purpose = 'item_video' then greatest(p_grace, interval '3 hours') else p_grace end);
  return queued;
end $$;

-- A removed gallery photo, or a staff picture that was replaced or removed, is queued in the same transaction.
create or replace function public.media_gc_from_shop_pictures() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_table_name = 'gallery_photos' then
    if public.is_cloudinary_id(old.path) then
      insert into public.media_gc (public_id, reason) values (old.path, 'gallery_removed') on conflict (public_id) do nothing;
    end if;
  elsif tg_op = 'DELETE' or old.photo_path is distinct from new.photo_path then
    if public.is_cloudinary_id(old.photo_path) then
      insert into public.media_gc (public_id, reason) values (old.photo_path, 'staff_photo_removed') on conflict (public_id) do nothing;
    end if;
  end if;
  return null;
end $$;
revoke all on function public.media_gc_from_shop_pictures() from public, anon, authenticated;
drop trigger if exists gallery_photos_media_gc on public.gallery_photos;
create trigger gallery_photos_media_gc after delete on public.gallery_photos for each row execute function public.media_gc_from_shop_pictures();
drop trigger if exists staff_members_media_gc on public.staff_members;
create trigger staff_members_media_gc after update of photo_path or delete on public.staff_members for each row execute function public.media_gc_from_shop_pictures();

-- A deleted business takes its gallery rows with it (cascade): queue their files too.
create or replace function public.media_gc_from_business() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    insert into public.media_gc (public_id, reason)
    select x, 'business_deleted' from unnest(array[old.logo_path, old.cover_path]) as x
    where public.is_cloudinary_id(x)
    on conflict (public_id) do nothing;
    insert into public.media_gc (public_id, reason)
    select x, 'business_deleted' from (
      select g.path as x from public.gallery_photos g where g.business_id = old.id
      union all select s.photo_path from public.staff_members s where s.business_id = old.id
    ) q where public.is_cloudinary_id(x)
    on conflict (public_id) do nothing;
    return null;
  end if;
  insert into public.media_gc (public_id, reason)
  select x, 'shop_image_replaced'
  from unnest(array[
    case when old.logo_path is distinct from new.logo_path then old.logo_path end,
    case when old.cover_path is distinct from new.cover_path then old.cover_path end
  ]) as x
  where public.is_cloudinary_id(x)
  on conflict (public_id) do nothing;
  return null;
end $$;

-- ---------------------------------------------------------------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------------------------------------------------------------
-- Service only: called by seller-media-finalize once Cloudinary's signature on the upload has been checked.
create or replace function public.attach_gallery_photo(
  p_business uuid, p_path text, p_mime text, p_width integer, p_height integer, p_size bigint,
  p_caption text default null, p_pair_id uuid default null, p_pair_role text default null
) returns uuid language plpgsql security definer set search_path = public as $$
declare v_sort integer; v_id uuid;
begin
  if not public.is_cloudinary_id(p_path) or p_path not like p_business::text || '/gallery/%' then
    raise exception 'path_not_owned' using errcode = '42501';
  end if;
  select coalesce(max(g.sort) + 1, 0) into v_sort from public.gallery_photos g where g.business_id = p_business;
  insert into public.gallery_photos (business_id, path, mime, width, height, size_bytes, caption, sort, pair_id, pair_role)
  values (p_business, p_path, p_mime, p_width, p_height, p_size, nullif(trim(p_caption), ''), v_sort, p_pair_id, p_pair_role)
  returning id into v_id;
  return v_id;
end $$;
revoke all on function public.attach_gallery_photo(uuid, text, text, integer, integer, bigint, text, uuid, text) from public, anon, authenticated;
grant execute on function public.attach_gallery_photo(uuid, text, text, integer, integer, bigint, text, uuid, text) to service_role;

-- Service only: lets seller-media-sign say "limit reached" before the seller waits on an upload.
create or replace function public.gallery_room(p_business uuid) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare v_plan text; v_limit integer; v_count integer;
begin
  select b.plan_key into v_plan from public.businesses b where b.id = p_business;
  select (case v_plan when 'premium' then g.premium else g.standard end ->> 'galleryPhotos')::integer into v_limit from public.global_limits g where g.id = 1;
  if v_limit is null then return true; end if;
  select count(*) into v_count from public.gallery_photos p where p.business_id = p_business and public.is_counted_gallery(p);
  return v_count < v_limit;
end $$;
revoke all on function public.gallery_room(uuid) from public, anon, authenticated;
grant execute on function public.gallery_room(uuid) to service_role;

create or replace function public.seller_reorder_gallery(p_ids uuid[]) returns integer
language plpgsql set search_path = public as $$
declare v_bid uuid := public.my_business_id(); v_n integer;
begin
  perform public.assert_seller_active();
  if v_bid is null then raise exception 'forbidden' using errcode = '42501'; end if;
  if (select count(distinct x) from unnest(p_ids) x) <> coalesce(cardinality(p_ids), 0) then raise exception 'invalid_order'; end if;
  update public.gallery_photos g set sort = o.ord - 1
    from unnest(p_ids) with ordinality as o(id, ord)
    where g.id = o.id and g.business_id = v_bid and g.deleted_at is null;
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function public.seller_reorder_gallery(uuid[]) from public, anon;
grant execute on function public.seller_reorder_gallery(uuid[]) to authenticated, service_role;

create or replace function public.seller_gallery_usage() returns integer
language plpgsql stable security definer set search_path = public as $$
begin
  perform public.assert_seller_active();
  return (select count(*)::integer from public.gallery_photos p where p.business_id = public.my_business_id() and public.is_counted_gallery(p));
end $$;
revoke all on function public.seller_gallery_usage() from public, anon;
grant execute on function public.seller_gallery_usage() to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- Public views (what the shop page will read)
-- ---------------------------------------------------------------------------------------------------------------------
create or replace view public.public_gallery_photos with (security_invoker = false) as
select g.id, g.business_id, b.slug as business_slug, g.path, g.caption, g.sort, g.pair_id, g.pair_role, g.width, g.height
from public.gallery_photos g
join public.businesses b on b.id = g.business_id
where b.status = 'live' and public.is_counted_gallery(g);

create or replace view public.public_staff with (security_invoker = false) as
select s.id, s.business_id, b.slug as business_slug, s.name, s.role, s.specialties, s.photo_path, s.sort,
       case when b.plan_key = 'premium'
            then coalesce((select array_agg(ss.item_id) from public.staff_services ss where ss.staff_id = s.id), '{}'::uuid[])
            else '{}'::uuid[] end as item_ids
from public.staff_members s
join public.businesses b on b.id = s.business_id
where b.status = 'live' and not s.hidden_by_admin and not s.removed_by_admin and coalesce(s.admin_status, 'ok') = 'ok';

create or replace view public.public_timetable with (security_invoker = false) as
select t.id, t.business_id, b.slug as business_slug, t.day_of_week, t.start_time, t.end_time, t.class_name, t.staff_id
from public.timetable_slots t
join public.businesses b on b.id = t.business_id
where b.status = 'live' and b.plan_key = 'premium'
  and not t.hidden_by_admin and not t.removed_by_admin and coalesce(t.admin_status, 'ok') = 'ok';

revoke all on public.public_gallery_photos, public.public_staff, public.public_timetable from public;
grant select on public.public_gallery_photos, public.public_staff, public.public_timetable to anon, authenticated, service_role;

$m_0063_gallery_team_schedule$),
    ('0064_seller_prefs_enforced', $m_0064_seller_prefs_enforced$
-- 0064_seller_prefs_enforced.sql
-- Makes the seller's saved preferences (0062) actually do something.
--
--   1. Notification preferences. A trigger on `messages` applies the seller's choices at the moment a message is queued:
--        * critical events (expiry, payment, admin questions, suspension) are never held back or dropped;
--        * a non-critical text or email the seller switched off is not queued at all;
--        * a non-critical in-app message the seller switched off arrives already read (no unread badge);
--        * a non-critical text or email waits for the seller's own quiet hours to end (Nairobi time, like site quiet hours).
--      Messages with no matching event (approvals, general notes from the team) are never touched.
--   2. The public shop page can read three seller settings through public_businesses.shop_settings:
--      the WhatsApp greeting, whether to show "Closes ..." text, and the partial-closure message (only when something
--      is sold out or unavailable).
-- Additive and safe to run again.

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. Notification preferences
-- ---------------------------------------------------------------------------------------------------------------------
-- Which seller event a message belongs to, from its kind. null = not covered by a preference.
create or replace function public.message_event_key(p_kind text) returns text
language sql immutable as $$
  select case p_kind
    when 'reminder' then 'expiry' when 'grace' then 'expiry' when 'expiry' then 'expiry'
    when 'payment' then 'payment'
    when 'question' then 'admin_question'
    when 'strike' then 'suspension'
    when 'change' then 'change_decision'
    when 'report' then 'customer_report'
    when 'removal' then 'removal'
    else null end
$$;

create or replace function public.event_is_critical(p_event text) returns boolean
language sql immutable as $$ select p_event in ('expiry', 'payment', 'admin_question', 'suspension') $$;

-- The channel defaults the seller screen shows when nothing has been saved.
create or replace function public.notify_default(p_event text, p_channel text) returns boolean
language sql immutable as $$
  select case p_channel
    when 'in_app' then true
    when 'sms' then p_event <> 'customer_report' and p_event <> 'closure_reminder'
    else false end
$$;

create or replace function public.notify_wanted(p_settings jsonb, p_event text, p_channel text) returns boolean
language sql immutable as $$
  select coalesce((p_settings #>> array['notifications', 'events', p_event, p_channel])::boolean, public.notify_default(p_event, p_channel))
$$;

-- When the seller's own quiet hours end, or null when they are not in them (or have none on).
create or replace function public.notify_quiet_release(p_settings jsonb, p_now timestamptz) returns timestamptz
language plpgsql immutable as $$
declare
  q jsonb := coalesce(p_settings -> 'notifications' -> 'quiet_hours', '{}'::jsonb);
  s time := coalesce((q ->> 'start')::time, time '21:00');
  e time := coalesce((q ->> 'end')::time, time '07:00');
  t time := (p_now at time zone 'Africa/Nairobi')::time;
  d date := (p_now at time zone 'Africa/Nairobi')::date;
  inside boolean;
  r timestamptz;
begin
  if coalesce((q ->> 'enabled')::boolean, true) is not true or s = e then return null; end if;
  inside := case when s < e then t >= s and t < e else t >= s or t < e end;
  if not inside then return null; end if;
  r := (d + e) at time zone 'Africa/Nairobi';
  if r <= p_now then r := ((d + 1) + e) at time zone 'Africa/Nairobi'; end if;
  return r;
exception when others then
  return null;   -- a malformed setting must never hold back a message
end $$;

create or replace function public.messages_apply_seller_prefs() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_event text := public.message_event_key(new.kind);
  v_settings jsonb;
  v_release timestamptz;
begin
  if new.business_id is null or v_event is null or public.event_is_critical(v_event) or new.transactional then return new; end if;
  select s.settings into v_settings from public.seller_settings s where s.business_id = new.business_id;
  v_settings := coalesce(v_settings, '{}'::jsonb);
  if not public.notify_wanted(v_settings, v_event, new.channel) then
    if new.channel = 'in_app' then
      new.read_at := coalesce(new.read_at, now());
      return new;
    end if;
    return null;   -- the seller does not want this text or email: it is never queued
  end if;
  if new.channel in ('sms', 'email') and new.status = 'queued' then
    v_release := public.notify_quiet_release(v_settings, greatest(coalesce(new.scheduled_at, now()), now()));
    if v_release is not null then new.scheduled_at := v_release; end if;
  end if;
  return new;
end $$;
revoke all on function public.messages_apply_seller_prefs() from public, anon, authenticated;

drop trigger if exists t_messages_seller_prefs on public.messages;
create trigger t_messages_seller_prefs before insert on public.messages for each row execute function public.messages_apply_seller_prefs();

revoke all on function public.message_event_key(text), public.event_is_critical(text), public.notify_default(text, text),
  public.notify_wanted(jsonb, text, text), public.notify_quiet_release(jsonb, timestamptz) from public, anon, authenticated;
grant execute on function public.message_event_key(text), public.event_is_critical(text), public.notify_default(text, text),
  public.notify_wanted(jsonb, text, text), public.notify_quiet_release(jsonb, timestamptz) to service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 2. Seller settings the public shop page reads
-- ---------------------------------------------------------------------------------------------------------------------
-- New column goes last so the view can be replaced in place.
create or replace view public.public_businesses with (security_barrier = true) as
select
  b.id, b.slug, b.name, b.category_id, b.plan_key, b.verification_level, b.tagline, b.description,
  b.phone, b.whatsapp, b.socials, b.amenities, b.payment_methods, b.delivery_area,
  b.county, b.town, b.address, b.lat, b.lng, b.logo_path, b.cover_path, b.tags, b.hours, b.created_at,
  public.public_exceptions(b.exceptions) as exceptions,
  (select count(*)::integer from public.items i
    where i.business_id = b.id and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
      and public.item_is_listed(i.availability)) as product_count,
  b.timezone,
  jsonb_strip_nulls(jsonb_build_object(
    'whatsapp_greeting', b.profile ->> 'whatsapp_greeting',
    'show_closes_chip', case when b.profile ? 'show_closes_chip' then (b.profile ->> 'show_closes_chip')::boolean end,
    'partial_closure_message',
      case when exists (select 1 from public.items i
                         where i.business_id = b.id and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
                           and not public.item_is_listed(i.availability))
           then b.profile ->> 'partial_closure_message' end
  )) as shop_settings
from public.businesses b
where public.business_is_visible(b);
revoke all on public.public_businesses from public;
grant select on public.public_businesses to anon, authenticated, service_role;

$m_0064_seller_prefs_enforced$),
    ('0065_seller_set_hours', $m_0065_seller_set_hours$
-- 0065_seller_set_hours.sql
-- Sellers can now set their weekly opening hours themselves. Until now nothing let them: seller_update_profile refuses an
-- `hours` field and sellers cannot write the column directly, so only staff could change it.
--
-- seller_set_hours(p_hours) takes { mon: ["08:00","18:00"], ... } with keys mon..sun. A day that is null or left out is
-- closed. An end earlier than the start runs past midnight (see intervalsOn in shared/src/utils.js); start = end is refused,
-- because the app reads it as neither zero hours nor a full day (a full day is stored as 00:00 to 23:59).
-- The same rules live in shared/src/seller/hours.js (validateWeeklyHours); supabase/tests/hours.test.mjs checks they agree.
-- The stored value keeps only the open days, so null days never reach the database.

create or replace function public.seller_set_hours(p_hours jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_days constant text[] := array['mon','tue','wed','thu','fri','sat','sun'];
  v_day text;
  v_slot jsonb;
  v_clean jsonb := '{}';
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if p_hours is null or jsonb_typeof(p_hours) <> 'object' then raise exception 'invalid_hours' using errcode = 'P0001'; end if;
  if exists (select 1 from jsonb_object_keys(p_hours) as k where k <> all (v_days)) then raise exception 'unknown_day' using errcode = 'P0001'; end if;

  foreach v_day in array v_days loop
    v_slot := p_hours -> v_day;
    if v_slot is null or jsonb_typeof(v_slot) = 'null' then continue; end if;
    if jsonb_typeof(v_slot) <> 'array' or jsonb_array_length(v_slot) <> 2 then raise exception 'invalid_interval' using errcode = 'P0001'; end if;
    if jsonb_typeof(v_slot -> 0) <> 'string' or jsonb_typeof(v_slot -> 1) <> 'string'
       or (v_slot ->> 0) !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or (v_slot ->> 1) !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
      raise exception 'invalid_time' using errcode = 'P0001';
    end if;
    if (v_slot ->> 0) = (v_slot ->> 1) then raise exception 'zero_length' using errcode = 'P0001'; end if;
    v_clean := v_clean || jsonb_build_object(v_day, v_slot);
  end loop;

  perform 1 from public.businesses b where b.id = v_biz for update;
  update public.businesses b set hours = v_clean where b.id = v_biz;
  perform public.write_audit(v_biz, 'hours_updated', 'business', v_biz::text,
    jsonb_build_object('open_days', coalesce((select jsonb_agg(t.d order by t.ord) from unnest(v_days) with ordinality as t(d, ord) where v_clean ? t.d), '[]')));
  return v_clean;
end $$;

revoke all on function public.seller_set_hours(jsonb) from public, anon;
grant execute on function public.seller_set_hours(jsonb) to authenticated, service_role;

$m_0065_seller_set_hours$),
    ('0066_seller_set_location', $m_0066_seller_set_location$
-- 0066_seller_set_location.sql
-- Sellers can now set and move their shop pin on the map themselves. Until now the pin was only captured on the
-- application form: seller_update_profile refuses lat/lng and sellers cannot write the columns directly.
--
-- seller_set_location(p_lat, p_lng, p_address) stores the pin and, when p_address is given, the landmark text.
-- The pin must sit inside the same box the application form accepts (lat -5 to 5.5, lng 33.5 to 42), so a mistyped or
-- far-off point never reaches the public map or the search ranking (businesses.geo is generated from lat/lng).
-- p_address null leaves the address as it is; an empty string clears it. At most 200 characters, like seller_update_profile.

create or replace function public.seller_set_location(p_lat double precision, p_lng double precision, p_address text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_row public.businesses;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if p_lat is null or p_lng is null
     or p_lat <> p_lat or p_lng <> p_lng
     or p_lat not between -5 and 5.5 or p_lng not between 33.5 and 42 then
    raise exception 'invalid_location' using errcode = 'P0001';
  end if;
  if p_address is not null and char_length(p_address) > 200 then raise exception 'invalid_address' using errcode = 'P0001'; end if;

  perform 1 from public.businesses b where b.id = v_biz for update;
  update public.businesses b set
    lat = round(p_lat::numeric, 6)::double precision,
    lng = round(p_lng::numeric, 6)::double precision,
    address = case when p_address is null then b.address else nullif(btrim(p_address), '') end
  where b.id = v_biz
  returning * into v_row;

  perform public.write_audit(v_biz, 'location_updated', 'business', v_biz::text,
    jsonb_build_object('lat', v_row.lat, 'lng', v_row.lng));
  return jsonb_build_object('lat', v_row.lat, 'lng', v_row.lng, 'address', v_row.address);
end $$;

revoke all on function public.seller_set_location(double precision, double precision, text) from public, anon;
grant execute on function public.seller_set_location(double precision, double precision, text) to authenticated, service_role;

$m_0066_seller_set_location$),
    ('0067_conversation_state', $m_0067_conversation_state$
-- 0067_conversation_state.sql
-- Admins can mark a seller conversation resolved and reopen it. A new seller message reopens it by itself.
--
--   * One row per resolved conversation (a conversation is one business, as on the Messages page). No row = open.
--   * Written only by admin_set_conversation_resolved(), which checks the role and writes the audit entry.
--   * The reopen on a seller message is a trigger and is not audited: there is no admin to name.
--
-- Additive and safe to re-run.
--
-- ROLLBACK (run by hand):
--   drop trigger if exists t_messages_reopen on public.messages;
--   drop function if exists public.messages_reopen();
--   drop function if exists public.admin_set_conversation_resolved(uuid, boolean);
--   drop table if exists public.admin_conversation_state;

create table if not exists public.admin_conversation_state (
  business_id uuid        primary key references public.businesses(id) on delete cascade,
  resolved_at timestamptz not null default now(),
  resolved_by uuid        references auth.users(id) on delete set null
);

alter table public.admin_conversation_state enable row level security;

drop policy if exists "admin reads conversation state" on public.admin_conversation_state;
create policy "admin reads conversation state" on public.admin_conversation_state
  for select to authenticated using (public.is_admin());

revoke all on public.admin_conversation_state from public, anon, authenticated;
grant select on public.admin_conversation_state to authenticated;
grant all on public.admin_conversation_state to service_role;

create or replace function public.admin_set_conversation_resolved(p_business uuid, p_resolved boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_was boolean;
begin
  if not public.has_role(array['reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_business is null or p_resolved is null then raise exception 'invalid_input'; end if;
  if not exists (
    select 1 from public.messages m
     where m.business_id = p_business and m.channel = 'in_app' and m.admin_hidden_at is null
  ) then raise exception 'conversation_not_found'; end if;

  select exists (select 1 from public.admin_conversation_state s where s.business_id = p_business) into v_was;
  if v_was = p_resolved then
    return jsonb_build_object('resolved', p_resolved, 'changed', false);
  end if;

  if p_resolved then
    insert into public.admin_conversation_state (business_id, resolved_at, resolved_by)
    values (p_business, now(), auth.uid())
    on conflict (business_id) do nothing;
  else
    delete from public.admin_conversation_state where business_id = p_business;
  end if;

  perform public.admin_audit_action(
    case when p_resolved then 'conversation.resolve' else 'conversation.reopen' end,
    'business', p_business::text,
    jsonb_build_object('resolved', v_was), jsonb_build_object('resolved', p_resolved),
    case when p_resolved then 'Conversation resolved' else 'Conversation reopened' end, p_business);
  return jsonb_build_object('resolved', p_resolved, 'changed', true);
end $$;
revoke all on function public.admin_set_conversation_resolved(uuid, boolean) from public, anon;
grant execute on function public.admin_set_conversation_resolved(uuid, boolean) to authenticated, service_role;

create or replace function public.messages_reopen() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.sender = 'seller' and new.channel = 'in_app' and new.business_id is not null then
    delete from public.admin_conversation_state where business_id = new.business_id;
  end if;
  return new;
end $$;

drop trigger if exists t_messages_reopen on public.messages;
create trigger t_messages_reopen after insert on public.messages for each row execute function public.messages_reopen();

$m_0067_conversation_state$),
    ('0068_premium_badges', $m_0068_premium_badges$
-- 0068_premium_badges.sql
-- A business on the Premium plan is Featured automatically. Verified is NOT touched: it only comes from the admin's
-- document check (verification_level), never from the plan.
--
--   1. Trigger: when a business is created on Premium, or its plan changes to Premium (upgrade payment, plan change at
--      renewal, admin edit), featured is switched on once. If an admin later un-features it, that choice stays until the
--      plan next changes to Premium.
--   2. Leaving Premium switches Featured off.
--   3. Backfill: existing Premium businesses become Featured.
-- Additive and safe to run again.

create or replace function public.apply_premium_badges() returns trigger
language plpgsql as $$
begin
  if new.plan_key = 'premium' then
    if tg_op = 'INSERT' or old.plan_key is distinct from 'premium' then
      new.featured := true;
    end if;
  elsif tg_op = 'UPDATE' and old.plan_key = 'premium' then
    new.featured := false;
  end if;
  return new;
end $$;

drop trigger if exists trg_apply_premium_badges on public.businesses;
create trigger trg_apply_premium_badges
  before insert or update of plan_key on public.businesses
  for each row execute function public.apply_premium_badges();

update public.businesses set featured = true where plan_key = 'premium' and featured is not true;

$m_0068_premium_badges$),
    ('0069_similar_items', $m_0069_similar_items$
-- "Similar items" on the product page: find other stores' items of the same KIND as one item, fast on a table of millions.
--
-- The client computes what the item is (its head noun, with synonyms and plurals, in shared/src/similar.js) and sends the
-- written forms ("bread", "breads", "loaf", "loaves") as p_terms. This function is only the coarse net: items whose NAME contains
-- one of the words as a whole word (full-text search, not a substring, so "tea" never matches "steak"), or that sit in the same
-- section. The real relevance gate and the ordering are applied afterwards by the shared rankSimilar, identically for the demo
-- backend, so a looser net here cannot put an unrelated product in the row.
--
-- Built to stay fast as the table grows (measured on 1,000,000 items, 3,000 stores, the real public_items view: 30 to 80 ms for every
-- kind of product from very common to rare; a first version that joined the view to every match took 5 to 10 seconds):
--   1. A bounded pool from the base table, newest first (never every match, never the view, which is costly per row). Unlisted items
--      are skipped here by calling the same function the view uses, so they cannot take a store's slot. Store visibility (expired,
--      suspended) is deliberately NOT checked here: business_is_visible() is too costly to run per candidate row (it took seconds), so
--      it is applied only to the final few ids by the view; an invisible store can only waste its own slots, never another store's.
--      A rare word reads its few matches through the word index; a common word walks the newest-first index and stops at 600.
--      The function decides which by probing how common the word is, so it does not depend on the planner guessing.
--   2. At most three items per store, each store's best first, so a store with a thousand loaves cannot crowd out the others.
--   3. The exact visibility rules by asking public_items about only those few ids. Listed and public only, defined in that one view.
-- Never the current item, never the current store. Returns just the card columns plus brand, as a JSON array.
--
-- Needs these indexes (create them first, with the CONCURRENTLY migrations that follow, so writes are never blocked):
--   items_name_words_idx     GIN on the name words                                       (0070)
--   items_section_recent_idx btree on (normalised section, created_at desc)              (0071)
--   items_created_at_id_idx  already exists
-- It still works without them, only slowly. This migration itself takes no locks and is instant.
--
-- Not done here on purpose: a stored per-item product_type / taxonomy column. A value derived from the name goes stale as the
-- vocabulary improves, and a seller-chosen one needs seller UI. shared/src/similar.js already accepts an optional `productType`
-- on items, so adding it later changes no ranking code.

create or replace function public.similar_item_candidates(
  p_item_id uuid,
  p_terms text[] default '{}',
  p_limit integer default 120
) returns jsonb
language plpgsql stable security definer set search_path = public, extensions set statement_timeout = '3s' as $$
declare
  v_business uuid;
  v_section text;
  v_query tsquery;
  v_limit integer := least(300, greatest(1, coalesce(p_limit, 120)));
  -- About sqrt(600 x rows): the size at which "read every match" and "walk newest-first until 600 are found" cost the same.
  v_probe integer := least(60000, greatest(2000, floor(sqrt(600.0 * greatest(1000, (select c.reltuples from pg_class c where c.oid = 'public.items'::regclass))))::integer));
  v_rare boolean := false;
  v_ids uuid[];
  v_out jsonb;
begin
  select pi.business_id, nullif(lower(btrim(pi.section)), '')
    into v_business, v_section
    from public.public_items pi
   where pi.id = p_item_id;
  if v_business is null then return '[]'::jsonb; end if;

  -- Letters and digits only, so the words can never alter the query; at most 24 of them.
  select to_tsquery('simple', string_agg(quote_literal(t.term), ' | '))
    into v_query
    from (
      select distinct left(regexp_replace(lower(x), '[^a-z0-9]', '', 'g'), 30) as term
        from unnest(coalesce(p_terms, '{}'::text[])) as x
       limit 24
    ) t
   where t.term <> '';

  if v_query is null and v_section is null then return '[]'::jsonb; end if;

  -- How common is this word? Reading at most v_probe matches is cheap whatever the table size.
  if v_query is not null then
    select count(*) < v_probe into v_rare
      from (select 1 from public.items i where to_tsvector('simple', coalesce(i.name, '')) @@ v_query limit v_probe) p;
  end if;

  -- Stage 1: a bounded pool, newest first. Never the whole set of matches, and never the view, which is costly per row.
  --   rare word:   read all of its matches through the word index (at most v_probe), keep the newest 600
  --   common word: walk the newest-first index and stop at 600
  with named_rare as materialized (
    select i.id, i.business_id, i.created_at
      from public.items i
     where v_rare and v_query is not null and to_tsvector('simple', coalesce(i.name, '')) @@ v_query
       and i.business_id <> v_business and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
       and public.item_is_listed(i.availability)
     limit v_probe
  ), named_common as (
    select i.id, i.business_id, i.created_at
      from public.items i
     where not v_rare and v_query is not null and to_tsvector('simple', coalesce(i.name, '')) @@ v_query
       and i.business_id <> v_business and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
       and public.item_is_listed(i.availability)
     order by i.created_at desc, i.id limit 600
  ), named as (
    select id, business_id, created_at from (select * from named_rare order by created_at desc, id limit 600) r
    union all
    select id, business_id, created_at from named_common
  ), sectioned as (
    select i.id, i.business_id, i.created_at
      from public.items i
     where v_section is not null and lower(btrim(i.section)) = v_section
       and i.business_id <> v_business and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
       and public.item_is_listed(i.availability)
     order by i.created_at desc, i.id limit 300
  ), pool as (
    select u.id, u.business_id, u.created_at, bool_or(u.by_name) as by_name, bool_or(u.by_section) as by_section
      from (select n.id, n.business_id, n.created_at, true as by_name, false as by_section from named n
            union all
            select s.id, s.business_id, s.created_at, false, true from sectioned s) u
     group by u.id, u.business_id, u.created_at
  ), ranked as (
    select p.*, row_number() over (partition by p.business_id order by p.by_name desc, p.by_section desc, p.created_at desc, p.id) as rn
      from pool p
  )
  -- Stage 2: at most three per store, each store's best first, a little more than will be returned (some may drop out below).
  select array_agg(r.id order by r.rn, r.by_name desc, r.by_section desc, r.created_at desc, r.id)
    into v_ids
    from (select * from ranked where rn <= 3 order by rn, by_name desc, by_section desc, created_at desc, id limit v_limit * 2) r;
  if v_ids is null then return '[]'::jsonb; end if;

  -- Stage 3: the exact visibility rules, by asking public_items about only these few ids. The rules stay defined in that one view.
  select coalesce(jsonb_agg(f.j order by f.pos), '[]'::jsonb)
    into v_out
    from (
      select g.j, g.pos, row_number() over (order by g.pos) as place
        from (
          select array_position(v_ids, card.id) as pos,
                 jsonb_build_object(
                   'id', card.id, 'business_id', card.business_id, 'name', card.name, 'description', card.description,
                   'price', card.price, 'price_type', card.price_type, 'unit', card.unit, 'section', card.section,
                   'availability', card.availability, 'stock_left', card.stock_left, 'image_paths', card.image_paths,
                   'video_paths', card.video_paths, 'media', card.media, 'sort', card.sort, 'created_at', card.created_at,
                   'brand', card.brand
                 ) as j
            from public.public_items card
           where card.id = any(v_ids)
        ) g
    ) f
   where f.place <= v_limit;

  return v_out;
end $$;

revoke all on function public.similar_item_candidates(uuid, text[], integer) from public;
grant execute on function public.similar_item_candidates(uuid, text[], integer) to anon, authenticated, service_role;

$m_0069_similar_items$),
    ('0070_items_name_words_idx', $m_0070_items_name_words_idx$
-- Word index for "Similar items" (see 0069). CONCURRENTLY: builds without blocking writes, so it is safe on a live table of millions.
-- It cannot run inside a transaction, so run this statement on its own. If a build is interrupted it leaves an INVALID index that
-- "if not exists" would skip; check with:  select indexrelid::regclass from pg_index where not indisvalid;  and drop it, then rerun.
create index if not exists items_name_words_idx on public.items using gin (to_tsvector('simple', coalesce(name, '')));

$m_0070_items_name_words_idx$),
    ('0071_items_section_recent_idx', $m_0071_items_section_recent_idx$
-- Same-section, newest-first index for "Similar items" (see 0069). CONCURRENTLY: no write blocking; run this statement on its own.
-- Replaces the plain section index of the first version of 0069; once this exists that one can be dropped:
--   drop index concurrently if exists items_section_norm_idx;
create index if not exists items_section_recent_idx on public.items (lower(btrim(section)), created_at desc) where section is not null;

$m_0071_items_section_recent_idx$),
    ('0072_broadcast_cancel', $m_0072_broadcast_cancel$
-- 0072_broadcast_cancel.sql
-- Cancel a broadcast that has not gone out yet.
--
--   * messages.batch_id groups the rows one admin-message call created (one row per recipient and channel).
--     Older broadcasts are grouped from the idempotency key already stored in their dedupe_key.
--   * messages.claimed_at is set by claim_due_messages() when the dispatcher takes a row, so "not yet claimed" can be told
--     apart from "scheduled for later" (claiming only pushes scheduled_at forward and leaves the status queued).
--   * status 'cancelled' is new. Nothing else reads it as sent: the seller inbox policy and the dispatcher ignore it.
--   * admin_cancel_broadcast() cancels only queued, unclaimed rows and reports what was cancelled and what had already gone.
--
-- Additive and safe to re-run.
--
-- ROLLBACK (run by hand):
--   drop function if exists public.admin_cancel_broadcast(uuid, text);
--   drop function if exists public.admin_pending_broadcasts();
--   update public.messages set status = 'failed', error = 'cancelled' where status = 'cancelled';
--   alter table public.messages drop constraint if exists messages_status_check;
--   alter table public.messages add constraint messages_status_check check (status in ('queued','sent','delivered','failed'));
--   re-run "create or replace function public.claim_due_messages" from 0021_messaging.sql
--   alter table public.messages drop column if exists claimed_at, drop column if exists batch_id;

alter table public.messages add column if not exists batch_id uuid;
alter table public.messages add column if not exists claimed_at timestamptz;

do $$
declare c record;
begin
  for c in
    select con.conname from pg_constraint con
     where con.conrelid = 'public.messages'::regclass and con.contype = 'c'
       and pg_get_constraintdef(con.oid) like '%status%' and pg_get_constraintdef(con.oid) like '%queued%'
  loop
    execute format('alter table public.messages drop constraint %I', c.conname);
  end loop;
  alter table public.messages add constraint messages_status_check
    check (status in ('queued', 'sent', 'delivered', 'failed', 'cancelled'));
end $$;

update public.messages
   set batch_id = split_part(dedupe_key, ':', 2)::uuid
 where batch_id is null
   and dedupe_key like 'admin:%'
   and split_part(dedupe_key, ':', 2) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

create index if not exists messages_batch_idx on public.messages (batch_id) where batch_id is not null;

create or replace function public.claim_due_messages(p_now timestamptz default now(), p_limit integer default 50, p_lease_seconds integer default 300)
returns setof public.messages
language plpgsql security definer set search_path = public as $$
begin
  -- Promotional SMS/email never go out during quiet hours; they wait for the morning.
  -- Transactional messages and in-app messages (silent) are not delayed.
  if public.in_quiet_hours(p_now) then
    update public.messages
       set scheduled_at = public.quiet_hours_end(p_now)
     where status = 'queued' and scheduled_at <= p_now
       and transactional = false and channel in ('sms', 'email');
  end if;

  return query
    with due as (
      select id from public.messages
       where status = 'queued' and scheduled_at <= p_now and channel in ('sms', 'email', 'in_app')
       order by transactional desc, scheduled_at, created_at
       limit greatest(1, least(coalesce(p_limit, 50), 200))
       for update skip locked
    )
    update public.messages m
       set scheduled_at = p_now + make_interval(secs => p_lease_seconds), claimed_at = p_now
      from due
     where m.id = due.id
    returning m.*;
end $$;
revoke all on function public.claim_due_messages(timestamptz, integer, integer) from public, anon, authenticated;
grant execute on function public.claim_due_messages(timestamptz, integer, integer) to service_role;

-- Broadcasts that still have rows waiting and not yet taken by the dispatcher.
create or replace function public.admin_pending_broadcasts() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role(array['reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.scheduled_at, x.created_at)
    from (
      select m.batch_id,
             min(m.created_at) as created_at,
             min(m.scheduled_at) filter (where m.status = 'queued' and m.claimed_at is null) as scheduled_at,
             min(m.subject) as subject,
             min(m.template_key) as template_key,
             count(*) filter (where m.status = 'queued' and m.claimed_at is null)::integer as pending,
             count(*) filter (where m.status in ('sent', 'delivered'))::integer as sent,
             count(*)::integer as total,
             count(distinct coalesce(m.business_id, m.application_id))::integer as recipients,
             array_agg(distinct m.channel order by m.channel) as channels
        from public.messages m
       where m.batch_id is not null
       group by m.batch_id
      having count(*) filter (where m.status = 'queued' and m.claimed_at is null) > 0
       order by min(m.scheduled_at) filter (where m.status = 'queued' and m.claimed_at is null), min(m.created_at)
       limit 50
    ) x
  ), '[]'::jsonb);
end $$;
revoke all on function public.admin_pending_broadcasts() from public, anon;
grant execute on function public.admin_pending_broadcasts() to authenticated, service_role;

create or replace function public.admin_cancel_broadcast(p_batch uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_cancelled integer;
  v_sent integer;
  v_failed integer;
  v_in_flight integer;
  v_total integer;
begin
  if not public.has_role(array['reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_batch is null then raise exception 'invalid_input'; end if;
  if not exists (select 1 from public.messages where batch_id = p_batch) then raise exception 'broadcast_not_found'; end if;

  with picked as (
    select id from public.messages
     where batch_id = p_batch and status = 'queued' and claimed_at is null
     order by id for update skip locked
  ), upd as (
    update public.messages m set status = 'cancelled'
      from picked where m.id = picked.id returning m.id
  )
  select count(*) into v_cancelled from upd;

  select count(*) filter (where status in ('sent', 'delivered')),
         count(*) filter (where status = 'failed'),
         count(*) filter (where status = 'queued'),
         count(*)
    into v_sent, v_failed, v_in_flight, v_total
    from public.messages where batch_id = p_batch;

  if v_cancelled > 0 then
    perform public.admin_audit_action('broadcast.cancel', 'message_batch', p_batch::text,
      jsonb_build_object('pending', v_cancelled + v_in_flight),
      jsonb_build_object('cancelled', v_cancelled, 'sent', v_sent, 'failed', v_failed, 'in_flight', v_in_flight, 'total', v_total),
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Broadcast cancelled'), null);
  end if;
  return jsonb_build_object('cancelled', v_cancelled, 'sent', v_sent, 'failed', v_failed, 'inFlight', v_in_flight, 'total', v_total);
end $$;
revoke all on function public.admin_cancel_broadcast(uuid, text) from public, anon;
grant execute on function public.admin_cancel_broadcast(uuid, text) to authenticated, service_role;

$m_0072_broadcast_cancel$),
    ('0073_template_state', $m_0073_template_state$
-- 0073_template_state.sql
-- Message templates can be disabled, enabled and deleted, and a broadcast to one category accepts the category's name.
--
--   * disabled_at: a disabled template cannot be used for a broadcast (admin-message answers template_disabled).
--   * Delete is refused with template_in_use for the keys the system itself writes into messages: welcome, login_details,
--     application.* (admin-decide-application) and billing_* (the daily lifecycle). Disable those instead.
--   * Owner only, like editing a template. Every change is audited.
--   * message_segment('category:<x>') matched the category id only, but the admin pickers list category names.
--     It now matches either. This is the 0029 definition with that one branch widened.
--
-- Additive and safe to re-run.
--
-- ROLLBACK (run by hand):
--   drop function if exists public.admin_delete_template(text);
--   drop function if exists public.admin_set_template_enabled(text, boolean);
--   drop function if exists public.message_template_is_system(text);
--   alter table public.message_templates drop column if exists disabled_at;
--   re-run "create or replace function public.admin_templates_list" from 0025 and "message_segment" from 0029.

alter table public.message_templates add column if not exists disabled_at timestamptz;

create or replace function public.message_template_is_system(p_key text) returns boolean
language sql immutable as $$
  select p_key in ('welcome', 'login_details') or p_key like 'application.%' or p_key like 'billing\_%'
$$;
revoke all on function public.message_template_is_system(text) from public, anon;
grant execute on function public.message_template_is_system(text) to authenticated, service_role;

create or replace function public.admin_templates_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.key)
    from (
      select t.key, t.channel, t.subject, t.body_en, t.body_sw, t.transactional, t.version, t.updated_at,
             t.disabled_at, public.message_template_is_system(t.key) as system,
             (select count(*) from public.messages m where m.template_key = t.key and m.created_at >= now() - interval '30 days') as used_30d
        from public.message_templates t
    ) x
  ), '[]'::jsonb);
end $$;

create or replace function public.admin_set_template_enabled(p_key text, p_enabled boolean) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  t public.message_templates;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_key is null or p_enabled is null then raise exception 'invalid_input'; end if;
  select * into t from public.message_templates where key = p_key for update;
  if not found then raise exception 'template_not_found'; end if;
  if (t.disabled_at is null) = p_enabled then return false; end if;

  update public.message_templates set disabled_at = case when p_enabled then null else now() end where key = p_key;
  perform public.admin_audit_action(case when p_enabled then 'template.enable' else 'template.disable' end, 'template', p_key,
    jsonb_build_object('enabled', t.disabled_at is null), jsonb_build_object('enabled', p_enabled), null, null);
  return true;
end $$;
revoke all on function public.admin_set_template_enabled(text, boolean) from public, anon;
grant execute on function public.admin_set_template_enabled(text, boolean) to authenticated, service_role;

create or replace function public.admin_delete_template(p_key text) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  t public.message_templates;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_key is null then raise exception 'invalid_input'; end if;
  select * into t from public.message_templates where key = p_key for update;
  if not found then raise exception 'template_not_found'; end if;
  if public.message_template_is_system(p_key) then raise exception 'template_in_use'; end if;

  delete from public.message_templates where key = p_key;
  perform public.admin_audit_action('template.delete', 'template', p_key,
    jsonb_build_object('channel', t.channel, 'subject', t.subject, 'body_en', t.body_en, 'version', t.version), null, null, null);
  return true;
end $$;
revoke all on function public.admin_delete_template(text) from public, anon;
grant execute on function public.admin_delete_template(text) to authenticated, service_role;

CREATE OR REPLACE FUNCTION public.message_segment(p_segment text, p_now timestamp with time zone DEFAULT now())
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- `return query` does not end a set-returning function, so each branch returns explicitly.
  if p_segment = 'all_live' then
    return query select id from public.businesses where status = 'live';
    return;
  elsif p_segment = 'expiring_7d' then
    return query select id from public.businesses
      where status = 'live' and paid_until is not null
        and public.nairobi_day(paid_until) between public.nairobi_day(p_now) and public.nairobi_day(p_now) + 7;
    return;
  elsif p_segment = 'in_grace' then
    return query select id from public.businesses
      where status <> 'deleted' and paid_until is not null and public.listing_state(paid_until, p_now, grace_days) = 'grace';
    return;
  elsif p_segment = 'expired' then
    return query select id from public.businesses
      where status <> 'deleted' and paid_until is not null and public.listing_state(paid_until, p_now, grace_days) = 'expired';
    return;
  elsif p_segment like 'category:%' then
    return query select b.id from public.businesses b
      where b.status = 'live'
        and (b.category_id = substr(p_segment, 10)
             or b.category_id in (select c.id from public.categories c where lower(c.name) = lower(btrim(substr(p_segment, 10)))));
    return;
  elsif p_segment like 'town:%' then
    return query select id from public.businesses where status = 'live' and lower(town) = lower(substr(p_segment, 6));
    return;
  end if;
  raise exception 'unknown_segment' using errcode = '22023';
end $function$;
revoke all on function public.message_segment(text, timestamptz) from public, anon, authenticated;
grant execute on function public.message_segment(text, timestamptz) to service_role;

$m_0073_template_state$),
    ('0074_message_log_detail', $m_0074_message_log_detail$
-- 0074_message_log_detail.sql
-- Message log: applicants show the business they applied with instead of "Applicant", the status filter accepts
-- 'cancelled' (0072), and admin_message_detail() returns one message in full for the detail dialog.
--
-- Same roles as the log: owner, reviewer, support. Read only, so nothing is audited. Seller-sent messages are not part of
-- the log and are refused here too. Safe to re-run.
--
-- ROLLBACK (run by hand):
--   drop function if exists public.admin_message_detail(uuid);
--   re-run "create or replace function public.admin_message_log_query" from 0025_admin_messaging_console.sql

create or replace function public.admin_message_log_query(
  p_channel text default 'all', p_status text default 'all', p_search text default null,
  p_limit integer default 50, p_offset integer default 0
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_total bigint;
  v_rows jsonb;
begin
  if not public.has_role(array['owner', 'reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(p_channel, 'all') not in ('all', 'sms', 'email', 'in_app') then raise exception 'invalid_channel'; end if;
  if coalesce(p_status, 'all') not in ('all', 'queued', 'sent', 'delivered', 'failed', 'cancelled') then raise exception 'invalid_status'; end if;

  select count(*) into v_total
    from public.messages m left join public.businesses b on b.id = m.business_id
   where m.sender <> 'seller'
     and (coalesce(p_channel, 'all') = 'all' or m.channel = p_channel)
     and (coalesce(p_status, 'all') = 'all' or m.status = p_status)
     and (v_search is null or m.subject ilike '%' || v_search || '%' or m.to_address ilike '%' || v_search || '%'
          or m.template_key ilike '%' || v_search || '%' or b.name ilike '%' || v_search || '%');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb) into v_rows from (
    select m.id, m.created_at, m.channel, m.status, m.kind, m.subject, m.template_key, m.to_address, m.transactional,
           m.business_id, b.name as business_name, m.application_id, a.business_name as application_name,
           m.attempts, m.error, m.cost_kes, m.scheduled_at, m.sent_at
      from public.messages m
      left join public.businesses b on b.id = m.business_id
      left join public.applications a on a.id = m.application_id
     where m.sender <> 'seller'
       and (coalesce(p_channel, 'all') = 'all' or m.channel = p_channel)
       and (coalesce(p_status, 'all') = 'all' or m.status = p_status)
       and (v_search is null or m.subject ilike '%' || v_search || '%' or m.to_address ilike '%' || v_search || '%'
            or m.template_key ilike '%' || v_search || '%' or b.name ilike '%' || v_search || '%')
     order by m.created_at desc
     limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0)
  ) x;
  return jsonb_build_object('rows', v_rows, 'total', v_total);
end $$;

create or replace function public.admin_message_detail(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb;
begin
  if not public.has_role(array['owner', 'reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_id is null then raise exception 'invalid_input'; end if;
  select to_jsonb(x) into v from (
    select m.id, m.created_at, m.channel, m.status, m.kind, m.subject, m.body, m.template_key, m.to_address, m.transactional,
           m.business_id, b.name as business_name, b.seller_id,
           m.application_id, a.business_name as application_name, a.owner_full_name as applicant_name,
           m.attempts, m.error, m.cost_kes, m.provider_id, m.scheduled_at, m.sent_at, m.batch_id,
           (select u.email from auth.users u where u.id = m.created_by) as created_by_email
      from public.messages m
      left join public.businesses b on b.id = m.business_id
      left join public.applications a on a.id = m.application_id
     where m.id = p_id and m.sender <> 'seller'
  ) x;
  if v is null then raise exception 'message_not_found'; end if;
  return v;
end $$;
revoke all on function public.admin_message_detail(uuid) from public, anon;
grant execute on function public.admin_message_detail(uuid) to authenticated, service_role;

$m_0074_message_log_detail$),
    ('0078_business_health', $m_0078_business_health$
-- 0078_business_health.sql
-- One business health score, defined once, in SQL.
--
-- What the score is for: CHURN RISK. "How likely is this business to stop paying?" It is built from four parts, each 0 to 100:
--   profile    the same 8 checks as before (tagline, description, logo, cover, address, WhatsApp, hours, at least one item)
--   freshness  the share of items whose price was confirmed in the last N days (N can differ per category). No items = 0
--   activity   how recently the business did ANYTHING: the latest of login, business edit, item edit, price confirmation
--   trust      100 minus capped penalties for open flags, open reports and strikes
--
-- What this replaces. The formula used to live in three places (the admin_businesses_v view, a hand-built ORDER BY string in
-- admin_businesses_query, and admin/src/lib/health.js), so changing a weight in one made the sort disagree with the number shown.
-- It also had three bugs: an empty catalogue scored 100 for price freshness (coalesce(price_age_days, 0)), a business that had
-- never logged in counted as 30 days idle (so every new business looked unhealthy), and the stalest single item decided the whole
-- freshness part. Now:
--   * business_health(...)        the only place the formula exists. Returns score, band, the four parts, weights and reasons.
--   * business_health_inputs_v    the raw numbers per business, one grouped pass (no subquery per row).
--   * business_health_v           inputs + business_health(...). admin_businesses_v, the sort and the UI all read this.
--   * site_settings 'health_config'   every weight and threshold. Tune it from Settings, no deploy needed.
--   * business_health_snapshots   one row per business per day, written by the daily job: history, trend, and the data to
--                                 calibrate the weights against real non-renewals later.
--
-- Rules worth knowing:
--   * New-business grace (grace_days, default 14): while a business is that young, an unmeasurable freshness (no items) or
--     activity (never active) part is NEUTRAL (default 70) instead of 0. Once the grace is over they count as 0.
--   * Hard caps: a suspended or expired business, one with a serious open flag (still unanswered after serious_flag_days),
--     or one that has reached the strike threshold can never score above "At risk", whatever its other parts say.
--   * Bands: Healthy (70+), Watch (40 to 69), At risk (below 40).
-- Additive; safe to run again.

-- ---------------------------------------------------------------------------
-- 1. Configuration. Read defensively: a bad value typed into site_settings falls back to its default instead of breaking the list.
-- ---------------------------------------------------------------------------
create or replace function public.health_num(p jsonb, p_path text[], p_default numeric, p_min numeric, p_max numeric)
returns numeric language plpgsql immutable as $$
declare
  v numeric;
begin
  v := (p #>> p_path)::numeric;
  if v is null or v = 'NaN'::numeric then return p_default; end if;
  return least(p_max, greatest(p_min, v));
exception when others then
  return p_default;
end $$;

-- Fills in every missing key, clamps every number into its allowed range and drops anything it does not know.
create or replace function public.health_normalize(s jsonb) returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  v_s jsonb := case when jsonb_typeof(s) = 'object' then s else '{}'::jsonb end;
  v_map jsonb := '{}'::jsonb;
  v_healthy numeric := public.health_num(v_s, '{bands,healthy}', 70, 2, 100);
  v_watch numeric;
  v_full numeric := public.health_num(v_s, '{activity_full_days}', 3, 0, 90);
  v_zero numeric;
begin
  v_watch := least(public.health_num(v_s, '{bands,watch}', 40, 1, 99), v_healthy - 1);
  v_zero := greatest(public.health_num(v_s, '{activity_zero_days}', 30, 1, 365), v_full + 1);
  if jsonb_typeof(v_s -> 'freshness_days_by_category') = 'object' then
    select coalesce(jsonb_object_agg(e.k, e.v::integer), '{}'::jsonb) into v_map
      from jsonb_each_text(v_s -> 'freshness_days_by_category') as e(k, v)
     where case when e.v ~ '^[0-9]{1,3}$' then e.v::integer between 1 and 365 else false end;
  end if;
  return jsonb_build_object(
    'weights', jsonb_build_object(
      'profile',   public.health_num(v_s, '{weights,profile}',   20, 0, 100)::integer,
      'freshness', public.health_num(v_s, '{weights,freshness}', 25, 0, 100)::integer,
      'activity',  public.health_num(v_s, '{weights,activity}',  35, 0, 100)::integer,
      'trust',     public.health_num(v_s, '{weights,trust}',     20, 0, 100)::integer),
    'grace_days', public.health_num(v_s, '{grace_days}', 14, 0, 90)::integer,
    'neutral', public.health_num(v_s, '{neutral}', 70, 0, 100)::integer,
    'freshness_days', public.health_num(v_s, '{freshness_days}', 14, 1, 365)::integer,
    'freshness_days_by_category', v_map,
    'activity_full_days', v_full::integer,
    'activity_zero_days', v_zero::integer,
    'trust', jsonb_build_object(
      'flag',       public.health_num(v_s, '{trust,flag}',       25, 0, 100)::integer,
      'flag_cap',   public.health_num(v_s, '{trust,flag_cap}',   50, 0, 100)::integer,
      'report',     public.health_num(v_s, '{trust,report}',     15, 0, 100)::integer,
      'report_cap', public.health_num(v_s, '{trust,report_cap}', 30, 0, 100)::integer,
      'strike',     public.health_num(v_s, '{trust,strike}',     20, 0, 100)::integer,
      'strike_cap', public.health_num(v_s, '{trust,strike_cap}', 60, 0, 100)::integer),
    'serious_flag_days', public.health_num(v_s, '{serious_flag_days}', 7, 0, 90)::integer,
    'bands', jsonb_build_object('healthy', v_healthy::integer, 'watch', v_watch::integer));
end $$;

-- The live configuration, plus the strike threshold the admin already sets on the Settings page (one setting, not two).
create or replace function public.health_config() returns jsonb
language plpgsql stable set search_path = public as $$
declare
  v_s jsonb;
  v_strike integer;
begin
  select value into v_s from public.site_settings where key = 'health_config';
  begin
    select (value #>> '{}')::integer into v_strike from public.site_settings where key = 'strike_threshold';
  exception when others then
    v_strike := null;
  end;
  return public.health_normalize(coalesce(v_s, '{}'::jsonb))
      || jsonb_build_object('strike_threshold', greatest(1, coalesce(v_strike, 3)));
end $$;

-- Seed the defaults once. bakery and tailor are examples of a per-category window (days); an id that does not exist is ignored.
insert into public.site_settings (key, value)
values ('health_config', public.health_normalize('{"freshness_days_by_category": {"bakery": 3, "tailor": 60}}'::jsonb))
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- 2. The formula. The only place it exists. Pure: everything it needs comes in as arguments.
-- ---------------------------------------------------------------------------
create or replace function public.business_health(
  p_state text,                  -- deleted, pending, live, expiring, grace, expired, paused, suspended
  p_age_days integer,            -- days since the business was created
  p_missing text[],              -- the profile checks that failed, by label
  p_items integer,               -- items (not removed by an admin)
  p_fresh_items integer,         -- of those, price confirmed within p_fresh_days
  p_fresh_days integer,          -- the freshness window that applies to this business's category
  p_activity_age integer,        -- days since the latest login, edit or price confirmation; null = never
  p_open_flags integer,
  p_serious_flags integer,       -- open flags still unanswered after serious_flag_days
  p_open_reports integer,
  p_strikes integer,
  p_cfg jsonb                    -- health_config()
) returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  w_p numeric := (p_cfg #>> '{weights,profile}')::numeric;
  w_f numeric := (p_cfg #>> '{weights,freshness}')::numeric;
  w_a numeric := (p_cfg #>> '{weights,activity}')::numeric;
  w_t numeric := (p_cfg #>> '{weights,trust}')::numeric;
  v_wsum numeric;
  v_neutral numeric := (p_cfg ->> 'neutral')::numeric;
  v_grace boolean := coalesce(p_age_days, 0) < (p_cfg ->> 'grace_days')::integer;
  v_full integer := (p_cfg ->> 'activity_full_days')::integer;
  v_zero integer := (p_cfg ->> 'activity_zero_days')::integer;
  v_healthy integer := (p_cfg #>> '{bands,healthy}')::integer;
  v_watch integer := (p_cfg #>> '{bands,watch}')::integer;
  v_checks integer := 8 - coalesce(cardinality(p_missing), 0);
  s_p numeric;
  s_f numeric;
  s_a numeric;
  s_t numeric;
  v_neutral_f boolean := false;
  v_neutral_a boolean := false;
  v_pen_flags numeric;
  v_pen_reports numeric;
  v_pen_strikes numeric;
  v_raw numeric;
  v_score integer;
  v_cap integer := (p_cfg #>> '{bands,watch}')::integer - 1;
  v_capped boolean := false;
  v_band text;
  l_p numeric;
  l_f numeric;
  l_a numeric;
  l_t numeric;
  v_weakest text;
  v_max numeric := 0;
  v_bits text[];
  v_reasons jsonb := '[]'::jsonb;
  v_deleted boolean := p_state = 'deleted';
begin
  v_wsum := w_p + w_f + w_a + w_t;
  if v_wsum <= 0 then
    w_p := 1; w_f := 1; w_a := 1; w_t := 1; v_wsum := 4;
  end if;

  -- profile
  s_p := round(100.0 * v_checks / 8);

  -- freshness: the share of items confirmed recently. Nothing to measure is 0, except for a brand new business.
  if coalesce(p_items, 0) > 0 then
    s_f := round(100.0 * coalesce(p_fresh_items, 0) / p_items);
  elsif v_grace then
    s_f := v_neutral; v_neutral_f := true;
  else
    s_f := 0;
  end if;

  -- activity: full marks up to activity_full_days of silence, falling in a straight line to 0 at activity_zero_days.
  if p_activity_age is null then
    if v_grace then s_a := v_neutral; v_neutral_a := true; else s_a := 0; end if;
  elsif p_activity_age <= v_full then
    s_a := 100;
  elsif p_activity_age >= v_zero then
    s_a := 0;
  else
    s_a := round(100.0 * (v_zero - p_activity_age) / (v_zero - v_full));
  end if;

  -- trust: capped penalties
  v_pen_flags   := least((p_cfg #>> '{trust,flag_cap}')::numeric,   coalesce(p_open_flags, 0)   * (p_cfg #>> '{trust,flag}')::numeric);
  v_pen_reports := least((p_cfg #>> '{trust,report_cap}')::numeric, coalesce(p_open_reports, 0) * (p_cfg #>> '{trust,report}')::numeric);
  v_pen_strikes := least((p_cfg #>> '{trust,strike_cap}')::numeric, coalesce(p_strikes, 0)      * (p_cfg #>> '{trust,strike}')::numeric);
  s_t := greatest(0, 100 - v_pen_flags - v_pen_reports - v_pen_strikes);

  v_raw := (w_p * s_p + w_f * s_f + w_a * s_a + w_t * s_t) / v_wsum;
  v_score := round(v_raw);

  -- points each part costs the total (they add up to 100 minus the uncapped score)
  l_p := w_p / v_wsum * (100 - s_p);
  l_f := w_f / v_wsum * (100 - s_f);
  l_a := w_a / v_wsum * (100 - s_a);
  l_t := w_t / v_wsum * (100 - s_t);

  if l_p > v_max then v_weakest := 'profile';   v_max := l_p; end if;
  if l_f > v_max then v_weakest := 'freshness'; v_max := l_f; end if;
  if l_a > v_max then v_weakest := 'activity';  v_max := l_a; end if;
  if l_t > v_max then v_weakest := 'trust';     v_max := l_t; end if;
  if v_max < 1 then v_weakest := null; end if;

  -- reasons, biggest first (caps on top). 'ord' only sorts them and is removed below.
  if p_state in ('suspended', 'expired') then
    v_reasons := v_reasons || jsonb_build_object('part', 'cap', 'tone', 'bad', 'points', 0, 'ord', 1000,
      'text', case p_state when 'suspended' then 'Suspended' else 'Expired' end || ': the score cannot rise above ' || v_cap);
    if v_score > v_cap then v_score := v_cap; v_capped := true; end if;
  end if;
  if coalesce(p_serious_flags, 0) > 0 then
    v_reasons := v_reasons || jsonb_build_object('part', 'cap', 'tone', 'bad', 'points', 0, 'ord', 999,
      'text', 'Open flag unanswered for over ' || (p_cfg ->> 'serious_flag_days') || ' days: the score cannot rise above ' || v_cap);
    if v_score > v_cap then v_score := v_cap; v_capped := true; end if;
  end if;
  if coalesce(p_strikes, 0) >= (p_cfg ->> 'strike_threshold')::integer then
    v_reasons := v_reasons || jsonb_build_object('part', 'cap', 'tone', 'bad', 'points', 0, 'ord', 998,
      'text', 'Strike threshold reached (' || p_strikes || '): the score cannot rise above ' || v_cap);
    if v_score > v_cap then v_score := v_cap; v_capped := true; end if;
  end if;

  if round(l_p) >= 1 then
    v_reasons := v_reasons || jsonb_build_object('part', 'profile', 'points', round(l_p), 'ord', l_p,
      'tone', case when s_p < v_watch then 'bad' when s_p < v_healthy then 'warn' else 'note' end,
      'text', 'Profile ' || v_checks || ' of 8 complete. Missing: ' || array_to_string(p_missing, ', '));
  end if;
  if round(l_f) >= 1 and not v_neutral_f then
    v_reasons := v_reasons || jsonb_build_object('part', 'freshness', 'points', round(l_f), 'ord', l_f,
      'tone', case when s_f < v_watch then 'bad' when s_f < v_healthy then 'warn' else 'note' end,
      'text', case when coalesce(p_items, 0) = 0 then 'No items listed, so there are no prices to keep fresh'
                   else coalesce(p_fresh_items, 0) || ' of ' || p_items || case when p_items = 1 then ' price' else ' prices' end
                        || ' confirmed in the last ' || p_fresh_days || ' days' end);
  end if;
  if round(l_a) >= 1 and not v_neutral_a then
    v_reasons := v_reasons || jsonb_build_object('part', 'activity', 'points', round(l_a), 'ord', l_a,
      'tone', case when s_a < v_watch then 'bad' when s_a < v_healthy then 'warn' else 'note' end,
      'text', case when p_activity_age is null then 'No login, edit or price confirmation yet'
                   else 'No login, edit or price confirmation for ' || p_activity_age || case when p_activity_age = 1 then ' day' else ' days' end end);
  end if;
  if round(l_t) >= 1 then
    v_bits := array[]::text[];
    if coalesce(p_open_flags, 0) > 0 then v_bits := v_bits || (p_open_flags || ' open ' || case when p_open_flags = 1 then 'flag' else 'flags' end); end if;
    if coalesce(p_open_reports, 0) > 0 then v_bits := v_bits || (p_open_reports || ' open ' || case when p_open_reports = 1 then 'report' else 'reports' end); end if;
    if coalesce(p_strikes, 0) > 0 then v_bits := v_bits || (p_strikes || case when p_strikes = 1 then ' strike' else ' strikes' end); end if;
    v_reasons := v_reasons || jsonb_build_object('part', 'trust', 'points', round(l_t), 'ord', l_t,
      'tone', case when s_t < v_watch then 'bad' when s_t < v_healthy then 'warn' else 'note' end,
      'text', array_to_string(v_bits, ', '));
  end if;
  if v_neutral_f or v_neutral_a then
    v_reasons := v_reasons || jsonb_build_object('part', 'grace', 'tone', 'info', 'points', 0, 'ord', 0.5,
      'text', 'New business: ' || case when v_neutral_f and v_neutral_a then 'freshness and activity are'
                                       when v_neutral_f then 'freshness is' else 'activity is' end
              || ' scored as neutral (' || v_neutral::integer || ') until day ' || (p_cfg ->> 'grace_days'));
  end if;

  select coalesce(jsonb_agg(r - 'ord' order by (r ->> 'ord')::numeric desc), '[]'::jsonb) into v_reasons
    from jsonb_array_elements(v_reasons) as r;

  v_band := case when v_score >= v_healthy then 'healthy' when v_score >= v_watch then 'watch' else 'at_risk' end;

  return jsonb_build_object(
    'score', case when v_deleted then null else v_score end,
    'band', case when v_deleted then 'none' else v_band end,
    'label', case when v_deleted then 'No score'
                  else case v_band when 'healthy' then 'Healthy' when 'watch' then 'Watch' else 'At risk' end end,
    'capped', v_capped and not v_deleted,
    'weakest', case when v_deleted then null else v_weakest end,
    'grace', v_grace,
    'bands', jsonb_build_object('healthy', v_healthy, 'watch', v_watch),
    'subs', jsonb_build_object('profile', s_p::integer, 'freshness', s_f::integer, 'activity', s_a::integer, 'trust', s_t::integer),
    'weights', jsonb_build_object(
      'profile', round(100 * w_p / v_wsum), 'freshness', round(100 * w_f / v_wsum),
      'activity', round(100 * w_a / v_wsum), 'trust', round(100 * w_t / v_wsum)),
    'reasons', case when v_deleted then '[]'::jsonb else v_reasons end);
end $$;

-- ---------------------------------------------------------------------------
-- 3. The raw numbers, one grouped pass each (no subquery per business), and the score on top of them.
-- ---------------------------------------------------------------------------
create or replace view public.business_health_inputs_v with (security_invoker = true) as
select
  b.id as business_id,
  case
    when (b.deleted_at is not null) or b.status = 'deleted' then 'deleted'
    when b.status <> 'live' then b.status
    when b.paid_until is null then 'pending'
    when public.listing_state(b.paid_until, now(), b.grace_days) = 'expired' then 'expired'
    when public.listing_state(b.paid_until, now(), b.grace_days) = 'grace' then 'grace'
    when public.days_left(b.paid_until) <= 7 then 'expiring'
    else 'live'
  end as state,
  (public.nairobi_today() - public.nairobi_day(b.created_at))::integer as age_days,
  array_remove(array[
    case when coalesce(btrim(b.tagline), '') = '' then 'tagline' end,
    case when coalesce(btrim(b.description), '') = '' then 'description' end,
    case when b.logo_path is null then 'logo' end,
    case when b.cover_path is null then 'cover photo' end,
    case when coalesce(btrim(b.address), '') = '' then 'address' end,
    case when coalesce(btrim(b.whatsapp), '') = '' then 'WhatsApp number' end,
    case when coalesce(b.hours, '{}'::jsonb) = '{}'::jsonb then 'opening hours' end,
    case when coalesce(s.items, 0) = 0 then 'items' end
  ], null) as missing,
  coalesce(s.items, 0)::integer as items,
  coalesce(s.fresh_items, 0)::integer as fresh_items,
  coalesce((cfg.c -> 'freshness_days_by_category' ->> b.category_id)::integer, (cfg.c ->> 'freshness_days')::integer) as fresh_days,
  s.price_age_days::integer as price_age_days,      -- the stalest item; null when there are no items (it used to be 0)
  greatest(b.last_login_at, b.last_edit_at, s.last_item_edit, s.last_price_confirm) as last_activity_at,
  (public.nairobi_today() - public.nairobi_day(greatest(b.last_login_at, b.last_edit_at, s.last_item_edit, s.last_price_confirm)))::integer as activity_age_days,
  coalesce(f.open_flags, 0)::integer as open_flags,
  coalesce(f.serious_flags, 0)::integer as serious_flags,
  coalesce(r.open_reports, 0)::integer as open_reports,
  b.strikes
from public.businesses b
cross join (select public.health_config() as c) cfg
left join (
  select i.business_id,
         count(*) as items,
         count(*) filter (where public.nairobi_today() - public.nairobi_day(i.price_confirmed_at) <= w.days) as fresh_items,
         max(public.nairobi_today() - public.nairobi_day(i.price_confirmed_at)) as price_age_days,
         max(i.updated_at) as last_item_edit,
         max(i.price_confirmed_at) as last_price_confirm
    from public.items i
    join public.businesses bb on bb.id = i.business_id
    cross join (select public.health_config() as c) k
    cross join lateral (select coalesce((k.c -> 'freshness_days_by_category' ->> bb.category_id)::integer, (k.c ->> 'freshness_days')::integer) as days) w
   where not i.removed_by_admin
   group by i.business_id
) s on s.business_id = b.id
left join (
  select fl.business_id,
         count(*) as open_flags,
         count(*) filter (where fl.status = 'open'
                            and public.nairobi_today() - public.nairobi_day(fl.created_at) > (k.c ->> 'serious_flag_days')::integer) as serious_flags
    from public.flags fl
    cross join (select public.health_config() as c) k
   where fl.status in ('open', 'replied')
   group by fl.business_id
) f on f.business_id = b.id
left join (
  select rp.business_id, count(*) as open_reports
    from public.reports rp
   where rp.status = 'open'
   group by rp.business_id
) r on r.business_id = b.id;

create or replace view public.business_health_v with (security_invoker = true) as
select i.*,
       public.business_health(i.state, i.age_days, i.missing, i.items, i.fresh_items, i.fresh_days, i.activity_age_days,
                              i.open_flags, i.serious_flags, i.open_reports, i.strikes, cfg.c) as health
  from public.business_health_inputs_v i
  cross join (select public.health_config() as c) cfg;

revoke all on public.business_health_inputs_v, public.business_health_v from public, anon;
grant select on public.business_health_inputs_v, public.business_health_v to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 4. Daily snapshots: history, a 7-day trend, and the data to calibrate the weights against real non-renewals later.
--    The four parts are stored, so any other set of weights can be replayed over the past.
-- ---------------------------------------------------------------------------
create table if not exists public.business_health_snapshots (
  business_id uuid not null references public.businesses(id) on delete cascade,
  day date not null,
  score smallint not null check (score between 0 and 100),
  band text not null check (band in ('healthy', 'watch', 'at_risk')),
  state text not null,
  profile smallint not null,
  freshness smallint not null,
  activity smallint not null,
  trust smallint not null,
  capped boolean not null default false,
  reasons jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  primary key (business_id, day)
);
create index if not exists business_health_snapshots_day_idx on public.business_health_snapshots (day, score);

alter table public.business_health_snapshots enable row level security;
drop policy if exists "admin reads health snapshots" on public.business_health_snapshots;
create policy "admin reads health snapshots" on public.business_health_snapshots for select to authenticated using (public.is_admin());
revoke all on public.business_health_snapshots from public, anon, authenticated;
grant select on public.business_health_snapshots to authenticated;
grant all on public.business_health_snapshots to service_role;

-- Called by the daily job (daily-lifecycle). Running it again the same day just refreshes that day's rows.
-- Deleted businesses are not scored. Snapshots older than 400 days are dropped.
create or replace function public.snapshot_business_health(p_day date default null) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_day date := coalesce(p_day, public.nairobi_today());
  v_n integer;
begin
  insert into public.business_health_snapshots as s (business_id, day, score, band, state, profile, freshness, activity, trust, capped, reasons)
  select h.business_id, v_day, (h.health ->> 'score')::integer, h.health ->> 'band', h.state,
         (h.health #>> '{subs,profile}')::integer, (h.health #>> '{subs,freshness}')::integer,
         (h.health #>> '{subs,activity}')::integer, (h.health #>> '{subs,trust}')::integer,
         (h.health ->> 'capped')::boolean, h.health -> 'reasons'
    from public.business_health_v h
   where h.state <> 'deleted'
  on conflict (business_id, day) do update
    set score = excluded.score, band = excluded.band, state = excluded.state, profile = excluded.profile,
        freshness = excluded.freshness, activity = excluded.activity, trust = excluded.trust,
        capped = excluded.capped, reasons = excluded.reasons, created_at = now();
  get diagnostics v_n = row_count;
  delete from public.business_health_snapshots where day < v_day - 400;
  return v_n;
end $$;
revoke all on function public.snapshot_business_health(date) from public, anon, authenticated;
grant execute on function public.snapshot_business_health(date) to service_role;

-- ---------------------------------------------------------------------------
-- 5. The admin list. admin_businesses_v now carries the score, band, breakdown and 7-day trend from business_health_v, and the
--    three per-row subqueries (items, flags, reports) are gone. price_age_days and login_age_days are no longer columns: nothing
--    reads them, and both were part of the bugs.
-- ---------------------------------------------------------------------------
drop function if exists public.admin_businesses_filtered(jsonb, text);
drop view if exists public.admin_businesses_v;

create view public.admin_businesses_v with (security_invoker = true) as
select
  b.id,
  b.seller_id,
  b.slug,
  b.name,
  c.name as category,
  b.county,
  b.town,
  b.owner_name,
  b.phone,
  initcap(b.plan_key) as plan,
  (b.verification_level = 'verified') as verified,
  b.featured,
  ((b.deleted_at is not null) or (b.status = 'deleted')) as deleted,
  case when (b.status = 'live' and b.paid_until is null) then 'pending' else b.status end as ui_status,
  b.paid_until,
  public.nairobi_day(b.paid_until) as paid_day,
  public.days_left(b.paid_until) as days_left,
  h.state,
  h.items,
  h.open_flags,
  h.open_reports,
  exists (select 1 from public.payments p where p.business_id = b.id and p.status = 'submitted') as unconfirmed_payment,
  b.strikes,
  b.tags,
  b.last_login_at,
  coalesce(b.last_edit_at, b.updated_at) as last_edit_at,
  b.created_at,
  public.nairobi_day(b.created_at) as created_day,
  (h.health #>> '{subs,profile}')::integer as completeness,
  (h.health ->> 'score')::integer as health_score,
  h.health ->> 'band' as health_band,
  h.health as health,
  ((h.health ->> 'score')::integer - p.score)::integer as health_trend
from public.businesses b
left join public.categories c on c.id = b.category_id
join public.business_health_v h on h.business_id = b.id
left join (
  select distinct on (s.business_id) s.business_id, s.score
    from public.business_health_snapshots s
   where s.day between public.nairobi_today() - 14 and public.nairobi_today() - 7
   order by s.business_id, s.day desc
) p on p.business_id = b.id;

revoke all on public.admin_businesses_v from public, anon;
grant select on public.admin_businesses_v to authenticated, service_role;

create or replace function public.admin_businesses_filtered(p_filters jsonb default '{}', p_search text default null)
returns setof public.admin_businesses_v
language sql stable security invoker set search_path = public as $$
  select v.*
    from public.admin_businesses_v v
   where public.is_admin()
     and (coalesce(p_filters->>'category', '') = '' or v.category = p_filters->>'category')
     and (coalesce(p_filters->>'county', '')   = '' or v.county   = p_filters->>'county')
     and (coalesce(p_filters->>'town', '')     = '' or v.town     = p_filters->>'town')
     and (coalesce(p_filters->>'plan', '')     = '' or v.plan     = p_filters->>'plan')
     and (coalesce(p_filters->>'verified', '') = '' or v.verified = (p_filters->>'verified' = 'yes'))
     and (coalesce(p_filters->>'featured', '') = '' or v.featured = (p_filters->>'featured' = 'yes'))
     and (coalesce(p_filters->>'status', '')   = '' or v.state    = p_filters->>'status')
     and (coalesce(p_filters->>'health', '')   = '' or v.health_band = p_filters->>'health')
     and (coalesce(p_filters->>'daysMin', '') = '' or v.days_left >= (p_filters->>'daysMin')::numeric)
     and (coalesce(p_filters->>'daysMax', '') = '' or v.days_left <= (p_filters->>'daysMax')::numeric)
     and (coalesce(p_filters->>'hasFlags', 'false') <> 'true' or v.open_flags > 0)
     and (coalesce(p_filters->>'hasUnconfirmed', 'false') <> 'true' or v.unconfirmed_payment)
     and (coalesce(p_filters->>'agent', '') = ''
          or (p_filters->>'agent' = '__none__' and not exists (select 1 from public.businesses x where x.id = v.id and x.agent is not null))
          or exists (select 1 from public.businesses x where x.id = v.id and x.agent = p_filters->>'agent'))
     and (coalesce(p_filters->>'createdFrom', '') = '' or v.created_day >= (p_filters->>'createdFrom')::date)
     and (coalesce(p_filters->>'createdTo', '')   = '' or v.created_day <= (p_filters->>'createdTo')::date)
     and (btrim(coalesce(p_search, '')) = '' or
          v.name ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
       or v.phone ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
       or v.seller_id ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
       or v.slug ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%'
       or v.owner_name ilike '%' || replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%')
$$;
revoke all on function public.admin_businesses_filtered(jsonb, text) from public, anon;
grant execute on function public.admin_businesses_filtered(jsonb, text) to authenticated, service_role;

-- Same as 0061, except: healthScore sorts on the view's health_score column (no formula pasted into the ORDER BY), and each
-- row carries 'health' (the breakdown) and 'healthTrend' (points gained or lost against about 7 days ago; null until then).
create or replace function public.admin_businesses_query(
  p_tab text default 'all', p_search text default null, p_sort text default 'paidUntil', p_dir text default 'asc',
  p_filters jsonb default '{}', p_limit integer default 50, p_offset integer default 0
) returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare
  v_order text;
  v_dir text := case when lower(coalesce(p_dir, 'asc')) = 'desc' then 'desc' else 'asc' end;
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 5000);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_total bigint;
  v_rows jsonb;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  -- Only these columns can be sorted on: the key is looked up here, never pasted into the query.
  v_order := case p_sort
    when 'name' then 'lower(name)'
    when 'items' then 'items'
    when 'healthScore' then 'health_score'
    when 'lastLogin' then 'last_login_at'
    when 'createdAt' then 'created_at'
    when 'lastEdit' then 'last_edit_at'
    when 'strikes' then 'strikes'
    else 'paid_until'
  end;

  select count(*) into v_total
    from public.admin_businesses_filtered(p_filters, p_search) v
   where public.admin_business_in_tab(p_tab, v.state, v.open_flags);

  execute format($q$
    select coalesce(jsonb_agg(r.j order by r.rn), '[]'::jsonb) from (
      select row_number() over (order by %1$s %2$s nulls last, id) as rn,
        jsonb_build_object(
          'id', id, 'sellerId', seller_id, 'slug', slug, 'name', name, 'category', coalesce(category, ''),
          'county', coalesce(county, ''), 'town', coalesce(town, ''), 'ownerName', coalesce(owner_name, ''),
          'phone', coalesce(phone, ''), 'plan', plan, 'verified', verified, 'featured', featured,
          'status', ui_status, 'paidUntil', to_char(paid_day, 'YYYY-MM-DD'), 'items', items,
          'openFlags', open_flags, 'strikes', strikes, 'completeness', completeness, 'openReports', open_reports,
          'healthScore', health_score, 'healthBand', health_band, 'health', health, 'healthTrend', health_trend,
          'lastLogin', last_login_at, 'lastEdit', last_edit_at, 'createdAt', created_at,
          'state', state, 'agent', (select x.agent from public.businesses x where x.id = v.id), 'tags', to_jsonb(tags), 'deleted', deleted, 'unconfirmedPayment', unconfirmed_payment
        ) as j
      from public.admin_businesses_filtered($1, $2) v
      where public.admin_business_in_tab($3, v.state, v.open_flags)
      order by %1$s %2$s nulls last, id
      limit $4 offset $5
    ) r
  $q$, v_order, v_dir)
  into v_rows
  using p_filters, p_search, p_tab, v_limit, v_offset;

  return jsonb_build_object('total', v_total, 'rows', v_rows);
end $$;

-- One business: the live breakdown plus its last 30 days of snapshots, for the business page.
create or replace function public.admin_business_health(p_business uuid) returns jsonb
language plpgsql stable security invoker set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'current', (select h.health from public.business_health_v h where h.business_id = p_business),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object('day', s.day, 'score', s.score, 'band', s.band) order by s.day)
        from public.business_health_snapshots s
       where s.business_id = p_business and s.day >= public.nairobi_today() - 29), '[]'::jsonb));
end $$;
revoke all on function public.admin_business_health(uuid) from public, anon;
grant execute on function public.admin_business_health(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 6. Tuning. Owner only, validated strictly (a settings form should say "no", not silently clamp), audited like the other settings.
-- ---------------------------------------------------------------------------
create or replace function public.health_int_ok(p jsonb, p_path text[], p_min integer, p_max integer) returns boolean
language plpgsql immutable as $$
declare
  v text := p #>> p_path;
begin
  return case when v ~ '^[0-9]{1,4}$' then v::integer between p_min and p_max else false end;
end $$;

create or replace function public.admin_get_health_config() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role(array[]::text[]) then raise exception 'forbidden' using errcode = '42501'; end if;
  return public.health_config() - 'strike_threshold';
end $$;

create or replace function public.admin_save_health_config(p_config jsonb, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_before jsonb;
  v_ok boolean;
  v_entry record;
begin
  if not public.has_role(array[]::text[]) then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(p_config) is distinct from 'object' then raise exception 'invalid_health_config' using errcode = '22023'; end if;
  v_before := public.health_config() - 'strike_threshold';

  v_ok := public.health_int_ok(p_config, '{weights,profile}', 0, 100)
      and public.health_int_ok(p_config, '{weights,freshness}', 0, 100)
      and public.health_int_ok(p_config, '{weights,activity}', 0, 100)
      and public.health_int_ok(p_config, '{weights,trust}', 0, 100)
      and public.health_int_ok(p_config, '{grace_days}', 0, 90)
      and public.health_int_ok(p_config, '{neutral}', 0, 100)
      and public.health_int_ok(p_config, '{freshness_days}', 1, 365)
      and public.health_int_ok(p_config, '{activity_full_days}', 0, 90)
      and public.health_int_ok(p_config, '{activity_zero_days}', 1, 365)
      and public.health_int_ok(p_config, '{trust,flag}', 0, 100)
      and public.health_int_ok(p_config, '{trust,flag_cap}', 0, 100)
      and public.health_int_ok(p_config, '{trust,report}', 0, 100)
      and public.health_int_ok(p_config, '{trust,report_cap}', 0, 100)
      and public.health_int_ok(p_config, '{trust,strike}', 0, 100)
      and public.health_int_ok(p_config, '{trust,strike_cap}', 0, 100)
      and public.health_int_ok(p_config, '{serious_flag_days}', 0, 90)
      and public.health_int_ok(p_config, '{bands,healthy}', 2, 100)
      and public.health_int_ok(p_config, '{bands,watch}', 1, 99);
  if not v_ok then raise exception 'invalid_health_config' using errcode = '22023'; end if;

  if (p_config #>> '{weights,profile}')::integer + (p_config #>> '{weights,freshness}')::integer
     + (p_config #>> '{weights,activity}')::integer + (p_config #>> '{weights,trust}')::integer <= 0 then
    raise exception 'invalid_health_weights' using errcode = '22023';
  end if;
  if (p_config #>> '{bands,watch}')::integer >= (p_config #>> '{bands,healthy}')::integer then
    raise exception 'invalid_health_bands' using errcode = '22023';
  end if;
  if (p_config ->> 'activity_zero_days')::integer <= (p_config ->> 'activity_full_days')::integer then
    raise exception 'invalid_health_activity' using errcode = '22023';
  end if;
  if p_config ? 'freshness_days_by_category' then
    if jsonb_typeof(p_config -> 'freshness_days_by_category') <> 'object' then
      raise exception 'invalid_health_config' using errcode = '22023';
    end if;
    for v_entry in select e.key, e.value from jsonb_each(p_config -> 'freshness_days_by_category') e loop
      if v_entry.key !~ '^[a-z0-9-]{2,50}$' or not public.health_int_ok(jsonb_build_object('v', v_entry.value), '{v}', 1, 365) then
        raise exception 'invalid_health_config' using errcode = '22023';
      end if;
    end loop;
  end if;

  insert into public.site_settings (key, value) values ('health_config', public.health_normalize(p_config))
  on conflict (key) do update set value = excluded.value, updated_at = now();

  perform public.admin_audit_action('settings.update', 'settings', 'health', v_before,
    public.health_config() - 'strike_threshold', nullif(btrim(coalesce(p_reason, '')), ''));
  return public.health_config() - 'strike_threshold';
end $$;

revoke all on function public.health_num(jsonb, text[], numeric, numeric, numeric), public.health_normalize(jsonb),
  public.health_config(), public.business_health(text, integer, text[], integer, integer, integer, integer, integer, integer, integer, integer, jsonb),
  public.health_int_ok(jsonb, text[], integer, integer) from public, anon;
grant execute on function public.health_num(jsonb, text[], numeric, numeric, numeric), public.health_normalize(jsonb),
  public.health_config(), public.business_health(text, integer, text[], integer, integer, integer, integer, integer, integer, integer, integer, jsonb),
  public.health_int_ok(jsonb, text[], integer, integer) to authenticated, service_role;
revoke all on function public.admin_get_health_config(), public.admin_save_health_config(jsonb, text) from public, anon;
grant execute on function public.admin_get_health_config(), public.admin_save_health_config(jsonb, text) to authenticated, service_role;

-- First snapshot, so the trend starts counting from today.
select public.snapshot_business_health();

$m_0078_business_health$),
    ('0079_message_simulated_status', $m_0079_message_simulated_status$
-- 0079_message_simulated_status.sql
-- A message that was never sent (messaging mode "mock": the default outside production) used to be recorded as
-- 'sent', so the log and the cost summary looked like real traffic. It is now recorded as 'simulated'.
--
--   * messages.status accepts 'simulated' (it is only ever written when the dispatcher is in mock mode). 'cancelled'
--     (0072) stays allowed: this rebuilds the CHECK from the full list.
--   * record_message_result() accepts p_final_status = 'simulated'. Its retry policy and the live path are unchanged.
--   * admin_message_log_query() can filter on 'simulated'. It is the version from 0074 (applicant names, 'cancelled')
--     with 'simulated' added, so nothing 0074 added is lost.
--   * admin_message_summary(): by_status lists 'simulated' on its own, and cost_kes no longer counts simulated rows.
--   * admin_automation_status().last_sent_at keeps counting only 'sent' and 'delivered', so a simulated row is not
--     reported as the last real send. It needs no change here.
--   * A simulated row is not counted as sent in the pending-broadcast and cancel summaries (0072): it was never sent.
--
-- Existing rows keep their status: rows already recorded as 'sent' with provider_id 'dev' stay as they are.
-- Must run AFTER 0072 and 0074 (it is numbered after them; 0078 is unrelated), and BEFORE deploying dispatch-messages: a mock-mode
-- dispatcher would otherwise violate the CHECK constraint. Safe to run more than once.

do $$
declare v_name text;
begin
  for v_name in
    select c.conname from pg_constraint c
     where c.conrelid = 'public.messages'::regclass and c.contype = 'c'
       and pg_get_constraintdef(c.oid) like '%status%' and pg_get_constraintdef(c.oid) like '%queued%'
  loop
    execute format('alter table public.messages drop constraint %I', v_name);
  end loop;
  alter table public.messages add constraint messages_status_check
    check (status in ('queued', 'sent', 'delivered', 'simulated', 'failed', 'cancelled'));
end $$;

create or replace function public.record_message_result(
  p_id uuid, p_ok boolean, p_provider_id text default null, p_error text default null, p_cost numeric default null,
  p_now timestamptz default now(), p_max_attempts integer default 3, p_final_status text default 'sent')
returns text
language plpgsql security definer set search_path = public as $$
declare
  m public.messages;
  v_attempts integer;
  v_error text := left(coalesce(nullif(p_error, ''), 'send_failed'), 500);
begin
  if p_final_status not in ('sent', 'delivered', 'simulated') then raise exception 'bad_final_status' using errcode = '22023'; end if;
  select * into m from public.messages where id = p_id for update;
  if not found or m.status <> 'queued' then return 'noop'; end if;
  v_attempts := m.attempts + 1;

  if p_ok then
    update public.messages
       set status = p_final_status, attempts = v_attempts, provider_id = p_provider_id,
           cost_kes = p_cost, error = null, sent_at = p_now
     where id = p_id;
    return 'sent';
  end if;

  if v_attempts >= greatest(p_max_attempts, 1) then
    update public.messages set status = 'failed', attempts = v_attempts, error = v_error where id = p_id;
    insert into public.admin_notifications (kind, business_id, data)
    values ('message_failed', m.business_id, jsonb_build_object(
      'message_id', m.id, 'channel', m.channel, 'attempts', v_attempts, 'error', v_error,
      'subject', m.subject, 'template_key', m.template_key, 'application_id', m.application_id));
    return 'failed';
  end if;

  update public.messages
     set attempts = v_attempts, error = v_error,
         scheduled_at = p_now + make_interval(mins => case v_attempts when 1 then 5 else 15 end)
   where id = p_id;
  return 'retry';
end $$;

create or replace function public.admin_message_log_query(
  p_channel text default 'all', p_status text default 'all', p_search text default null,
  p_limit integer default 50, p_offset integer default 0
) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_total bigint;
  v_rows jsonb;
begin
  if not public.has_role(array['owner', 'reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(p_channel, 'all') not in ('all', 'sms', 'email', 'in_app') then raise exception 'invalid_channel'; end if;
  if coalesce(p_status, 'all') not in ('all', 'queued', 'sent', 'delivered', 'simulated', 'failed', 'cancelled') then raise exception 'invalid_status'; end if;

  select count(*) into v_total
    from public.messages m left join public.businesses b on b.id = m.business_id
   where m.sender <> 'seller'
     and (coalesce(p_channel, 'all') = 'all' or m.channel = p_channel)
     and (coalesce(p_status, 'all') = 'all' or m.status = p_status)
     and (v_search is null or m.subject ilike '%' || v_search || '%' or m.to_address ilike '%' || v_search || '%'
          or m.template_key ilike '%' || v_search || '%' or b.name ilike '%' || v_search || '%');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb) into v_rows from (
    select m.id, m.created_at, m.channel, m.status, m.kind, m.subject, m.template_key, m.to_address, m.transactional,
           m.business_id, b.name as business_name, m.application_id, a.business_name as application_name,
           m.attempts, m.error, m.cost_kes, m.scheduled_at, m.sent_at
      from public.messages m
      left join public.businesses b on b.id = m.business_id
      left join public.applications a on a.id = m.application_id
     where m.sender <> 'seller'
       and (coalesce(p_channel, 'all') = 'all' or m.channel = p_channel)
       and (coalesce(p_status, 'all') = 'all' or m.status = p_status)
       and (v_search is null or m.subject ilike '%' || v_search || '%' or m.to_address ilike '%' || v_search || '%'
            or m.template_key ilike '%' || v_search || '%' or b.name ilike '%' || v_search || '%')
     order by m.created_at desc
     limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0)
  ) x;
  return jsonb_build_object('rows', v_rows, 'total', v_total);
end $$;

create or replace function public.admin_message_summary(p_days integer default 7) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_days integer := least(greatest(coalesce(p_days, 7), 1), 90);
begin
  if not public.has_role(array['owner', 'reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'days', v_days,
    'by_status', coalesce((
      select jsonb_object_agg(s.status, s.n) from (
        select m.status, count(*) as n from public.messages m
         where m.sender <> 'seller' and m.channel in ('sms', 'email') and m.created_at >= now() - make_interval(days => v_days)
         group by m.status) s), '{}'::jsonb),
    'cost_kes', coalesce((select sum(m.cost_kes) from public.messages m
       where m.channel = 'sms' and m.status <> 'simulated' and m.created_at >= now() - make_interval(days => v_days)), 0),
    'queued_now', (select count(*) from public.messages m where m.status = 'queued' and m.channel in ('sms', 'email')),
    'due_now', (select count(*) from public.messages m where m.status = 'queued' and m.channel in ('sms', 'email') and m.scheduled_at <= now()),
    'oldest_due_at', (select min(m.scheduled_at) from public.messages m where m.status = 'queued' and m.channel in ('sms', 'email') and m.scheduled_at <= now()),
    'failed_now', (select count(*) from public.messages m where m.status = 'failed' and m.created_at >= now() - make_interval(days => v_days))
  );
end $$;

$m_0079_message_simulated_status$),
    ('0080_admin_conversations_page', $m_0080_admin_conversations_page$
-- 0080_admin_conversations_page.sql
-- The admin Messages inbox used to load the newest 1000 messages across ALL businesses and group, search, filter and count
-- them in the browser. Older conversations dropped off, and the unread numbers (counted from those 1000 rows) disagreed with
-- the sidebar badge (admin_unread_messages(), counted over every message).
--
-- admin_conversations_page() does that work on the server, one page at a time, newest activity first, one row per business:
--   * p_filter  'all' | 'unread' | 'waiting' | 'resolved'   (same meaning as the tabs on the Messages page:
--               waiting = staff asked for a reply and the last word was staff's, and the conversation is not resolved)
--   * p_search  matches the business name, the seller ID, or any message subject or body (case-insensitive)
--   * `counts`  the size of each tab, scoped to the search (so the tab badges stay right whichever tab is open)
--   * `unread`  per row uses EXACTLY the predicate of admin_unread_messages() (a seller message, in-app, not read by an
--               admin, not hidden), and `unread_total` IS admin_unread_messages(), so the list and the badge cannot drift.
--   * `resolved` comes from admin_conversation_state (migration 0067).
-- A conversation's messages are then loaded for one business at a time.
--
-- Same rules as the other admin reads: any admin, security definer, read only, safe to run more than once.
create or replace function public.admin_conversations_page(
  p_limit integer default 30, p_offset integer default 0, p_filter text default 'all', p_search text default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_filter text := coalesce(nullif(btrim(p_filter), ''), 'all');
  v_needle text := nullif(btrim(regexp_replace(coalesce(p_search, ''), '\s+', ' ', 'g')), '');
  v_pat text;
  v_counts jsonb;
  v_total bigint;
  v_rows jsonb;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if v_filter not in ('all', 'unread', 'waiting', 'resolved') then raise exception 'invalid_filter'; end if;
  -- LIKE pattern for the search, with the wildcard characters in what was typed taken literally.
  v_pat := case when v_needle is null then null
                else '%' || replace(replace(replace(lower(v_needle), '\', '\\'), '%', '\%'), '_', '\_') || '%' end;

  with vis as (
    select m.* from public.messages m
     where m.channel = 'in_app' and m.business_id is not null and m.admin_hidden_at is null
  ), per_thread as (
    -- A thread "waits for a reply" when staff asked for one somewhere in it and the last word was staff's (as in groupThreads()).
    select v.business_id, coalesce(v.thread_id, v.id) as thread_id,
           bool_or(v.sender = 'admin' and v.needs_reply) as asked,
           (array_agg(v.sender order by v.created_at desc, v.id desc))[1] as last_sender
      from vis v group by 1, 2
  ), waiting as (
    select t.business_id, bool_or(t.asked and t.last_sender = 'admin') as waiting from per_thread t group by 1
  ), per_business as (
    select v.business_id, b.name as business_name, b.seller_id,
           max(v.created_at) as last_at,
           (array_agg(v.subject order by v.created_at desc, v.id desc))[1] as last_subject,
           count(*) as message_count,
           count(*) filter (where v.sender = 'seller' and v.admin_read_at is null) as unread
      from vis v join public.businesses b on b.id = v.business_id
     group by v.business_id, b.name, b.seller_id
  ), scoped as (
    select p.*, coalesce(w.waiting, false) as waiting,
           exists (select 1 from public.admin_conversation_state s where s.business_id = p.business_id) as resolved
      from per_business p left join waiting w on w.business_id = p.business_id
     where v_pat is null
        or lower(coalesce(p.business_name, '')) like v_pat escape '\'
        or lower(coalesce(p.seller_id, '')) like v_pat escape '\'
        or exists (select 1 from vis v where v.business_id = p.business_id
                    and (lower(coalesce(v.subject, '')) like v_pat escape '\' or lower(coalesce(v.body, '')) like v_pat escape '\'))
  ), shown as (
    select s.* from scoped s
     where case v_filter when 'unread' then s.unread > 0
                         when 'waiting' then s.waiting and not s.resolved
                         when 'resolved' then s.resolved
                         else true end
  )
  select
    jsonb_build_object('all', (select count(*) from scoped),
                       'unread', (select count(*) from scoped where unread > 0),
                       'waiting', (select count(*) from scoped where waiting and not resolved),
                       'resolved', (select count(*) from scoped where resolved)),
    (select count(*) from shown),
    coalesce((select jsonb_agg(to_jsonb(x) order by x.last_at desc, x.business_id) from (
      select business_id, business_name, seller_id, last_at, last_subject, message_count, unread, waiting, resolved
        from shown order by last_at desc, business_id
       limit least(greatest(coalesce(p_limit, 30), 1), 100) offset greatest(coalesce(p_offset, 0), 0)) x), '[]'::jsonb)
  into v_counts, v_total, v_rows;

  return jsonb_build_object('rows', v_rows, 'total', v_total, 'counts', v_counts, 'unread_total', public.admin_unread_messages());
end $$;

revoke all on function public.admin_conversations_page(integer, integer, text, text) from public, anon;
grant execute on function public.admin_conversations_page(integer, integer, text, text) to authenticated, service_role;

$m_0080_admin_conversations_page$),
    ('0081_admin_all_scheduled_jobs', $m_0081_admin_all_scheduled_jobs$
-- 0081_admin_all_scheduled_jobs.sql
-- Admin > Automation watched two of the four scheduled jobs. proofs-purge and media-gc (both in supabase/cron/schedule.sql)
-- could not be seen, paused or run from the admin.
--
-- admin_automation_status() (what is shown), admin_set_job_active() (pause / resume) and admin_run_job() (Run now) all work
-- from this one list, so listing the two missing jobs gives them the same view / pause / run-now controls as the others.
-- Run now calls /functions/v1/<name> with the cron secret, exactly as the schedule does, and both functions accept it.
--
-- A job that is listed but not scheduled in the project shows as "Not scheduled" with the fix: re-run supabase/cron/schedule.sql.
-- Keep this list equal to the jobs in schedule.sql; scripts/cron-schedule.test.mjs fails if they differ.
create or replace function public.admin_job_names() returns text[]
language sql immutable as $$ select array['dispatch-messages', 'daily-lifecycle', 'proofs-purge', 'media-gc'] $$;

$m_0081_admin_all_scheduled_jobs$),
    ('0082_business_events', $m_0082_business_events$
-- 0082_business_events.sql
-- Views and contact taps, stored for real, so the seller Performance panel reads numbers that survive a restart.
--
-- Until now logContactEvent only bumped an in-memory mock. This adds:
--   business_events        short-lived raw rows, used ONLY to de-duplicate (like search_events). One row per
--                          (business, item, type, anonymous client, hour). Pruned after 2 days.
--   business_event_daily   the permanent record: one row per (business, Nairobi day, type, item) with a count.
--                          A 36-month or all-time range reads at most ~365 rows per type per business, never raw events.
--   log_business_event()   what the customer app calls. Writes the raw row and, only when it was new, adds 1 to the rollup in
--                          the same transaction, so the two can never disagree and no job is needed to keep them fresh.
--   seller_performance()   the panel's read: totals plus a gap-filled series for a range. Same for every plan (no plan gate).
--   seller_item_history()  the item History list. Everyone gets the newest 5; Premium gets all (limit key historyEntries).
--
-- Privacy: no raw IP is stored. The client hash is sha256(salt : UTC day : IP), salted per purpose so it cannot be joined to
-- search_events, and it changes every day. Rows with no IP header are dropped, as log_search does.
-- Days are Nairobi calendar days (docs/timezones.md: an analytics day bucket is a date; the zone is named, never the session's).
-- Rollup rows keep item_id as a plain uuid with no foreign key: deleting an item must not change the shop's totals.
-- Additive; safe to run again.

create table if not exists public.business_events (
  id bigint generated always as identity primary key,
  business_id uuid not null references public.businesses(id) on delete cascade,
  item_id uuid references public.items(id) on delete cascade,
  type text not null check (type in ('view', 'call', 'whatsapp', 'directions')),
  client_hash text not null,
  bucket bigint not null,
  created_at timestamptz not null default now()
);
create unique index if not exists business_events_dedupe_idx
  on public.business_events (business_id, coalesce(item_id, '00000000-0000-0000-0000-000000000000'::uuid), type, client_hash, bucket);
create index if not exists business_events_created_idx on public.business_events (created_at);
create index if not exists business_events_client_idx on public.business_events (client_hash, created_at desc);

create table if not exists public.business_event_daily (
  business_id uuid not null references public.businesses(id) on delete cascade,
  day date not null,
  type text not null check (type in ('view', 'call', 'whatsapp', 'directions')),
  item_id uuid,
  n integer not null default 0 check (n >= 0)
);
create unique index if not exists business_event_daily_key
  on public.business_event_daily (business_id, day, type, coalesce(item_id, '00000000-0000-0000-0000-000000000000'::uuid));
create index if not exists business_event_daily_day_idx on public.business_event_daily (business_id, day);

alter table public.business_events enable row level security;
alter table public.business_event_daily enable row level security;
revoke all on public.business_events, public.business_event_daily from public, anon, authenticated;
grant all on public.business_events, public.business_event_daily to service_role;

create or replace function public.log_business_event(p_business_id uuid, p_type text, p_item_id uuid default null) returns void
language plpgsql volatile security definer set search_path = public, extensions set statement_timeout = '2s' as
$$
declare
  v_headers jsonb;
  v_ip text;
  v_client text;
  v_rows integer;
  c_zero constant uuid := '00000000-0000-0000-0000-000000000000';
begin
  if p_business_id is null or p_type is null or p_type not in ('view', 'call', 'whatsapp', 'directions') then
    return;
  end if;

  v_headers := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb;
  v_ip := coalesce(nullif(btrim(v_headers ->> 'cf-connecting-ip'), ''), nullif(btrim(v_headers ->> 'x-real-ip'), ''));
  if v_ip is null then
    return;
  end if;

  if not exists (select 1 from public.businesses b where b.id = p_business_id and b.status = 'live') then
    return;
  end if;
  if p_item_id is not null and not exists (select 1 from public.items i where i.id = p_item_id and i.business_id = p_business_id) then
    return;
  end if;

  v_client := encode(digest((select salt from public.search_salt limit 1) || ':event:' || (now() at time zone 'UTC')::date::text || ':' || v_ip, 'sha256'), 'hex');

  if (select count(*) from public.business_events where client_hash = v_client and created_at > now() - interval '1 minute') >= 60 then
    return;
  end if;
  if (select count(*) from public.business_events where created_at > now() - interval '1 minute') >= 3000 then
    return;
  end if;

  insert into public.business_events (business_id, item_id, type, client_hash, bucket)
  values (p_business_id, p_item_id, p_type, v_client, floor(extract(epoch from now()) / 3600)::bigint)
  on conflict do nothing;
  get diagnostics v_rows = row_count;

  if v_rows > 0 then
    insert into public.business_event_daily (business_id, day, type, item_id, n)
    values (p_business_id, (now() at time zone 'Africa/Nairobi')::date, p_type, p_item_id, 1)
    on conflict (business_id, day, type, (coalesce(item_id, c_zero))) do update set n = public.business_event_daily.n + 1;
  end if;

  if random() < 0.01 then
    delete from public.business_events
    where id in (select id from public.business_events where created_at < now() - interval '2 days' order by created_at limit 5000);
  end if;
exception when others then
  return;
end $$;
revoke all on function public.log_business_event(uuid, text, uuid) from public;
grant execute on function public.log_business_event(uuid, text, uuid) to anon, authenticated, service_role;

-- Ranges: 7d, 1m, 6m, 12m, 24m, 36m, all. The series is gap-filled so the chart never has to guess a missing day.
-- Grain follows the span so a long range stays a few dozen points: up to 62 days by day, up to 400 by week, longer by month.
create or replace function public.seller_performance(p_range text default '1m', p_item_id uuid default null) returns jsonb
language plpgsql stable security definer set search_path = public set statement_timeout = '5s' as
$$
declare
  v_id uuid := public.my_business_id();
  v_today date := (now() at time zone 'Africa/Nairobi')::date;
  v_from date;
  v_grain text;
  v_first date;
begin
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  if p_range = '7d' then v_from := v_today - 6;
  elsif p_range = '1m' then v_from := (v_today - interval '1 month')::date + 1;
  elsif p_range = '6m' then v_from := (v_today - interval '6 months')::date + 1;
  elsif p_range = '12m' then v_from := (v_today - interval '12 months')::date + 1;
  elsif p_range = '24m' then v_from := (v_today - interval '24 months')::date + 1;
  elsif p_range = '36m' then v_from := (v_today - interval '36 months')::date + 1;
  elsif p_range = 'all' then
    select min(d.day) into v_first from public.business_event_daily d where d.business_id = v_id;
    v_from := coalesce(v_first, v_today);
  else
    raise exception 'invalid_range' using errcode = 'P0001';
  end if;

  v_grain := case when v_today - v_from <= 62 then 'day' when v_today - v_from <= 400 then 'week' else 'month' end;

  return jsonb_build_object(
    'range', p_range,
    'grain', v_grain,
    'from', v_from,
    'to', v_today,
    'totals', (
      select jsonb_build_object(
        'view', coalesce(sum(d.n) filter (where d.type = 'view'), 0),
        'whatsapp', coalesce(sum(d.n) filter (where d.type = 'whatsapp'), 0),
        'call', coalesce(sum(d.n) filter (where d.type = 'call'), 0),
        'directions', coalesce(sum(d.n) filter (where d.type = 'directions'), 0))
      from public.business_event_daily d
      where d.business_id = v_id and d.day between v_from and v_today and (p_item_id is null or d.item_id = p_item_id)
    ),
    'series', coalesce((
      select jsonb_agg(jsonb_build_object('bucket', g.b, 'view', coalesce(s.v, 0), 'whatsapp', coalesce(s.w, 0), 'call', coalesce(s.c, 0), 'directions', coalesce(s.r, 0)) order by g.b)
      from generate_series(date_trunc(v_grain, v_from::timestamp), v_today::timestamp, ('1 ' || v_grain)::interval) as g(b)
      left join (
        select date_trunc(v_grain, d.day::timestamp) as b,
          sum(d.n) filter (where d.type = 'view') as v,
          sum(d.n) filter (where d.type = 'whatsapp') as w,
          sum(d.n) filter (where d.type = 'call') as c,
          sum(d.n) filter (where d.type = 'directions') as r
        from public.business_event_daily d
        where d.business_id = v_id and d.day between v_from and v_today and (p_item_id is null or d.item_id = p_item_id)
        group by 1
      ) s on s.b = g.b
    ), '[]'::jsonb)
  );
end $$;
revoke all on function public.seller_performance(text, uuid) from public, anon;
grant execute on function public.seller_performance(text, uuid) to authenticated, service_role;

-- The History gate. Same resolution as the app's limitsFor(): the plan default (standard 5, premium all) unless global_limits
-- carries a historyEntries key for that plan, where an explicit null means "all".
create or replace function public.seller_item_history(p_item_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as
$$
declare
  v_id uuid := public.my_business_id();
  v_plan text;
  v_over jsonb;
  v_limit integer;
  v_total integer;
begin
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item_id and i.business_id = v_id) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;

  select b.plan_key into v_plan from public.businesses b where b.id = v_id;
  select case when v_plan = 'premium' then g.premium else g.standard end into v_over from public.global_limits g where g.id = 1;
  v_over := coalesce(v_over, '{}'::jsonb);
  v_limit := case when v_over ? 'historyEntries' then (v_over ->> 'historyEntries')::integer
                  when v_plan = 'premium' then null else 5 end;

  select count(*) into v_total from public.item_history h where h.item_id = p_item_id and h.business_id = v_id;

  return jsonb_build_object(
    'limit', v_limit,
    'total', v_total,
    'locked', v_limit is not null and v_total > v_limit,
    'entries', coalesce((
      select jsonb_agg(jsonb_build_object('id', e.id, 'field', e.field, 'old_value', e.old_value, 'new_value', e.new_value, 'actor_role', e.actor_role, 'created_at', e.created_at) order by e.created_at desc, e.id desc)
      from (
        select h.id, h.field, h.old_value, h.new_value, h.actor_role, h.created_at
        from public.item_history h
        where h.item_id = p_item_id and h.business_id = v_id
        order by h.created_at desc, h.id desc
        limit v_limit
      ) e
    ), '[]'::jsonb)
  );
end $$;
revoke all on function public.seller_item_history(uuid) from public, anon;
grant execute on function public.seller_item_history(uuid) to authenticated, service_role;

-- Deals tab: how this item did on the days each flash sale or offer ran. The rollup is per Nairobi day, so a deal is credited with
-- every view and tap the item got on any day the deal was running (a day it shared with normal trading counts in full).
-- Premium only (limit key flashAttribution). Standard gets { locked: true } and no numbers at all, never a partial answer.
create or replace function public.seller_item_deals(p_item_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public set statement_timeout = '5s' as
$$
declare
  v_id uuid := public.my_business_id();
  v_plan text;
  v_over jsonb;
  v_allowed boolean;
  v_today date := (now() at time zone 'Africa/Nairobi')::date;
begin
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item_id and i.business_id = v_id) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;

  select b.plan_key into v_plan from public.businesses b where b.id = v_id;
  select case when v_plan = 'premium' then g.premium else g.standard end into v_over from public.global_limits g where g.id = 1;
  v_over := coalesce(v_over, '{}'::jsonb);
  v_allowed := case when v_over ? 'flashAttribution' then coalesce((v_over ->> 'flashAttribution')::boolean, false) else v_plan = 'premium' end;
  if not v_allowed then
    return jsonb_build_object('locked', true, 'flash', '[]'::jsonb, 'offers', '[]'::jsonb);
  end if;

  return jsonb_build_object(
    'locked', false,
    'flash', coalesce((
      select jsonb_agg(row_to_json(x) order by x.starts_at desc) from (
        select f.id, f.headline, f.status, f.starts_at, f.ends_at,
          coalesce(sum(d.n) filter (where d.type = 'view'), 0)::int as view,
          coalesce(sum(d.n) filter (where d.type = 'whatsapp'), 0)::int as whatsapp,
          coalesce(sum(d.n) filter (where d.type = 'call'), 0)::int as call,
          coalesce(sum(d.n) filter (where d.type = 'directions'), 0)::int as directions
        from public.flash_sales f
        left join public.business_event_daily d on d.business_id = f.business_id and d.item_id = f.item_id
          and d.day between (f.starts_at at time zone 'Africa/Nairobi')::date and (coalesce(f.ended_at, f.ends_at) at time zone 'Africa/Nairobi')::date
        where f.item_id = p_item_id and f.business_id = v_id and f.status <> 'cancelled'
        group by f.id
        order by f.starts_at desc limit 20
      ) x), '[]'::jsonb),
    'offers', coalesce((
      select jsonb_agg(row_to_json(x) order by x.starts_at desc) from (
        select o.id, o.title, o.active, coalesce(o.starts_at, o.created_at) as starts_at, o.ends_at,
          coalesce(sum(d.n) filter (where d.type = 'view'), 0)::int as view,
          coalesce(sum(d.n) filter (where d.type = 'whatsapp'), 0)::int as whatsapp,
          coalesce(sum(d.n) filter (where d.type = 'call'), 0)::int as call,
          coalesce(sum(d.n) filter (where d.type = 'directions'), 0)::int as directions
        from public.offer_items oi
        join public.offers o on o.id = oi.offer_id and o.business_id = v_id and not o.removed_by_admin
        left join public.business_event_daily d on d.business_id = o.business_id and d.item_id = oi.item_id
          and d.day between (coalesce(o.starts_at, o.created_at) at time zone 'Africa/Nairobi')::date
            and least(v_today, (case when o.active then coalesce(o.ends_at, now()) else least(coalesce(o.ends_at, o.updated_at), o.updated_at) end at time zone 'Africa/Nairobi')::date)
        where oi.item_id = p_item_id
        group by o.id
        order by coalesce(o.starts_at, o.created_at) desc limit 20
      ) x), '[]'::jsonb)
  );
end $$;
revoke all on function public.seller_item_deals(uuid) from public, anon;
grant execute on function public.seller_item_deals(uuid) to authenticated, service_role;

$m_0082_business_events$),
    ('0083_seller_analytics_suspension_guard', $m_0083_seller_analytics_suspension_guard$
-- 0083_seller_analytics_suspension_guard.sql
-- 0082 added three seller read functions without the suspension guard that every other seller function has, so a
-- suspended seller could still read their Performance numbers, item history and item deals. The repo's own rule
-- (conversations.test.mjs: "every plpgsql seller function refuses a suspended seller") already flagged it.
--
-- Same mechanism 0016 used: make perform public.assert_seller_active() the first statement of each function, by rewriting the
-- stored definition rather than copying its body here (a copy would drift from 0082). Nothing else about the functions changes:
-- CREATE OR REPLACE keeps their grants and ownership. Safe to run again: a function that already has the guard is skipped.
-- It raises if one of the three is missing or the rewrite finds no begin to hook into, so it can never silently do nothing.
do $$
declare
  r record;
  def text;
  patched integer := 0;
  found integer := 0;
begin
  for r in
    select p.oid, p.proname from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and p.proname in ('seller_performance', 'seller_item_history', 'seller_item_deals')
  loop
    found := found + 1;
    def := pg_get_functiondef(r.oid);
    if position('assert_seller_active' in def) = 0 then
      def := regexp_replace(def, E'\nbegin\n', E'\nbegin\n  perform public.assert_seller_active();\n', 'i');
      if position('assert_seller_active' in def) = 0 then
        raise exception '0083: could not add the guard to %', r.proname;
      end if;
      execute def;
      patched := patched + 1;
    end if;
  end loop;
  if found <> 3 then
    raise exception '0083: expected 3 seller analytics functions (from 0082), found %', found;
  end if;
  raise notice '0083: guarded % of 3 functions (the rest already were)', patched;
end $$;

$m_0083_seller_analytics_suspension_guard$),
    ('0084_items_realtime', $m_0084_items_realtime$
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['items', 'item_history'] loop
      if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

$m_0084_items_realtime$),
    ('0085_item_variants', $m_0085_item_variants$
update public.items set variants = '[]'::jsonb where jsonb_typeof(variants) is distinct from 'array';
alter table public.items alter column variants set default '[]'::jsonb;

create or replace function public.item_variants_valid(p_variants jsonb) returns boolean
language plpgsql immutable as
$$
declare
  v_e jsonb;
  v_ids text[] := '{}';
  v_labels text[] := '{}';
  v_label text;
begin
  if p_variants is null or jsonb_typeof(p_variants) <> 'array' or jsonb_array_length(p_variants) > 10 then return false; end if;
  for v_e in select e from jsonb_array_elements(p_variants) as t(e) loop
    if jsonb_typeof(v_e) <> 'object' or exists (select 1 from jsonb_object_keys(v_e) k where k not in ('id', 'label', 'price', 'stock')) then return false; end if;
    if jsonb_typeof(v_e -> 'id') <> 'string' or (v_e ->> 'id') !~ '^[a-z0-9_-]{1,20}$' or (v_e ->> 'id') = any (v_ids) then return false; end if;
    v_label := lower(btrim(coalesce(v_e ->> 'label', '')));
    if jsonb_typeof(v_e -> 'label') <> 'string' or char_length(v_label) < 1 or char_length(v_label) > 40 or v_label = any (v_labels) then return false; end if;
    if jsonb_typeof(v_e -> 'price') <> 'number' or (v_e ->> 'price') !~ '^\d{1,10}(\.\d{1,2})?$' then return false; end if;
    if coalesce(v_e ->> 'stock', '') <> '' and ((v_e ->> 'stock') !~ '^\d{1,6}$') then return false; end if;
    v_ids := v_ids || (v_e ->> 'id');
    v_labels := v_labels || v_label;
  end loop;
  return true;
end $$;

create or replace function public.seller_save_item(p_id uuid, p_fields jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_old public.items;
  v_name text := btrim(coalesce(f ->> 'name', ''));
  v_desc text := nullif(btrim(coalesce(f ->> 'description', '')), '');
  v_section text := nullif(btrim(coalesce(f ->> 'section', '')), '');
  v_unit text := nullif(btrim(coalesce(f ->> 'unit', '')), '');
  v_type text := f ->> 'price_type';
  v_avail text := f ->> 'availability';
  v_old_item public.items;
  v_track boolean;
  v_count integer;
  v_low integer;
  v_show boolean;
  v_price numeric;
  v_max numeric;
  v_sale numeric;
  v_sort integer;
  v_new uuid;
  v_brand text;
  v_short text;
  v_terms text;
  v_pack text;
  v_hl jsonb;
  v_specs jsonb;
  v_inc text[];
  v_var jsonb;
  c_money constant text := '^\d{1,10}(\.\d{1,2})?$';
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  if char_length(v_name) < 2 or char_length(v_name) > 120 then raise exception 'invalid_name' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_desc, '')) > 2000 or char_length(coalesce(v_section, '')) > 60 or char_length(coalesce(v_unit, '')) > 30 then
    raise exception 'invalid_text' using errcode = 'P0001';
  end if;
  if v_avail is null or v_avail not in ('available','limited_stock','out_of_stock','unavailable','by_appointment') then
    raise exception 'invalid_availability' using errcode = 'P0001';
  end if;
  if v_type is null or v_type not in ('fixed','from','range','free','contact') then raise exception 'invalid_price' using errcode = 'P0001'; end if;

  if p_id is not null then
    select * into v_old_item from public.items i where i.id = p_id and i.business_id = v_id;
  end if;
  if (f ? 'low_stock_threshold' and coalesce(f ->> 'low_stock_threshold', '') !~ '^\d{1,4}$')
     or (f ? 'track_stock' and coalesce(f ->> 'track_stock', '') not in ('true', 'false'))
     or (f ? 'show_stock_count' and coalesce(f ->> 'show_stock_count', '') not in ('true', 'false')) then
    raise exception 'invalid_stock' using errcode = 'P0001';
  end if;
  v_track := case when f ? 'track_stock' then coalesce((f ->> 'track_stock')::boolean, false) else coalesce(v_old_item.track_stock, false) end;
  v_low := case when f ? 'low_stock_threshold' then (f ->> 'low_stock_threshold')::integer else coalesce(v_old_item.low_stock_threshold, 3) end;
  v_show := case when f ? 'show_stock_count' then coalesce((f ->> 'show_stock_count')::boolean, false) else coalesce(v_old_item.show_stock_count, false) end;
  if f ? 'stock_count' and coalesce(f ->> 'stock_count', '') <> '' then
    if (f ->> 'stock_count') !~ '^\d{1,6}$' then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
    v_count := (f ->> 'stock_count')::integer;
  elsif f ? 'stock_count' then
    v_count := null;
  else
    v_count := v_old_item.stock_count;
  end if;
  if v_low is null or v_low < 0 or v_low > 9999 then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
  if v_track and v_count is null then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
  if v_track then v_avail := 'available'; end if;

  if (f ? 'brand' and jsonb_typeof(f -> 'brand') not in ('string', 'null'))
     or (f ? 'short_description' and jsonb_typeof(f -> 'short_description') not in ('string', 'null'))
     or (f ? 'terms' and jsonb_typeof(f -> 'terms') not in ('string', 'null'))
     or (f ? 'pack_size' and jsonb_typeof(f -> 'pack_size') not in ('string', 'null'))
     or (f ? 'highlights' and jsonb_typeof(f -> 'highlights') not in ('array', 'null'))
     or (f ? 'specs' and jsonb_typeof(f -> 'specs') not in ('array', 'null'))
     or (f ? 'includes' and jsonb_typeof(f -> 'includes') not in ('array', 'null'))
     or (f ? 'variants' and jsonb_typeof(f -> 'variants') not in ('array', 'null')) then
    raise exception 'invalid_details' using errcode = 'P0001';
  end if;
  v_brand := case when f ? 'brand' then nullif(btrim(coalesce(f ->> 'brand', '')), '') else v_old_item.brand end;
  v_short := case when f ? 'short_description' then nullif(btrim(coalesce(f ->> 'short_description', '')), '') else v_old_item.short_description end;
  v_terms := case when f ? 'terms' then nullif(btrim(coalesce(f ->> 'terms', '')), '') else v_old_item.terms end;
  v_pack := case when f ? 'pack_size' then nullif(btrim(coalesce(f ->> 'pack_size', '')), '') else v_old_item.pack_size end;
  v_hl := case when f ? 'highlights' then coalesce(nullif(f -> 'highlights', 'null'::jsonb), '[]'::jsonb) else coalesce(v_old_item.highlights, '[]'::jsonb) end;
  v_specs := case when f ? 'specs' then coalesce(nullif(f -> 'specs', 'null'::jsonb), '[]'::jsonb) else coalesce(v_old_item.specs, '[]'::jsonb) end;
  if f ? 'specs' then
    select coalesce(jsonb_agg(
      case when jsonb_typeof(x.e) = 'object' and (not x.e ? 'group' or jsonb_typeof(x.e -> 'group') = 'null')
        then x.e || jsonb_build_object('group', 'Features & Specs') else x.e end
      order by x.n), '[]'::jsonb) into v_specs
      from jsonb_array_elements(v_specs) with ordinality as x(e, n);
  end if;
  if f ? 'highlights' then
    select coalesce(jsonb_agg(
      case when jsonb_typeof(x.e) = 'object' and (jsonb_typeof(x.e -> 'title') = 'null' or btrim(coalesce(x.e ->> 'title', 'x')) = '') then x.e - 'title' else x.e end
      order by x.n), '[]'::jsonb) into v_hl
      from jsonb_array_elements(v_hl) with ordinality as x(e, n);
  end if;
  if f ? 'includes' then
    if exists (select 1 from jsonb_array_elements(case when jsonb_typeof(f -> 'includes') = 'array' then f -> 'includes' else '[]'::jsonb end) e
               where jsonb_typeof(e) <> 'string') then
      raise exception 'invalid_details' using errcode = 'P0001';
    end if;
    select coalesce(array_agg(btrim(x.t) order by x.n), '{}') into v_inc
      from jsonb_array_elements_text(case when jsonb_typeof(f -> 'includes') = 'array' then f -> 'includes' else '[]'::jsonb end) with ordinality as x(t, n);
  else
    v_inc := coalesce(v_old_item.includes, '{}');
  end if;
  v_var := case when f ? 'variants' then coalesce(nullif(f -> 'variants', 'null'::jsonb), '[]'::jsonb) else case when jsonb_typeof(v_old_item.variants) = 'array' then v_old_item.variants else '[]'::jsonb end end;
  if f ? 'variants' and not public.item_variants_valid(v_var) then
    raise exception 'invalid_variants' using errcode = 'P0001';
  end if;
  if f ? 'variants' then
    select coalesce(jsonb_agg(
      case when jsonb_typeof(x.e) = 'object'
        then jsonb_build_object('id', x.e -> 'id', 'label', to_jsonb(btrim(coalesce(x.e ->> 'label', ''))), 'price', x.e -> 'price', 'stock', coalesce(x.e -> 'stock', 'null'::jsonb))
        else x.e end
      order by x.n), '[]'::jsonb) into v_var
      from jsonb_array_elements(v_var) with ordinality as x(e, n);
  end if;
  if not public.item_variants_valid(v_var) or (jsonb_array_length(v_var) > 0 and v_type not in ('fixed', 'from')) then
    raise exception 'invalid_variants' using errcode = 'P0001';
  end if;
  if char_length(coalesce(v_brand, '')) > 60 or char_length(coalesce(v_short, '')) > 140
     or char_length(coalesce(v_terms, '')) > 500 or char_length(coalesce(v_pack, '')) > 40
     or not public.item_highlights_valid(v_hl) or not public.item_specs_valid(v_specs) or not public.item_includes_valid(v_inc) then
    raise exception 'invalid_details' using errcode = 'P0001';
  end if;

  if v_type in ('fixed','from','range') then
    if coalesce(f ->> 'price', '') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    v_price := (f ->> 'price')::numeric;
    if v_type = 'range' then
      if coalesce(f ->> 'price_max', '') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
      v_max := (f ->> 'price_max')::numeric;
      if v_max < v_price then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    end if;
    if coalesce(f ->> 'sale_price', '') <> '' then
      if (f ->> 'sale_price') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
      v_sale := (f ->> 'sale_price')::numeric;
      if v_sale >= v_price then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    end if;
  end if;

  if p_id is null then
    select coalesce(max(sort), 0) + 1 into v_sort from public.items where business_id = v_id;
    insert into public.items (business_id, name, description, section, price_type, price, price_max, sale_price, unit, availability, track_stock, stock_count, low_stock_threshold, show_stock_count, visible, draft, sort,
      brand, short_description, highlights, specs, includes, terms, pack_size, variants)
    values (v_id, v_name, v_desc, v_section, v_type, v_price, v_max, v_sale, v_unit, v_avail, v_track, v_count, v_low, v_show, false, true, v_sort,
      v_brand, v_short, v_hl, v_specs, v_inc, v_terms, v_pack, v_var)
    returning id into v_new;
    return v_new;
  end if;

  select * into v_old from public.items i where i.id = p_id and i.business_id = v_id and not i.removed_by_admin for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;

  if (v_old.price, v_old.price_max, v_old.price_type, v_old.sale_price) is distinct from (v_price, v_max, v_type, v_sale)
     and exists (select 1 from public.flash_sales s where s.item_id = p_id and s.status in ('scheduled','live')) then
    raise exception 'item_in_flash_sale' using errcode = 'P0001';
  end if;

  if v_var is distinct from (case when jsonb_typeof(v_old.variants) = 'array' then v_old.variants else '[]'::jsonb end)
     and exists (select 1 from public.flash_sales s where s.item_id = p_id and s.status in ('scheduled','live')) then
    raise exception 'item_in_flash_sale' using errcode = 'P0001';
  end if;

  update public.items set
    name = v_name, description = v_desc, section = v_section, price_type = v_type, price = v_price, price_max = v_max,
    sale_price = v_sale, unit = v_unit, availability = v_avail,
    track_stock = v_track, stock_count = v_count, low_stock_threshold = v_low, show_stock_count = v_show,
    brand = v_brand, short_description = v_short, highlights = v_hl, specs = v_specs, includes = v_inc, terms = v_terms, pack_size = v_pack, variants = v_var
  where id = p_id;
  return p_id;
end $$;

create or replace view public.public_items with (security_barrier = true) as
select
  i.id, i.business_id, i.name, i.description, i.section, i.price, i.price_max, i.price_type, i.unit,
  i.availability, i.sort, i.created_at,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id and m.kind = 'image'), '[]'::jsonb) as image_paths,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id and m.kind = 'video'), '[]'::jsonb) as video_paths,
  case when i.track_stock and i.show_stock_count and i.availability = 'limited_stock' and i.stock_count > 0 then i.stock_count end as stock_left,
  i.brand, i.short_description, i.highlights, i.specs, i.includes, i.terms, i.pack_size,
  coalesce((select jsonb_agg(jsonb_build_object('path', m.path, 'kind', m.kind, 'duration', m.duration_sec) order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id), '[]'::jsonb) as media,
  coalesce((select jsonb_agg(jsonb_build_object('id', x.e ->> 'id', 'label', x.e ->> 'label', 'price', (x.e ->> 'price')::numeric) order by x.n)
    from jsonb_array_elements(case when jsonb_typeof(i.variants) = 'array' then i.variants else '[]'::jsonb end) with ordinality as x(e, n)
    where coalesce(x.e ->> 'stock', '') <> '0'), '[]'::jsonb) as variants
from public.items i
join public.businesses b on b.id = i.business_id
where public.business_is_visible(b) and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
  and public.item_is_listed(i.availability);

revoke all on public.public_items from public;
grant select on public.public_items to anon, authenticated, service_role;


$m_0085_item_variants$),
    ('0086_item_options', $m_0086_item_options$
-- 0086_item_options.sql
-- Product options (up to 3 axes), variants (one row per sellable combination), an availability matrix, and an admin-owned size chart library.
--
--   * items.option_axes   jsonb  [{key,label,display,values:[{id,label,color?,mediaId?}]}], max 3 axes, 1..40 values per axis.
--   * item_variants       one row per sellable combination (unique per item on combo_key). A combination with NO row is "unavailable":
--                         public_item_options() returns that as an explicit availability matrix, so the client never guesses.
--   * size_charts         library owned by admin (admin_save_size_chart). items.size_chart_id points at one chart, items.size_chart_override
--                         optionally replaces its rows for that item.
--   * public_item_options(item)  the public read: { options, variants, availability, sizeChart }. null when the item is not public.
--   * seller_item_options(item)  the seller read (raw stock counts).
--   * seller_save_item           accepts `options` {axes, variants}, `size_chart_id`, `size_chart_override`. A key that is absent leaves the
--                                stored value alone; `options: null` clears. Items without options behave exactly as before.
--   * seller_duplicate_item      copies axes, variants and the size chart. Media ids cannot exist yet (the files are copied afterwards by
--                                seller-item-copy-media), so the old ids are parked in copy_media_ids / copyMediaId and
--                                item_remap_copied_media() resolves them once the new media rows exist.
--   * seller_bulk_items          price_percent also scales variant prices (otherwise an item and its variants drift apart).
--   * Legacy: items.variants (0017) was never written by any function and is '[]' on every real row. item_options_convert_legacy() turns an
--     old [{id,label,price}] list into one "option" axis; it runs once below for any non-empty row. The old column is kept, unused.
-- Validation mirrors shared/src/seller/options.js (same limits, same error names); db and shared tests keep the two aligned.
-- Idempotent where possible; never edit this file once applied.

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. Validators (immutable, reused by CHECK constraints and by the save helper)
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.option_slug_ok(p jsonb, p_max integer) returns boolean
language sql immutable parallel safe as
$$ select coalesce(jsonb_typeof(p) = 'string' and (p #>> '{}') ~ '^[a-z0-9][a-z0-9_-]*$' and char_length(p #>> '{}') <= p_max, false) $$;

create or replace function public.option_uuid_ok(p jsonb) returns boolean
language sql immutable parallel safe as
$$ select coalesce(jsonb_typeof(p) = 'string' and (p #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$', false) $$;

create or replace function public.item_option_axes_valid(p jsonb) returns boolean
language plpgsql immutable parallel safe as $$
declare
  a jsonb;
  v jsonb;
  k text;
  v_keys text[] := '{}';
  v_ids text[];
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 3 then return false; end if;
  for a in select jsonb_array_elements(p) loop
    if jsonb_typeof(a) <> 'object' then return false; end if;
    for k in select jsonb_object_keys(a) loop
      if k not in ('key', 'label', 'display', 'values') then return false; end if;
    end loop;
    if not public.option_slug_ok(a -> 'key', 30) or (a ->> 'key') = any (v_keys) then return false; end if;
    v_keys := v_keys || (a ->> 'key');
    if not public.item_detail_text_ok(a -> 'label', 30) then return false; end if;
    if jsonb_typeof(a -> 'display') is distinct from 'string' or (a ->> 'display') <> all (array['swatch', 'image-card', 'button', 'dropdown', 'text-card']) then return false; end if;
    if jsonb_typeof(a -> 'values') is distinct from 'array' or jsonb_array_length(a -> 'values') not between 1 and 40 then return false; end if;
    v_ids := '{}';
    for v in select jsonb_array_elements(a -> 'values') loop
      if jsonb_typeof(v) <> 'object' then return false; end if;
      for k in select jsonb_object_keys(v) loop
        if k not in ('id', 'label', 'color', 'mediaId', 'copyMediaId') then return false; end if;
      end loop;
      if not public.option_slug_ok(v -> 'id', 40) or (v ->> 'id') = any (v_ids) then return false; end if;
      v_ids := v_ids || (v ->> 'id');
      if not public.item_detail_text_ok(v -> 'label', 40) then return false; end if;
      if v ? 'color' and (jsonb_typeof(v -> 'color') <> 'string' or (v ->> 'color') !~ '^#[0-9a-fA-F]{6}$') then return false; end if;
      if v ? 'mediaId' and not public.option_uuid_ok(v -> 'mediaId') then return false; end if;
      if v ? 'copyMediaId' and not public.option_uuid_ok(v -> 'copyMediaId') then return false; end if;
    end loop;
  end loop;
  return true;
end $$;

-- The identity of a combination: "color=red|size=m", axis order. null when the choice is not exactly one valid value per axis.
create or replace function public.item_option_combo_key(p_axes jsonb, p_choice jsonb) returns text
language plpgsql immutable parallel safe as $$
declare
  a jsonb;
  v_val text;
  v_parts text[] := '{}';
begin
  if p_axes is null or jsonb_typeof(p_axes) <> 'array' or jsonb_array_length(p_axes) = 0 then return null; end if;
  if p_choice is null or jsonb_typeof(p_choice) <> 'object' then return null; end if;
  if (select count(*) from jsonb_object_keys(p_choice)) <> jsonb_array_length(p_axes) then return null; end if;
  for a in select jsonb_array_elements(p_axes) loop
    if jsonb_typeof(p_choice -> (a ->> 'key')) is distinct from 'string' then return null; end if;
    v_val := p_choice ->> (a ->> 'key');
    if not exists (select 1 from jsonb_array_elements(a -> 'values') x where x ->> 'id' = v_val) then return null; end if;
    v_parts := v_parts || ((a ->> 'key') || '=' || v_val);
  end loop;
  return array_to_string(v_parts, '|');
end $$;

-- Rebuilds user-sent axes keeping only the known keys (never copyMediaId), trimming text and lower-casing colours.
-- Anything that is not the expected shape is returned unchanged so item_option_axes_valid refuses it.
create or replace function public.item_option_axes_clean(p jsonb) returns jsonb
language plpgsql immutable parallel safe as $$
declare
  a jsonb;
  v jsonb;
  v_axis jsonb;
  v_vals jsonb;
  v_out jsonb := '[]'::jsonb;
  v_one jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'array' then return p; end if;
  for a in select jsonb_array_elements(p) loop
    if jsonb_typeof(a) <> 'object' or jsonb_typeof(a -> 'values') is distinct from 'array' then return p; end if;
    v_vals := '[]'::jsonb;
    for v in select jsonb_array_elements(a -> 'values') loop
      if jsonb_typeof(v) <> 'object' then return p; end if;
      v_one := jsonb_build_object('id', v -> 'id', 'label', case when jsonb_typeof(v -> 'label') = 'string' then to_jsonb(btrim(v ->> 'label')) else v -> 'label' end);
      if v ? 'color' and jsonb_typeof(v -> 'color') <> 'null' then v_one := v_one || jsonb_build_object('color', case when jsonb_typeof(v -> 'color') = 'string' then to_jsonb(lower(v ->> 'color')) else v -> 'color' end); end if;
      if v ? 'mediaId' and jsonb_typeof(v -> 'mediaId') <> 'null' then v_one := v_one || jsonb_build_object('mediaId', case when jsonb_typeof(v -> 'mediaId') = 'string' then to_jsonb(lower(v ->> 'mediaId')) else v -> 'mediaId' end); end if;
      v_vals := v_vals || jsonb_build_array(v_one);
    end loop;
    v_axis := jsonb_build_object('key', a -> 'key', 'label', case when jsonb_typeof(a -> 'label') = 'string' then to_jsonb(btrim(a ->> 'label')) else a -> 'label' end,
                                 'display', a -> 'display', 'values', v_vals);
    v_out := v_out || jsonb_build_array(v_axis);
  end loop;
  return v_out;
end $$;

-- The public/seller view of the axes: no internal keys (copyMediaId).
create or replace function public.item_option_axes_public(p jsonb) returns jsonb
language sql immutable parallel safe as $$
  select coalesce(jsonb_agg(
    jsonb_build_object('key', a.e -> 'key', 'label', a.e -> 'label', 'display', a.e -> 'display', 'values', (
      select coalesce(jsonb_agg(
        jsonb_build_object('id', v.e -> 'id', 'label', v.e -> 'label')
          || case when v.e ? 'color' then jsonb_build_object('color', v.e -> 'color') else '{}'::jsonb end
          || case when v.e ? 'mediaId' then jsonb_build_object('mediaId', v.e -> 'mediaId') else '{}'::jsonb end
        order by v.n), '[]'::jsonb)
      from jsonb_array_elements(a.e -> 'values') with ordinality as v(e, n)))
    order by a.n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as a(e, n)
$$;

-- Duplicate: the new item has no media yet, so each mediaId is parked as copyMediaId until item_remap_copied_media runs.
create or replace function public.item_option_axes_for_copy(p jsonb) returns jsonb
language sql immutable parallel safe as $$
  select coalesce(jsonb_agg(
    jsonb_build_object('key', a.e -> 'key', 'label', a.e -> 'label', 'display', a.e -> 'display', 'values', (
      select coalesce(jsonb_agg(
        jsonb_build_object('id', v.e -> 'id', 'label', v.e -> 'label')
          || case when v.e ? 'color' then jsonb_build_object('color', v.e -> 'color') else '{}'::jsonb end
          || case when v.e ? 'mediaId' then jsonb_build_object('copyMediaId', v.e -> 'mediaId')
                  when v.e ? 'copyMediaId' then jsonb_build_object('copyMediaId', v.e -> 'copyMediaId') else '{}'::jsonb end
        order by v.n), '[]'::jsonb)
      from jsonb_array_elements(a.e -> 'values') with ordinality as v(e, n)))
    order by a.n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as a(e, n)
$$;

-- Resolves parked copyMediaId values with {oldId: newId}; an id with no mapping (a file that failed to copy) is dropped.
create or replace function public.item_option_axes_remap(p jsonb, p_map jsonb) returns jsonb
language sql immutable parallel safe as $$
  select coalesce(jsonb_agg(
    jsonb_build_object('key', a.e -> 'key', 'label', a.e -> 'label', 'display', a.e -> 'display', 'values', (
      select coalesce(jsonb_agg(
        jsonb_build_object('id', v.e -> 'id', 'label', v.e -> 'label')
          || case when v.e ? 'color' then jsonb_build_object('color', v.e -> 'color') else '{}'::jsonb end
          || case when v.e ? 'copyMediaId' and p_map ? (v.e ->> 'copyMediaId') then jsonb_build_object('mediaId', p_map -> (v.e ->> 'copyMediaId'))
                  when v.e ? 'mediaId' then jsonb_build_object('mediaId', v.e -> 'mediaId') else '{}'::jsonb end
        order by v.n), '[]'::jsonb)
      from jsonb_array_elements(a.e -> 'values') with ordinality as v(e, n)))
    order by a.n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as a(e, n)
$$;

-- A deleted photo can no longer be a value's picture.
create or replace function public.item_option_axes_drop_media(p jsonb, p_media uuid) returns jsonb
language sql immutable parallel safe as $$
  select coalesce(jsonb_agg(
    jsonb_build_object('key', a.e -> 'key', 'label', a.e -> 'label', 'display', a.e -> 'display', 'values', (
      select coalesce(jsonb_agg(
        case when lower(v.e ->> 'mediaId') = p_media::text then v.e - 'mediaId' else v.e end order by v.n), '[]'::jsonb)
      from jsonb_array_elements(a.e -> 'values') with ordinality as v(e, n)))
    order by a.n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as a(e, n)
$$;

create or replace function public.size_chart_columns_valid(p jsonb) returns boolean
language plpgsql immutable parallel safe as $$
declare
  e jsonb;
  v_seen text[] := '{}';
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) not between 1 and 12 then return false; end if;
  for e in select jsonb_array_elements(p) loop
    if not public.item_detail_text_ok(e, 30) or lower(btrim(e #>> '{}')) = any (v_seen) then return false; end if;
    v_seen := v_seen || lower(btrim(e #>> '{}'));
  end loop;
  return true;
end $$;

-- Rows of cells. p_width null = any width (a seller override is compared with the chart's columns when it is saved and when it is read).
create or replace function public.size_chart_rows_valid(p jsonb, p_width integer) returns boolean
language plpgsql immutable parallel safe as $$
declare
  r jsonb;
  c jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) not between 1 and 60 then return false; end if;
  for r in select jsonb_array_elements(p) loop
    if jsonb_typeof(r) <> 'array' or jsonb_array_length(r) not between 1 and 12 then return false; end if;
    if p_width is not null and jsonb_array_length(r) <> p_width then return false; end if;
    for c in select jsonb_array_elements(r) loop
      if not public.item_detail_text_ok(c, 20) then return false; end if;
    end loop;
  end loop;
  return true;
end $$;

create or replace function public.size_chart_override_valid(p jsonb) returns boolean
language sql immutable parallel safe as $$
  select p is null or (jsonb_typeof(p) = 'object' and (select count(*) from jsonb_object_keys(p)) = 1 and p ? 'rows' and public.size_chart_rows_valid(p -> 'rows', null))
$$;

revoke all on function public.option_slug_ok(jsonb, integer), public.option_uuid_ok(jsonb), public.item_option_axes_valid(jsonb),
  public.item_option_combo_key(jsonb, jsonb), public.item_option_axes_clean(jsonb), public.item_option_axes_public(jsonb),
  public.item_option_axes_for_copy(jsonb), public.item_option_axes_remap(jsonb, jsonb), public.item_option_axes_drop_media(jsonb, uuid),
  public.size_chart_columns_valid(jsonb), public.size_chart_rows_valid(jsonb, integer), public.size_chart_override_valid(jsonb) from public;
grant execute on function public.option_slug_ok(jsonb, integer), public.option_uuid_ok(jsonb), public.item_option_axes_valid(jsonb),
  public.item_option_combo_key(jsonb, jsonb), public.item_option_axes_public(jsonb),
  public.size_chart_columns_valid(jsonb), public.size_chart_rows_valid(jsonb, integer), public.size_chart_override_valid(jsonb) to anon, authenticated, service_role;
grant execute on function public.item_option_axes_clean(jsonb), public.item_option_axes_for_copy(jsonb), public.item_option_axes_remap(jsonb, jsonb),
  public.item_option_axes_drop_media(jsonb, uuid) to service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 2. Tables and columns
-- ---------------------------------------------------------------------------------------------------------------------

create table if not exists public.size_charts (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(btrim(name)) between 2 and 80),
  category text references public.categories(id) on update cascade on delete set null,
  unit text not null default 'cm' check (unit in ('cm', 'in', 'mm', 'kg', 'lb', 'none')),
  columns jsonb not null check (public.size_chart_columns_valid(columns)),
  rows jsonb not null,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint size_charts_rows_shape check (public.size_chart_rows_valid(rows, jsonb_array_length(columns)))
);
create unique index if not exists size_charts_name_idx on public.size_charts (coalesce(category, ''), lower(btrim(name)));
create index if not exists size_charts_category_idx on public.size_charts (category) where active;

alter table public.items
  add column if not exists option_axes jsonb not null default '[]'::jsonb,
  add column if not exists size_chart_id uuid references public.size_charts(id) on delete restrict,
  add column if not exists size_chart_override jsonb;

alter table public.items
  drop constraint if exists items_option_axes_shape,
  drop constraint if exists items_size_chart_override_shape,
  add constraint items_option_axes_shape check (public.item_option_axes_valid(option_axes)),
  add constraint items_size_chart_override_shape check (size_chart_override is null or (size_chart_id is not null and public.size_chart_override_valid(size_chart_override)));
create index if not exists items_size_chart_idx on public.items (size_chart_id) where size_chart_id is not null;

create table if not exists public.item_variants (
  id uuid primary key default gen_random_uuid(),
  item_id uuid not null references public.items(id) on delete cascade,
  business_id uuid not null references public.businesses(id) on delete cascade,
  combo_key text not null check (char_length(combo_key) between 3 and 400),
  choice jsonb not null check (jsonb_typeof(choice) = 'object'),
  price numeric(12,2) check (price >= 0),
  sale_price numeric(12,2) check (sale_price >= 0),
  stock_count integer check (stock_count between 0 and 999999),
  status text not null default 'available' check (status in ('available', 'limited_stock', 'out_of_stock', 'unavailable')),
  sku text check (char_length(sku) between 1 and 40),
  media_ids uuid[] not null default '{}' check (cardinality(media_ids) <= 10),
  copy_media_ids uuid[] not null default '{}' check (cardinality(copy_media_ids) <= 10),
  sort integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint item_variants_combo_uq unique (item_id, combo_key),
  constraint item_variants_sale_ck check (sale_price is null or (price is not null and sale_price < price))
);
create unique index if not exists item_variants_sku_idx on public.item_variants (item_id, lower(sku)) where sku is not null;
create index if not exists item_variants_business_idx on public.item_variants (business_id);

alter table public.size_charts enable row level security;
alter table public.item_variants enable row level security;
drop policy if exists "admin reads size_charts" on public.size_charts;
create policy "admin reads size_charts" on public.size_charts for select to authenticated using (public.is_admin());
drop policy if exists "seller reads own variants" on public.item_variants;
create policy "seller reads own variants" on public.item_variants for select to authenticated using (business_id = public.my_business_id());
drop policy if exists "admin reads item_variants" on public.item_variants;
create policy "admin reads item_variants" on public.item_variants for select to authenticated using (public.is_admin());
revoke all on public.size_charts, public.item_variants from public, anon, authenticated;
grant select on public.size_charts, public.item_variants to authenticated;
grant all on public.size_charts, public.item_variants to service_role;

-- A deleted media row can no longer picture a variant or an option value.
create or replace function public.item_options_media_removed() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  update public.item_variants set media_ids = array_remove(media_ids, old.id), updated_at = now()
    where item_id = old.item_id and old.id = any (media_ids);
  update public.items set option_axes = public.item_option_axes_drop_media(option_axes, old.id)
    where id = old.item_id and option_axes::text ilike '%' || old.id::text || '%';
  return null;
end $$;
drop trigger if exists item_options_media_removed on public.item_media;
create trigger item_options_media_removed after delete on public.item_media for each row execute function public.item_options_media_removed();
revoke all on function public.item_options_media_removed() from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------
-- 3. Legacy items.variants -> one "option" axis
-- ---------------------------------------------------------------------------------------------------------------------

-- items.variants (0017) holds [{id, label, price, stock?}], up to 10, written by the seller editor since 0085. Those entries stay the
-- source for any item that has no option_axes: the public and seller reads below turn them into ONE "option" axis on the fly, so
-- nothing visible changes and an edit made in the old editor shows at once. (A one-time copy into item_variants would go stale the
-- moment the old editor saved again.) Saving real options supersedes the old list: item_options_apply empties it.
-- Returns { axes: [ the one axis, or none ], rows: [{ slug, label, price, stock }] }. Entries without a label are skipped; ids become
-- unique slugs (the old id when it has one, so selections keep working); a numeric stock is kept, 0 meaning out of stock.
create or replace function public.item_options_from_legacy(p_variants jsonb) returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  e jsonb;
  n integer := 0;
  v_i integer := 0;
  v_slug text;
  v_used text[] := '{}';
  v_vals jsonb := '[]'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_label text;
begin
  if p_variants is null or jsonb_typeof(p_variants) <> 'array' then return jsonb_build_object('axes', '[]'::jsonb, 'rows', '[]'::jsonb); end if;
  for e in select jsonb_array_elements(p_variants) loop
    v_i := v_i + 1;
    exit when n >= 40;
    if jsonb_typeof(e) <> 'object' then continue; end if;
    v_label := btrim(coalesce(e ->> 'label', ''));
    if not public.item_detail_text_ok(to_jsonb(v_label), 40) then continue; end if;
    v_slug := regexp_replace(lower(coalesce(nullif(btrim(e ->> 'id'), ''), v_label)), '[^a-z0-9_-]+', '-', 'g');
    v_slug := left(regexp_replace(v_slug, '^[^a-z0-9]+', ''), 40);
    if v_slug = '' then v_slug := 'option-' || v_i; end if;
    if v_slug = any (v_used) then v_slug := left(v_slug, 36) || '-' || v_i; end if;
    if v_slug = any (v_used) then continue; end if;
    v_used := v_used || v_slug;
    n := n + 1;
    v_vals := v_vals || jsonb_build_array(jsonb_build_object('id', v_slug, 'label', v_label));
    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'slug', v_slug, 'label', v_label,
      'price', case when coalesce(e ->> 'price', '') ~ '^\d{1,10}(\.\d{1,2})?$' then (e ->> 'price')::numeric end,
      'stock', case when coalesce(e ->> 'stock', '') ~ '^\d{1,6}$' then (e ->> 'stock')::integer end));
  end loop;
  if n = 0 then return jsonb_build_object('axes', '[]'::jsonb, 'rows', '[]'::jsonb); end if;
  return jsonb_build_object('axes', jsonb_build_array(jsonb_build_object('key', 'option', 'label', 'Option', 'display', 'button', 'values', v_vals)), 'rows', v_rows);
end $$;
revoke all on function public.item_options_from_legacy(jsonb) from public;
grant execute on function public.item_options_from_legacy(jsonb) to anon, authenticated, service_role;

-- For the editor task's one-time move to stored options (not run by this migration): copies an item's old list into option_axes and
-- item_variants and empties the old list. Returns true when it converted something.
create or replace function public.item_options_convert_legacy(p_item uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  r public.items;
  c jsonb;
begin
  select * into r from public.items where id = p_item for update;
  if not found or r.option_axes <> '[]'::jsonb then return false; end if;
  c := public.item_options_from_legacy(r.variants);
  if jsonb_array_length(c -> 'axes') = 0 then return false; end if;
  update public.items set option_axes = c -> 'axes', variants = '[]'::jsonb where id = p_item;
  insert into public.item_variants (item_id, business_id, combo_key, choice, price, stock_count, status, sort)
  select p_item, r.business_id, 'option=' || (x.e ->> 'slug'), jsonb_build_object('option', x.e ->> 'slug'), (x.e ->> 'price')::numeric,
         (x.e ->> 'stock')::integer, case when (x.e ->> 'stock') = '0' then 'out_of_stock' else 'available' end, (x.n - 1)::integer
    from jsonb_array_elements(c -> 'rows') with ordinality as x(e, n);
  return true;
end $$;
revoke all on function public.item_options_convert_legacy(uuid) from public, anon, authenticated;
grant execute on function public.item_options_convert_legacy(uuid) to service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 4. Saving options (called by seller_save_item)
-- ---------------------------------------------------------------------------------------------------------------------

-- Validates and stores what a seller_save_item call sent for options and the size chart. Internal: the caller has checked ownership.
-- Errors (P0001): invalid_options, too_many_variants, invalid_variant, duplicate_variant, duplicate_sku, invalid_size_chart, item_in_flash_sale.
create or replace function public.item_options_apply(p_item uuid, p_business uuid, f jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_old public.items;
  v_opts jsonb;
  v_axes jsonb;
  v_vars jsonb;
  e jsonb;
  k text;
  n integer := 0;
  v_key text;
  v_keys text[] := '{}';
  v_skus text[] := '{}';
  v_sku text;
  v_status text;
  v_stock integer;
  v_price numeric;
  v_sale numeric;
  v_media uuid[];
  v_rows jsonb := '[]'::jsonb;
  m jsonb;
  v_changed boolean;
  v_chart public.size_charts;
  v_chart_id uuid;
  c_money constant text := '^\d{1,10}(\.\d{1,2})?$';
begin
  select * into v_old from public.items where id = p_item and business_id = p_business for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;

  if f ? 'options' then
    v_opts := f -> 'options';
    if v_opts is null or jsonb_typeof(v_opts) = 'null' then
      v_axes := '[]'::jsonb;
      v_vars := '[]'::jsonb;
    else
      if jsonb_typeof(v_opts) <> 'object' then raise exception 'invalid_options' using errcode = 'P0001'; end if;
      for k in select jsonb_object_keys(v_opts) loop
        if k not in ('axes', 'variants') then raise exception 'invalid_options' using errcode = 'P0001'; end if;
      end loop;
      v_axes := coalesce(nullif(v_opts -> 'axes', 'null'::jsonb), '[]'::jsonb);
      v_vars := coalesce(nullif(v_opts -> 'variants', 'null'::jsonb), '[]'::jsonb);
    end if;
    if jsonb_typeof(v_axes) <> 'array' or jsonb_typeof(v_vars) <> 'array' then raise exception 'invalid_options' using errcode = 'P0001'; end if;
    v_axes := public.item_option_axes_clean(v_axes);
    if not public.item_option_axes_valid(v_axes) then raise exception 'invalid_options' using errcode = 'P0001'; end if;
    if jsonb_array_length(v_vars) > 200 then raise exception 'too_many_variants' using errcode = 'P0001'; end if;
    if jsonb_array_length(v_axes) = 0 and jsonb_array_length(v_vars) > 0 then raise exception 'invalid_options' using errcode = 'P0001'; end if;

    -- A value's picture must be one of this item's own media.
    for m in select v.e from jsonb_array_elements(v_axes) a(e), jsonb_array_elements(a.e -> 'values') v(e) where v.e ? 'mediaId' loop
      if not exists (select 1 from public.item_media im where im.id = (m ->> 'mediaId')::uuid and im.item_id = p_item) then
        raise exception 'invalid_options' using errcode = 'P0001';
      end if;
    end loop;

    -- Check every variant first (collected in v_rows), then write.

    for e in select jsonb_array_elements(v_vars) loop
      n := n + 1;
      if jsonb_typeof(e) <> 'object' then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      for k in select jsonb_object_keys(e) loop
        if k not in ('id', 'choice', 'price', 'salePrice', 'stock', 'status', 'sku', 'mediaIds') then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      end loop;
      v_key := public.item_option_combo_key(v_axes, e -> 'choice');
      if v_key is null then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      if v_key = any (v_keys) then raise exception 'duplicate_variant' using errcode = 'P0001'; end if;
      v_keys := v_keys || v_key;

      v_price := null; v_sale := null; v_stock := null; v_sku := null; v_media := '{}';
      if jsonb_typeof(e -> 'price') not in ('null') and e ? 'price' then
        if (e ->> 'price') !~ c_money then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        v_price := (e ->> 'price')::numeric;
      end if;
      if e ? 'salePrice' and jsonb_typeof(e -> 'salePrice') <> 'null' then
        if (e ->> 'salePrice') !~ c_money or v_price is null then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        v_sale := (e ->> 'salePrice')::numeric;
        if v_sale >= v_price then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      end if;
      if e ? 'stock' and jsonb_typeof(e -> 'stock') <> 'null' then
        if (e ->> 'stock') !~ '^\d{1,6}$' then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        v_stock := (e ->> 'stock')::integer;
      end if;
      v_status := coalesce(case when e ? 'status' and jsonb_typeof(e -> 'status') <> 'null' then e ->> 'status' end, 'available');
      if jsonb_typeof(coalesce(e -> 'status', '"available"'::jsonb)) not in ('string', 'null')
         or v_status not in ('available', 'limited_stock', 'out_of_stock', 'unavailable') then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      if v_stock = 0 then v_status := 'out_of_stock'; end if;
      if e ? 'sku' and jsonb_typeof(e -> 'sku') <> 'null' then
        if jsonb_typeof(e -> 'sku') <> 'string' then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        v_sku := nullif(btrim(e ->> 'sku'), '');
        if char_length(coalesce(v_sku, '')) > 40 then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        if v_sku is not null then
          if lower(v_sku) = any (v_skus) then raise exception 'duplicate_sku' using errcode = 'P0001'; end if;
          v_skus := v_skus || lower(v_sku);
        end if;
      end if;
      if e ? 'mediaIds' and jsonb_typeof(e -> 'mediaIds') <> 'null' then
        if jsonb_typeof(e -> 'mediaIds') <> 'array' or jsonb_array_length(e -> 'mediaIds') > 10 then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        for m in select jsonb_array_elements(e -> 'mediaIds') loop
          if not public.option_uuid_ok(m) then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
          if (m #>> '{}')::uuid = any (v_media) then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
          if not exists (select 1 from public.item_media im where im.id = (m #>> '{}')::uuid and im.item_id = p_item) then
            raise exception 'invalid_variant' using errcode = 'P0001';
          end if;
          v_media := v_media || (m #>> '{}')::uuid;
        end loop;
      end if;
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('ord', n, 'combo_key', v_key, 'choice', e -> 'choice', 'price', v_price, 'sale_price', v_sale,
                                                               'stock_count', v_stock, 'status', v_status, 'sku', v_sku, 'media_ids', to_jsonb(v_media)));
    end loop;

    -- The flash guard of seller_save_item covers variant prices too: they cannot change while the item is in a scheduled or live sale.
    if exists (select 1 from public.flash_sales s where s.item_id = p_item and s.status in ('scheduled', 'live')) then
      select exists (
        select 1 from jsonb_to_recordset(v_rows) as t(combo_key text, price numeric, sale_price numeric)
          full join public.item_variants o on o.item_id = p_item and o.combo_key = t.combo_key
        where (t.combo_key is null or o.combo_key is null) and coalesce(t.price, o.price) is not null
           or (t.combo_key is not null and o.combo_key is not null and (t.price, t.sale_price) is distinct from (o.price, o.sale_price))
      ) into v_changed;
      if v_changed then raise exception 'item_in_flash_sale' using errcode = 'P0001'; end if;
    end if;

    delete from public.item_variants where item_id = p_item and not (combo_key = any (v_keys));
    update public.item_variants set sku = null where item_id = p_item;   -- a SKU may move between combinations in one save
    insert into public.item_variants (item_id, business_id, combo_key, choice, price, sale_price, stock_count, status, sku, media_ids, copy_media_ids, sort)
    select p_item, p_business, t.combo_key, t.choice, t.price, t.sale_price, t.stock_count, t.status, t.sku,
           array(select jsonb_array_elements_text(t.media_ids)::uuid), '{}', t.ord - 1
      from jsonb_to_recordset(v_rows) as t(ord integer, combo_key text, choice jsonb, price numeric, sale_price numeric, stock_count integer, status text, sku text, media_ids jsonb)
    on conflict (item_id, combo_key) do update set
      choice = excluded.choice, price = excluded.price, sale_price = excluded.sale_price, stock_count = excluded.stock_count, status = excluded.status,
      sku = excluded.sku, media_ids = excluded.media_ids, copy_media_ids = '{}', sort = excluded.sort, updated_at = now();
    -- Real options supersede the old single-list variants (still written by the old editor); leaving both would show two lists.
    update public.items set option_axes = v_axes, variants = case when jsonb_array_length(v_axes) > 0 then '[]'::jsonb else variants end where id = p_item;
  end if;

  if f ? 'size_chart_id' then
    if jsonb_typeof(f -> 'size_chart_id') = 'null' then
      update public.items set size_chart_id = null, size_chart_override = null where id = p_item;
    else
      if not public.option_uuid_ok(f -> 'size_chart_id') then raise exception 'invalid_size_chart' using errcode = 'P0001'; end if;
      v_chart_id := (f ->> 'size_chart_id')::uuid;
      -- An item may keep a chart that was retired since, but cannot newly pick one.
      if not exists (select 1 from public.size_charts sc where sc.id = v_chart_id and (sc.active or sc.id = v_old.size_chart_id)) then
        raise exception 'invalid_size_chart' using errcode = 'P0001';
      end if;
      update public.items set size_chart_id = v_chart_id, size_chart_override = case when v_chart_id is distinct from v_old.size_chart_id then null else size_chart_override end
        where id = p_item;
    end if;
  end if;

  if f ? 'size_chart_override' then
    select * into v_old from public.items where id = p_item;
    if jsonb_typeof(f -> 'size_chart_override') = 'null' then
      update public.items set size_chart_override = null where id = p_item;
    else
      if v_old.size_chart_id is null or jsonb_typeof(f -> 'size_chart_override') <> 'object' then raise exception 'invalid_size_chart' using errcode = 'P0001'; end if;
      for k in select jsonb_object_keys(f -> 'size_chart_override') loop
        if k <> 'rows' then raise exception 'invalid_size_chart' using errcode = 'P0001'; end if;
      end loop;
      select * into v_chart from public.size_charts where id = v_old.size_chart_id;
      if not public.size_chart_rows_valid(f #> '{size_chart_override,rows}', jsonb_array_length(v_chart.columns)) then raise exception 'invalid_size_chart' using errcode = 'P0001'; end if;
      update public.items set size_chart_override = jsonb_build_object('rows', f #> '{size_chart_override,rows}') where id = p_item;
    end if;
  end if;
end $$;
revoke all on function public.item_options_apply(uuid, uuid, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------
-- 5. Reads: availability matrix, public payload, seller payload
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.option_status_rank(p text) returns integer
language sql immutable parallel safe as
$$ select case p when 'available' then 4 when 'limited_stock' then 3 when 'out_of_stock' then 2 else 1 end $$;

-- { axes: [key], missing: 'unavailable', cells: [{ key, choice, status, variantId }], values: { axisKey: { valueId: status } } }
-- p_cells: [{ id, key, choice, status }] in display order (stored variants, or the old list read as one axis). A combination with no
-- cell is unavailable: `missing` says so. `values` gives every option value its best status across the cells that contain it, so a
-- picker can grey out a value without enumerating combinations.
create or replace function public.item_options_matrix(p_axes jsonb, p_cells jsonb) returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  a jsonb;
  v jsonb;
  v_values jsonb := '{}'::jsonb;
  v_axis jsonb;
  v_best text;
begin
  for a in select jsonb_array_elements(coalesce(p_axes, '[]'::jsonb)) loop
    v_axis := '{}'::jsonb;
    for v in select jsonb_array_elements(a -> 'values') loop
      select c ->> 'status' into v_best from jsonb_array_elements(coalesce(p_cells, '[]'::jsonb)) c
        where c -> 'choice' ->> (a ->> 'key') = v ->> 'id'
        order by public.option_status_rank(c ->> 'status') desc limit 1;
      v_axis := v_axis || jsonb_build_object(v ->> 'id', coalesce(v_best, 'unavailable'));
    end loop;
    v_values := v_values || jsonb_build_object(a ->> 'key', v_axis);
  end loop;
  return jsonb_build_object(
    'axes', coalesce((select jsonb_agg(x ->> 'key') from jsonb_array_elements(coalesce(p_axes, '[]'::jsonb)) x), '[]'::jsonb),
    'missing', 'unavailable',
    'cells', coalesce((select jsonb_agg(jsonb_build_object('key', c ->> 'key', 'choice', c -> 'choice', 'status', c ->> 'status', 'variantId', c -> 'id') order by n)
                       from jsonb_array_elements(coalesce(p_cells, '[]'::jsonb)) with ordinality as t(c, n)), '[]'::jsonb),
    'values', v_values);
end $$;
revoke all on function public.item_options_matrix(jsonb, jsonb), public.option_status_rank(text) from public;
grant execute on function public.item_options_matrix(jsonb, jsonb), public.option_status_rank(text) to service_role;

create or replace function public.item_size_chart_payload(p_item public.items) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when c.id is null then null else jsonb_build_object(
    'id', c.id, 'name', c.name, 'category', c.category, 'unit', c.unit, 'columns', c.columns,
    'rows', case when p_item.size_chart_override is not null and public.size_chart_rows_valid(p_item.size_chart_override -> 'rows', jsonb_array_length(c.columns))
                 then p_item.size_chart_override -> 'rows' else c.rows end,
    'overridden', p_item.size_chart_override is not null and public.size_chart_rows_valid(p_item.size_chart_override -> 'rows', jsonb_array_length(c.columns))) end
  from (select 1) one left join public.size_charts c on c.id = p_item.size_chart_id and c.active
$$;
revoke all on function public.item_size_chart_payload(public.items) from public;
grant execute on function public.item_size_chart_payload(public.items) to service_role;

-- "Red / S": the chosen values' labels in axis order. Every option variant carries it, as the old {id, label, price} entries did.
create or replace function public.item_variant_label(p_axes jsonb, p_choice jsonb) returns text
language sql immutable parallel safe as $$
  select string_agg(v.e ->> 'label', ' / ' order by a.n)
  from jsonb_array_elements(coalesce(p_axes, '[]'::jsonb)) with ordinality as a(e, n)
  join lateral jsonb_array_elements(a.e -> 'values') as v(e) on v.e ->> 'id' = p_choice ->> (a.e ->> 'key')
$$;
revoke all on function public.item_variant_label(jsonb, jsonb) from public;
grant execute on function public.item_variant_label(jsonb, jsonb) to anon, authenticated, service_role;

-- The axes, the variants (id, label, choice, price, sale price, status, sku, media, stock) and the cells for one item: stored options,
-- or, when the item has none, its old variants list read as one "option" axis. `legacy` says which. Internal to the two reads below.
create or replace function public.item_options_source(i public.items) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c jsonb;
  v_axes jsonb;
  v_vars jsonb;
begin
  if i.option_axes <> '[]'::jsonb then
    return jsonb_build_object('legacy', false, 'axes', i.option_axes, 'variants', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'label', public.item_variant_label(i.option_axes, s.choice), 'key', s.combo_key, 'choice', s.choice,
        'price', s.price, 'salePrice', s.sale_price, 'stock', s.stock_count, 'status', s.status, 'sku', s.sku, 'mediaIds', to_jsonb(s.media_ids)) order by s.sort, s.id)
      from public.item_variants s where s.item_id = i.id), '[]'::jsonb));
  end if;
  c := public.item_options_from_legacy(case when jsonb_typeof(i.variants) = 'array' then i.variants else '[]'::jsonb end);
  v_axes := c -> 'axes';
  select coalesce(jsonb_agg(jsonb_build_object('id', x.e ->> 'slug', 'label', x.e ->> 'label', 'key', 'option=' || (x.e ->> 'slug'),
      'choice', jsonb_build_object('option', x.e ->> 'slug'), 'price', x.e -> 'price', 'salePrice', null, 'stock', x.e -> 'stock',
      'status', case when (x.e ->> 'stock') = '0' then 'out_of_stock' else 'available' end, 'sku', null, 'mediaIds', '[]'::jsonb) order by x.n), '[]'::jsonb)
    into v_vars from jsonb_array_elements(c -> 'rows') with ordinality as x(e, n);
  return jsonb_build_object('legacy', jsonb_array_length(v_axes) > 0, 'axes', v_axes, 'variants', v_vars);
end $$;
revoke all on function public.item_options_source(public.items) from public;
grant execute on function public.item_options_source(public.items) to service_role;

-- The public read. null when the item is not public (hidden, draft, removed, sold out, shop not visible).
-- New keys on purpose: the item already has `availability` (its own status string) and `variants` (the old list, which pricing is built
-- from), and pages read both. options / optionVariants / optionAvailability / sizeChart sit beside them.
create or replace function public.public_item_options(p_item uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  i public.items;
  src jsonb;
begin
  if not exists (select 1 from public.public_items pi where pi.id = p_item) then return null; end if;
  select * into i from public.items where id = p_item;
  src := public.item_options_source(i);
  return jsonb_build_object(
    'options', public.item_option_axes_public(src -> 'axes'),
    'optionVariants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', x.e -> 'id', 'label', x.e -> 'label', 'choice', x.e -> 'choice',
        'price', coalesce(nullif(x.e -> 'price', 'null'::jsonb), to_jsonb(i.price)),
        'salePrice', case when jsonb_typeof(x.e -> 'price') = 'null' then to_jsonb(i.sale_price) else x.e -> 'salePrice' end,
        'status', x.e -> 'status', 'sku', x.e -> 'sku', 'mediaIds', x.e -> 'mediaIds',
        'stockLeft', case when i.show_stock_count and x.e ->> 'status' = 'limited_stock' and (x.e ->> 'stock')::integer > 0 then x.e -> 'stock' end) order by x.n)
      from jsonb_array_elements(src -> 'variants') with ordinality as x(e, n)), '[]'::jsonb),
    'optionAvailability', public.item_options_matrix(src -> 'axes', (
      select coalesce(jsonb_agg(jsonb_build_object('id', x.e -> 'id', 'key', x.e -> 'key', 'choice', x.e -> 'choice', 'status', x.e -> 'status') order by x.n), '[]'::jsonb)
      from jsonb_array_elements(src -> 'variants') with ordinality as x(e, n))),
    'sizeChart', public.item_size_chart_payload(i));
end $$;

create or replace function public.seller_item_options(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  i public.items;
  src jsonb;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into i from public.items where id = p_id and business_id = v_id and not removed_by_admin;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  src := public.item_options_source(i);
  return jsonb_build_object(
    'fromLegacy', src -> 'legacy',
    'axes', public.item_option_axes_public(src -> 'axes'),
    'variants', coalesce((
      select jsonb_agg(jsonb_build_object('id', x.e -> 'id', 'choice', x.e -> 'choice', 'price', x.e -> 'price', 'salePrice', x.e -> 'salePrice', 'stock', x.e -> 'stock',
                                          'status', x.e -> 'status', 'sku', x.e -> 'sku', 'mediaIds', x.e -> 'mediaIds') order by x.n)
      from jsonb_array_elements(src -> 'variants') with ordinality as x(e, n)), '[]'::jsonb),
    'optionAvailability', public.item_options_matrix(src -> 'axes', (
      select coalesce(jsonb_agg(jsonb_build_object('id', x.e -> 'id', 'key', x.e -> 'key', 'choice', x.e -> 'choice', 'status', x.e -> 'status') order by x.n), '[]'::jsonb)
      from jsonb_array_elements(src -> 'variants') with ordinality as x(e, n))),
    'sizeChartId', i.size_chart_id,
    'sizeChartOverride', i.size_chart_override);
end $$;

-- Called by seller-item-copy-media (service role) once the copied media exists: {oldMediaId: newMediaId}.
create or replace function public.item_remap_copied_media(p_item uuid, p_map jsonb) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_n integer;
begin
  if p_map is null or jsonb_typeof(p_map) <> 'object' then raise exception 'invalid_map' using errcode = 'P0001'; end if;
  update public.item_variants v set
    media_ids = coalesce((
      select array_agg((p_map ->> u.old::text)::uuid order by u.ord)
      from unnest(v.copy_media_ids) with ordinality as u(old, ord)
      where p_map ? u.old::text
        and exists (select 1 from public.item_media im where im.id = (p_map ->> u.old::text)::uuid and im.item_id = p_item)), '{}'),
    copy_media_ids = '{}', updated_at = now()
  where v.item_id = p_item and cardinality(v.copy_media_ids) > 0;
  get diagnostics v_n = row_count;
  update public.items set option_axes = public.item_option_axes_remap(option_axes, p_map)
    where id = p_item and option_axes::text like '%copyMediaId%';
  return v_n;
end $$;
revoke all on function public.item_remap_copied_media(uuid, jsonb) from public, anon, authenticated;
grant execute on function public.item_remap_copied_media(uuid, jsonb) to service_role;

revoke all on function public.public_item_options(uuid), public.seller_item_options(uuid) from public, anon;
grant execute on function public.public_item_options(uuid) to anon, authenticated, service_role;
grant execute on function public.seller_item_options(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 6. Size chart library (admin owns it; everyone can read the active charts)
-- ---------------------------------------------------------------------------------------------------------------------

create or replace view public.public_size_charts with (security_barrier = true) as
select c.id, c.name, c.category, c.unit, c.columns, c.rows from public.size_charts c where c.active;
revoke all on public.public_size_charts from public;
grant select on public.public_size_charts to anon, authenticated, service_role;

create or replace function public.admin_size_charts_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.category nulls last, x.name)
    from (select c.id, c.name, c.category, c.unit, c.columns, c.rows, c.active, c.updated_at,
                 (select count(*) from public.items i where i.size_chart_id = c.id) as items_using
            from public.size_charts c) x), '[]'::jsonb);
end $$;

create or replace function public.admin_save_size_chart(p_id uuid, p_fields jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_name text := btrim(coalesce(f ->> 'name', ''));
  v_category text := nullif(btrim(coalesce(f ->> 'category', '')), '');
  v_unit text := coalesce(f ->> 'unit', 'cm');
  v_active boolean := coalesce((f ->> 'active')::boolean, true);
  v_old public.size_charts;
  v_id uuid;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if char_length(v_name) not between 2 and 80 then raise exception 'invalid_name' using errcode = 'P0001'; end if;
  if v_unit not in ('cm', 'in', 'mm', 'kg', 'lb', 'none') then raise exception 'invalid_unit' using errcode = 'P0001'; end if;
  if v_category is not null and not exists (select 1 from public.categories c where c.id = v_category) then raise exception 'invalid_category' using errcode = 'P0001'; end if;
  if not public.size_chart_columns_valid(f -> 'columns') or not public.size_chart_rows_valid(f -> 'rows', jsonb_array_length(f -> 'columns')) then
    raise exception 'invalid_chart' using errcode = 'P0001';
  end if;
  begin
    if p_id is null then
      insert into public.size_charts (name, category, unit, columns, rows, active) values (v_name, v_category, v_unit, f -> 'columns', f -> 'rows', v_active) returning id into v_id;
      perform public.admin_audit_action('size_chart.create', 'size_chart', v_id::text, null, jsonb_build_object('name', v_name, 'category', v_category), null, null);
    else
      select * into v_old from public.size_charts where id = p_id for update;
      if not found then raise exception 'chart_not_found' using errcode = 'P0001'; end if;
      update public.size_charts set name = v_name, category = v_category, unit = v_unit, columns = f -> 'columns', rows = f -> 'rows', active = v_active, updated_at = now() where id = p_id;
      v_id := p_id;
      perform public.admin_audit_action('size_chart.update', 'size_chart', v_id::text, jsonb_build_object('name', v_old.name, 'active', v_old.active), jsonb_build_object('name', v_name, 'active', v_active), null, null);
    end if;
  exception when unique_violation then
    raise exception 'duplicate_chart' using errcode = 'P0001';
  end;
  return v_id;
end $$;

create or replace function public.admin_delete_size_chart(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_old public.size_charts;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into v_old from public.size_charts where id = p_id for update;
  if not found then raise exception 'chart_not_found' using errcode = 'P0001'; end if;
  if exists (select 1 from public.items i where i.size_chart_id = p_id) then raise exception 'size_chart_in_use' using errcode = 'P0001'; end if;
  delete from public.size_charts where id = p_id;
  perform public.admin_audit_action('size_chart.delete', 'size_chart', p_id::text, jsonb_build_object('name', v_old.name), null, null, null);
end $$;

revoke all on function public.admin_size_charts_list(), public.admin_save_size_chart(uuid, jsonb), public.admin_delete_size_chart(uuid) from public, anon;
grant execute on function public.admin_size_charts_list(), public.admin_save_size_chart(uuid, jsonb), public.admin_delete_size_chart(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 7. seller_save_item, seller_duplicate_item, seller_bulk_items (latest definitions: 0085, 0050, 004600; changes marked "0086")
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.seller_save_item(p_id uuid, p_fields jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_old public.items;
  v_name text := btrim(coalesce(f ->> 'name', ''));
  v_desc text := nullif(btrim(coalesce(f ->> 'description', '')), '');
  v_section text := nullif(btrim(coalesce(f ->> 'section', '')), '');
  v_unit text := nullif(btrim(coalesce(f ->> 'unit', '')), '');
  v_type text := f ->> 'price_type';
  v_avail text := f ->> 'availability';
  v_old_item public.items;
  v_track boolean;
  v_count integer;
  v_low integer;
  v_show boolean;
  v_price numeric;
  v_max numeric;
  v_sale numeric;
  v_sort integer;
  v_new uuid;
  v_brand text;
  v_short text;
  v_terms text;
  v_pack text;
  v_hl jsonb;
  v_specs jsonb;
  v_inc text[];
  v_var jsonb;
  c_money constant text := '^\d{1,10}(\.\d{1,2})?$';
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  if char_length(v_name) < 2 or char_length(v_name) > 120 then raise exception 'invalid_name' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_desc, '')) > 2000 or char_length(coalesce(v_section, '')) > 60 or char_length(coalesce(v_unit, '')) > 30 then
    raise exception 'invalid_text' using errcode = 'P0001';
  end if;
  if v_avail is null or v_avail not in ('available','limited_stock','out_of_stock','unavailable','by_appointment') then
    raise exception 'invalid_availability' using errcode = 'P0001';
  end if;
  if v_type is null or v_type not in ('fixed','from','range','free','contact') then raise exception 'invalid_price' using errcode = 'P0001'; end if;

  if p_id is not null then
    select * into v_old_item from public.items i where i.id = p_id and i.business_id = v_id;
  end if;
  if (f ? 'low_stock_threshold' and coalesce(f ->> 'low_stock_threshold', '') !~ '^\d{1,4}$')
     or (f ? 'track_stock' and coalesce(f ->> 'track_stock', '') not in ('true', 'false'))
     or (f ? 'show_stock_count' and coalesce(f ->> 'show_stock_count', '') not in ('true', 'false')) then
    raise exception 'invalid_stock' using errcode = 'P0001';
  end if;
  v_track := case when f ? 'track_stock' then coalesce((f ->> 'track_stock')::boolean, false) else coalesce(v_old_item.track_stock, false) end;
  v_low := case when f ? 'low_stock_threshold' then (f ->> 'low_stock_threshold')::integer else coalesce(v_old_item.low_stock_threshold, 3) end;
  v_show := case when f ? 'show_stock_count' then coalesce((f ->> 'show_stock_count')::boolean, false) else coalesce(v_old_item.show_stock_count, false) end;
  if f ? 'stock_count' and coalesce(f ->> 'stock_count', '') <> '' then
    if (f ->> 'stock_count') !~ '^\d{1,6}$' then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
    v_count := (f ->> 'stock_count')::integer;
  elsif f ? 'stock_count' then
    v_count := null;
  else
    v_count := v_old_item.stock_count;
  end if;
  if v_low is null or v_low < 0 or v_low > 9999 then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
  if v_track and v_count is null then raise exception 'invalid_stock' using errcode = 'P0001'; end if;
  if v_track then v_avail := 'available'; end if;

  if (f ? 'brand' and jsonb_typeof(f -> 'brand') not in ('string', 'null'))
     or (f ? 'short_description' and jsonb_typeof(f -> 'short_description') not in ('string', 'null'))
     or (f ? 'terms' and jsonb_typeof(f -> 'terms') not in ('string', 'null'))
     or (f ? 'pack_size' and jsonb_typeof(f -> 'pack_size') not in ('string', 'null'))
     or (f ? 'highlights' and jsonb_typeof(f -> 'highlights') not in ('array', 'null'))
     or (f ? 'specs' and jsonb_typeof(f -> 'specs') not in ('array', 'null'))
     or (f ? 'includes' and jsonb_typeof(f -> 'includes') not in ('array', 'null'))
     or (f ? 'variants' and jsonb_typeof(f -> 'variants') not in ('array', 'null')) then
    raise exception 'invalid_details' using errcode = 'P0001';
  end if;
  v_brand := case when f ? 'brand' then nullif(btrim(coalesce(f ->> 'brand', '')), '') else v_old_item.brand end;
  v_short := case when f ? 'short_description' then nullif(btrim(coalesce(f ->> 'short_description', '')), '') else v_old_item.short_description end;
  v_terms := case when f ? 'terms' then nullif(btrim(coalesce(f ->> 'terms', '')), '') else v_old_item.terms end;
  v_pack := case when f ? 'pack_size' then nullif(btrim(coalesce(f ->> 'pack_size', '')), '') else v_old_item.pack_size end;
  v_hl := case when f ? 'highlights' then coalesce(nullif(f -> 'highlights', 'null'::jsonb), '[]'::jsonb) else coalesce(v_old_item.highlights, '[]'::jsonb) end;
  v_specs := case when f ? 'specs' then coalesce(nullif(f -> 'specs', 'null'::jsonb), '[]'::jsonb) else coalesce(v_old_item.specs, '[]'::jsonb) end;
  if f ? 'specs' then
    select coalesce(jsonb_agg(
      case when jsonb_typeof(x.e) = 'object' and (not x.e ? 'group' or jsonb_typeof(x.e -> 'group') = 'null')
        then x.e || jsonb_build_object('group', 'Features & Specs') else x.e end
      order by x.n), '[]'::jsonb) into v_specs
      from jsonb_array_elements(v_specs) with ordinality as x(e, n);
  end if;
  if f ? 'highlights' then
    select coalesce(jsonb_agg(
      case when jsonb_typeof(x.e) = 'object' and (jsonb_typeof(x.e -> 'title') = 'null' or btrim(coalesce(x.e ->> 'title', 'x')) = '') then x.e - 'title' else x.e end
      order by x.n), '[]'::jsonb) into v_hl
      from jsonb_array_elements(v_hl) with ordinality as x(e, n);
  end if;
  if f ? 'includes' then
    if exists (select 1 from jsonb_array_elements(case when jsonb_typeof(f -> 'includes') = 'array' then f -> 'includes' else '[]'::jsonb end) e
               where jsonb_typeof(e) <> 'string') then
      raise exception 'invalid_details' using errcode = 'P0001';
    end if;
    select coalesce(array_agg(btrim(x.t) order by x.n), '{}') into v_inc
      from jsonb_array_elements_text(case when jsonb_typeof(f -> 'includes') = 'array' then f -> 'includes' else '[]'::jsonb end) with ordinality as x(t, n);
  else
    v_inc := coalesce(v_old_item.includes, '{}');
  end if;
  v_var := case when f ? 'variants' then coalesce(nullif(f -> 'variants', 'null'::jsonb), '[]'::jsonb) else case when jsonb_typeof(v_old_item.variants) = 'array' then v_old_item.variants else '[]'::jsonb end end;
  if f ? 'variants' and not public.item_variants_valid(v_var) then
    raise exception 'invalid_variants' using errcode = 'P0001';
  end if;
  if f ? 'variants' then
    select coalesce(jsonb_agg(
      case when jsonb_typeof(x.e) = 'object'
        then jsonb_build_object('id', x.e -> 'id', 'label', to_jsonb(btrim(coalesce(x.e ->> 'label', ''))), 'price', x.e -> 'price', 'stock', coalesce(x.e -> 'stock', 'null'::jsonb))
        else x.e end
      order by x.n), '[]'::jsonb) into v_var
      from jsonb_array_elements(v_var) with ordinality as x(e, n);
  end if;
  if not public.item_variants_valid(v_var) or (jsonb_array_length(v_var) > 0 and v_type not in ('fixed', 'from')) then
    raise exception 'invalid_variants' using errcode = 'P0001';
  end if;
  if char_length(coalesce(v_brand, '')) > 60 or char_length(coalesce(v_short, '')) > 140
     or char_length(coalesce(v_terms, '')) > 500 or char_length(coalesce(v_pack, '')) > 40
     or not public.item_highlights_valid(v_hl) or not public.item_specs_valid(v_specs) or not public.item_includes_valid(v_inc) then
    raise exception 'invalid_details' using errcode = 'P0001';
  end if;

  if v_type in ('fixed','from','range') then
    if coalesce(f ->> 'price', '') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    v_price := (f ->> 'price')::numeric;
    if v_type = 'range' then
      if coalesce(f ->> 'price_max', '') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
      v_max := (f ->> 'price_max')::numeric;
      if v_max < v_price then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    end if;
    if coalesce(f ->> 'sale_price', '') <> '' then
      if (f ->> 'sale_price') !~ c_money then raise exception 'invalid_price' using errcode = 'P0001'; end if;
      v_sale := (f ->> 'sale_price')::numeric;
      if v_sale >= v_price then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    end if;
  end if;

  if p_id is null then
    select coalesce(max(sort), 0) + 1 into v_sort from public.items where business_id = v_id;
    insert into public.items (business_id, name, description, section, price_type, price, price_max, sale_price, unit, availability, track_stock, stock_count, low_stock_threshold, show_stock_count, visible, draft, sort,
      brand, short_description, highlights, specs, includes, terms, pack_size, variants)
    values (v_id, v_name, v_desc, v_section, v_type, v_price, v_max, v_sale, v_unit, v_avail, v_track, v_count, v_low, v_show, false, true, v_sort,
      v_brand, v_short, v_hl, v_specs, v_inc, v_terms, v_pack, v_var)
    returning id into v_new;
    perform public.item_options_apply(v_new, v_id, f);   -- 0086
    return v_new;
  end if;

  select * into v_old from public.items i where i.id = p_id and i.business_id = v_id and not i.removed_by_admin for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;

  if (v_old.price, v_old.price_max, v_old.price_type, v_old.sale_price) is distinct from (v_price, v_max, v_type, v_sale)
     and exists (select 1 from public.flash_sales s where s.item_id = p_id and s.status in ('scheduled','live')) then
    raise exception 'item_in_flash_sale' using errcode = 'P0001';
  end if;

  if v_var is distinct from (case when jsonb_typeof(v_old.variants) = 'array' then v_old.variants else '[]'::jsonb end)
     and exists (select 1 from public.flash_sales s where s.item_id = p_id and s.status in ('scheduled','live')) then
    raise exception 'item_in_flash_sale' using errcode = 'P0001';
  end if;

  update public.items set
    name = v_name, description = v_desc, section = v_section, price_type = v_type, price = v_price, price_max = v_max,
    sale_price = v_sale, unit = v_unit, availability = v_avail,
    track_stock = v_track, stock_count = v_count, low_stock_threshold = v_low, show_stock_count = v_show,
    brand = v_brand, short_description = v_short, highlights = v_hl, specs = v_specs, includes = v_inc, terms = v_terms, pack_size = v_pack, variants = v_var
  where id = p_id;
  perform public.item_options_apply(p_id, v_id, f);   -- 0086
  return p_id;
end $$;

create or replace function public.seller_duplicate_item(p_id uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_src public.items;
  v_new uuid;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into v_src from public.items where id = p_id and business_id = v_id and not removed_by_admin;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  insert into public.items (business_id, name, description, section, price, price_max, price_type, unit, sale_price, availability, stock_count,
    track_stock, low_stock_threshold, show_stock_count, season, tags, badge, variants, visible, draft, sort,
    brand, short_description, highlights, specs, includes, terms, pack_size, option_axes, size_chart_id, size_chart_override)
  values (v_id, left(v_src.name, 111) || ' (copy)', v_src.description, v_src.section, v_src.price, v_src.price_max, v_src.price_type, v_src.unit,
    v_src.sale_price, v_src.availability, v_src.stock_count, v_src.track_stock, v_src.low_stock_threshold, v_src.show_stock_count, v_src.season,
    v_src.tags, v_src.badge, v_src.variants, false, true, v_src.sort + 1,
    v_src.brand, v_src.short_description, v_src.highlights, v_src.specs, v_src.includes, v_src.terms, v_src.pack_size,
    public.item_option_axes_for_copy(v_src.option_axes), v_src.size_chart_id, v_src.size_chart_override)   -- 0086
  returning id into v_new;
  -- 0086: variants are copied with their media ids parked in copy_media_ids; item_remap_copied_media resolves them after the files are copied.
  insert into public.item_variants (item_id, business_id, combo_key, choice, price, sale_price, stock_count, status, sku, media_ids, copy_media_ids, sort)
  select v_new, v_id, s.combo_key, s.choice, s.price, s.sale_price, s.stock_count, s.status, s.sku, '{}', case when cardinality(s.media_ids) > 0 then s.media_ids else s.copy_media_ids end, s.sort
    from public.item_variants s where s.item_id = p_id;
  return v_new;
end $$;

create or replace function public.seller_bulk_items(p_action text, p_ids uuid[], p_args jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_ids uuid[];
  v_n integer := 0;
  v_skipped integer := 0;
  v_tenths integer;
  v_section text;
  v_avail text;
  v_blocked integer := 0;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if p_action is null or p_action not in ('hide','show','delete','move_section','set_availability','price_percent','confirm_prices') then
    raise exception 'invalid_action' using errcode = 'P0001';
  end if;
  if p_ids is null or cardinality(p_ids) = 0 then raise exception 'no_items' using errcode = 'P0001'; end if;
  if cardinality(p_ids) > 500 then raise exception 'too_many_items' using errcode = 'P0001'; end if;

  perform 1 from public.items i where i.business_id = v_id and i.id = any (p_ids) and not i.removed_by_admin order by i.id for update;
  select coalesce(array_agg(i.id order by i.id), '{}') into v_ids
    from public.items i
    where i.business_id = v_id and i.id = any (p_ids) and not i.removed_by_admin;
  v_skipped := cardinality(p_ids) - cardinality(v_ids);

  if p_action = 'hide' then
    update public.items set visible = false where id = any (v_ids) and visible;
    get diagnostics v_n = row_count;
  elsif p_action = 'show' then
    update public.items set visible = true, draft = false where id = any (v_ids) and (not visible or draft);
    get diagnostics v_n = row_count;
  elsif p_action = 'delete' then
    delete from public.items where id = any (v_ids);
    get diagnostics v_n = row_count;
  elsif p_action = 'move_section' then
    v_section := nullif(btrim(coalesce(p_args ->> 'section', '')), '');
    if v_section is not null and char_length(v_section) > 60 then raise exception 'invalid_section' using errcode = 'P0001'; end if;
    update public.items set section = v_section where id = any (v_ids) and section is distinct from v_section;
    get diagnostics v_n = row_count;
  elsif p_action = 'set_availability' then
    v_avail := p_args ->> 'availability';
    if v_avail is null or v_avail not in ('available','limited_stock','out_of_stock','unavailable','by_appointment') then
      raise exception 'invalid_availability' using errcode = 'P0001';
    end if;
    -- A counted item takes its availability from its count, so a status alone cannot relist it: with no stock in hand it
    -- would flip straight back out. Those are skipped, and the seller is told to give them a count (Back in stock).
    select count(*) into v_blocked from public.items i
      where i.id = any (v_ids) and i.track_stock and v_avail in ('available','limited_stock') and coalesce(i.stock_count, 0) <= 0;
    update public.items set
      availability = v_avail,
      stock_count = case when track_stock and v_avail in ('out_of_stock','unavailable') then 0 else stock_count end
    where id = any (v_ids) and availability <> v_avail
      and not (track_stock and v_avail in ('available','limited_stock') and coalesce(stock_count, 0) <= 0);
    get diagnostics v_n = row_count;
    v_skipped := v_skipped + v_blocked;
  elsif p_action = 'price_percent' then
    begin
      v_tenths := round((p_args ->> 'percent')::numeric * 10)::integer;
    exception when others then
      raise exception 'invalid_percent' using errcode = 'P0001';
    end;
    if v_tenths = 0 or v_tenths < -900 or v_tenths > 3000 then raise exception 'invalid_percent' using errcode = 'P0001'; end if;
    if exists (
      select 1 from public.items i
      where i.id = any (v_ids) and i.price_type in ('fixed','from','range') and not exists (select 1 from public.flash_sales s where s.item_id = i.id and s.status in ('scheduled','live'))
        and greatest(public.seller_scale_price(i.price, v_tenths), coalesce(public.seller_scale_price(i.price_max, v_tenths), 0)) > 9999999999.99
    ) then raise exception 'price_too_large' using errcode = 'P0001'; end if;
    -- 0086: variant prices follow the item's percent change, for the same items.
    if exists (
      select 1 from public.item_variants x join public.items i on i.id = x.item_id
      where i.id = any (v_ids) and i.price_type in ('fixed','from','range') and x.price is not null and not exists (select 1 from public.flash_sales s where s.item_id = i.id and s.status in ('scheduled','live'))
        and public.seller_scale_price(x.price, v_tenths) > 9999999999.99
    ) then raise exception 'price_too_large' using errcode = 'P0001'; end if;
    update public.items i set
      price = public.seller_scale_price(i.price, v_tenths),
      price_max = public.seller_scale_price(i.price_max, v_tenths),
      sale_price = case
        when i.sale_price is null then null
        when public.seller_scale_price(i.sale_price, v_tenths) < public.seller_scale_price(i.price, v_tenths) then public.seller_scale_price(i.sale_price, v_tenths)
        when public.seller_scale_price(i.price, v_tenths) > 1 then public.seller_scale_price(i.price, v_tenths) - 1
        else null end
    where i.id = any (v_ids) and i.price_type in ('fixed','from','range') and i.price is not null
      and not exists (select 1 from public.flash_sales s where s.item_id = i.id and s.status in ('scheduled','live'));
    get diagnostics v_n = row_count;
    v_skipped := v_skipped + (cardinality(v_ids) - v_n);
    update public.item_variants x set
      price = public.seller_scale_price(x.price, v_tenths),
      sale_price = case
        when x.sale_price is null then null
        when public.seller_scale_price(x.sale_price, v_tenths) < public.seller_scale_price(x.price, v_tenths) then public.seller_scale_price(x.sale_price, v_tenths)
        when public.seller_scale_price(x.price, v_tenths) > 1 then public.seller_scale_price(x.price, v_tenths) - 1
        else null end,
      updated_at = now()
    where x.item_id = any (v_ids) and x.price is not null
      and exists (select 1 from public.items i where i.id = x.item_id and i.price_type in ('fixed','from','range')
                  and not exists (select 1 from public.flash_sales s where s.item_id = i.id and s.status in ('scheduled','live')));   -- 0086
  else
    update public.items set price_confirmed_at = now() where id = any (v_ids);
    get diagnostics v_n = row_count;
  end if;

  perform public.write_audit(v_id, 'items_bulk_' || p_action, 'item', null, jsonb_build_object('count', v_n, 'skipped', v_skipped, 'args', coalesce(p_args, '{}')));
  return jsonb_build_object('affected', v_n, 'skipped', v_skipped);
end $$;

revoke all on function public.seller_save_item(uuid, jsonb), public.seller_duplicate_item(uuid), public.seller_bulk_items(text, uuid[], jsonb) from public, anon;
grant execute on function public.seller_save_item(uuid, jsonb), public.seller_duplicate_item(uuid), public.seller_bulk_items(text, uuid[], jsonb) to authenticated, service_role;

$m_0086_item_options$),
    ('0087_hours_shop_zone', $m_0087_hours_shop_zone$
-- 0087: hours and exceptions follow the shop's zone; 00:00-23:59 reads open until midnight.

create or replace function public.hours_open(p_hours jsonb, p_exceptions jsonb, p_at timestamptz default now()) returns boolean
language plpgsql immutable as $$
declare
  v_local timestamp := p_at at time zone 'Africa/Nairobi';
  v_date date := v_local::date;
  v_min integer := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_iv jsonb;
  v_start integer;
  v_end integer;
begin
  for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date)) loop
    v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
    v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
    if v_start = 0 and v_end = 1439 then v_end := 1440; end if;
    if v_end > v_start then
      if v_min >= v_start and v_min < v_end then return true; end if;
    elsif v_min >= v_start then
      return true;
    end if;
  end loop;
  if coalesce(public.hours_exception_on(p_exceptions, v_date) ->> 'kind', '') <> 'closed' then
    for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date - 1)) loop
      v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
      v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
      if v_end <= v_start and v_end > 0 and v_min < v_end then return true; end if;
    end loop;
  end if;
  return false;
end $$;

create or replace function public.hours_open_in(p_hours jsonb, p_exceptions jsonb, p_at timestamptz, p_tz text) returns boolean
language plpgsql stable as $$
declare
  v_local timestamp := p_at at time zone coalesce(nullif(p_tz, ''), 'Africa/Nairobi');
  v_date date := v_local::date;
  v_min integer := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_iv jsonb;
  v_start integer;
  v_end integer;
begin
  for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date)) loop
    v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
    v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
    if v_start = 0 and v_end = 1439 then v_end := 1440; end if;
    if v_end > v_start then
      if v_min >= v_start and v_min < v_end then return true; end if;
    elsif v_min >= v_start then
      return true;
    end if;
  end loop;
  if coalesce(public.hours_exception_on(p_exceptions, v_date) ->> 'kind', '') <> 'closed' then
    for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date - 1)) loop
      v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
      v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
      if v_end <= v_start and v_end > 0 and v_min < v_end then return true; end if;
    end loop;
  end if;
  return false;
end $$;

create or replace function public.shop_day(p_at timestamptz, p_tz text) returns date
language sql stable as $$
  select (p_at at time zone coalesce(nullif(p_tz, ''), 'Africa/Nairobi'))::date
$$;
revoke all on function public.shop_day(timestamptz, text) from public;
grant execute on function public.shop_day(timestamptz, text) to anon, authenticated, service_role;

create or replace function public.public_exceptions(p_list jsonb, p_tz text) returns jsonb
language sql stable set search_path = public as $$
  select coalesce(
    (select jsonb_agg(jsonb_build_object('id', e -> 'id', 'date', e -> 'date', 'kind', e -> 'kind', 'intervals', coalesce(e -> 'intervals', '[]'::jsonb), 'note', e -> 'note') order by e ->> 'date')
       from jsonb_array_elements(case when jsonb_typeof(p_list) = 'array' then p_list else '[]'::jsonb end) e
      where e ->> 'date' ~ '^\d{4}-\d{2}-\d{2}$'
        and (e ->> 'date')::date >= public.shop_day(now(), p_tz) - 1),
    '[]'::jsonb);
$$;
revoke all on function public.public_exceptions(jsonb, text) from public;
grant execute on function public.public_exceptions(jsonb, text) to anon, authenticated, service_role;

do $$
declare
  v_name text;
  v_def text;
  v_new text;
begin
  foreach v_name in array array['public_businesses', 'public_flash_sales'] loop
    v_def := pg_get_viewdef(('public.' || v_name)::regclass, true);
    v_new := regexp_replace(v_def, 'public_exceptions\((b\.)?exceptions\)', 'public_exceptions(\1exceptions, \1timezone)', 'g');
    if v_new = v_def then raise exception '%: public_exceptions call not found', v_name; end if;
    execute format('create or replace view public.%I with (security_barrier = true) as %s', v_name, v_new);
  end loop;
end $$;

create or replace function public.seller_save_exception(p_id uuid, p_date date, p_kind text, p_intervals jsonb default '[]', p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_tz text;
  v_today date;
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_list jsonb;
  v_item jsonb;
  v_known boolean;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select b.exceptions, b.timezone into v_list, v_tz from public.businesses b where b.id = v_biz for update;
  v_today := public.shop_day(now(), v_tz);
  v_item := public.exception_normalize(p_date, p_kind, p_intervals, p_note, v_today) || jsonb_build_object('id', v_id);
  v_list := coalesce((select jsonb_agg(e order by e ->> 'date') from jsonb_array_elements(coalesce(v_list, '[]')) e where (e ->> 'date')::date >= v_today - 1), '[]');
  v_known := exists (select 1 from jsonb_array_elements(v_list) e where e ->> 'id' = v_id::text);
  if exists (select 1 from jsonb_array_elements(v_list) e where e ->> 'date' = p_date::text and e ->> 'id' <> v_id::text) then raise exception 'date_taken'; end if;
  if not v_known and jsonb_array_length(v_list) >= 60 then raise exception 'limit_reached:exceptions' using errcode = 'P0001'; end if;
  v_list := (select jsonb_agg(s.x order by s.x ->> 'date') from (
    select e as x from jsonb_array_elements(v_list) e where e ->> 'id' <> v_id::text
    union all select v_item) s);
  update public.businesses b set exceptions = v_list where b.id = v_biz;
  perform public.write_audit(v_biz, case when v_known then 'exception_updated' else 'exception_added' end, 'business', v_biz::text, jsonb_build_object('date', p_date::text, 'kind', p_kind));
  return v_item;
end $$;

create or replace function public.seller_delete_exception(p_id uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_tz text;
  v_today date;
  v_list jsonb;
  v_found boolean;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select b.exceptions, b.timezone into v_list, v_tz from public.businesses b where b.id = v_biz for update;
  v_today := public.shop_day(now(), v_tz);
  v_found := exists (select 1 from jsonb_array_elements(coalesce(v_list, '[]')) e where e ->> 'id' = p_id::text);
  v_list := coalesce((select jsonb_agg(e order by e ->> 'date') from jsonb_array_elements(coalesce(v_list, '[]')) e
                      where e ->> 'id' <> p_id::text and (e ->> 'date')::date >= v_today - 1), '[]');
  update public.businesses b set exceptions = v_list where b.id = v_biz;
  if v_found then perform public.write_audit(v_biz, 'exception_deleted', 'business', v_biz::text, '{}'); end if;
  return v_found;
end $$;

revoke all on function public.seller_save_exception(uuid, date, text, jsonb, text), public.seller_delete_exception(uuid) from public, anon;
grant execute on function public.seller_save_exception(uuid, date, text, jsonb, text), public.seller_delete_exception(uuid) to authenticated, service_role;

$m_0087_hours_shop_zone$),
    ('0088_option_dependencies', $m_0088_option_dependencies$
-- 0088: option dependencies, the seller's default variant, per-variant spec overrides, a database cap on variants, seller_check_item.
-- Builds on 0086 (item_variants, option_axes, item_options_apply, the reads). Nothing from 0086 is edited; the functions below are
-- re-created with their 0086 text plus the changes marked 0088.
--
--   1. items.default_variant_id        the seller's default combination (an item_variants row of the SAME item; cleared if that variant is removed).
--   2. item_variants.specs             spec rows that replace the item's own rows for one combination ("Compatible devices" by style).
--   3. axes: `dependsOn`               an axis may depend on an EARLIER axis; the value lists are derived from the sellable combinations in
--                                      shared/src/options/dependent.js, never stored a second time.
--   4. a trigger                       at most 200 variants per item, enforced by the database (the save function checks it first, with a name).
--   5. seller_save_item (via item_options_apply)   options.defaultChoice, variants[].specs.
--   6. reads                           public_item_options / seller_item_options add defaultVariantId, specs, dependsOn.
--   7. seller_check_item               runs the real save in a sub-transaction and rolls it back: same checks, nothing written.
--
-- Old items (no options) are untouched: the new columns default to null / [] and every read keeps its old keys.

-- ---------------------------------------------------------------------------------------------------------------------
-- 1 + 2. Columns
-- ---------------------------------------------------------------------------------------------------------------------

-- (id, item_id) is unique so items can point at "a variant of this same item" with one composite foreign key.
alter table public.item_variants add column if not exists specs jsonb not null default '[]'::jsonb;
alter table public.item_variants drop constraint if exists item_variants_specs_shape;
alter table public.item_variants add constraint item_variants_specs_shape check (public.item_specs_valid(specs));
alter table public.item_variants drop constraint if exists item_variants_id_item_uq;
alter table public.item_variants add constraint item_variants_id_item_uq unique (id, item_id);

alter table public.items add column if not exists default_variant_id uuid;
alter table public.items drop constraint if exists items_default_variant_fk;
-- on delete set null (default_variant_id): removing the default variant clears the default and leaves item_id alone.
alter table public.items add constraint items_default_variant_fk foreign key (default_variant_id, id)
  references public.item_variants (id, item_id) on delete set null (default_variant_id);

-- ---------------------------------------------------------------------------------------------------------------------
-- 3. Axes: dependsOn
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.item_option_axes_valid(p jsonb) returns boolean
language plpgsql immutable parallel safe as $$
declare
  a jsonb;
  v jsonb;
  k text;
  v_keys text[] := '{}';
  v_ids text[];
begin
  if p is null or jsonb_typeof(p) <> 'array' or jsonb_array_length(p) > 3 then return false; end if;
  for a in select jsonb_array_elements(p) loop
    if jsonb_typeof(a) <> 'object' then return false; end if;
    for k in select jsonb_object_keys(a) loop
      if k not in ('key', 'label', 'display', 'values', 'dependsOn') then return false; end if;
    end loop;
    if not public.option_slug_ok(a -> 'key', 30) or (a ->> 'key') = any (v_keys) then return false; end if;
    -- dependsOn names an EARLIER axis (so the chain can never loop); v_keys holds only the axes before this one.
    if a ? 'dependsOn' and (not public.option_slug_ok(a -> 'dependsOn', 30) or not ((a ->> 'dependsOn') = any (v_keys))) then return false; end if;
    v_keys := v_keys || (a ->> 'key');
    if not public.item_detail_text_ok(a -> 'label', 30) then return false; end if;
    if jsonb_typeof(a -> 'display') is distinct from 'string' or (a ->> 'display') <> all (array['swatch', 'image-card', 'button', 'dropdown', 'text-card']) then return false; end if;
    if jsonb_typeof(a -> 'values') is distinct from 'array' or jsonb_array_length(a -> 'values') not between 1 and 40 then return false; end if;
    v_ids := '{}';
    for v in select jsonb_array_elements(a -> 'values') loop
      if jsonb_typeof(v) <> 'object' then return false; end if;
      for k in select jsonb_object_keys(v) loop
        if k not in ('id', 'label', 'color', 'mediaId', 'copyMediaId') then return false; end if;
      end loop;
      if not public.option_slug_ok(v -> 'id', 40) or (v ->> 'id') = any (v_ids) then return false; end if;
      v_ids := v_ids || (v ->> 'id');
      if not public.item_detail_text_ok(v -> 'label', 40) then return false; end if;
      if v ? 'color' and (jsonb_typeof(v -> 'color') <> 'string' or (v ->> 'color') !~ '^#[0-9a-fA-F]{6}$') then return false; end if;
      if v ? 'mediaId' and not public.option_uuid_ok(v -> 'mediaId') then return false; end if;
      if v ? 'copyMediaId' and not public.option_uuid_ok(v -> 'copyMediaId') then return false; end if;
    end loop;
  end loop;
  return true;
end $$;

create or replace function public.item_option_axes_clean(p jsonb) returns jsonb
language plpgsql immutable parallel safe as $$
declare
  a jsonb;
  v jsonb;
  v_axis jsonb;
  v_vals jsonb;
  v_out jsonb := '[]'::jsonb;
  v_one jsonb;
begin
  if p is null or jsonb_typeof(p) <> 'array' then return p; end if;
  for a in select jsonb_array_elements(p) loop
    if jsonb_typeof(a) <> 'object' or jsonb_typeof(a -> 'values') is distinct from 'array' then return p; end if;
    v_vals := '[]'::jsonb;
    for v in select jsonb_array_elements(a -> 'values') loop
      if jsonb_typeof(v) <> 'object' then return p; end if;
      v_one := jsonb_build_object('id', v -> 'id', 'label', case when jsonb_typeof(v -> 'label') = 'string' then to_jsonb(btrim(v ->> 'label')) else v -> 'label' end);
      if v ? 'color' and jsonb_typeof(v -> 'color') <> 'null' then v_one := v_one || jsonb_build_object('color', case when jsonb_typeof(v -> 'color') = 'string' then to_jsonb(lower(v ->> 'color')) else v -> 'color' end); end if;
      if v ? 'mediaId' and jsonb_typeof(v -> 'mediaId') <> 'null' then v_one := v_one || jsonb_build_object('mediaId', case when jsonb_typeof(v -> 'mediaId') = 'string' then to_jsonb(lower(v ->> 'mediaId')) else v -> 'mediaId' end); end if;
      v_vals := v_vals || jsonb_build_array(v_one);
    end loop;
    v_axis := jsonb_build_object('key', a -> 'key', 'label', case when jsonb_typeof(a -> 'label') = 'string' then to_jsonb(btrim(a ->> 'label')) else a -> 'label' end,
                                 'display', a -> 'display', 'values', v_vals);
    if a ? 'dependsOn' and jsonb_typeof(a -> 'dependsOn') <> 'null' then v_axis := v_axis || jsonb_build_object('dependsOn', a -> 'dependsOn'); end if;
    v_out := v_out || jsonb_build_array(v_axis);
  end loop;
  return v_out;
end $$;

create or replace function public.item_option_axes_public(p jsonb) returns jsonb
language sql immutable parallel safe as $$
  select coalesce(jsonb_agg(
    jsonb_build_object('key', a.e -> 'key', 'label', a.e -> 'label', 'display', a.e -> 'display', 'values', (
      select coalesce(jsonb_agg(
        jsonb_build_object('id', v.e -> 'id', 'label', v.e -> 'label')
          || case when v.e ? 'color' then jsonb_build_object('color', v.e -> 'color') else '{}'::jsonb end
          || case when v.e ? 'mediaId' then jsonb_build_object('mediaId', v.e -> 'mediaId') else '{}'::jsonb end
        order by v.n), '[]'::jsonb)
      from jsonb_array_elements(a.e -> 'values') with ordinality as v(e, n))) || case when a.e ? 'dependsOn' then jsonb_build_object('dependsOn', a.e -> 'dependsOn') else '{}'::jsonb end
    order by a.n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as a(e, n)
$$;

create or replace function public.item_option_axes_for_copy(p jsonb) returns jsonb
language sql immutable parallel safe as $$
  select coalesce(jsonb_agg(
    jsonb_build_object('key', a.e -> 'key', 'label', a.e -> 'label', 'display', a.e -> 'display', 'values', (
      select coalesce(jsonb_agg(
        jsonb_build_object('id', v.e -> 'id', 'label', v.e -> 'label')
          || case when v.e ? 'color' then jsonb_build_object('color', v.e -> 'color') else '{}'::jsonb end
          || case when v.e ? 'mediaId' then jsonb_build_object('copyMediaId', v.e -> 'mediaId')
                  when v.e ? 'copyMediaId' then jsonb_build_object('copyMediaId', v.e -> 'copyMediaId') else '{}'::jsonb end
        order by v.n), '[]'::jsonb)
      from jsonb_array_elements(a.e -> 'values') with ordinality as v(e, n))) || case when a.e ? 'dependsOn' then jsonb_build_object('dependsOn', a.e -> 'dependsOn') else '{}'::jsonb end
    order by a.n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as a(e, n)
$$;

create or replace function public.item_option_axes_remap(p jsonb, p_map jsonb) returns jsonb
language sql immutable parallel safe as $$
  select coalesce(jsonb_agg(
    jsonb_build_object('key', a.e -> 'key', 'label', a.e -> 'label', 'display', a.e -> 'display', 'values', (
      select coalesce(jsonb_agg(
        jsonb_build_object('id', v.e -> 'id', 'label', v.e -> 'label')
          || case when v.e ? 'color' then jsonb_build_object('color', v.e -> 'color') else '{}'::jsonb end
          || case when v.e ? 'copyMediaId' and p_map ? (v.e ->> 'copyMediaId') then jsonb_build_object('mediaId', p_map -> (v.e ->> 'copyMediaId'))
                  when v.e ? 'mediaId' then jsonb_build_object('mediaId', v.e -> 'mediaId') else '{}'::jsonb end
        order by v.n), '[]'::jsonb)
      from jsonb_array_elements(a.e -> 'values') with ordinality as v(e, n))) || case when a.e ? 'dependsOn' then jsonb_build_object('dependsOn', a.e -> 'dependsOn') else '{}'::jsonb end
    order by a.n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as a(e, n)
$$;

-- ---------------------------------------------------------------------------------------------------------------------
-- 4. Variant cap in the database
-- ---------------------------------------------------------------------------------------------------------------------

-- A row that only updates an existing combination (the upsert in item_options_apply) does not add one, so it is never refused.
create or replace function public.item_variants_limit() returns trigger
language plpgsql set search_path = public as $$
begin
  if exists (select 1 from public.item_variants v where v.item_id = new.item_id and v.combo_key = new.combo_key) then return new; end if;
  if (select count(*) from public.item_variants v where v.item_id = new.item_id) >= 200 then
    raise exception 'too_many_variants' using errcode = 'P0001';
  end if;
  return new;
end $$;
revoke all on function public.item_variants_limit() from public, anon, authenticated;
drop trigger if exists item_variants_limit on public.item_variants;
create trigger item_variants_limit before insert on public.item_variants for each row execute function public.item_variants_limit();

-- ---------------------------------------------------------------------------------------------------------------------
-- 5. Save: defaultChoice and variant specs (seller_save_item itself is unchanged; it calls this)
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.item_options_apply(p_item uuid, p_business uuid, f jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_old public.items;
  v_opts jsonb;
  v_axes jsonb;
  v_vars jsonb;
  e jsonb;
  k text;
  n integer := 0;
  v_key text;
  v_keys text[] := '{}';
  v_skus text[] := '{}';
  v_sku text;
  v_status text;
  v_stock integer;
  v_price numeric;
  v_sale numeric;
  v_media uuid[];
  v_specs jsonb;
  v_has_def boolean := false;
  v_def_key text;
  v_rows jsonb := '[]'::jsonb;
  m jsonb;
  v_changed boolean;
  v_chart public.size_charts;
  v_chart_id uuid;
  c_money constant text := '^\d{1,10}(\.\d{1,2})?$';
begin
  select * into v_old from public.items where id = p_item and business_id = p_business for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;

  if f ? 'options' then
    v_opts := f -> 'options';
    if v_opts is null or jsonb_typeof(v_opts) = 'null' then
      v_axes := '[]'::jsonb;
      v_vars := '[]'::jsonb;
    else
      if jsonb_typeof(v_opts) <> 'object' then raise exception 'invalid_options' using errcode = 'P0001'; end if;
      for k in select jsonb_object_keys(v_opts) loop
        if k not in ('axes', 'variants', 'defaultChoice') then raise exception 'invalid_options' using errcode = 'P0001'; end if;
      end loop;
      v_axes := coalesce(nullif(v_opts -> 'axes', 'null'::jsonb), '[]'::jsonb);
      v_vars := coalesce(nullif(v_opts -> 'variants', 'null'::jsonb), '[]'::jsonb);
    end if;
    if jsonb_typeof(v_axes) <> 'array' or jsonb_typeof(v_vars) <> 'array' then raise exception 'invalid_options' using errcode = 'P0001'; end if;
    v_axes := public.item_option_axes_clean(v_axes);
    if not public.item_option_axes_valid(v_axes) then raise exception 'invalid_options' using errcode = 'P0001'; end if;
    if jsonb_array_length(v_vars) > 200 then raise exception 'too_many_variants' using errcode = 'P0001'; end if;
    if jsonb_array_length(v_axes) = 0 and jsonb_array_length(v_vars) > 0 then raise exception 'invalid_options' using errcode = 'P0001'; end if;
    -- The seller's default combination; checked against the saved variants once they are collected. null clears it.
    if jsonb_typeof(v_opts) = 'object' and v_opts ? 'defaultChoice' then
      v_has_def := true;
      if jsonb_typeof(v_opts -> 'defaultChoice') <> 'null' then
        v_def_key := public.item_option_combo_key(v_axes, v_opts -> 'defaultChoice');
        if v_def_key is null then raise exception 'invalid_default' using errcode = 'P0001'; end if;
      end if;
    end if;

    -- A value's picture must be one of this item's own media.
    for m in select v.e from jsonb_array_elements(v_axes) a(e), jsonb_array_elements(a.e -> 'values') v(e) where v.e ? 'mediaId' loop
      if not exists (select 1 from public.item_media im where im.id = (m ->> 'mediaId')::uuid and im.item_id = p_item) then
        raise exception 'invalid_options' using errcode = 'P0001';
      end if;
    end loop;

    -- Check every variant first (collected in v_rows), then write.

    for e in select jsonb_array_elements(v_vars) loop
      n := n + 1;
      if jsonb_typeof(e) <> 'object' then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      for k in select jsonb_object_keys(e) loop
        if k not in ('id', 'choice', 'price', 'salePrice', 'stock', 'status', 'sku', 'mediaIds', 'specs') then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      end loop;
      v_key := public.item_option_combo_key(v_axes, e -> 'choice');
      if v_key is null then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      if v_key = any (v_keys) then raise exception 'duplicate_variant' using errcode = 'P0001'; end if;
      v_keys := v_keys || v_key;

      v_price := null; v_sale := null; v_stock := null; v_sku := null; v_media := '{}'; v_specs := '[]'::jsonb;
      if jsonb_typeof(e -> 'price') not in ('null') and e ? 'price' then
        if (e ->> 'price') !~ c_money then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        v_price := (e ->> 'price')::numeric;
      end if;
      if e ? 'salePrice' and jsonb_typeof(e -> 'salePrice') <> 'null' then
        if (e ->> 'salePrice') !~ c_money or v_price is null then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        v_sale := (e ->> 'salePrice')::numeric;
        if v_sale >= v_price then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      end if;
      if e ? 'stock' and jsonb_typeof(e -> 'stock') <> 'null' then
        if (e ->> 'stock') !~ '^\d{1,6}$' then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        v_stock := (e ->> 'stock')::integer;
      end if;
      v_status := coalesce(case when e ? 'status' and jsonb_typeof(e -> 'status') <> 'null' then e ->> 'status' end, 'available');
      if jsonb_typeof(coalesce(e -> 'status', '"available"'::jsonb)) not in ('string', 'null')
         or v_status not in ('available', 'limited_stock', 'out_of_stock', 'unavailable') then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      if v_stock = 0 then v_status := 'out_of_stock'; end if;
      if e ? 'sku' and jsonb_typeof(e -> 'sku') <> 'null' then
        if jsonb_typeof(e -> 'sku') <> 'string' then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        v_sku := nullif(btrim(e ->> 'sku'), '');
        if char_length(coalesce(v_sku, '')) > 40 then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        if v_sku is not null then
          if lower(v_sku) = any (v_skus) then raise exception 'duplicate_sku' using errcode = 'P0001'; end if;
          v_skus := v_skus || lower(v_sku);
        end if;
      end if;
      if e ? 'mediaIds' and jsonb_typeof(e -> 'mediaIds') <> 'null' then
        if jsonb_typeof(e -> 'mediaIds') <> 'array' or jsonb_array_length(e -> 'mediaIds') > 10 then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        for m in select jsonb_array_elements(e -> 'mediaIds') loop
          if not public.option_uuid_ok(m) then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
          if (m #>> '{}')::uuid = any (v_media) then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
          if not exists (select 1 from public.item_media im where im.id = (m #>> '{}')::uuid and im.item_id = p_item) then
            raise exception 'invalid_variant' using errcode = 'P0001';
          end if;
          v_media := v_media || (m #>> '{}')::uuid;
        end loop;
      end if;
      -- Spec rows that replace the item's own rows for this combination (same shape and limits as items.specs); trimmed like the JS mirror.
      if e ? 'specs' and jsonb_typeof(e -> 'specs') <> 'null' then
        if jsonb_typeof(e -> 'specs') <> 'array' or jsonb_array_length(e -> 'specs') > 20 then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
        select coalesce(jsonb_agg(case when jsonb_typeof(r.e) = 'object' then r.e
                 || case when jsonb_typeof(r.e -> 'label') = 'string' then jsonb_build_object('label', btrim(r.e ->> 'label')) else '{}'::jsonb end
                 || case when jsonb_typeof(r.e -> 'value') = 'string' then jsonb_build_object('value', btrim(r.e ->> 'value')) else '{}'::jsonb end
               else r.e end order by r.n), '[]'::jsonb)
          into v_specs from jsonb_array_elements(e -> 'specs') with ordinality as r(e, n);
        if not public.item_specs_valid(v_specs) then raise exception 'invalid_variant' using errcode = 'P0001'; end if;
      end if;
      v_rows := v_rows || jsonb_build_array(jsonb_build_object('ord', n, 'combo_key', v_key, 'choice', e -> 'choice', 'price', v_price, 'sale_price', v_sale,
                                                               'stock_count', v_stock, 'status', v_status, 'sku', v_sku, 'media_ids', to_jsonb(v_media), 'specs', v_specs));
    end loop;

    if v_def_key is not null and not (v_def_key = any (v_keys)) then raise exception 'invalid_default' using errcode = 'P0001'; end if;

    -- The flash guard of seller_save_item covers variant prices too: they cannot change while the item is in a scheduled or live sale.
    if exists (select 1 from public.flash_sales s where s.item_id = p_item and s.status in ('scheduled', 'live')) then
      select exists (
        select 1 from jsonb_to_recordset(v_rows) as t(combo_key text, price numeric, sale_price numeric)
          full join public.item_variants o on o.item_id = p_item and o.combo_key = t.combo_key
        where (t.combo_key is null or o.combo_key is null) and coalesce(t.price, o.price) is not null
           or (t.combo_key is not null and o.combo_key is not null and (t.price, t.sale_price) is distinct from (o.price, o.sale_price))
      ) into v_changed;
      if v_changed then raise exception 'item_in_flash_sale' using errcode = 'P0001'; end if;
    end if;

    delete from public.item_variants where item_id = p_item and not (combo_key = any (v_keys));
    update public.item_variants set sku = null where item_id = p_item;   -- a SKU may move between combinations in one save
    insert into public.item_variants (item_id, business_id, combo_key, choice, price, sale_price, stock_count, status, sku, media_ids, copy_media_ids, sort, specs)
    select p_item, p_business, t.combo_key, t.choice, t.price, t.sale_price, t.stock_count, t.status, t.sku,
           array(select jsonb_array_elements_text(t.media_ids)::uuid), '{}', t.ord - 1, t.specs
      from jsonb_to_recordset(v_rows) as t(ord integer, combo_key text, choice jsonb, price numeric, sale_price numeric, stock_count integer, status text, sku text, media_ids jsonb, specs jsonb)
    on conflict (item_id, combo_key) do update set
      choice = excluded.choice, price = excluded.price, sale_price = excluded.sale_price, stock_count = excluded.stock_count, status = excluded.status,
      sku = excluded.sku, media_ids = excluded.media_ids, copy_media_ids = '{}', sort = excluded.sort, specs = excluded.specs, updated_at = now();
    -- Real options supersede the old single-list variants (still written by the old editor); leaving both would show two lists.
    update public.items set option_axes = v_axes, variants = case when jsonb_array_length(v_axes) > 0 then '[]'::jsonb else variants end where id = p_item;
    -- The default: left alone when the save does not mention it (a removed variant clears it by itself, see the foreign key), set or cleared when it does.
    if v_has_def then
      update public.items set default_variant_id = (select iv.id from public.item_variants iv where iv.item_id = p_item and iv.combo_key = v_def_key) where id = p_item;
    end if;
  end if;

  if f ? 'size_chart_id' then
    if jsonb_typeof(f -> 'size_chart_id') = 'null' then
      update public.items set size_chart_id = null, size_chart_override = null where id = p_item;
    else
      if not public.option_uuid_ok(f -> 'size_chart_id') then raise exception 'invalid_size_chart' using errcode = 'P0001'; end if;
      v_chart_id := (f ->> 'size_chart_id')::uuid;
      -- An item may keep a chart that was retired since, but cannot newly pick one.
      if not exists (select 1 from public.size_charts sc where sc.id = v_chart_id and (sc.active or sc.id = v_old.size_chart_id)) then
        raise exception 'invalid_size_chart' using errcode = 'P0001';
      end if;
      update public.items set size_chart_id = v_chart_id, size_chart_override = case when v_chart_id is distinct from v_old.size_chart_id then null else size_chart_override end
        where id = p_item;
    end if;
  end if;

  if f ? 'size_chart_override' then
    select * into v_old from public.items where id = p_item;
    if jsonb_typeof(f -> 'size_chart_override') = 'null' then
      update public.items set size_chart_override = null where id = p_item;
    else
      if v_old.size_chart_id is null or jsonb_typeof(f -> 'size_chart_override') <> 'object' then raise exception 'invalid_size_chart' using errcode = 'P0001'; end if;
      for k in select jsonb_object_keys(f -> 'size_chart_override') loop
        if k <> 'rows' then raise exception 'invalid_size_chart' using errcode = 'P0001'; end if;
      end loop;
      select * into v_chart from public.size_charts where id = v_old.size_chart_id;
      if not public.size_chart_rows_valid(f #> '{size_chart_override,rows}', jsonb_array_length(v_chart.columns)) then raise exception 'invalid_size_chart' using errcode = 'P0001'; end if;
      update public.items set size_chart_override = jsonb_build_object('rows', f #> '{size_chart_override,rows}') where id = p_item;
    end if;
  end if;
end $$;
revoke all on function public.item_options_apply(uuid, uuid, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------------------------
-- 6. Reads and duplicate
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.item_options_source(i public.items) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c jsonb;
  v_axes jsonb;
  v_vars jsonb;
begin
  if i.option_axes <> '[]'::jsonb then
    return jsonb_build_object('legacy', false, 'axes', i.option_axes, 'variants', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'label', public.item_variant_label(i.option_axes, s.choice), 'key', s.combo_key, 'choice', s.choice,
        'price', s.price, 'salePrice', s.sale_price, 'stock', s.stock_count, 'status', s.status, 'sku', s.sku, 'mediaIds', to_jsonb(s.media_ids), 'specs', s.specs) order by s.sort, s.id)
      from public.item_variants s where s.item_id = i.id), '[]'::jsonb));
  end if;
  c := public.item_options_from_legacy(case when jsonb_typeof(i.variants) = 'array' then i.variants else '[]'::jsonb end);
  v_axes := c -> 'axes';
  select coalesce(jsonb_agg(jsonb_build_object('id', x.e ->> 'slug', 'label', x.e ->> 'label', 'key', 'option=' || (x.e ->> 'slug'),
      'choice', jsonb_build_object('option', x.e ->> 'slug'), 'price', x.e -> 'price', 'salePrice', null, 'stock', x.e -> 'stock',
      'status', case when (x.e ->> 'stock') = '0' then 'out_of_stock' else 'available' end, 'sku', null, 'mediaIds', '[]'::jsonb) order by x.n), '[]'::jsonb)
    into v_vars from jsonb_array_elements(c -> 'rows') with ordinality as x(e, n);
  return jsonb_build_object('legacy', jsonb_array_length(v_axes) > 0, 'axes', v_axes, 'variants', v_vars);
end $$;
revoke all on function public.item_options_source(public.items) from public;
grant execute on function public.item_options_source(public.items) to service_role;

create or replace function public.public_item_options(p_item uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  i public.items;
  src jsonb;
begin
  if not exists (select 1 from public.public_items pi where pi.id = p_item) then return null; end if;
  select * into i from public.items where id = p_item;
  src := public.item_options_source(i);
  return jsonb_build_object(
    'options', public.item_option_axes_public(src -> 'axes'),
    'optionVariants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', x.e -> 'id', 'label', x.e -> 'label', 'choice', x.e -> 'choice',
        'price', coalesce(nullif(x.e -> 'price', 'null'::jsonb), to_jsonb(i.price)),
        'salePrice', case when jsonb_typeof(x.e -> 'price') = 'null' then to_jsonb(i.sale_price) else x.e -> 'salePrice' end,
        'status', x.e -> 'status', 'sku', x.e -> 'sku', 'mediaIds', x.e -> 'mediaIds', 'specs', coalesce(x.e -> 'specs', '[]'::jsonb),
        'stockLeft', case when i.show_stock_count and x.e ->> 'status' = 'limited_stock' and (x.e ->> 'stock')::integer > 0 then x.e -> 'stock' end) order by x.n)
      from jsonb_array_elements(src -> 'variants') with ordinality as x(e, n)), '[]'::jsonb),
    'optionAvailability', public.item_options_matrix(src -> 'axes', (
      select coalesce(jsonb_agg(jsonb_build_object('id', x.e -> 'id', 'key', x.e -> 'key', 'choice', x.e -> 'choice', 'status', x.e -> 'status') order by x.n), '[]'::jsonb)
      from jsonb_array_elements(src -> 'variants') with ordinality as x(e, n))),
    'defaultVariantId', i.default_variant_id,
    'sizeChart', public.item_size_chart_payload(i));
end $$;

create or replace function public.seller_item_options(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  i public.items;
  src jsonb;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into i from public.items where id = p_id and business_id = v_id and not removed_by_admin;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  src := public.item_options_source(i);
  return jsonb_build_object(
    'fromLegacy', src -> 'legacy',
    'axes', public.item_option_axes_public(src -> 'axes'),
    'variants', coalesce((
      select jsonb_agg(jsonb_build_object('id', x.e -> 'id', 'choice', x.e -> 'choice', 'price', x.e -> 'price', 'salePrice', x.e -> 'salePrice', 'stock', x.e -> 'stock',
                                          'status', x.e -> 'status', 'sku', x.e -> 'sku', 'mediaIds', x.e -> 'mediaIds', 'specs', coalesce(x.e -> 'specs', '[]'::jsonb)) order by x.n)
      from jsonb_array_elements(src -> 'variants') with ordinality as x(e, n)), '[]'::jsonb),
    'optionAvailability', public.item_options_matrix(src -> 'axes', (
      select coalesce(jsonb_agg(jsonb_build_object('id', x.e -> 'id', 'key', x.e -> 'key', 'choice', x.e -> 'choice', 'status', x.e -> 'status') order by x.n), '[]'::jsonb)
      from jsonb_array_elements(src -> 'variants') with ordinality as x(e, n))),
    'defaultVariantId', i.default_variant_id,
    'sizeChartId', i.size_chart_id,
    'sizeChartOverride', i.size_chart_override);
end $$;

create or replace function public.seller_duplicate_item(p_id uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_src public.items;
  v_new uuid;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into v_src from public.items where id = p_id and business_id = v_id and not removed_by_admin;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  insert into public.items (business_id, name, description, section, price, price_max, price_type, unit, sale_price, availability, stock_count,
    track_stock, low_stock_threshold, show_stock_count, season, tags, badge, variants, visible, draft, sort,
    brand, short_description, highlights, specs, includes, terms, pack_size, option_axes, size_chart_id, size_chart_override)
  values (v_id, left(v_src.name, 111) || ' (copy)', v_src.description, v_src.section, v_src.price, v_src.price_max, v_src.price_type, v_src.unit,
    v_src.sale_price, v_src.availability, v_src.stock_count, v_src.track_stock, v_src.low_stock_threshold, v_src.show_stock_count, v_src.season,
    v_src.tags, v_src.badge, v_src.variants, false, true, v_src.sort + 1,
    v_src.brand, v_src.short_description, v_src.highlights, v_src.specs, v_src.includes, v_src.terms, v_src.pack_size,
    public.item_option_axes_for_copy(v_src.option_axes), v_src.size_chart_id, v_src.size_chart_override)   -- 0086
  returning id into v_new;
  -- 0086: variants are copied with their media ids parked in copy_media_ids; item_remap_copied_media resolves them after the files are copied.
  insert into public.item_variants (item_id, business_id, combo_key, choice, price, sale_price, stock_count, status, sku, media_ids, copy_media_ids, sort, specs)
  select v_new, v_id, s.combo_key, s.choice, s.price, s.sale_price, s.stock_count, s.status, s.sku, '{}', case when cardinality(s.media_ids) > 0 then s.media_ids else s.copy_media_ids end, s.sort, s.specs
    from public.item_variants s where s.item_id = p_id;
  -- 0088: the copy keeps the same default combination (its variants have new ids, so look it up by combination).
  if v_src.default_variant_id is not null then
    update public.items set default_variant_id = (select n.id from public.item_variants n join public.item_variants o on o.combo_key = n.combo_key
                                                   where n.item_id = v_new and o.id = v_src.default_variant_id) where id = v_new;
  end if;
  return v_new;
end $$;

revoke all on function public.public_item_options(uuid), public.seller_item_options(uuid) from public, anon;
grant execute on function public.public_item_options(uuid) to anon, authenticated, service_role;
grant execute on function public.seller_item_options(uuid) to authenticated, service_role;
revoke all on function public.seller_duplicate_item(uuid) from public, anon;
grant execute on function public.seller_duplicate_item(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 7. seller_check_item: the issues a save would raise, without saving
-- ---------------------------------------------------------------------------------------------------------------------

-- Same arguments as seller_save_item (p_id null checks a new item). It runs the real save inside a sub-transaction and always rolls it
-- back, so the checks cannot drift from the save. Returns { ok: true } or { ok: false, issues: [{ code }] } (the save's error name).
-- The save stops at the first problem, so there is at most one issue; the shared validator (shared/src/seller/options.js) lists them all
-- for the form. Any error that is not one of the save's own is reported as invalid_item rather than leaking the database's text.
create or replace function public.seller_check_item(p_id uuid, p_fields jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_state text;
  v_msg text;
begin
  perform public.assert_seller_active();
  if public.my_business_id() is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  begin
    perform public.seller_save_item(p_id, p_fields);
    raise exception 'check_done' using errcode = 'P0002';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
    if v_state = 'P0002' and v_msg = 'check_done' then
      return jsonb_build_object('ok', true, 'issues', '[]'::jsonb);
    elsif v_state = '42501' then
      raise;
    elsif v_state = 'P0001' then
      return jsonb_build_object('ok', false, 'issues', jsonb_build_array(jsonb_build_object('code', v_msg)));
    end if;
    return jsonb_build_object('ok', false, 'issues', jsonb_build_array(jsonb_build_object('code', 'invalid_item')));
  end;
end $$;
revoke all on function public.seller_check_item(uuid, jsonb) from public, anon;
grant execute on function public.seller_check_item(uuid, jsonb) to authenticated, service_role;

$m_0088_option_dependencies$),
    ('0089_break_exceptions', $m_0089_break_exceptions$
-- 0089: break exceptions. The shop is closed for a few hours (a lunch break) and the normal hours apply around it.
-- A break covers one date, every date up to "until", or (with weekdays) those weekdays from its date until "until".

create or replace function public.break_applies_on(e jsonb, d date) returns boolean
language sql immutable as $$
  select e ->> 'kind' = 'break'
    and e ->> 'date' ~ '^\d{4}-\d{2}-\d{2}$'
    and (e ->> 'date')::date <= d
    and case
      when jsonb_typeof(e -> 'weekdays') = 'array' then
        (coalesce(e ->> 'until', '') !~ '^\d{4}-\d{2}-\d{2}$' or d <= (e ->> 'until')::date)
        and (e -> 'weekdays') ? (array['sun','mon','tue','wed','thu','fri','sat'])[extract(dow from d)::int + 1]
      when coalesce(e ->> 'until', '') ~ '^\d{4}-\d{2}-\d{2}$' then d <= (e ->> 'until')::date
      else (e ->> 'date')::date = d
    end
$$;

create or replace function public.hours_in_break(p_exceptions jsonb, p_date date, p_min integer) returns boolean
language sql immutable as $$
  select public.hours_exception_on(p_exceptions, p_date) is null
    and exists (
      select 1
      from jsonb_array_elements(case when jsonb_typeof(p_exceptions) = 'array' then p_exceptions else '[]'::jsonb end) e,
           jsonb_array_elements(case when jsonb_typeof(e -> 'intervals') = 'array' then e -> 'intervals' else '[]'::jsonb end) iv
      where jsonb_typeof(e) = 'object'
        and public.break_applies_on(e, p_date)
        and public.hours_interval_ok(iv)
        and p_min >= split_part(iv ->> 0, ':', 1)::int * 60 + split_part(iv ->> 0, ':', 2)::int
        and p_min < split_part(iv ->> 1, ':', 1)::int * 60 + split_part(iv ->> 1, ':', 2)::int
    )
$$;

create or replace function public.exception_last_day(e jsonb) returns date
language sql immutable as $$
  select case
    when coalesce(e ->> 'until', '') ~ '^\d{4}-\d{2}-\d{2}$' then (e ->> 'until')::date
    when e ->> 'kind' = 'break' and jsonb_typeof(e -> 'weekdays') = 'array' then date '9999-12-31'
    else (e ->> 'date')::date
  end
$$;

create or replace function public.hours_open(p_hours jsonb, p_exceptions jsonb, p_at timestamptz default now()) returns boolean
language plpgsql immutable as $$
declare
  v_local timestamp := p_at at time zone 'Africa/Nairobi';
  v_date date := v_local::date;
  v_min integer := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_iv jsonb;
  v_start integer;
  v_end integer;
begin
  if public.hours_in_break(p_exceptions, v_date, v_min) then return false; end if;
  for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date)) loop
    v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
    v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
    if v_start = 0 and v_end = 1439 then v_end := 1440; end if;
    if v_end > v_start then
      if v_min >= v_start and v_min < v_end then return true; end if;
    elsif v_min >= v_start then
      return true;
    end if;
  end loop;
  if coalesce(public.hours_exception_on(p_exceptions, v_date) ->> 'kind', '') <> 'closed' then
    for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date - 1)) loop
      v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
      v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
      if v_end <= v_start and v_end > 0 and v_min < v_end then return true; end if;
    end loop;
  end if;
  return false;
end $$;

create or replace function public.hours_open_in(p_hours jsonb, p_exceptions jsonb, p_at timestamptz, p_tz text) returns boolean
language plpgsql stable as $$
declare
  v_local timestamp := p_at at time zone coalesce(nullif(p_tz, ''), 'Africa/Nairobi');
  v_date date := v_local::date;
  v_min integer := extract(hour from v_local)::int * 60 + extract(minute from v_local)::int;
  v_iv jsonb;
  v_start integer;
  v_end integer;
begin
  if public.hours_in_break(p_exceptions, v_date, v_min) then return false; end if;
  for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date)) loop
    v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
    v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
    if v_start = 0 and v_end = 1439 then v_end := 1440; end if;
    if v_end > v_start then
      if v_min >= v_start and v_min < v_end then return true; end if;
    elsif v_min >= v_start then
      return true;
    end if;
  end loop;
  if coalesce(public.hours_exception_on(p_exceptions, v_date) ->> 'kind', '') <> 'closed' then
    for v_iv in select jsonb_array_elements(public.hours_intervals_on(p_hours, p_exceptions, v_date - 1)) loop
      v_start := split_part(v_iv ->> 0, ':', 1)::int * 60 + split_part(v_iv ->> 0, ':', 2)::int;
      v_end := split_part(v_iv ->> 1, ':', 1)::int * 60 + split_part(v_iv ->> 1, ':', 2)::int;
      if v_end <= v_start and v_end > 0 and v_min < v_end then return true; end if;
    end loop;
  end if;
  return false;
end $$;

create or replace function public.public_exceptions(p_list jsonb, p_tz text) returns jsonb
language sql stable set search_path = public as $$
  select coalesce(
    (select jsonb_agg(
              jsonb_build_object('id', e -> 'id', 'date', e -> 'date', 'kind', e -> 'kind', 'intervals', coalesce(e -> 'intervals', '[]'::jsonb), 'note', e -> 'note')
              || case when e ->> 'kind' = 'break' then jsonb_build_object('until', e -> 'until', 'weekdays', e -> 'weekdays') else '{}'::jsonb end
              order by e ->> 'date')
       from jsonb_array_elements(case when jsonb_typeof(p_list) = 'array' then p_list else '[]'::jsonb end) e
      where e ->> 'date' ~ '^\d{4}-\d{2}-\d{2}$'
        and public.exception_last_day(e) >= public.shop_day(now(), p_tz) - 1),
    '[]'::jsonb);
$$;

drop function public.exception_normalize(date, text, jsonb, text, date);
create function public.exception_normalize(p_date date, p_kind text, p_intervals jsonb, p_note text, p_today date, p_until date default null, p_weekdays jsonb default null) returns jsonb
language plpgsql immutable set search_path = public as $$
declare
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_ints jsonb := '[]';
  v_days jsonb := null;
  v_prev_end text;
  r record;
  n integer;
begin
  if p_date is null then raise exception 'invalid_date'; end if;
  if p_date < p_today then raise exception 'date_in_past'; end if;
  if p_date > p_today + 730 then raise exception 'date_too_far'; end if;
  if p_kind is null or p_kind not in ('closed','special','break') then raise exception 'invalid_kind'; end if;
  if v_note is not null and (char_length(v_note) > 120 or v_note ~ '[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]') then raise exception 'invalid_note'; end if;

  if p_kind = 'break' then
    if p_until is not null then
      if p_until < p_date then raise exception 'until_before_date'; end if;
      if p_until > p_today + 730 then raise exception 'date_too_far'; end if;
    end if;
    if p_weekdays is not null then
      if jsonb_typeof(p_weekdays) <> 'array' or jsonb_array_length(p_weekdays) = 0
         or exists (select 1 from jsonb_array_elements(p_weekdays) w where jsonb_typeof(w) <> 'string' or (w #>> '{}') not in ('mon','tue','wed','thu','fri','sat','sun')) then
        raise exception 'invalid_weekdays';
      end if;
      select jsonb_agg(d order by i) into v_days from unnest(array['mon','tue','wed','thu','fri','sat','sun']) with ordinality t(d, i) where p_weekdays ? d;
    end if;
  end if;

  if p_kind in ('special', 'break') then
    if p_intervals is null or jsonb_typeof(p_intervals) <> 'array' or jsonb_array_length(p_intervals) = 0 then raise exception 'intervals_required'; end if;
    n := jsonb_array_length(p_intervals);
    if n > 3 then raise exception 'too_many_intervals'; end if;
    for r in select e as iv from jsonb_array_elements(p_intervals) e loop
      if jsonb_typeof(r.iv) <> 'array' or jsonb_array_length(r.iv) <> 2
         or jsonb_typeof(r.iv -> 0) <> 'string' or jsonb_typeof(r.iv -> 1) <> 'string'
         or (r.iv ->> 0) !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or (r.iv ->> 1) !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then
        raise exception 'invalid_time';
      end if;
      if p_kind = 'break' and (r.iv ->> 1) <= (r.iv ->> 0) then raise exception 'break_order'; end if;
    end loop;
    for r in select e as iv from jsonb_array_elements(p_intervals) e order by e ->> 0 loop
      if v_prev_end is not null and (r.iv ->> 0) <= v_prev_end then raise exception 'intervals_overlap'; end if;
      v_prev_end := case when (r.iv ->> 1) > (r.iv ->> 0) then r.iv ->> 1 else '24:00' end;
      v_ints := v_ints || jsonb_build_array(r.iv);
    end loop;
  end if;

  return jsonb_build_object('date', p_date::text, 'kind', p_kind, 'intervals', v_ints, 'note', v_note)
    || case when p_kind = 'break' then jsonb_build_object('until', p_until::text, 'weekdays', v_days) else '{}'::jsonb end;
end $$;
revoke all on function public.exception_normalize(date, text, jsonb, text, date, date, jsonb) from public, anon;
grant execute on function public.exception_normalize(date, text, jsonb, text, date, date, jsonb) to authenticated, service_role;

drop function public.seller_save_exception(uuid, date, text, jsonb, text);
create function public.seller_save_exception(p_id uuid, p_date date, p_kind text, p_intervals jsonb default '[]', p_note text default null, p_until date default null, p_weekdays jsonb default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_tz text;
  v_today date;
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_list jsonb;
  v_item jsonb;
  v_known boolean;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select b.exceptions, b.timezone into v_list, v_tz from public.businesses b where b.id = v_biz for update;
  v_today := public.shop_day(now(), v_tz);
  v_item := public.exception_normalize(p_date, p_kind, p_intervals, p_note, v_today, p_until, p_weekdays) || jsonb_build_object('id', v_id);
  v_list := coalesce((select jsonb_agg(e order by e ->> 'date') from jsonb_array_elements(coalesce(v_list, '[]')) e where public.exception_last_day(e) >= v_today - 1), '[]');
  v_known := exists (select 1 from jsonb_array_elements(v_list) e where e ->> 'id' = v_id::text);
  if p_kind <> 'break' and exists (select 1 from jsonb_array_elements(v_list) e where e ->> 'date' = p_date::text and e ->> 'kind' <> 'break' and e ->> 'id' <> v_id::text) then raise exception 'date_taken'; end if;
  if not v_known and jsonb_array_length(v_list) >= 60 then raise exception 'limit_reached:exceptions' using errcode = 'P0001'; end if;
  v_list := (select jsonb_agg(s.x order by s.x ->> 'date') from (
    select e as x from jsonb_array_elements(v_list) e where e ->> 'id' <> v_id::text
    union all select v_item) s);
  update public.businesses b set exceptions = v_list where b.id = v_biz;
  perform public.write_audit(v_biz, case when v_known then 'exception_updated' else 'exception_added' end, 'business', v_biz::text, jsonb_build_object('date', p_date::text, 'kind', p_kind));
  return v_item;
end $$;

create or replace function public.seller_delete_exception(p_id uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_tz text;
  v_today date;
  v_list jsonb;
  v_found boolean;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select b.exceptions, b.timezone into v_list, v_tz from public.businesses b where b.id = v_biz for update;
  v_today := public.shop_day(now(), v_tz);
  v_found := exists (select 1 from jsonb_array_elements(coalesce(v_list, '[]')) e where e ->> 'id' = p_id::text);
  v_list := coalesce((select jsonb_agg(e order by e ->> 'date') from jsonb_array_elements(coalesce(v_list, '[]')) e
                      where e ->> 'id' <> p_id::text and public.exception_last_day(e) >= v_today - 1), '[]');
  update public.businesses b set exceptions = v_list where b.id = v_biz;
  if v_found then perform public.write_audit(v_biz, 'exception_deleted', 'business', v_biz::text, '{}'); end if;
  return v_found;
end $$;

revoke all on function public.seller_save_exception(uuid, date, text, jsonb, text, date, jsonb) from public, anon;
grant execute on function public.seller_save_exception(uuid, date, text, jsonb, text, date, jsonb) to authenticated, service_role;

$m_0089_break_exceptions$),
    ('0090_option_values', $m_0090_option_values$
-- 0090_option_values.sql
-- The open values dictionary (A18): typed material, colour, brand, finish and flavour shared by every shop.
--
--   * option_values            one row per value. `key` is the canonical form (normalize_value_key), so "Samsung", "SAMSUNG" and
--                              " samsung " are one row and one filter choice. kind: material | color | brand | finish | flavour.
--                              status: pending (typed by a seller, usable at once, shown as typed, waiting for review) | approved | merged
--                              (folded into another value; `merged_into` always points at a value that is not merged, never a chain).
--                              `tags` e.g. precious-metal; `hex` only for colours.
--   * item_option_value_uses   which items use which value, and where: slot 'brand' (items.brand), 'spec' (a row of items.specs or of a
--                              variant's specs) or 'axis' (the label of an option value in items.option_axes). This is what lets a
--                              rename or a merge find every item that uses a value and rewrite its text. Items with no rows here are
--                              untouched, so items with no dictionary value behave exactly as before.
--   * normalize_value_key(text)  the SQL twin of normalizeValueKey in shared/src/openValues.js (rules are written there; the db test runs
--                              one table of cases through both).
--   * seller_option_values(kind, query, limit)  type-ahead: "Mahog" -> Mahogany, Mahogany veneer; says whether Add "<typed>" is offered.
--   * seller_add_option_value(kind, label, hex)  usable at once; an existing value (same key, merged ones followed) is returned instead.
--   * seller_link_item_values(item, uses)        replaces the dictionary links of one of the seller's items.
--   * public_option_value_filter(kind)           the buyer's filter choices: one row per value, with how many live items use it.
--   * admin_option_values / admin_approve_option_value / admin_update_option_value / admin_rename_option_value /
--     admin_merge_option_value                   the review queue. Rename and merge rewrite the text on every item that uses the value.
-- No existing function or table is changed. seller_save_item is not touched: the app calls seller_link_item_values after a save.
-- TODO(contract:A01): once items store typed spec rows and option values with a valueId, point the rewrites at those and drop the text match.
-- Never edit this file once applied.

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. Canonical key
-- ---------------------------------------------------------------------------------------------------------------------

-- Same rules, same order as normalizeValueKey: NFKD, drop accents, NFC, lower case, drop apostrophes, "&" -> and, runs of spaces and
-- punctuation -> one space, trim. Letters outside a-z pass through.
create or replace function public.normalize_value_key(p text) returns text
language sql immutable parallel safe as
$$
  select btrim(regexp_replace(
    replace(
      regexp_replace(
        lower(normalize(regexp_replace(normalize(coalesce(p, ''), NFKD), '[̀-ͯ]', '', 'g'), NFC)),
        '[''‘’ʼ`´]', '', 'g'),
      '&', ' and '),
    '[[:space:]!"#$%()*+,./:;<=>?@\[\\\]^_{|}~‐-―…·• 　-]+', ' ', 'g'))
$$;

-- ---------------------------------------------------------------------------------------------------------------------
-- 2. Tables
-- ---------------------------------------------------------------------------------------------------------------------

create table if not exists public.option_values (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('material', 'color', 'brand', 'finish', 'flavour')),
  key text not null check (key <> '' and key = public.normalize_value_key(key)),
  label text not null check (btrim(label) <> '' and char_length(label) <= 60),
  status text not null default 'pending' check (status in ('pending', 'approved', 'merged')),
  tags text[] not null default '{}' check (cardinality(tags) <= 8),
  hex text check (hex ~ '^#[0-9a-f]{6}$'),
  merged_into uuid references public.option_values (id),
  created_by_business uuid references public.businesses (id) on delete set null,
  reviewed_by uuid,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check ((status = 'merged') = (merged_into is not null)),
  check (merged_into is distinct from id),
  check (hex is null or kind = 'color')
);

-- One live value per kind and key. A merged row keeps its key so a seller who types the old spelling lands on the target.
create unique index if not exists option_values_live_key on public.option_values (kind, key) where status <> 'merged';
create index if not exists option_values_key_lookup on public.option_values (kind, key text_pattern_ops);
create index if not exists option_values_queue on public.option_values (status, created_at);
create index if not exists option_values_merged_into on public.option_values (merged_into) where merged_into is not null;

create table if not exists public.item_option_value_uses (
  item_id uuid not null references public.items (id) on delete cascade,
  slot text not null check (slot in ('brand', 'spec', 'axis')),
  value_id uuid not null references public.option_values (id),
  primary key (item_id, slot, value_id)
);
create index if not exists item_option_value_uses_value on public.item_option_value_uses (value_id);

drop trigger if exists t_option_values_touch on public.option_values;
create trigger t_option_values_touch before update on public.option_values for each row execute function public.touch_updated_at();

-- Everything goes through the functions below (security definer). Browser roles read and write nothing directly.
alter table public.option_values enable row level security;
alter table public.item_option_value_uses enable row level security;
revoke all on public.option_values, public.item_option_value_uses from public, anon, authenticated;
grant all on public.option_values, public.item_option_value_uses to service_role;
drop policy if exists "admin read option_values" on public.option_values;
create policy "admin read option_values" on public.option_values for select to authenticated using (public.is_admin());
grant select on public.option_values to authenticated;

-- ---------------------------------------------------------------------------------------------------------------------
-- 3. Helpers (not callable from the browser)
-- ---------------------------------------------------------------------------------------------------------------------

-- The live value for a typed label: the value with that key, or the target of a merged one. null when there is none.
create or replace function public.option_value_resolve(p_kind text, p_key text) returns public.option_values
language plpgsql stable security definer set search_path = public as $$
declare
  v public.option_values;
begin
  select * into v from public.option_values where kind = p_kind and key = p_key and status <> 'merged';
  if found then return v; end if;
  select t.* into v from public.option_values m join public.option_values t on t.id = m.merged_into
   where m.kind = p_kind and m.key = p_key and m.status = 'merged' order by m.updated_at desc limit 1;
  if found then return v; end if;
  return null;
end $$;

create or replace function public.option_value_json(v public.option_values) returns jsonb
language sql immutable as
$$ select jsonb_build_object('id', v.id, 'kind', v.kind, 'label', v.label, 'key', v.key, 'status', v.status, 'hex', v.hex, 'tags', to_jsonb(v.tags)) $$;

-- Rewrites, on one item, every spec row whose value has key p_old_key to p_label. Returns true when something changed.
create or replace function public.option_value_rewrite_specs(p jsonb, p_old_key text, p_label text) returns jsonb
language sql immutable as
$$
  select coalesce(jsonb_agg(case when public.normalize_value_key(e ->> 'value') = p_old_key then e || jsonb_build_object('value', p_label) else e end order by n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as x(e, n)
$$;

-- Same for the label of every option value in the axes; the value id (used in variant combinations) is never changed.
create or replace function public.option_value_rewrite_axes(p jsonb, p_old_key text, p_label text, p_hex text) returns jsonb
language sql immutable as
$$
  select coalesce(jsonb_agg(a.e || jsonb_build_object('values', (
    select coalesce(jsonb_agg(case when public.normalize_value_key(v.e ->> 'label') = p_old_key
                                   then (v.e || jsonb_build_object('label', p_label)) || case when p_hex is not null and v.e ? 'color' then jsonb_build_object('color', p_hex) else '{}'::jsonb end
                                   else v.e end order by v.n), '[]'::jsonb)
    from jsonb_array_elements(a.e -> 'values') with ordinality as v(e, n))) order by a.n), '[]'::jsonb)
  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) with ordinality as a(e, n)
$$;

-- Makes every item that uses value p_from show p_to's label and (when p_from == p_to, a rename) keeps the links. p_old_key is the key the
-- items' text currently has. Links are moved to p_to first, dropping the ones an item already has on p_to.
create or replace function public.option_value_apply_to_items(p_from uuid, p_to uuid, p_old_key text) returns integer
language plpgsql security definer set search_path = public as $$
declare
  t public.option_values;
  v_n integer := 0;
  r record;
begin
  select * into t from public.option_values where id = p_to;
  if p_from <> p_to then
    delete from public.item_option_value_uses u where u.value_id = p_from
      and exists (select 1 from public.item_option_value_uses o where o.item_id = u.item_id and o.slot = u.slot and o.value_id = p_to);
    update public.item_option_value_uses set value_id = p_to where value_id = p_from;
  end if;
  for r in select distinct item_id from public.item_option_value_uses where value_id = p_to loop
    if exists (select 1 from public.item_option_value_uses where item_id = r.item_id and value_id = p_to and slot = 'brand') then
      update public.items set brand = t.label where id = r.item_id and brand is distinct from t.label and public.normalize_value_key(brand) = p_old_key;
    end if;
    if exists (select 1 from public.item_option_value_uses where item_id = r.item_id and value_id = p_to and slot = 'spec') then
      update public.items set specs = public.option_value_rewrite_specs(specs, p_old_key, t.label)
       where id = r.item_id and specs is distinct from public.option_value_rewrite_specs(specs, p_old_key, t.label);
      update public.item_variants set specs = public.option_value_rewrite_specs(specs, p_old_key, t.label)
       where item_id = r.item_id and specs is distinct from public.option_value_rewrite_specs(specs, p_old_key, t.label);
    end if;
    if exists (select 1 from public.item_option_value_uses where item_id = r.item_id and value_id = p_to and slot = 'axis') then
      update public.items set option_axes = public.option_value_rewrite_axes(option_axes, p_old_key, t.label, t.hex)
       where id = r.item_id and option_axes is distinct from public.option_value_rewrite_axes(option_axes, p_old_key, t.label, t.hex);
    end if;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

revoke all on function public.option_value_resolve(text, text), public.option_value_json(public.option_values),
  public.option_value_rewrite_specs(jsonb, text, text), public.option_value_rewrite_axes(jsonb, text, text, text),
  public.option_value_apply_to_items(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.option_value_resolve(text, text), public.option_value_json(public.option_values),
  public.option_value_rewrite_specs(jsonb, text, text), public.option_value_rewrite_axes(jsonb, text, text, text),
  public.option_value_apply_to_items(uuid, uuid, text) to service_role;
revoke all on function public.normalize_value_key(text) from public;
grant execute on function public.normalize_value_key(text) to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 4. Seller functions
-- ---------------------------------------------------------------------------------------------------------------------

-- Type-ahead. { kind, query, matches: [{id,kind,label,key,status,hex,tags,uses}], canAdd, addLabel }.
-- "Mahog" -> Mahogany, Mahogany veneer. An empty query lists the most used values. Merged values are never listed: a merged spelling
-- that is typed in full answers with its target. canAdd is true when the query is a valid value and no value has exactly that key.
create or replace function public.seller_option_values(p_kind text, p_query text default '', p_limit integer default 8) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_label text := left(regexp_replace(btrim(coalesce(p_query, '')), '[[:space:]]+', ' ', 'g'), 200);
  v_key text := public.normalize_value_key(v_label);
  v_limit integer := least(greatest(coalesce(p_limit, 8), 1), 20);
  v_exact public.option_values;
  v_matches jsonb;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if p_kind is null or p_kind <> all (array['material', 'color', 'brand', 'finish', 'flavour']) then raise exception 'invalid_kind' using errcode = 'P0001'; end if;
  v_exact := case when v_key = '' then null else public.option_value_resolve(p_kind, v_key) end;
  select coalesce(jsonb_agg(m.j order by m.rank, m.approved desc, m.uses desc, m.label), '[]'::jsonb) into v_matches
  from (
    select public.option_value_json(v) || jsonb_build_object('uses', (select count(*) from public.item_option_value_uses u where u.value_id = v.id)) as j,
           v.label,
           (select count(*) from public.item_option_value_uses u where u.value_id = v.id) as uses,
           case when v.key = v_key then 0 when v.key like v_key || '%' then 1 else 2 end as rank,
           (v.status = 'approved') as approved
    from public.option_values v
    where v.kind = p_kind and v.status <> 'merged'
      and (v_key = '' or v.key like v_key || '%' or v.key like '% ' || v_key || '%')
    order by 4, 5 desc, 3 desc, v.label
    limit v_limit
  ) m;
  -- A merged spelling typed in full is answered with its target, listed first.
  if v_exact.id is not null and not exists (select 1 from jsonb_array_elements(v_matches) x where x ->> 'id' = v_exact.id::text) then
    v_matches := jsonb_build_array(public.option_value_json(v_exact) || jsonb_build_object('uses', (select count(*) from public.item_option_value_uses u where u.value_id = v_exact.id))) || v_matches;
  end if;
  return jsonb_build_object('kind', p_kind, 'query', v_label, 'matches', v_matches,
    'canAdd', v_key <> '' and char_length(v_label) <= 60 and v_exact.id is null,
    'addLabel', case when v_key <> '' and char_length(v_label) <= 60 and v_exact.id is null then v_label end);
end $$;

-- Adds a value so it can be used straight away. If the key is already known (a merged spelling follows its target) that value is
-- returned and nothing is created. A new value is pending, keeps the seller's spelling, and shows up in the admin queue.
-- Returns { created, value }. A shade (hex) is accepted for colours only and is stored lower case.
create or replace function public.seller_add_option_value(p_kind text, p_label text, p_hex text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_label text := regexp_replace(btrim(coalesce(p_label, '')), '[[:space:]]+', ' ', 'g');
  v_key text := public.normalize_value_key(v_label);
  v_hex text := nullif(lower(btrim(coalesce(p_hex, ''))), '');
  v public.option_values;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if p_kind is null or p_kind <> all (array['material', 'color', 'brand', 'finish', 'flavour']) then raise exception 'invalid_kind' using errcode = 'P0001'; end if;
  if v_key = '' then raise exception 'invalid_label' using errcode = 'P0001'; end if;
  if char_length(v_label) > 60 then raise exception 'label_too_long' using errcode = 'P0001'; end if;
  if v_hex is not null and (p_kind <> 'color' or v_hex !~ '^#[0-9a-f]{6}$') then raise exception 'invalid_hex' using errcode = 'P0001'; end if;
  v := public.option_value_resolve(p_kind, v_key);
  if v.id is not null then
    return jsonb_build_object('created', false, 'value', public.option_value_json(v));
  end if;
  -- A shop cannot flood the review queue.
  if (select count(*) from public.option_values where created_by_business = v_biz and status = 'pending') >= 50 then
    raise exception 'too_many_pending' using errcode = 'P0001';
  end if;
  begin
    insert into public.option_values (kind, key, label, status, hex, created_by_business) values (p_kind, v_key, v_label, 'pending', v_hex, v_biz) returning * into v;
  exception when unique_violation then   -- two sellers typed it at the same moment
    v := public.option_value_resolve(p_kind, v_key);
    return jsonb_build_object('created', false, 'value', public.option_value_json(v));
  end;
  return jsonb_build_object('created', true, 'value', public.option_value_json(v));
end $$;

-- Replaces the dictionary links of one of the seller's items. p_uses: [{ "slot": "brand"|"spec"|"axis", "valueId": uuid }].
-- Only values that are not merged can be linked (a merged id is followed to its target). The item text itself is saved by seller_save_item.
create or replace function public.seller_link_item_values(p_item uuid, p_uses jsonb) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  e jsonb;
  v public.option_values;
  v_n integer := 0;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items where id = p_item and business_id = v_biz and not removed_by_admin) then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  if p_uses is null or jsonb_typeof(p_uses) <> 'array' or jsonb_array_length(p_uses) > 120 then raise exception 'invalid_uses' using errcode = 'P0001'; end if;
  delete from public.item_option_value_uses where item_id = p_item;
  for e in select jsonb_array_elements(p_uses) loop
    if jsonb_typeof(e) <> 'object' or e ->> 'slot' is null or (e ->> 'slot') <> all (array['brand', 'spec', 'axis'])
       or not public.option_uuid_ok(e -> 'valueId') then raise exception 'invalid_uses' using errcode = 'P0001'; end if;
    select * into v from public.option_values where id = (e ->> 'valueId')::uuid;
    if not found then raise exception 'value_not_found' using errcode = 'P0001'; end if;
    if v.status = 'merged' then select * into v from public.option_values where id = v.merged_into; end if;
    insert into public.item_option_value_uses (item_id, slot, value_id) values (p_item, e ->> 'slot', v.id) on conflict do nothing;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- ---------------------------------------------------------------------------------------------------------------------
-- 5. Public filter choices
-- ---------------------------------------------------------------------------------------------------------------------

-- One row per value for a filter list: "Samsung", "SAMSUNG" and "samsung" are one value, so one choice. Counts items that are public now.
create or replace function public.public_option_value_filter(p_kind text) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'label', x.label, 'key', x.key, 'hex', x.hex, 'count', x.n) order by x.n desc, x.label), '[]'::jsonb)
  from (
    select v.id, v.label, v.key, v.hex, count(distinct u.item_id) as n
    from public.option_values v
    join public.item_option_value_uses u on u.value_id = v.id
    join public.public_items pi on pi.id = u.item_id
    where v.kind = p_kind and v.status <> 'merged'
    group by v.id
  ) x
$$;

-- ---------------------------------------------------------------------------------------------------------------------
-- 6. Admin review
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.admin_option_values(p_status text default null, p_kind text default null, p_query text default '', p_limit integer default 50, p_offset integer default 0) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_key text := public.normalize_value_key(p_query);
begin
  if not public.has_role(array['reviewer']) then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'total', (select count(*) from public.option_values v where (p_status is null or v.status = p_status) and (p_kind is null or v.kind = p_kind) and (v_key = '' or v.key like '%' || v_key || '%')),
    'values', coalesce((
      select jsonb_agg(public.option_value_json(v) || jsonb_build_object(
        'uses', (select count(distinct u.item_id) from public.item_option_value_uses u where u.value_id = v.id),
        'mergedInto', v.merged_into, 'createdByBusiness', v.created_by_business, 'createdAt', v.created_at, 'reviewedAt', v.reviewed_at) order by v.created_at desc, v.label)
      from (select * from public.option_values w where (p_status is null or w.status = p_status) and (p_kind is null or w.kind = p_kind) and (v_key = '' or w.key like '%' || v_key || '%')
            order by w.created_at desc, w.label limit least(greatest(coalesce(p_limit, 50), 1), 200) offset greatest(coalesce(p_offset, 0), 0)) v), '[]'::jsonb));
end $$;

-- Change tags and/or the shade of a value without touching its status. p_fields: { tags: [text], hex: "#rrggbb" | null }; absent keys stay.
create or replace function public.admin_update_option_value(p_id uuid, p_fields jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v public.option_values;
  v_tags text[];
  v_hex text;
begin
  if not public.has_role(array['reviewer']) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into v from public.option_values where id = p_id for update;
  if not found then raise exception 'value_not_found' using errcode = 'P0001'; end if;
  if v.status = 'merged' then raise exception 'value_merged' using errcode = 'P0001'; end if;
  v_tags := v.tags;
  v_hex := v.hex;
  if f ? 'tags' then
    if jsonb_typeof(f -> 'tags') <> 'array' or jsonb_array_length(f -> 'tags') > 8 then raise exception 'invalid_tags' using errcode = 'P0001'; end if;
    select coalesce(array_agg(distinct t order by t), '{}') into v_tags from (
      select regexp_replace(public.normalize_value_key(x), ' ', '-', 'g') as t from jsonb_array_elements_text(f -> 'tags') x) q;
    if exists (select 1 from unnest(v_tags) t where t = '' or char_length(t) > 30) then raise exception 'invalid_tags' using errcode = 'P0001'; end if;
  end if;
  if f ? 'hex' then
    v_hex := nullif(lower(btrim(coalesce(f ->> 'hex', ''))), '');
    if v_hex is not null and (v.kind <> 'color' or v_hex !~ '^#[0-9a-f]{6}$') then raise exception 'invalid_hex' using errcode = 'P0001'; end if;
  end if;
  update public.option_values set tags = v_tags, hex = v_hex where id = p_id returning * into v;
  perform public.admin_audit_action('option_value.update', 'option_value', p_id::text, null, jsonb_build_object('tags', to_jsonb(v.tags), 'hex', v.hex), null, null);
  return public.option_value_json(v);
end $$;

-- Approve a pending value (optionally setting tags and shade in the same step). Approving an approved value is a no-op.
create or replace function public.admin_approve_option_value(p_id uuid, p_fields jsonb default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v public.option_values;
  v_old_status text;
begin
  if not public.has_role(array['reviewer']) then raise exception 'forbidden' using errcode = '42501'; end if;
  select status into v_old_status from public.option_values where id = p_id for update;
  if not found then raise exception 'value_not_found' using errcode = 'P0001'; end if;
  if v_old_status = 'merged' then raise exception 'value_merged' using errcode = 'P0001'; end if;
  if p_fields is not null then perform public.admin_update_option_value(p_id, p_fields); end if;
  update public.option_values set status = 'approved', reviewed_by = auth.uid(), reviewed_at = now() where id = p_id returning * into v;
  perform public.admin_audit_action('option_value.approve', 'option_value', p_id::text, jsonb_build_object('status', v_old_status), jsonb_build_object('status', v.status, 'label', v.label), null, null);
  return public.option_value_json(v);
end $$;

-- Rename: the new spelling is shown on every item that uses the value. Refused when another live value already has that key (merge instead).
create or replace function public.admin_rename_option_value(p_id uuid, p_label text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_label text := regexp_replace(btrim(coalesce(p_label, '')), '[[:space:]]+', ' ', 'g');
  v_key text := public.normalize_value_key(v_label);
  v_old public.option_values;
  v public.option_values;
  v_items integer;
begin
  if not public.has_role(array['reviewer']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if v_key = '' then raise exception 'invalid_label' using errcode = 'P0001'; end if;
  if char_length(v_label) > 60 then raise exception 'label_too_long' using errcode = 'P0001'; end if;
  select * into v_old from public.option_values where id = p_id for update;
  if not found then raise exception 'value_not_found' using errcode = 'P0001'; end if;
  if v_old.status = 'merged' then raise exception 'value_merged' using errcode = 'P0001'; end if;
  if exists (select 1 from public.option_values where kind = v_old.kind and key = v_key and status <> 'merged' and id <> p_id) then
    raise exception 'value_exists' using errcode = 'P0001';
  end if;
  update public.option_values set label = v_label, key = v_key where id = p_id returning * into v;
  v_items := public.option_value_apply_to_items(p_id, p_id, v_old.key);
  perform public.admin_audit_action('option_value.rename', 'option_value', p_id::text, jsonb_build_object('label', v_old.label), jsonb_build_object('label', v.label, 'items', v_items), null, null);
  return public.option_value_json(v) || jsonb_build_object('itemsUpdated', v_items);
end $$;

-- Merge p_from into p_into (same kind). Every item that used p_from now uses p_into and shows its label; p_from keeps its key, so the old
-- spelling still resolves to p_into. Tags are combined and a missing shade is copied. If p_into was itself merged, its target is used.
create or replace function public.admin_merge_option_value(p_from uuid, p_into uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_from public.option_values;
  v_into public.option_values;
  v_items integer;
begin
  if not public.has_role(array['reviewer']) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into v_from from public.option_values where id = p_from for update;
  if not found then raise exception 'value_not_found' using errcode = 'P0001'; end if;
  select * into v_into from public.option_values where id = p_into for update;
  if not found then raise exception 'value_not_found' using errcode = 'P0001'; end if;
  if v_into.status = 'merged' then select * into v_into from public.option_values where id = v_into.merged_into for update; end if;
  if v_from.status = 'merged' then raise exception 'value_merged' using errcode = 'P0001'; end if;
  if v_from.id = v_into.id then raise exception 'same_value' using errcode = 'P0001'; end if;
  if v_from.kind <> v_into.kind then raise exception 'kind_mismatch' using errcode = 'P0001'; end if;
  update public.option_values set status = 'merged', merged_into = v_into.id, reviewed_by = auth.uid(), reviewed_at = now() where id = v_from.id;
  update public.option_values set merged_into = v_into.id where merged_into = v_from.id;     -- never leave a chain
  update public.option_values set
      tags = (select coalesce(array_agg(distinct t order by t), '{}') from unnest(v_into.tags || v_from.tags) t),
      hex = coalesce(v_into.hex, v_from.hex)
    where id = v_into.id returning * into v_into;
  v_items := public.option_value_apply_to_items(v_from.id, v_into.id, v_from.key);
  perform public.admin_audit_action('option_value.merge', 'option_value', v_from.id::text, jsonb_build_object('label', v_from.label),
    jsonb_build_object('into', v_into.id, 'label', v_into.label, 'items', v_items), null, null);
  return public.option_value_json(v_into) || jsonb_build_object('itemsUpdated', v_items, 'mergedFrom', v_from.id);
end $$;

revoke all on function public.seller_option_values(text, text, integer), public.seller_add_option_value(text, text, text), public.seller_link_item_values(uuid, jsonb),
  public.public_option_value_filter(text), public.admin_option_values(text, text, text, integer, integer), public.admin_approve_option_value(uuid, jsonb),
  public.admin_update_option_value(uuid, jsonb), public.admin_rename_option_value(uuid, text), public.admin_merge_option_value(uuid, uuid) from public, anon;
grant execute on function public.seller_option_values(text, text, integer), public.seller_add_option_value(text, text, text), public.seller_link_item_values(uuid, jsonb),
  public.admin_option_values(text, text, text, integer, integer), public.admin_approve_option_value(uuid, jsonb), public.admin_update_option_value(uuid, jsonb),
  public.admin_rename_option_value(uuid, text), public.admin_merge_option_value(uuid, uuid) to authenticated, service_role;
grant execute on function public.public_option_value_filter(text) to anon, authenticated, service_role;

$m_0090_option_values$),
    ('0091_departments_restrictions', $m_0091_departments_restrictions$
-- 0091 (A08): departments as data, selling restrictions on product types, missing-type requests.
--
--   1. departments            Clothing, Shoes, Bags ... one row each (data, not code). Types point at one.
--   2. product_types          contract-shaped table (id, slug, name, kind, department_id, category_ids, restricted_to, quantity_mode, axes, spec_rows,
--                             size_chart_id). Seeded here ONLY with the five types this migration needs to be testable (the regulated three
--                             plus fragrance and stationery). TODO(contract:A06): A06 owns the full type list and must add the remaining types with
--                             `insert ... on conflict (id) do update`; every column below is created `if not exists` so A06 can add the rest.
--   3. restricted_to          shop CATEGORY ids (businesses.category_id). Empty = any shop may sell the type. A restriction naming a category that
--                             does not exist simply means nobody can sell the type (it fails closed).
--   4. items.product_type_id  nullable; null is "Other goods". Items that have no type are untouched.
--   5. enforcement            shop_can_sell_type() + a trigger on items (the guarantee, whoever writes the row) + seller_save_item, which now
--                             accepts `productTypeId` and checks it first so the seller gets a named error.
--                             seller_save_item(uuid, jsonb) is WRAPPED: the 0086 function is renamed seller_save_item_base (no direct grant) and
--                             called by the new wrapper, so none of its 170 lines is copied. seller_check_item (0088) calls seller_save_item and so
--                             checks types too, with nothing written.
--   6. type_requests          a seller who cannot find a type asks for one (seller_request_type) and still adds the item as Other goods.
--                             Admin side: admin_type_requests_list, admin_resolve_type_request.
--   7. seller_product_types   departments + the types THIS shop may sell. TODO(contract:A06): A06 may replace the body; keep the shape
--                             { departments: [{id, name}], types: [ProductType] } and keep leaving out types the shop may not sell.
--
-- Nothing already applied is edited. Old items (no type) behave exactly as before.

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. Departments
-- ---------------------------------------------------------------------------------------------------------------------

create table if not exists public.departments (
  id text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(id) <= 40),
  name text not null check (char_length(btrim(name)) between 2 and 60),
  sort integer not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
alter table public.departments enable row level security;
drop policy if exists "departments are public" on public.departments;
create policy "departments are public" on public.departments for select to anon, authenticated using (active);
grant select on public.departments to anon, authenticated;
grant all on public.departments to service_role;

insert into public.departments (id, name, sort) values
  ('clothing',            'Clothing',                  10),
  ('shoes',               'Shoes',                     20),
  ('bags',                'Bags',                      30),
  ('jewellery',           'Jewellery',                 40),
  ('fragrance',           'Fragrance',                 50),
  ('phones',              'Phones',                    60),
  ('computers',           'Computers',                 70),
  ('cables-power',        'Cables and power',          80),
  ('lighting',            'Lighting',                  90),
  ('batteries',           'Batteries',                100),
  ('printers-ink',        'Printers and ink',         110),
  ('printing-services',   'Printing services',        120),
  ('stationery',          'Stationery',               130),
  -- the rest of the live shop categories (client/src/data/categories.js groups), so no live category has nowhere to sell
  ('water-energy',        'Water and energy',         200),
  ('food-drink',          'Food and drink',           210),
  ('medicine-health',     'Medicine and health',      220),
  ('eyewear',             'Eyewear',                  230),
  ('beauty-personal-care','Beauty and personal care', 240),
  ('fitness',             'Fitness',                  250),
  ('farm-inputs',         'Farm inputs and vet',      260),
  ('electronics',         'Electronics and appliances',270),
  ('hardware-building',   'Hardware and building',    280),
  ('plumbing-electrical', 'Plumbing and electrical',  290),
  ('furniture',           'Furniture',                300),
  ('home-kitchen',        'Home and kitchen',         310),
  ('cleaning-laundry',    'Cleaning and laundry',     320),
  ('auto-parts',          'Auto parts and garage',    330),
  ('education',           'Education and childcare',  340),
  ('photography-events',  'Photography and events',   350)
on conflict (id) do nothing;

-- ---------------------------------------------------------------------------------------------------------------------
-- 2 + 3. Product types (contract-shaped) and restricted_to
-- ---------------------------------------------------------------------------------------------------------------------

create table if not exists public.product_types (id text primary key);
alter table public.product_types add column if not exists slug text;
alter table public.product_types add column if not exists name text;
alter table public.product_types add column if not exists kind text not null default 'good';
alter table public.product_types add column if not exists department_id text references public.departments (id);
alter table public.product_types add column if not exists category_ids text[] not null default '{}';
alter table public.product_types add column if not exists restricted_to text[] not null default '{}';
alter table public.product_types add column if not exists quantity_mode text not null default 'units';
alter table public.product_types add column if not exists axes jsonb not null default '[]'::jsonb;
alter table public.product_types add column if not exists spec_rows jsonb not null default '[]'::jsonb;
alter table public.product_types add column if not exists size_chart_id uuid;
alter table public.product_types add column if not exists active boolean not null default true;
alter table public.product_types add column if not exists created_at timestamptz not null default now();

alter table public.product_types drop constraint if exists product_types_kind_ok;
alter table public.product_types add constraint product_types_kind_ok check (kind in ('good', 'service', 'package'));
alter table public.product_types drop constraint if exists product_types_quantity_mode_ok;
alter table public.product_types add constraint product_types_quantity_mode_ok check (quantity_mode in ('units', 'measure', 'none'));
alter table public.product_types drop constraint if exists product_types_restricted_ok;
-- no empty strings, no nulls inside the list
alter table public.product_types add constraint product_types_restricted_ok check (array_position(restricted_to, null) is null and array_position(restricted_to, '') is null);
alter table public.product_types drop constraint if exists product_types_axes_max;
alter table public.product_types add constraint product_types_axes_max check (jsonb_typeof(axes) = 'array' and jsonb_array_length(axes) <= 3);
alter table public.product_types drop constraint if exists product_types_spec_rows_shape;
alter table public.product_types add constraint product_types_spec_rows_shape check (jsonb_typeof(spec_rows) = 'array');
create unique index if not exists product_types_slug_uq on public.product_types (slug) where slug is not null;

alter table public.product_types enable row level security;
drop policy if exists "product types are public" on public.product_types;
create policy "product types are public" on public.product_types for select to anon, authenticated using (active);
grant select on public.product_types to anon, authenticated;
grant all on public.product_types to service_role;

-- Seed. TODO(contract:A06): the full list is A06's. These five make restrictions testable and match shared/src/types/restrictions.js.
insert into public.product_types (id, slug, name, kind, department_id, category_ids, restricted_to, quantity_mode) values
  ('prescription-medicine', 'prescription-medicine', 'Prescription medicine', 'good', 'medicine-health', '{chemist}',  '{chemist}', 'units'),
  ('vet-medicine',          'vet-medicine',          'Veterinary medicine',   'good', 'farm-inputs',     '{agrovet}',  '{agrovet}', 'units'),
  ('agrochemicals',         'agrochemicals',         'Agrochemicals',         'good', 'farm-inputs',     '{agrovet}',  '{agrovet}', 'units'),
  ('fragrance',             'fragrance',             'Fragrance',             'good', 'fragrance',       '{salon-beauty,fashion-boutiques,tailor-boutique,supermarket-minimart}', '{}', 'units'),
  ('stationery',            'stationery',            'Stationery',            'good', 'stationery',      '{printing-stationery,electronics-computers,supermarket-minimart}',      '{}', 'units')
on conflict (id) do nothing;

-- ---------------------------------------------------------------------------------------------------------------------
-- 4 + 5. items.product_type_id and enforcement
-- ---------------------------------------------------------------------------------------------------------------------

alter table public.items add column if not exists product_type_id text references public.product_types (id);
create index if not exists items_product_type_idx on public.items (product_type_id) where product_type_id is not null;

-- May this shop sell this type? Unknown type, unknown shop, inactive type: no. Empty restricted_to: any shop.
create or replace function public.shop_can_sell_type(p_business uuid, p_type text) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select cardinality(t.restricted_to) = 0 or b.category_id = any (t.restricted_to)
      from public.product_types t, public.businesses b
     where t.id = p_type and t.active and b.id = p_business), false)
$$;
revoke all on function public.shop_can_sell_type(uuid, text) from public, anon;
grant execute on function public.shop_can_sell_type(uuid, text) to authenticated, service_role;

-- The guarantee: whichever function (or import, or admin tool) writes the row, a restricted type cannot be put on a shop that may not sell it.
-- Fires only when the type is set or changed, so editing an existing item never trips it.
create or replace function public.items_product_type_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.product_type_id is null then return new; end if;
  if tg_op = 'UPDATE' and new.product_type_id is not distinct from old.product_type_id then return new; end if;
  if not exists (select 1 from public.product_types t where t.id = new.product_type_id and t.active) then
    raise exception 'unknown_product_type' using errcode = 'P0001';
  end if;
  if not public.shop_can_sell_type(new.business_id, new.product_type_id) then
    raise exception 'type_not_allowed' using errcode = 'P0001';
  end if;
  return new;
end $$;
drop trigger if exists items_product_type_guard on public.items;
create trigger items_product_type_guard before insert or update of product_type_id on public.items
  for each row execute function public.items_product_type_guard();

-- Wrap seller_save_item. The 0086 text becomes seller_save_item_base (callable only through the wrapper).
do $$ begin
  if to_regprocedure('public.seller_save_item_base(uuid, jsonb)') is null then
    alter function public.seller_save_item(uuid, jsonb) rename to seller_save_item_base;
  end if;
end $$;
revoke all on function public.seller_save_item_base(uuid, jsonb) from public, anon, authenticated;
grant execute on function public.seller_save_item_base(uuid, jsonb) to service_role;

create or replace function public.seller_save_item(p_id uuid, p_fields jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_biz uuid := public.my_business_id();
  v_has boolean := f ? 'productTypeId';
  v_type text;
  v_id uuid;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  -- productTypeId: absent = leave the item's type alone; null = Other goods; text = a type this shop may sell.
  if v_has then
    if jsonb_typeof(f -> 'productTypeId') not in ('string', 'null') then raise exception 'invalid_product_type' using errcode = 'P0001'; end if;
    v_type := nullif(btrim(coalesce(f ->> 'productTypeId', '')), '');
    if v_type is not null then
      if not exists (select 1 from public.product_types t where t.id = v_type and t.active) then
        raise exception 'unknown_product_type' using errcode = 'P0001';
      end if;
      if not public.shop_can_sell_type(v_biz, v_type) then raise exception 'type_not_allowed' using errcode = 'P0001'; end if;
    end if;
  end if;

  v_id := public.seller_save_item_base(p_id, f - 'productTypeId');

  if v_has then
    update public.items set product_type_id = v_type where id = v_id and product_type_id is distinct from v_type;   -- the trigger checks again
  end if;
  return v_id;
end $$;
revoke all on function public.seller_save_item(uuid, jsonb) from public, anon;
grant execute on function public.seller_save_item(uuid, jsonb) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 6. Missing-type requests
-- ---------------------------------------------------------------------------------------------------------------------

create table if not exists public.type_requests (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  name text not null check (char_length(name) between 2 and 80),
  note text check (note is null or char_length(note) <= 500),
  status text not null default 'pending' check (status in ('pending', 'resolved', 'declined')),
  resolved_type_id text references public.product_types (id) on delete set null,
  admin_note text check (admin_note is null or char_length(admin_note) <= 500),
  resolved_by uuid,
  resolved_at timestamptz,
  created_at timestamptz not null default now(),
  check ((status = 'pending') = (resolved_at is null))
);
-- One open request per shop per name (case and spacing do not matter).
create unique index if not exists type_requests_open_name_uq on public.type_requests (business_id, lower(name)) where status = 'pending';
create index if not exists type_requests_status_idx on public.type_requests (status, created_at);

alter table public.type_requests enable row level security;
drop policy if exists "seller reads own type_requests" on public.type_requests;
create policy "seller reads own type_requests" on public.type_requests for select to authenticated using (business_id = public.my_business_id());
drop policy if exists "admin reads type_requests" on public.type_requests;
create policy "admin reads type_requests" on public.type_requests for select to authenticated using (public.is_admin());
revoke all on public.type_requests from public, anon;
grant select on public.type_requests to authenticated;
grant all on public.type_requests to service_role;

create or replace function public.seller_request_type(p_name text, p_note text default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
  v_name text := btrim(regexp_replace(coalesce(p_name, ''), '\s+', ' ', 'g'));
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_id uuid;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if char_length(v_name) not between 2 and 80 then raise exception 'invalid_name' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_note, '')) > 500 then raise exception 'invalid_note' using errcode = 'P0001'; end if;

  -- asking twice for the same thing returns the open request instead of a second row
  select r.id into v_id from public.type_requests r where r.business_id = v_biz and lower(r.name) = lower(v_name) and r.status = 'pending';
  if found then return v_id; end if;

  if (select count(*) from public.type_requests r where r.business_id = v_biz and r.status = 'pending') >= 20 then
    raise exception 'too_many_type_requests' using errcode = 'P0001';
  end if;
  begin
    insert into public.type_requests (business_id, name, note) values (v_biz, v_name, v_note) returning id into v_id;
  exception when unique_violation then
    select r.id into v_id from public.type_requests r where r.business_id = v_biz and lower(r.name) = lower(v_name) and r.status = 'pending';
    return v_id;
  end;
  perform public.write_audit(v_biz, 'type_request', 'type_request', v_id::text, jsonb_build_object('name', v_name));
  return v_id;
end $$;
revoke all on function public.seller_request_type(text, text) from public, anon;
grant execute on function public.seller_request_type(text, text) to authenticated, service_role;

create or replace function public.admin_type_requests_list(p_status text default 'pending') returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_status is not null and p_status not in ('pending', 'resolved', 'declined', 'all') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.created_at, x.id)
      from (select r.id, r.name, r.note, r.status, r.created_at, r.resolved_at, r.resolved_type_id as "resolvedTypeId", r.admin_note as "adminNote",
                   b.id as "businessId", b.name as "businessName", b.seller_id as "sellerId", b.category_id as "categoryId",
                   (select count(*) from public.type_requests o
                     where o.id <> r.id and o.status = 'pending' and lower(o.name) = lower(r.name)) as "alsoAskedBy"
              from public.type_requests r join public.businesses b on b.id = r.business_id
             where coalesce(p_status, 'pending') = 'all' or r.status = coalesce(p_status, 'pending')) x), '[]'::jsonb);
end $$;
revoke all on function public.admin_type_requests_list(text) from public, anon;
grant execute on function public.admin_type_requests_list(text) to authenticated, service_role;

-- outcome 'resolved' (optionally naming the type that now covers it) or 'declined' (a note is required so the seller learns why).
create or replace function public.admin_resolve_type_request(p_id uuid, p_outcome text, p_type_id text default null, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_old public.type_requests;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if not public.has_role(array['owner', 'reviewer']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_outcome is null or p_outcome not in ('resolved', 'declined') then raise exception 'invalid_outcome' using errcode = 'P0001'; end if;
  if char_length(coalesce(v_note, '')) > 500 then raise exception 'invalid_note' using errcode = 'P0001'; end if;
  if p_outcome = 'declined' and v_note is null then raise exception 'note_required' using errcode = 'P0001'; end if;
  if p_outcome = 'declined' and p_type_id is not null then raise exception 'invalid_outcome' using errcode = 'P0001'; end if;
  if p_type_id is not null and not exists (select 1 from public.product_types t where t.id = p_type_id and t.active) then
    raise exception 'unknown_product_type' using errcode = 'P0001';
  end if;
  select * into v_old from public.type_requests where id = p_id for update;
  if not found then raise exception 'type_request_not_found' using errcode = 'P0001'; end if;
  if v_old.status <> 'pending' then raise exception 'type_request_closed' using errcode = 'P0001'; end if;
  update public.type_requests set status = p_outcome, resolved_type_id = p_type_id, admin_note = v_note, resolved_by = auth.uid(), resolved_at = now() where id = p_id;
  perform public.admin_audit_action('type_request.' || p_outcome, 'type_request', p_id::text, jsonb_build_object('status', v_old.status, 'name', v_old.name),
    jsonb_build_object('status', p_outcome, 'typeId', p_type_id), v_note, v_old.business_id);
end $$;
revoke all on function public.admin_resolve_type_request(uuid, text, text, text) from public, anon;
grant execute on function public.admin_resolve_type_request(uuid, text, text, text) to authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 7. seller_product_types: departments and the types this shop may sell (restricted types the shop may not sell are left out)
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.seller_product_types() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_biz uuid := public.my_business_id();
begin
  perform public.assert_seller_active();   -- repo rule: every plpgsql seller_* function refuses a suspended seller (conversations.test.mjs)
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  return jsonb_build_object(
    'departments', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) order by d.sort, d.id) from public.departments d where d.active), '[]'::jsonb),
    'types', coalesce((
      select jsonb_agg(
        jsonb_build_object('id', t.id, 'slug', t.slug, 'name', t.name, 'kind', t.kind, 'departmentId', t.department_id, 'categoryIds', to_jsonb(t.category_ids),
                           'quantityMode', t.quantity_mode, 'axes', t.axes, 'specRows', t.spec_rows)
          || case when cardinality(t.restricted_to) > 0 then jsonb_build_object('restrictedTo', to_jsonb(t.restricted_to)) else '{}'::jsonb end
          || case when t.size_chart_id is not null then jsonb_build_object('sizeChartId', t.size_chart_id) else '{}'::jsonb end
        order by t.name, t.id)
      from public.product_types t where t.active and public.shop_can_sell_type(v_biz, t.id)), '[]'::jsonb));
end $$;
revoke all on function public.seller_product_types() from public, anon;
grant execute on function public.seller_product_types() to authenticated, service_role;

$m_0091_departments_restrictions$),
    ('0092_products_snapshot_brand', $m_0092_products_snapshot_brand$
-- 0092_products_snapshot_brand.sql
-- The home products snapshot carries each item's brand, so the buyer's Brand filter can offer one choice per brand
-- ("Samsung", "SAMSUNG" and "samsung" are one choice: the client groups by normalizeValueKey, see 0090_option_values.sql).
-- One extra column, `brand`, from public_items (which has had it since 0050). Like 0054 and 0057 this patches the function as it is now
-- (pg_get_functiondef + replace) instead of copying it, so every column added by an earlier migration (stock_left, video_paths, the
-- shop timezone ...) is kept. Running it twice changes nothing.

do $$
declare
  v_def text;
  v_new text;
begin
  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'products_snapshot';
  if position('i.brand' in v_def) = 0 then
    v_new := replace(v_def, 'i.image_paths ->> 0 as image_path', 'i.image_paths ->> 0 as image_path, i.brand');
    if v_new = v_def then raise exception 'products_snapshot: capped column list not found'; end if;
    v_def := v_new;
    v_new := replace(v_def, 'k.created_at, k.image_path,', 'k.created_at, k.image_path, k.brand,');
    if v_new = v_def then raise exception 'products_snapshot: item column list not found'; end if;
    execute v_new;
  end if;
end $$;

$m_0092_products_snapshot_brand$),
    ('0093_size_chart_types_shoe_conversion', $m_0093_size_chart_types_shoe_conversion$
-- A05: size charts attach to product types, and the shoe conversion chart becomes admin-editable data.
--
-- What A04 (0086) already gave: size_charts (library owned by admin), public_size_charts, admin_save_size_chart / admin_delete_size_chart /
-- admin_size_charts_list, items.size_chart_id and items.size_chart_override. What A08 (0091) gave: product_types with size_chart_id (the contract's
-- ProductType.sizeChartId; seller_product_types already returns it). This migration changes nothing that exists except where said:
--   * product_types.size_chart_id   gets its foreign key to size_charts (on delete restrict). A type has ONE default chart (the contract); an item can
--                                   still choose any chart (items.size_chart_id) and override its rows (items.size_chart_override).
--   * public_size_charts            gains product_type_ids (appended), worked out from product_types.size_chart_id. Existing readers are unaffected.
--   * admin_size_charts_list        gains product_type_ids the same way.
--   * admin_save_size_chart         accepts product_type_ids: it points those types at the chart (a type moves from its old chart) and releases types
--                                   that are no longer listed. An absent key changes nothing; null or [] releases every type. New error invalid_type_ids
--                                   (a type that does not exist, a repeat, or more than 20).
--   * admin_delete_size_chart       also refuses a chart that a type uses (size_chart_in_use), as it already refused one that items use.
--   * size_charts_for_type(type, category)  public read: the type's chart; when the type has none, the category's charts that no type uses.
--   * attach_default_size_charts()  points the types dress and shirt at the seeded charts when they have none (service role; safe to repeat).
--                                   Called here, and A06 calls it again after it seeds its types.
--   * shoe_conversion               ONE row, the shoe conversion chart: {adult: [{eu, uk, usM, usW, cm}], kids: [{eu, uk: null, usM: null, usW: null, cm}]}
--                                   (the shape of shared/src/scales/shoeChart.js, so A02's shoe scale reads it as it is). Only the rows are stored; the
--                                   systems and widths are fixed in code. A version number rises with every save.
--   * public_shoe_conversion        public read of the chart and its version.
--   * admin_save_shoe_conversion(chart) -> version   owner only, validated, audited. Edits do not change items: a size is stored as typed.
--   * Seeds: dress and tops (cm), shirt collar, men's shoes, women's shoes, kids clothes (age), and the default shoe conversion chart.
-- Errors (P0001): invalid_type_ids, invalid_shoe_chart, size_chart_in_use. forbidden (42501) for anyone but an owner.

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. Charts by product type (the link lives on product_types.size_chart_id)
-- ---------------------------------------------------------------------------------------------------------------------

alter table public.product_types drop constraint if exists product_types_size_chart_fk;
alter table public.product_types add constraint product_types_size_chart_fk foreign key (size_chart_id) references public.size_charts (id) on delete restrict;
create index if not exists product_types_size_chart_idx on public.product_types (size_chart_id) where size_chart_id is not null;

create or replace view public.public_size_charts with (security_barrier = true) as
select c.id, c.name, c.category, c.unit, c.columns, c.rows,
       coalesce((select array_agg(t.id order by t.id) from public.product_types t where t.size_chart_id = c.id and t.active), '{}'::text[]) as product_type_ids
  from public.size_charts c where c.active;
revoke all on public.public_size_charts from public;
grant select on public.public_size_charts to anon, authenticated, service_role;

create or replace function public.admin_size_charts_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.category nulls last, x.name)
    from (select c.id, c.name, c.category, c.unit, c.columns, c.rows, c.active, c.updated_at,
                 coalesce((select array_agg(t.id order by t.id) from public.product_types t where t.size_chart_id = c.id), '{}'::text[]) as product_type_ids,
                 (select count(*) from public.items i where i.size_chart_id = c.id) as items_using
            from public.size_charts c) x), '[]'::jsonb);
end $$;

create or replace function public.admin_save_size_chart(p_id uuid, p_fields jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_name text := btrim(coalesce(f ->> 'name', ''));
  v_category text := nullif(btrim(coalesce(f ->> 'category', '')), '');
  v_unit text := coalesce(f ->> 'unit', 'cm');
  v_active boolean := coalesce((f ->> 'active')::boolean, true);
  v_has_types boolean := f ? 'product_type_ids';
  v_types text[] := '{}';
  v_old public.size_charts;
  v_id uuid;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if char_length(v_name) not between 2 and 80 then raise exception 'invalid_name' using errcode = 'P0001'; end if;
  if v_unit not in ('cm', 'in', 'mm', 'kg', 'lb', 'none') then raise exception 'invalid_unit' using errcode = 'P0001'; end if;
  if v_category is not null and not exists (select 1 from public.categories c where c.id = v_category) then raise exception 'invalid_category' using errcode = 'P0001'; end if;
  if not public.size_chart_columns_valid(f -> 'columns') or not public.size_chart_rows_valid(f -> 'rows', jsonb_array_length(f -> 'columns')) then
    raise exception 'invalid_chart' using errcode = 'P0001';
  end if;
  if v_has_types and jsonb_typeof(f -> 'product_type_ids') <> 'null' then
    if jsonb_typeof(f -> 'product_type_ids') <> 'array'
       or jsonb_array_length(f -> 'product_type_ids') > 20
       or exists (select 1 from jsonb_array_elements(f -> 'product_type_ids') e where jsonb_typeof(e) <> 'string') then
      raise exception 'invalid_type_ids' using errcode = 'P0001';
    end if;
    select coalesce(array_agg(t), '{}') into v_types from jsonb_array_elements_text(f -> 'product_type_ids') t;
    if cardinality(v_types) <> (select count(distinct t) from unnest(v_types) t)
       or exists (select 1 from unnest(v_types) t where not exists (select 1 from public.product_types pt where pt.id = t)) then
      raise exception 'invalid_type_ids' using errcode = 'P0001';
    end if;
  end if;
  begin
    if p_id is null then
      insert into public.size_charts (name, category, unit, columns, rows, active)
        values (v_name, v_category, v_unit, f -> 'columns', f -> 'rows', v_active) returning id into v_id;
      perform public.admin_audit_action('size_chart.create', 'size_chart', v_id::text, null, jsonb_build_object('name', v_name, 'category', v_category, 'product_type_ids', v_types), null, null);
    else
      select * into v_old from public.size_charts where id = p_id for update;
      if not found then raise exception 'chart_not_found' using errcode = 'P0001'; end if;
      update public.size_charts set name = v_name, category = v_category, unit = v_unit, columns = f -> 'columns', rows = f -> 'rows', active = v_active, updated_at = now() where id = p_id;
      v_id := p_id;
      perform public.admin_audit_action('size_chart.update', 'size_chart', v_id::text,
        jsonb_build_object('name', v_old.name, 'active', v_old.active),
        jsonb_build_object('name', v_name, 'active', v_active, 'product_type_ids', case when v_has_types then to_jsonb(v_types) else null end), null, null);
    end if;
  exception when unique_violation then
    raise exception 'duplicate_chart' using errcode = 'P0001';
  end;
  if v_has_types then
    update public.product_types set size_chart_id = null where size_chart_id = v_id and not (id = any (v_types));
    update public.product_types set size_chart_id = v_id where id = any (v_types) and size_chart_id is distinct from v_id;
  end if;
  return v_id;
end $$;

create or replace function public.admin_delete_size_chart(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_old public.size_charts;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into v_old from public.size_charts where id = p_id for update;
  if not found then raise exception 'chart_not_found' using errcode = 'P0001'; end if;
  if exists (select 1 from public.items i where i.size_chart_id = p_id) or exists (select 1 from public.product_types t where t.size_chart_id = p_id) then
    raise exception 'size_chart_in_use' using errcode = 'P0001';
  end if;
  delete from public.size_charts where id = p_id;
  perform public.admin_audit_action('size_chart.delete', 'size_chart', p_id::text, jsonb_build_object('name', v_old.name), null, null, null);
end $$;
revoke all on function public.admin_size_charts_list(), public.admin_save_size_chart(uuid, jsonb), public.admin_delete_size_chart(uuid) from public, anon;
grant execute on function public.admin_size_charts_list(), public.admin_save_size_chart(uuid, jsonb), public.admin_delete_size_chart(uuid) to authenticated, service_role;

-- The charts a buyer can be shown for a product type: the type's own chart. When the type has none (or the chart is switched off), the charts of the
-- shop's category that no type uses.
create or replace function public.size_charts_for_type(p_type text, p_category text default null) returns jsonb
language sql stable set search_path = public as $$
  with own as (
    select c.* from public.public_size_charts c where c.id = (select t.size_chart_id from public.product_types t where t.id = p_type and t.active)
  ), picked as (
    select * from own
    union all
    select c.* from public.public_size_charts c
     where not exists (select 1 from own) and p_category is not null and c.category = p_category and cardinality(c.product_type_ids) = 0
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'category', x.category, 'unit', x.unit, 'columns', x.columns, 'rows', x.rows, 'product_type_ids', to_jsonb(x.product_type_ids)) order by x.name), '[]'::jsonb)
    from picked x
$$;
revoke all on function public.size_charts_for_type(text, text) from public;
grant execute on function public.size_charts_for_type(text, text) to anon, authenticated, service_role;

-- Default charts for the types that have none yet. A06 calls this after it seeds its types; it is safe to call again.
create or replace function public.attach_default_size_charts() returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_n integer;
begin
  update public.product_types t set size_chart_id = c.id
    from (values ('dress', 'Dresses and tops (cm)'), ('shirt', 'Shirt collar')) as m (type_id, chart_name)
    join public.size_charts c on c.category is null and lower(btrim(c.name)) = lower(m.chart_name)
   where t.id = m.type_id and t.size_chart_id is null;
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke all on function public.attach_default_size_charts() from public, anon, authenticated;
grant execute on function public.attach_default_size_charts() to service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 2. Shoe conversion chart (one row, admin-editable)
-- ---------------------------------------------------------------------------------------------------------------------

-- Rows of one set. adult: every size is needed. kids: EU and cm are needed, the other sizes may be null.
-- EU and cm rise row to row, and so does every other size that is filled in.
create or replace function public.shoe_chart_rows_valid(p jsonb, p_adult boolean) returns boolean
language plpgsql immutable parallel safe as $$
declare
  r jsonb;
  k text;
  v numeric;
  v_last jsonb := '{}'::jsonb;
  v_n integer;
begin
  if p is null or jsonb_typeof(p) <> 'array' then return false; end if;
  v_n := jsonb_array_length(p);
  if v_n > 60 or (p_adult and v_n < 2) then return false; end if;
  for r in select jsonb_array_elements(p) loop
    if jsonb_typeof(r) <> 'object' then return false; end if;
    if exists (select 1 from jsonb_object_keys(r) key where key not in ('eu', 'uk', 'usM', 'usW', 'cm')) then return false; end if;
    foreach k in array array['eu', 'uk', 'usM', 'usW', 'cm'] loop
      if not (r ? k) or jsonb_typeof(r -> k) = 'null' then
        if p_adult or k in ('eu', 'cm') then return false; end if;
        continue;
      end if;
      if jsonb_typeof(r -> k) <> 'number' then return false; end if;
      v := (r ->> k)::numeric;
      if k = 'eu' and v not between 10 and 60 then return false; end if;
      if k = 'cm' and v not between 8 and 40 then return false; end if;
      if k in ('uk', 'usM', 'usW') and v not between 0 and 25 then return false; end if;
      if v_last ? k and v <= (v_last ->> k)::numeric then return false; end if;
      v_last := v_last || jsonb_build_object(k, v);
    end loop;
  end loop;
  return true;
end $$;

create or replace function public.shoe_chart_valid(p jsonb) returns boolean
language plpgsql immutable parallel safe as $$
declare
  v_kids_cm numeric;
  v_kids_eu numeric;
begin
  if p is null or jsonb_typeof(p) <> 'object' then return false; end if;
  if exists (select 1 from jsonb_object_keys(p) key where key not in ('adult', 'kids')) then return false; end if;
  if not public.shoe_chart_rows_valid(p -> 'adult', true) or not public.shoe_chart_rows_valid(coalesce(p -> 'kids', '[]'::jsonb), false) then return false; end if;
  if jsonb_array_length(coalesce(p -> 'kids', '[]'::jsonb)) > 0 then
    v_kids_cm := (p -> 'kids' -> (jsonb_array_length(p -> 'kids') - 1) ->> 'cm')::numeric;
    v_kids_eu := (p -> 'kids' -> (jsonb_array_length(p -> 'kids') - 1) ->> 'eu')::numeric;
    if v_kids_cm >= (p -> 'adult' -> 0 ->> 'cm')::numeric or v_kids_eu >= (p -> 'adult' -> 0 ->> 'eu')::numeric then return false; end if;
  end if;
  return true;
end $$;
revoke all on function public.shoe_chart_rows_valid(jsonb, boolean), public.shoe_chart_valid(jsonb) from public;
grant execute on function public.shoe_chart_rows_valid(jsonb, boolean), public.shoe_chart_valid(jsonb) to anon, authenticated, service_role;

create table if not exists public.shoe_conversion (
  id text primary key default 'default' check (id = 'default'),
  chart jsonb not null check (public.shoe_chart_valid(chart)),
  version integer not null default 1 check (version >= 1),
  updated_at timestamptz not null default now()
);
alter table public.shoe_conversion enable row level security;
drop policy if exists "admin reads shoe_conversion" on public.shoe_conversion;
create policy "admin reads shoe_conversion" on public.shoe_conversion for select to authenticated using (public.is_admin());
revoke all on public.shoe_conversion from public, anon, authenticated;
grant select on public.shoe_conversion to authenticated;
grant all on public.shoe_conversion to service_role;

create or replace view public.public_shoe_conversion with (security_barrier = true) as
select s.chart, s.version, s.updated_at from public.shoe_conversion s where s.id = 'default';
revoke all on public.public_shoe_conversion from public;
grant select on public.public_shoe_conversion to anon, authenticated, service_role;

create or replace function public.admin_save_shoe_conversion(p_chart jsonb) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_old public.shoe_conversion;
  v_version integer;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if not public.shoe_chart_valid(p_chart) then raise exception 'invalid_shoe_chart' using errcode = 'P0001'; end if;
  select * into v_old from public.shoe_conversion where id = 'default' for update;
  if not found then
    insert into public.shoe_conversion (id, chart) values ('default', p_chart) returning version into v_version;
    perform public.admin_audit_action('shoe_conversion.create', 'shoe_conversion', 'default', null, jsonb_build_object('version', v_version), null, null);
  else
    update public.shoe_conversion set chart = p_chart, version = v_old.version + 1, updated_at = now() where id = 'default' returning version into v_version;
    perform public.admin_audit_action('shoe_conversion.update', 'shoe_conversion', 'default', jsonb_build_object('version', v_old.version), jsonb_build_object('version', v_version), null, null);
  end if;
  return v_version;
end $$;
revoke all on function public.admin_save_shoe_conversion(jsonb) from public, anon;
grant execute on function public.admin_save_shoe_conversion(jsonb) to authenticated, service_role;

