$m_0093_size_chart_types_shoe_conversion$),
    ('0094_price_tiers', $m_0094_price_tiers$
-- Quantity price tiers: [{minQty, maxQty, unitPrice}] on an item or on one option combination, with a mode (whole | graduated).
-- Prices are whole amounts, like the rest of the pricing core. Mirrors shared/src/pricing/tiers.js (validateTiers); a db test runs one table of cases through both.
-- seller_save_item takes priceTiers, priceTierMode and options.variants[].priceTiers (key absent = leave alone, null = clear).
-- Errors (P0001): invalid_price_tiers, tiers_need_from_price, item_in_flash_sale.

create or replace function public.price_tiers_valid(p_tiers jsonb) returns boolean
language plpgsql immutable set search_path = public as $$
declare
  n integer;
  i integer;
  t jsonb;
  k text;
  v_min numeric;
  v_max numeric;
  v_price numeric;
  v_prev_max numeric;
  v_prev_price numeric;
begin
  if p_tiers is null or jsonb_typeof(p_tiers) is distinct from 'array' then return false; end if;
  n := jsonb_array_length(p_tiers);
  if n < 1 or n > 10 then return false; end if;
  for i in 0 .. n - 1 loop
    t := p_tiers -> i;
    if jsonb_typeof(t) is distinct from 'object' then return false; end if;
    for k in select jsonb_object_keys(t) loop
      if k not in ('minQty', 'maxQty', 'unitPrice') then return false; end if;
    end loop;
    if not (t ? 'maxQty') then return false; end if;
    if jsonb_typeof(t -> 'minQty') is distinct from 'number' or jsonb_typeof(t -> 'unitPrice') is distinct from 'number' then return false; end if;
    v_min := (t ->> 'minQty')::numeric;
    v_price := (t ->> 'unitPrice')::numeric;
    if v_min <> trunc(v_min) or v_min < 1 or v_min > 1000000 then return false; end if;
    if v_price < 1 or v_price > 9999999999 or v_price <> trunc(v_price) then return false; end if;
    if jsonb_typeof(t -> 'maxQty') = 'null' then
      v_max := null;
    elsif jsonb_typeof(t -> 'maxQty') = 'number' then
      v_max := (t ->> 'maxQty')::numeric;
      if v_max <> trunc(v_max) or v_max < v_min or v_max > 1000000 then return false; end if;
    else
      return false;
    end if;
    if i = 0 then
      if v_min <> 1 then return false; end if;
    else
      if v_prev_max is null or v_min <> v_prev_max + 1 or v_price > v_prev_price then return false; end if;
    end if;
    if i < n - 1 and v_max is null then return false; end if;
    if i = n - 1 and v_max is not null then return false; end if;
    v_prev_max := v_max;
    v_prev_price := v_price;
  end loop;
  return true;
end $$;

alter table public.items add column if not exists price_tiers jsonb;
alter table public.items add column if not exists price_tier_mode text not null default 'whole';
alter table public.item_variants add column if not exists price_tiers jsonb;

alter table public.items drop constraint if exists items_price_tiers_ck;
alter table public.items add constraint items_price_tiers_ck check (price_tiers is null or public.price_tiers_valid(price_tiers));
alter table public.items drop constraint if exists items_price_tier_mode_ck;
alter table public.items add constraint items_price_tier_mode_ck check (price_tier_mode in ('whole', 'graduated'));
alter table public.item_variants drop constraint if exists item_variants_price_tiers_ck;
alter table public.item_variants add constraint item_variants_price_tiers_ck check (price_tiers is null or public.price_tiers_valid(price_tiers));

do $$ begin
  if to_regprocedure('public.seller_save_item_typed(uuid, jsonb)') is null then
    alter function public.seller_save_item(uuid, jsonb) rename to seller_save_item_typed;
  end if;
end $$;
revoke all on function public.seller_save_item_typed(uuid, jsonb) from public, anon, authenticated;
grant execute on function public.seller_save_item_typed(uuid, jsonb) to service_role;

create or replace function public.seller_save_item(p_id uuid, p_fields jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_biz uuid := public.my_business_id();
  v_has_tiers boolean := f ? 'priceTiers';
  v_has_mode boolean := f ? 'priceTierMode';
  v_tiers jsonb;
  v_mode text;
  v_old public.items;
  v_clean jsonb := '[]'::jsonb;
  v_vt jsonb := '[]'::jsonb;
  e jsonb;
  v_flash boolean := false;
  v_found boolean;
  v_id uuid;
  v_axes jsonb;
  v_key text;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;

  if v_has_tiers then
    v_tiers := f -> 'priceTiers';
    if jsonb_typeof(v_tiers) = 'null' then v_tiers := null;
    elsif not public.price_tiers_valid(v_tiers) then raise exception 'invalid_price_tiers' using errcode = 'P0001'; end if;
  end if;
  if v_has_mode then
    if jsonb_typeof(f -> 'priceTierMode') is distinct from 'string' or (f ->> 'priceTierMode') not in ('whole', 'graduated') then
      raise exception 'invalid_price_tiers' using errcode = 'P0001';
    end if;
    v_mode := f ->> 'priceTierMode';
  end if;

  if jsonb_typeof(f -> 'options') = 'object' and jsonb_typeof(f -> 'options' -> 'variants') = 'array' then
    for e in select jsonb_array_elements(f -> 'options' -> 'variants') loop
      if jsonb_typeof(e) = 'object' and e ? 'priceTiers' then
        if jsonb_typeof(e -> 'priceTiers') <> 'null' and not public.price_tiers_valid(e -> 'priceTiers') then
          raise exception 'invalid_price_tiers' using errcode = 'P0001';
        end if;
        v_vt := v_vt || jsonb_build_array(jsonb_build_object('choice', e -> 'choice', 'tiers', e -> 'priceTiers'));
        v_clean := v_clean || jsonb_build_array(e - 'priceTiers');
      else
        v_clean := v_clean || jsonb_build_array(e);
      end if;
    end loop;
    f := jsonb_set(f, '{options,variants}', v_clean);
  end if;
  f := f - 'priceTiers' - 'priceTierMode';

  if p_id is not null then
    select * into v_old from public.items where id = p_id and business_id = v_biz;
    v_found := found;
    v_flash := exists (select 1 from public.flash_sales s where s.item_id = p_id and s.status in ('scheduled', 'live'));
    if v_flash and v_found and (
      (v_has_tiers and v_tiers is distinct from v_old.price_tiers)
      or (v_has_mode and v_mode is distinct from v_old.price_tier_mode)
    ) then
      raise exception 'item_in_flash_sale' using errcode = 'P0001';
    end if;
  end if;

  v_id := public.seller_save_item_typed(p_id, f);

  if v_has_tiers then update public.items set price_tiers = v_tiers where id = v_id and price_tiers is distinct from v_tiers; end if;
  if v_has_mode then update public.items set price_tier_mode = v_mode where id = v_id and price_tier_mode is distinct from v_mode; end if;

  if jsonb_array_length(v_vt) > 0 then
    select option_axes into v_axes from public.items where id = v_id;
    for e in select jsonb_array_elements(v_vt) loop
      v_key := public.item_option_combo_key(v_axes, e -> 'choice');
      update public.item_variants set price_tiers = case when jsonb_typeof(e -> 'tiers') = 'null' then null else e -> 'tiers' end, updated_at = now()
        where item_id = v_id and combo_key = v_key
          and price_tiers is distinct from case when jsonb_typeof(e -> 'tiers') = 'null' then null else e -> 'tiers' end;
      if found and v_flash then raise exception 'item_in_flash_sale' using errcode = 'P0001'; end if;
    end loop;
  end if;

  if exists (
    select 1 from public.items i
    where i.id = v_id and i.price_type is distinct from 'from'
      and (i.price_tiers is not null or exists (select 1 from public.item_variants v where v.item_id = i.id and v.price_tiers is not null))
  ) then
    raise exception 'tiers_need_from_price' using errcode = 'P0001';
  end if;

  return v_id;
end $$;
revoke all on function public.seller_save_item(uuid, jsonb) from public, anon;
grant execute on function public.seller_save_item(uuid, jsonb) to authenticated, service_role;
revoke all on function public.price_tiers_valid(jsonb) from public, anon;
grant execute on function public.price_tiers_valid(jsonb) to authenticated, service_role;

$m_0094_price_tiers$),
    ('0095_flash_per_combination', $m_0095_flash_per_combination$
-- Flash sale per combination. variant_target: 'all' (every combination gets the sale's discount) or 'chosen' (only the combinations
-- listed in variant_overrides). variant_overrides entries are {combo, type, value}: that combination's own percent, amount_off or
-- sale_price. Older [{variantId, salePrice}] entries stay valid and are ignored. A combination is sold when it is a stored
-- item_variants row with its own price that is not 'unavailable' (the pricing core's isSold). Mirrors shared/src/flash/validateFlashVariants.js; a db test runs the same cases through both.
-- Errors (P0001): invalid_flash_overrides, flash_needs_combinations, invalid_flash_target, discount_too_large, sale_price_not_lower.
-- For 'chosen' the sale's own discount_type/discount_value are still required and checked against the item price by the 0013 rules,
-- but are not applied to combinations that are not listed.

alter table public.flash_sales add column if not exists variant_target text not null default 'all';
alter table public.flash_sales drop constraint if exists flash_sales_variant_target_ck;
alter table public.flash_sales add constraint flash_sales_variant_target_ck check (variant_target in ('all', 'chosen'));

create or replace function public.flash_overrides_shape_valid(p jsonb) returns boolean
language plpgsql immutable set search_path = public as $$
declare
  e jsonb;
  k text;
  v_type text;
  v_val numeric;
  v_seen text[] := '{}';
  v_combo text;
begin
  if p is null or jsonb_typeof(p) is distinct from 'array' then return false; end if;
  if jsonb_array_length(p) > 200 then return false; end if;
  for e in select jsonb_array_elements(p) loop
    if jsonb_typeof(e) is distinct from 'object' then return false; end if;
    if e ? 'variantId' then
      for k in select jsonb_object_keys(e) loop
        if k not in ('variantId', 'salePrice') then return false; end if;
      end loop;
      continue;
    end if;
    for k in select jsonb_object_keys(e) loop
      if k not in ('combo', 'type', 'value') then return false; end if;
    end loop;
    if jsonb_typeof(e -> 'combo') is distinct from 'string' or jsonb_typeof(e -> 'type') is distinct from 'string' or jsonb_typeof(e -> 'value') is distinct from 'number' then return false; end if;
    v_combo := e ->> 'combo';
    v_type := e ->> 'type';
    v_val := (e ->> 'value')::numeric;
    if char_length(v_combo) < 3 or char_length(v_combo) > 400 then return false; end if;
    if v_type not in ('percent', 'amount_off', 'sale_price') then return false; end if;
    if v_val <= 0 or v_val > 9999999999.99 or v_val <> round(v_val, 2) then return false; end if;
    if v_type = 'percent' and (v_val < 1 or v_val > 99) then return false; end if;
    if v_combo = any (v_seen) then return false; end if;
    v_seen := v_seen || v_combo;
  end loop;
  return true;
end $$;

create or replace function public.flash_combo_price(p_sale public.flash_sales, p_combo text, p_regular numeric) returns numeric
language plpgsql stable set search_path = public as $$
declare
  o jsonb;
  v_type text := null;
  v_val numeric;
  v_price numeric;
begin
  if p_regular is null then return null; end if;
  select x.e into o from jsonb_array_elements(p_sale.variant_overrides) x(e) where x.e ->> 'combo' = p_combo limit 1;
  if o is not null then
    v_type := o ->> 'type';
    v_val := (o ->> 'value')::numeric;
  elsif p_sale.variant_target = 'all' then
    v_type := p_sale.discount_type;
    v_val := p_sale.discount_value;
  end if;
  if v_type is null then return null; end if;
  v_price := public.flash_discounted_price(v_type, v_val, p_regular);
  if v_price <= 0 or v_price >= p_regular then return null; end if;
  return v_price;
end $$;

create or replace function public.flash_headline_price(p_sale public.flash_sales, p_item_price numeric) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select min(coalesce(public.flash_combo_price(p_sale, v.combo_key, v.price), v.price))
       from public.item_variants v where v.item_id = p_sale.item_id and v.status <> 'unavailable' and v.price is not null),
    public.flash_discounted_price(p_sale.discount_type, p_sale.discount_value, p_item_price));
$$;

create or replace function public.flash_check_variants() returns trigger
language plpgsql set search_path = public as $$
declare
  v_client boolean := current_user in ('authenticated', 'anon');
  e jsonb;
  v_regular numeric;
  v_new numeric;
begin
  if tg_op = 'UPDATE' then
    if v_client and old.starts_at <= now() and new.variant_target is distinct from old.variant_target then
      raise exception 'flash_locked' using errcode = 'P0001';
    end if;
    if new.status in ('ended', 'cancelled') then return new; end if;
    if (new.variant_target, new.variant_overrides, new.discount_type, new.discount_value)
       is not distinct from (old.variant_target, old.variant_overrides, old.discount_type, old.discount_value) then
      return new;
    end if;
  end if;

  if not public.flash_overrides_shape_valid(new.variant_overrides) then raise exception 'invalid_flash_overrides' using errcode = 'P0001'; end if;

  if new.variant_target = 'chosen' and (
    not exists (select 1 from public.item_variants v where v.item_id = new.item_id)
    or not exists (select 1 from jsonb_array_elements(new.variant_overrides) x(e) where x.e ? 'combo')
  ) then
    raise exception 'flash_needs_combinations' using errcode = 'P0001';
  end if;

  for e in select x.e from jsonb_array_elements(new.variant_overrides) x(e) where x.e ? 'combo' loop
    select v.price into v_regular
      from public.item_variants v where v.item_id = new.item_id and v.combo_key = e ->> 'combo' and v.status <> 'unavailable' and v.price is not null;
    if not found then raise exception 'invalid_flash_target' using errcode = 'P0001'; end if;
    v_new := public.flash_discounted_price(e ->> 'type', (e ->> 'value')::numeric, v_regular);
    if v_new <= 0 then raise exception 'discount_too_large' using errcode = 'P0001'; end if;
    if v_new >= v_regular then raise exception 'sale_price_not_lower' using errcode = 'P0001'; end if;
  end loop;
  return new;
end $$;
drop trigger if exists t_flash_sales_variants on public.flash_sales;
create trigger t_flash_sales_variants before insert or update on public.flash_sales for each row execute function public.flash_check_variants();

revoke all on function public.flash_overrides_shape_valid(jsonb), public.flash_combo_price(public.flash_sales, text, numeric), public.flash_headline_price(public.flash_sales, numeric) from public;
grant execute on function public.flash_overrides_shape_valid(jsonb), public.flash_combo_price(public.flash_sales, text, numeric), public.flash_headline_price(public.flash_sales, numeric) to anon, authenticated, service_role;

create or replace view public.public_flash_sales with (security_barrier = true) as
select
  s.id, s.business_id, s.item_id, s.headline, s.starts_at, s.ends_at,
  s.discount_type, s.discount_value, s.variant_overrides, s.quantity_note,
  i.name as item_name, i.description as item_description, i.section as item_section,
  i.price_type as item_price_type, i.unit as item_unit, i.availability as item_availability,
  (select m.path from public.item_media m where m.item_id = i.id and m.kind = 'image' order by m.sort, m.created_at limit 1) as item_image_path,
  i.price as regular_price,
  d.p as sale_price,
  i.price - d.p as savings,
  case when i.price > 0 then round((i.price - d.p) / i.price * 100) else 0 end as discount_percent,
  b.slug as business_slug, b.name as business_name, b.category_id as business_category_id,
  b.town as business_town, b.county as business_county, b.lat as business_lat, b.lng as business_lng,
  b.phone as business_phone, b.whatsapp as business_whatsapp, b.logo_path as business_logo_path,
  b.verification_level as business_verification_level, b.hours as business_hours,
  now() as server_now,
  floor(extract(epoch from (s.ends_at - now())) * 1000)::bigint as remaining_ms,
  public.public_exceptions(b.exceptions) as business_exceptions,
  b.timezone as business_timezone,
  s.variant_target,
  (select jsonb_agg(jsonb_build_object('combo', v.combo_key, 'choice', v.choice, 'regularPrice', v.price, 'salePrice', fp.p) order by v.sort)
     from public.item_variants v
     cross join lateral (select public.flash_combo_price(s, v.combo_key, v.price) as p) fp
    where v.item_id = i.id and v.status <> 'unavailable' and v.price is not null and fp.p is not null) as variant_flash
from public.flash_sales s
join public.items i on i.id = s.item_id
join public.businesses b on b.id = s.business_id
cross join lateral (
  select case when s.variant_target = 'all' and jsonb_array_length(s.variant_overrides) = 0
              then public.flash_discounted_price(s.discount_type, s.discount_value, i.price)
              else public.flash_headline_price(s, i.price) end as p
) d
where s.status in ('scheduled','live')
  and now() >= s.starts_at
  and now() < s.ends_at
  and public.business_is_visible(b)
  and i.visible and not i.hidden_by_admin and not i.removed_by_admin
  and i.availability not in ('out_of_stock','unavailable')
  and i.price is not null and i.price_type in ('fixed','from')
  and d.p > 0
  and (d.p < i.price or s.variant_target = 'chosen' or jsonb_array_length(s.variant_overrides) > 0);
revoke all on public.public_flash_sales from public;
grant select on public.public_flash_sales to anon, authenticated, service_role;

do $$ begin
  if to_regprocedure('public.public_item_options_base(uuid)') is null then
    alter function public.public_item_options(uuid) rename to public_item_options_base;
  end if;
end $$;
revoke all on function public.public_item_options_base(uuid) from public, anon, authenticated;
grant execute on function public.public_item_options_base(uuid) to service_role;

create or replace function public.public_item_options(p_item uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  r jsonb := public.public_item_options_base(p_item);
  s public.flash_sales;
begin
  if r is null then return null; end if;
  select * into s from public.flash_sales f
    where f.item_id = p_item and f.status in ('scheduled', 'live') and now() >= f.starts_at and now() < f.ends_at
    order by f.starts_at desc limit 1;
  if not found then return r; end if;
  return jsonb_set(r, '{optionVariants}', coalesce((
    select jsonb_agg(
      x.e || jsonb_build_object('flash', (
        select case when fp.p is null then null else jsonb_build_object(
          'type', coalesce(o.e ->> 'type', s.discount_type),
          'value', coalesce((o.e ->> 'value')::numeric, s.discount_value),
          'regularPrice', (x.e ->> 'price')::numeric,
          'salePrice', fp.p,
          'endsAt', s.ends_at) end
        from (select public.flash_combo_price(s, vr.combo_key, (x.e ->> 'price')::numeric) as p) fp
        left join lateral (select y.e from jsonb_array_elements(s.variant_overrides) y(e) where y.e ->> 'combo' = vr.combo_key limit 1) o on true
      )) order by x.n)
    from jsonb_array_elements(r -> 'optionVariants') with ordinality as x(e, n)
    left join public.item_variants vr on vr.id::text = x.e ->> 'id'
  ), r -> 'optionVariants'));
end $$;
revoke all on function public.public_item_options(uuid) from public, anon;
grant execute on function public.public_item_options(uuid) to anon, authenticated, service_role;

$m_0095_flash_per_combination$),
    ('0096_price_range_columns', $m_0096_price_range_columns$
-- Denormalised price range and list fields on items. price_min is the lowest price a buyer pays for one unit now, price_high the highest.
-- (items.price_max already exists: it is the seller's "range" top, so the new top is price_high; payloads call it priceMax.)
-- Follows the pricing core (shared/src/pricing.js priceBounds): over the combinations the shop sells (own price, not unavailable), the
-- in-stock ones (available, limited_stock) when there are any, else all of them; each at its price for quantity 1: the first quantity tier
-- if it has tiers, then the lower of the sale price and a live flash sale. Offers are not included. Prices are whole amounts (rounded).
-- An item with no combinations is priced from itself; a "range" item's top is its price_max. Other price types, or no price, are null.
-- Kept by triggers on items, item_variants, flash_sales and product_types, so seller_save_item, bulk edits, the flash sweep and admin
-- changes all keep it right. A flash that starts or ends by the clock shows here when the sweep next runs (within a minute).
-- has_options: the item has option axes (or the older variants list). department_id: the product type's department, null with no type.
-- has_3d: nothing stores a 3D view yet, so it stays false until a later migration sets it.
-- Payloads: public_items gets the columns; products_snapshot gets price_min, price_max, has_price_range, has_options, department_id,
-- product_type_id, has_3d; search_businesses and search_facets filter and sort on the lowest price_min.

alter table public.items add column if not exists price_min numeric(12, 2);
alter table public.items add column if not exists price_high numeric(12, 2);
alter table public.items add column if not exists has_options boolean not null default false;
alter table public.items add column if not exists department_id text;
alter table public.items add column if not exists has_3d boolean not null default false;
alter table public.items drop constraint if exists items_price_range_ck;
alter table public.items add constraint items_price_range_ck check (price_min is null or (price_high is not null and price_min <= price_high));
create index if not exists items_price_min_idx on public.items (price_min) where price_min is not null;
create index if not exists items_department_idx on public.items (department_id) where department_id is not null;

create or replace function public.item_denorm(it public.items) returns table (price_min numeric, price_high numeric, has_options boolean, department_id text)
language plpgsql stable security definer set search_path = public as $$
declare
  f public.flash_sales;
  r record;
  v_has boolean;
  v_listed numeric;
  v_now numeric;
  v_fl numeric;
  v_all numeric[] := '{}';
  v_stocked numeric[] := '{}';
  v_low numeric;
  v_high numeric;
begin
  select * into f from public.flash_sales s
    where s.item_id = it.id and s.status = 'live' and now() >= s.starts_at and now() < s.ends_at
    order by s.starts_at desc limit 1;
  v_has := exists (select 1 from public.item_variants v where v.item_id = it.id);

  if it.price_type in ('fixed', 'from', 'range') then
    for r in
      select round(v.price) as regular, round(v.sale_price) as sale, coalesce(v.price_tiers, it.price_tiers) as tiers, v.combo_key as combo,
             v.status in ('available', 'limited_stock') as stocked
        from public.item_variants v
       where v.item_id = it.id and v.status <> 'unavailable' and v.price is not null
      union all
      select round(it.price), round(it.sale_price), it.price_tiers, null::text, it.availability <> 'out_of_stock'
       where not v_has and it.price is not null
    loop
      v_listed := case when r.tiers is not null then round((r.tiers -> 0 ->> 'unitPrice')::numeric) else r.regular end;
      v_now := v_listed;
      if r.sale is not null and r.sale < v_now then v_now := r.sale; end if;
      if f.id is not null then
        v_fl := public.flash_combo_price(f, r.combo, v_listed);
        if v_fl is not null and v_fl < v_now then v_now := v_fl; end if;
      end if;
      v_all := v_all || v_now;
      if r.stocked then v_stocked := v_stocked || v_now; end if;
    end loop;
    select min(x), max(x) into v_low, v_high from unnest(case when cardinality(v_stocked) > 0 then v_stocked else v_all end) x;
    if v_low is not null and not v_has and it.price_type = 'range' and it.price_max is not null then v_high := greatest(v_high, it.price_max); end if;
  end if;

  return query select
    v_low,
    v_high,
    (jsonb_typeof(it.option_axes) = 'array' and jsonb_array_length(it.option_axes) > 0) or (jsonb_typeof(it.variants) = 'array' and jsonb_array_length(it.variants) > 0),
    (select t.department_id from public.product_types t where t.id = it.product_type_id);
end $$;

create or replace function public.items_denorm_before() returns trigger
language plpgsql security definer set search_path = public as $$
declare d record;
begin
  select * into d from public.item_denorm(new);
  new.price_min := d.price_min;
  new.price_high := d.price_high;
  new.has_options := d.has_options;
  new.department_id := d.department_id;
  return new;
end $$;
drop trigger if exists t_items_denorm on public.items;
create trigger t_items_denorm before insert or update on public.items for each row execute function public.items_denorm_before();

create or replace function public.items_refresh_denorm(p_ids uuid[]) returns void
language plpgsql security definer set search_path = public as $$
declare
  it public.items;
  d record;
begin
  for it in select * from public.items where id = any (p_ids) loop
    select * into d from public.item_denorm(it);
    update public.items set price_min = d.price_min, price_high = d.price_high, has_options = d.has_options, department_id = d.department_id
      where id = it.id and (price_min, price_high, has_options, department_id) is distinct from (d.price_min, d.price_high, d.has_options, d.department_id);
  end loop;
end $$;

create or replace function public.item_variants_denorm_ins() returns trigger language plpgsql security definer set search_path = public as $$
begin perform public.items_refresh_denorm(array(select distinct n.item_id from new_rows n)); return null; end $$;
create or replace function public.item_variants_denorm_upd() returns trigger language plpgsql security definer set search_path = public as $$
begin perform public.items_refresh_denorm(array(select distinct n.item_id from new_rows n)); return null; end $$;
create or replace function public.item_variants_denorm_del() returns trigger language plpgsql security definer set search_path = public as $$
begin perform public.items_refresh_denorm(array(select distinct o.item_id from old_rows o)); return null; end $$;
drop trigger if exists t_item_variants_denorm_ins on public.item_variants;
create trigger t_item_variants_denorm_ins after insert on public.item_variants referencing new table as new_rows for each statement execute function public.item_variants_denorm_ins();
drop trigger if exists t_item_variants_denorm_upd on public.item_variants;
create trigger t_item_variants_denorm_upd after update on public.item_variants referencing new table as new_rows for each statement execute function public.item_variants_denorm_upd();
drop trigger if exists t_item_variants_denorm_del on public.item_variants;
create trigger t_item_variants_denorm_del after delete on public.item_variants referencing old table as old_rows for each statement execute function public.item_variants_denorm_del();

create or replace function public.flash_sales_denorm() returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.items_refresh_denorm(array[coalesce(new.item_id, old.item_id)]);
  return null;
end $$;
drop trigger if exists t_flash_sales_denorm on public.flash_sales;
create trigger t_flash_sales_denorm after insert or update or delete on public.flash_sales for each row execute function public.flash_sales_denorm();

create or replace function public.product_types_denorm() returns trigger language plpgsql security definer set search_path = public as $$
begin
  update public.items set department_id = new.department_id where product_type_id = new.id and department_id is distinct from new.department_id;
  return null;
end $$;
drop trigger if exists t_product_types_denorm on public.product_types;
create trigger t_product_types_denorm after update of department_id on public.product_types for each row execute function public.product_types_denorm();

do $$
declare
  it public.items;
  d record;
begin
  for it in select * from public.items loop
    select * into d from public.item_denorm(it);
    update public.items set price_min = d.price_min, price_high = d.price_high, has_options = d.has_options, department_id = d.department_id where id = it.id;
  end loop;
end $$;

revoke all on function public.item_denorm(public.items), public.items_refresh_denorm(uuid[]) from public, anon, authenticated;
grant execute on function public.item_denorm(public.items), public.items_refresh_denorm(uuid[]) to service_role;

create or replace view public.public_items with (security_barrier = true) as
select
  i.id, i.business_id, i.name, i.description, i.section, i.price, i.price_max, i.price_type, i.unit,
  i.availability, i.sort, i.created_at,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id and m.kind = 'image'), '[]'::jsonb) as image_paths,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id and m.kind = 'video'), '[]'::jsonb) as video_paths,
  case when i.track_stock and i.show_stock_count and i.availability = 'limited_stock' and i.stock_count > 0 then i.stock_count end as stock_left,
  i.brand, i.short_description, i.highlights, i.specs, i.includes, i.terms, i.pack_size,
  coalesce((select jsonb_agg(jsonb_build_object('path', m.path, 'kind', m.kind, 'duration', m.duration_sec) order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id), '[]'::jsonb) as media,
  coalesce((select jsonb_agg(jsonb_build_object('id', x.e ->> 'id', 'label', x.e ->> 'label', 'price', (x.e ->> 'price')::numeric) order by x.n)
    from jsonb_array_elements(case when jsonb_typeof(i.variants) = 'array' then i.variants else '[]'::jsonb end) with ordinality as x(e, n)
    where coalesce(x.e ->> 'stock', '') <> '0'), '[]'::jsonb) as variants,
  i.price_min, i.price_high, i.has_options, i.department_id, i.product_type_id, i.has_3d
from public.items i
join public.businesses b on b.id = i.business_id
where public.business_is_visible(b) and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
  and public.item_is_listed(i.availability);
revoke all on public.public_items from public;
grant select on public.public_items to anon, authenticated, service_role;

do $$
declare
  v_def text;
  v_new text;
begin
  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'products_snapshot';
  if position('i.price_min' in v_def) = 0 then
    v_new := replace(v_def, 'i.brand, nullif(i.video_paths', 'i.brand, i.price_min, i.price_high, i.has_options, i.department_id, i.product_type_id, i.has_3d, nullif(i.video_paths');
    if v_new = v_def then raise exception 'products_snapshot: capped column list not found'; end if;
    v_def := v_new;
    v_new := replace(v_def, 'k.image_path, k.brand, k.video_paths,', 'k.image_path, k.brand, k.video_paths, k.price_min, k.price_high as price_max, k.price_min < k.price_high as has_price_range, k.has_options, k.department_id, k.product_type_id, k.has_3d,');
    if v_new = v_def then raise exception 'products_snapshot: item column list not found'; end if;
    execute v_new;
  end if;

  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'search_businesses';
  if position('min(i.price) as from_price' in v_def) > 0 then
    execute replace(v_def, 'min(i.price) as from_price', 'min(coalesce(i.price_min, i.price)) as from_price');
  end if;

  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'search_facets';
  if position('min(i.price) as from_price' in v_def) > 0 then
    execute replace(v_def, 'min(i.price) as from_price', 'min(coalesce(i.price_min, i.price)) as from_price');
  end if;
end $$;

$m_0096_price_range_columns$),
    ('0097_duplicate_item_tiers', $m_0097_duplicate_item_tiers$
-- 0097: seller_duplicate_item also copies quantity tiers (item and per combination).

do $$ begin
  if to_regprocedure('public.seller_duplicate_item_base(uuid)') is null then
    alter function public.seller_duplicate_item(uuid) rename to seller_duplicate_item_base;
  end if;
end $$;

revoke all on function public.seller_duplicate_item_base(uuid) from public, anon, authenticated;
grant execute on function public.seller_duplicate_item_base(uuid) to service_role;

create or replace function public.seller_duplicate_item(p_id uuid) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_new uuid;
begin
  perform public.assert_seller_active();
  v_new := public.seller_duplicate_item_base(p_id);
  update public.items n set price_tiers = s.price_tiers, price_tier_mode = s.price_tier_mode
    from public.items s where s.id = p_id and n.id = v_new;
  update public.item_variants n set price_tiers = o.price_tiers
    from public.item_variants o where o.item_id = p_id and n.item_id = v_new and n.combo_key = o.combo_key;
  return v_new;
end $$;

revoke all on function public.seller_duplicate_item(uuid) from public, anon;
grant execute on function public.seller_duplicate_item(uuid) to authenticated, service_role;

$m_0097_duplicate_item_tiers$),
    ('0098_flash_legacy_targets', $m_0098_flash_legacy_targets$
-- 0098: flash sales saved with the older id entries ({ variantId, salePrice? }, migration 0013) hit only the listed combinations, in the
-- price range and in the public option payload, as the pricing core does. Entries with { combo, type, value } are unchanged.

create or replace function public.flash_variant_price(p_sale public.flash_sales, p_variant uuid, p_combo text, p_regular numeric) returns numeric
language plpgsql stable set search_path = public as $$
declare
  v_price numeric;
begin
  if p_regular is null then return null; end if;
  if jsonb_array_length(p_sale.variant_overrides) > 0
     and not exists (select 1 from jsonb_array_elements(p_sale.variant_overrides) x(e) where x.e ? 'combo') then
    if p_variant is null or not exists (select 1 from jsonb_array_elements(p_sale.variant_overrides) x(e) where x.e ->> 'variantId' = p_variant::text) then
      return null;
    end if;
    v_price := public.flash_discounted_price(p_sale.discount_type, p_sale.discount_value, p_regular);
    if v_price <= 0 or v_price >= p_regular then return null; end if;
    return v_price;
  end if;
  return public.flash_combo_price(p_sale, p_combo, p_regular);
end $$;

revoke all on function public.flash_variant_price(public.flash_sales, uuid, text, numeric) from public;
grant execute on function public.flash_variant_price(public.flash_sales, uuid, text, numeric) to anon, authenticated, service_role;

do $$
declare
  v_def text;
begin
  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'item_denorm';
  v_def := replace(v_def, 'v.combo_key as combo,', 'v.combo_key as combo, v.id as vid,');
  v_def := replace(v_def, 'null::text, it.availability', 'null::text, null::uuid, it.availability');
  v_def := replace(v_def, 'public.flash_combo_price(f, r.combo, v_listed)', 'public.flash_variant_price(f, r.vid, r.combo, v_listed)');
  if v_def not like '%flash_variant_price%' or v_def not like '%r.vid%' then raise exception '0098: item_denorm patch did not apply'; end if;
  execute v_def;

  select pg_get_functiondef(p.oid) into strict v_def from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'public_item_options';
  v_def := replace(v_def, 'public.flash_combo_price(s, vr.combo_key, (x.e ->> ''price'')::numeric)', 'public.flash_variant_price(s, vr.id, vr.combo_key, (x.e ->> ''price'')::numeric)');
  if v_def not like '%flash_variant_price%' then raise exception '0098: public_item_options patch did not apply'; end if;
  execute v_def;
end $$;

select public.items_refresh_denorm(array(select id from public.items where price_type in ('fixed', 'from', 'range')));

$m_0098_flash_legacy_targets$),
    ('0099_publish_gate', $m_0099_publish_gate$
-- Prompt 5.4: the publish gate on the server.
--
--   * spec_* functions         the SQL twin of shared/src/specRules (specIssues, conditions, label sets). supabase/tests/publish-gate.test.mjs
--                              runs both on the same items and checks they agree, so change both together.
--   * item_check_publish(item) { canSave, canPublish, grandfathered, blockers[], warnings[], score }. Prompt 11.1 calls it.
--   * items_spec_gate trigger  an item cannot become live, and a live item cannot be edited, while a required row is missing. Drafts and hidden
--                              items are always saveable. It runs on the table, so no client and no other function can skip it.
--   * items.spec_gate_exempt   grandfathering: items that were live before this migration stay live; the first real edit of their type, specs,
--                              brand, pack size, includes or options turns the exemption off for good, and the checks apply from then on.
--   * seller_check_item        unchanged unless the fields carry `publish`. With `publish: false` the answer adds `spec` (the issue list the editor
--                              shows); with `publish: true` blockers also make `ok` false and appear in `issues`.
--   * product_types.spec_rows  at most four required rows (a row with requiredIf counts); fragrance gets its rows.
-- seller_save_item is not touched (A04 owns it).

alter table public.items add column if not exists spec_gate_exempt boolean not null default false;
update public.items set spec_gate_exempt = true where not draft;

create or replace function public.spec_rows_required_ok(p jsonb) returns boolean
language sql immutable parallel safe as
$$
  select case when jsonb_typeof(p) = 'array'
    then (select count(*) from jsonb_array_elements(p) e where e ->> 'level' = 'required' or e ? 'requiredIf') <= 4
    else false end
$$;

alter table public.product_types drop constraint if exists product_types_spec_rows_required_max;
alter table public.product_types add constraint product_types_spec_rows_required_max check (public.spec_rows_required_ok(spec_rows));

create or replace function public.spec_filled(v jsonb) returns boolean
language plpgsql immutable parallel safe as $$
declare e jsonb;
begin
  case jsonb_typeof(v)
    when 'string' then return btrim(v #>> '{}', E' \t\r\n') <> '';
    when 'number' then return true;
    when 'boolean' then return true;
    when 'array' then
      for e in select jsonb_array_elements(v) loop
        if public.spec_filled(e) then return true; end if;
      end loop;
      return false;
    else return false;
  end case;
end $$;

create or replace function public.spec_label_set(p text) returns text[]
language sql immutable parallel safe as
$$
  select case p
    when 'condition' then array['New', 'Refurbished', 'Used']
    when 'authenticity' then array['Original', 'Inspired']
    when 'fragranceState' then array['Sealed', 'Tester', 'Decant']
    when 'chargerKind' then array['Original', 'Compatible', 'Refill']
  end
$$;

create or replace function public.spec_row_choices(p_row jsonb) returns text[]
language plpgsql immutable parallel safe as $$
begin
  if jsonb_typeof(p_row -> 'choices') = 'array' then
    return array(select jsonb_array_elements_text(p_row -> 'choices'));
  end if;
  return public.spec_label_set(p_row ->> 'labelSet');
end $$;

create or replace function public.spec_row_own(p_item jsonb, p_row jsonb) returns jsonb
language plpgsql immutable parallel safe as $$
declare
  v_label text := public.normalize_value_key(p_row ->> 'label');
  e jsonb;
begin
  if jsonb_typeof(p_item -> 'specs') = 'array' then
    for e in select jsonb_array_elements(p_item -> 'specs') loop
      if jsonb_typeof(e) = 'object' and public.normalize_value_key(e ->> 'label') = v_label and public.spec_filled(e -> 'value') then
        return e -> 'value';
      end if;
    end loop;
  end if;
  return null;
end $$;

create or replace function public.spec_row_value(p_item jsonb, p_row jsonb) returns jsonb
language plpgsql immutable parallel safe as $$
declare
  v jsonb := public.spec_row_own(p_item, p_row);
  v_field text;
  a jsonb;
begin
  if v is not null then return v; end if;
  v_field := case p_row ->> 'key' when 'brand' then 'brand' when 'pack-size' then 'packSize' when 'includes' then 'includes' end;
  if v_field is not null and public.spec_filled(p_item -> v_field) then return p_item -> v_field; end if;
  if jsonb_typeof(p_item -> 'axes') = 'array' then
    for a in select jsonb_array_elements(p_item -> 'axes') loop
      if jsonb_typeof(a) = 'object' and a ->> 'key' = p_row ->> 'key' and jsonb_typeof(a -> 'values') = 'array' and jsonb_array_length(a -> 'values') > 0 then
        return to_jsonb((select string_agg(coalesce(x ->> 'label', x ->> 'id'), ', ') from jsonb_array_elements(a -> 'values') x));
      end if;
    end loop;
  end if;
  return null;
end $$;

create or replace function public.spec_tags(p_value jsonb) returns text[]
language sql stable security definer set search_path = public as
$$
  select coalesce(array_agg(distinct x), '{}')
  from public.option_values o
  join public.option_values t on t.id = coalesce(o.merged_into, o.id)
  cross join lateral unnest(t.tags) x
  where o.key = public.normalize_value_key(p_value #>> '{}')
$$;

create or replace function public.spec_cond_eval(p_cond jsonb, p_rows jsonb, p_item jsonb) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare
  c jsonb;
  v_row jsonb;
  v jsonb;
  v_key text;
begin
  if p_cond is null or jsonb_typeof(p_cond) = 'null' then return true; end if;
  if jsonb_typeof(p_cond -> 'all') = 'array' then
    for c in select jsonb_array_elements(p_cond -> 'all') loop
      if not public.spec_cond_eval(c, p_rows, p_item) then return false; end if;
    end loop;
    return true;
  end if;
  if jsonb_typeof(p_cond -> 'any') = 'array' then
    for c in select jsonb_array_elements(p_cond -> 'any') loop
      if public.spec_cond_eval(c, p_rows, p_item) then return true; end if;
    end loop;
    return false;
  end if;
  if p_cond ? 'not' then return not public.spec_cond_eval(p_cond -> 'not', p_rows, p_item); end if;
  select r into v_row from jsonb_array_elements(p_rows) r where r ->> 'key' = p_cond ->> 'row' limit 1;
  if v_row is null then return false; end if;
  v := public.spec_row_value(p_item, v_row);
  if p_cond ? 'present' then return public.spec_filled(v) = (p_cond ->> 'present')::boolean; end if;
  if not public.spec_filled(v) then return false; end if;
  if p_cond ? 'tag' then return (p_cond ->> 'tag') = any (public.spec_tags(v)); end if;
  v_key := public.normalize_value_key(v #>> '{}');
  if p_cond ? 'equals' then return public.normalize_value_key(p_cond ->> 'equals') = v_key; end if;
  if jsonb_typeof(p_cond -> 'in') = 'array' then
    return exists (select 1 from jsonb_array_elements_text(p_cond -> 'in') x where public.normalize_value_key(x) = v_key);
  end if;
  return false;
end $$;

create or replace function public.spec_generic_rows() returns jsonb
language sql immutable parallel safe as
$$
  select jsonb_build_array(
    jsonb_build_object('key', 'brand', 'label', 'Brand', 'level', 'recommended', 'input', 'openValue'),
    jsonb_build_object('key', 'material', 'label', 'Material', 'level', 'recommended', 'input', 'openValue'),
    jsonb_build_object('key', 'colour', 'label', 'Colour', 'level', 'recommended', 'input', 'openValue'),
    jsonb_build_object('key', 'size', 'label', 'Size', 'level', 'recommended', 'input', 'text'),
    jsonb_build_object('key', 'weight', 'label', 'Weight', 'level', 'recommended', 'input', 'text'),
    jsonb_build_object('key', 'pack-size', 'label', 'Pack size', 'level', 'recommended', 'input', 'text'),
    jsonb_build_object('key', 'warranty', 'label', 'Warranty', 'level', 'recommended', 'input', 'text'),
    jsonb_build_object('key', 'country-of-origin', 'label', 'Country of origin', 'level', 'recommended', 'input', 'text'),
    jsonb_build_object('key', 'includes', 'label', 'What is in the box', 'level', 'recommended', 'input', 'text'))
$$;

-- The rules engine. p_item: { productTypeId, specs: [{label, value}], brand, packSize, includes, axes: [...] }.
create or replace function public.item_spec_issues(p_item jsonb, p_grandfathered boolean default false) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_defined jsonb;
  v_rows jsonb := '[]'::jsonb;
  r jsonb;
  v_level text;
  v_present boolean;
  v_own jsonb;
  v_invalid boolean;
  v_choices text[];
  v_key text;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_recommended integer := 0;
  v_answered integer := 0;
  v_issue jsonb;
begin
  select t.spec_rows into v_defined from public.product_types t where t.id = nullif(p_item ->> 'productTypeId', '');
  if v_defined is null or jsonb_typeof(v_defined) <> 'array' or jsonb_array_length(v_defined) = 0 then v_defined := public.spec_generic_rows(); end if;

  for r in select jsonb_array_elements(v_defined) loop
    if r ? 'showIf' and not public.spec_cond_eval(r -> 'showIf', v_defined, p_item) then continue; end if;
    v_level := r ->> 'level';
    if r ? 'requiredIf' and public.spec_cond_eval(r -> 'requiredIf', v_defined, p_item) then v_level := 'required'; end if;
    if v_level = 'optional' then continue; end if;

    v_present := public.spec_filled(public.spec_row_value(p_item, r));
    v_own := public.spec_row_own(p_item, r);
    v_choices := public.spec_row_choices(r);
    v_invalid := false;
    if v_present and v_own is not null and r ->> 'input' = 'choice' and v_choices is not null then
      v_key := public.normalize_value_key(v_own #>> '{}');
      v_invalid := not exists (select 1 from unnest(v_choices) c where public.normalize_value_key(c) = v_key);
    end if;

    if v_level = 'recommended' then
      v_recommended := v_recommended + 1;
      if v_present and not v_invalid then v_answered := v_answered + 1;
      elsif v_invalid then
        v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('key', r ->> 'key', 'label', r ->> 'label', 'level', v_level, 'code', 'invalid',
          'message', (r ->> 'label') || ' must be one of: ' || array_to_string(v_choices, ', ')));
      else
        v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('key', r ->> 'key', 'label', r ->> 'label', 'level', v_level, 'code', 'missing',
          'message', (r ->> 'label') || ' is recommended'));
      end if;
      continue;
    end if;

    if v_present and not v_invalid then continue; end if;
    if v_invalid then
      v_issue := jsonb_build_object('key', r ->> 'key', 'label', r ->> 'label', 'level', v_level, 'code', 'invalid',
        'message', (r ->> 'label') || ' must be one of: ' || array_to_string(v_choices, ', '));
    else
      v_issue := jsonb_build_object('key', r ->> 'key', 'label', r ->> 'label', 'level', v_level, 'code', 'missing', 'message', (r ->> 'label') || ' is required');
    end if;
    if p_grandfathered then v_warnings := v_warnings || jsonb_build_array(v_issue);
    else v_blockers := v_blockers || jsonb_build_array(v_issue);
    end if;
  end loop;

  return jsonb_build_object('blockers', v_blockers, 'warnings', v_warnings,
    'score', case when v_recommended = 0 then 100 else round(v_answered::numeric * 100 / v_recommended)::integer end);
end $$;

-- The gate. p_item may carry `id` of a stored item: if that item is grandfathered and this is not an edit, blockers are only warnings.
create or replace function public.item_check_publish(p_item jsonb) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_id uuid;
  v_old public.items;
  v_found boolean := false;
  v_grand boolean := false;
  r jsonb;
begin
  if p_item is null or jsonb_typeof(p_item) <> 'object' then raise exception 'invalid_item' using errcode = 'P0001'; end if;
  begin
    v_id := nullif(p_item ->> 'id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'invalid_item' using errcode = 'P0001';
  end;
  if v_id is not null then
    select * into v_old from public.items i where i.id = v_id and i.business_id = coalesce(public.my_business_id(), i.business_id);
    v_found := found;
  end if;
  if v_found and v_old.spec_gate_exempt
     and (not (p_item ? 'productTypeId') or nullif(p_item ->> 'productTypeId', '') is not distinct from v_old.product_type_id)
     and (not (p_item ? 'specs') or coalesce(nullif(p_item -> 'specs', 'null'::jsonb), '[]'::jsonb) = v_old.specs)
     and (not (p_item ? 'axes') or coalesce(nullif(p_item -> 'axes', 'null'::jsonb), '[]'::jsonb) = coalesce(v_old.option_axes, '[]'::jsonb))
     and (not (p_item ? 'brand') or nullif(p_item ->> 'brand', '') is not distinct from v_old.brand)
     and (not (p_item ? 'packSize') or nullif(p_item ->> 'packSize', '') is not distinct from v_old.pack_size)
  then
    v_grand := true;
  end if;
  r := public.item_spec_issues(p_item, v_grand);
  return r || jsonb_build_object('canSave', true, 'canPublish', jsonb_array_length(r -> 'blockers') = 0, 'grandfathered', v_grand);
end $$;
revoke all on function public.item_check_publish(jsonb), public.item_spec_issues(jsonb, boolean) from public, anon;
grant execute on function public.item_check_publish(jsonb) to authenticated, service_role;
grant execute on function public.item_spec_issues(jsonb, boolean) to service_role;

create or replace function public.items_spec_gate() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_live_new boolean := not new.draft and new.visible;
  v_live_old boolean := false;
  v_edit boolean := false;
  v_publish boolean;
  r jsonb;
begin
  if tg_op = 'INSERT' then
    new.spec_gate_exempt := false;
  else
    v_live_old := not old.draft and old.visible;
    v_edit := (new.product_type_id, new.specs, new.option_axes, new.brand, new.pack_size, new.includes)
      is distinct from (old.product_type_id, old.specs, old.option_axes, old.brand, old.pack_size, old.includes);
    new.spec_gate_exempt := old.spec_gate_exempt and not v_edit;
  end if;
  if not v_live_new then return new; end if;
  v_publish := not v_live_old;
  if not (v_publish or v_edit) then return new; end if;
  if tg_op = 'UPDATE' and v_publish and not v_edit and old.spec_gate_exempt then return new; end if;

  r := public.item_spec_issues(jsonb_build_object('productTypeId', new.product_type_id, 'specs', new.specs, 'brand', new.brand,
    'packSize', new.pack_size, 'includes', to_jsonb(new.includes), 'axes', coalesce(new.option_axes, '[]'::jsonb)), false);
  if jsonb_array_length(r -> 'blockers') > 0 then
    raise exception 'publish_blocked' using errcode = 'P0001', detail = (r -> 'blockers')::text;
  end if;
  new.spec_gate_exempt := false;
  return new;
end $$;

drop trigger if exists items_spec_gate on public.items;
create trigger items_spec_gate before insert or update on public.items
  for each row execute function public.items_spec_gate();

-- seller_check_item: the old behaviour; the spec issue list is added when the caller sends `publish`.
create or replace function public.seller_check_item(p_id uuid, p_fields jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  f jsonb := coalesce(p_fields, '{}'::jsonb);
  v_asked boolean := f ? 'publish';
  v_publish boolean := coalesce(f ->> 'publish', 'false') = 'true';
  v_biz uuid := public.my_business_id();
  v_state text;
  v_msg text;
  v_base jsonb;
  v_old public.items;
  v_item jsonb;
  v_spec jsonb;
  v_issues jsonb;
  e jsonb;
begin
  perform public.assert_seller_active();
  if v_biz is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  f := f - 'publish';
  begin
    perform public.seller_save_item(p_id, f);
    raise exception 'check_done' using errcode = 'P0002';
  exception when others then
    get stacked diagnostics v_state = returned_sqlstate, v_msg = message_text;
    if v_state = 'P0002' and v_msg = 'check_done' then
      v_base := jsonb_build_object('ok', true, 'issues', '[]'::jsonb);
    elsif v_state = '42501' then
      raise;
    elsif v_state = 'P0001' then
      v_base := jsonb_build_object('ok', false, 'issues', jsonb_build_array(jsonb_build_object('code', v_msg)));
    else
      v_base := jsonb_build_object('ok', false, 'issues', jsonb_build_array(jsonb_build_object('code', 'invalid_item')));
    end if;
  end;

  if p_id is not null then select * into v_old from public.items i where i.id = p_id and i.business_id = v_biz; end if;
  if not v_asked then return v_base; end if;
  v_item := jsonb_build_object(
    'id', p_id,
    'productTypeId', case when f ? 'productTypeId' then f -> 'productTypeId' else to_jsonb(v_old.product_type_id) end,
    'specs', coalesce(case when f ? 'specs' then nullif(f -> 'specs', 'null'::jsonb) else v_old.specs end, '[]'::jsonb),
    'brand', case when f ? 'brand' then f -> 'brand' else to_jsonb(v_old.brand) end,
    'packSize', case when f ? 'pack_size' then f -> 'pack_size' else to_jsonb(v_old.pack_size) end,
    'includes', coalesce(case when f ? 'includes' then nullif(f -> 'includes', 'null'::jsonb) else to_jsonb(v_old.includes) end, '[]'::jsonb),
    'axes', coalesce(case when jsonb_typeof(f -> 'options') = 'object' and f -> 'options' ? 'axes' then f -> 'options' -> 'axes' else v_old.option_axes end, '[]'::jsonb));
  v_spec := public.item_check_publish(v_item);
  v_issues := v_base -> 'issues';
  if v_publish then
    for e in select jsonb_array_elements(v_spec -> 'blockers') loop
      v_issues := v_issues || jsonb_build_array(jsonb_build_object('code', 'spec_' || (e ->> 'code'), 'key', e -> 'key', 'label', e -> 'label', 'level', e -> 'level', 'message', e -> 'message'));
    end loop;
  end if;
  return jsonb_build_object('ok', (v_base ->> 'ok')::boolean and (not v_publish or (v_spec ->> 'canPublish')::boolean), 'issues', v_issues, 'spec', v_spec);
end $$;
revoke all on function public.seller_check_item(uuid, jsonb) from public, anon;
grant execute on function public.seller_check_item(uuid, jsonb) to authenticated, service_role;

update public.product_types set spec_rows = jsonb_build_array(
    jsonb_build_object('key', 'authenticity', 'label', 'Authenticity', 'level', 'required', 'input', 'choice', 'labelSet', 'authenticity'),
    jsonb_build_object('key', 'fragrance-state', 'label', 'Fragrance state', 'level', 'recommended', 'input', 'choice', 'labelSet', 'fragranceState'),
    jsonb_build_object('key', 'notes', 'label', 'Notes', 'level', 'recommended', 'input', 'text'))
  where id = 'fragrance' and spec_rows = '[]'::jsonb;

$m_0099_publish_gate$),
    ('0100_admin_item_size_chart', $m_0100_admin_item_size_chart$
-- Prompt 1.9 follow-up: an owner can set or clear the size chart of ONE item from admin, and see which items a chart is on.
-- Sellers already choose a chart per item through seller_save_item (0086); this is the admin side, for fixing a wrong chart without the seller.
--   * admin_set_item_size_chart(item, chart)   owner only. chart null clears it. The chart must exist and be active. A different chart drops the item's
--                                              own row overrides (they were edits of the old chart). Audited.
--   * admin_items_for_size_chart(chart, query, limit)   owner, reviewer, support: items on a chart (chart given) or items matching a name search (chart null)
--                                              with the business and chart they have now.

create or replace function public.admin_set_item_size_chart(p_item uuid, p_chart uuid) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_old public.items;
  v_chart public.size_charts;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into v_old from public.items where id = p_item for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  if p_chart is not null then
    select * into v_chart from public.size_charts where id = p_chart;
    if not found then raise exception 'chart_not_found' using errcode = 'P0001'; end if;
    if not v_chart.active and v_old.size_chart_id is distinct from p_chart then raise exception 'chart_inactive' using errcode = 'P0001'; end if;
  end if;
  if v_old.size_chart_id is not distinct from p_chart then return true; end if; -- already so: nothing to change, nothing to audit
  update public.items
     set size_chart_id = p_chart, size_chart_override = null
   where id = p_item;
  perform public.admin_audit_action('item.size_chart', 'item', p_item::text,
    jsonb_build_object('size_chart_id', v_old.size_chart_id), jsonb_build_object('size_chart_id', p_chart), null, null);
  return true;
end $$;

create or replace function public.admin_items_for_size_chart(p_chart uuid default null, p_query text default null, p_limit integer default 30) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
begin
  if not public.has_role(array['owner', 'reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_chart is null and v_q is null then return '[]'::jsonb; end if;
  return coalesce((
    select jsonb_agg(to_jsonb(x) order by x.name)
    from (
      select i.id, i.name, i.product_type_id, i.size_chart_id, c.name as size_chart_name, b.name as business_name
        from public.items i
        join public.businesses b on b.id = i.business_id
        left join public.size_charts c on c.id = i.size_chart_id
       where (p_chart is null or i.size_chart_id = p_chart)
         and (v_q is null or i.name ilike '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%')
       order by i.name
       limit least(greatest(coalesce(p_limit, 30), 1), 100)
    ) x
  ), '[]'::jsonb);
end $$;

revoke all on function public.admin_set_item_size_chart(uuid, uuid), public.admin_items_for_size_chart(uuid, text, integer) from public, anon;
grant execute on function public.admin_set_item_size_chart(uuid, uuid), public.admin_items_for_size_chart(uuid, text, integer) to authenticated, service_role;

$m_0100_admin_item_size_chart$),
    ('0101_media_3d', $m_0101_media_3d$
-- 0101_media_3d.sql  (A17: 3D data, media roles and signed uploads)
--
--   * item_media.role      image | video | spin-frame | model-glb | poster. item_media.kind gains model, spin and poster (one kind per role), so
--                          every existing query that filters kind = 'image' or 'video' (gallery, counts, limits, reorder, copy) keeps
--                          returning exactly what it did. Existing rows get role = kind.
--   * item_media.option_ids  text[] of option VALUE ids (plain ids, NO foreign key: J01 adds the link). A photo or video may list several
--                          values; a 3D asset lists none (the item) or exactly one. An empty list = belongs to the whole item.
--   * Files: a .glb is a file in the Supabase bucket (like a video; the bucket now allows model/gltf-binary). Posters and spin frames are
--     pictures in Cloudinary. media_uploads / media_register_upload / the GC trigger and queue know the three new purposes
--     (item_model, item_poster, item_spin).
--   * attach_item_media3d(...)  service-only. A model or poster REPLACES the one in the same scope (the old file is queued for deletion);
--                          a spin takes up to 72 frames per scope, in the order given by p_position (or upload order).
--   * seller_set_media_options  a seller sets which option values a photo or video belongs to.
--   * seller_item_media3d       the seller read for the 3D uploaders. seller_item_media now lists only photos and videos (plus role, optionIds).
--   * item_check_media3d(item jsonb)  issues for seller_check_item: view3d_missing_poster, spin_too_few_frames, spin_too_many_frames.
--   * public_item_media3d(item)  { view3d, view3dByOption } as PATHS (shared/src/media3d.js resolveMedia3d makes urls). A view needs a poster
--                          AND (a model, or 12 to 72 spin frames); anything else is left out.
--   * items.has_3d              kept by triggers on item_media: true when the item has at least one visible view.
--   * public_items.media        photos and videos only, each with id, role and optionIds (ids of values that still exist).
-- The rules mirror shared/src/media3d.js (db tests run both on the same cases). Never edit this file once applied.

-- ---------------------------------------------------------------------------------------------------------------------
-- 1. Columns and constraints
-- ---------------------------------------------------------------------------------------------------------------------

alter table public.item_media add column if not exists role text;
alter table public.item_media add column if not exists option_ids text[] not null default '{}';
update public.item_media set role = kind where role is null;
alter table public.item_media alter column role set not null;

create or replace function public.media_option_ids_ok(p_ids text[], p_role text) returns boolean
language sql immutable parallel safe as $$
  select p_ids is not null
    and cardinality(p_ids) <= (case when p_role in ('spin-frame', 'model-glb', 'poster') then 1 else 40 end)
    and (select count(distinct x) = cardinality(p_ids) and coalesce(bool_and(x ~ '^[a-z0-9][a-z0-9_-]{0,39}$'), true) from unnest(p_ids) as x)
$$;

create or replace function public.item_media_role_default() returns trigger
language plpgsql as $$
begin
  new.role := coalesce(new.role, case new.kind when 'model' then 'model-glb' when 'spin' then 'spin-frame' else new.kind end);
  return new;
end $$;
drop trigger if exists item_media_role_default on public.item_media;
create trigger item_media_role_default before insert on public.item_media for each row execute function public.item_media_role_default();

alter table public.item_media drop constraint if exists item_media_kind_check;
alter table public.item_media add constraint item_media_kind_check check (kind in ('image', 'video', 'model', 'spin', 'poster'));
alter table public.item_media drop constraint if exists item_media_role_ck;
alter table public.item_media add constraint item_media_role_ck check (
  (kind, role) in (('image', 'image'), ('video', 'video'), ('model', 'model-glb'), ('spin', 'spin-frame'), ('poster', 'poster')));
alter table public.item_media drop constraint if exists item_media_option_ids_ck;
alter table public.item_media add constraint item_media_option_ids_ck check (public.media_option_ids_ok(option_ids, role));
create index if not exists item_media_item_role_idx on public.item_media (item_id, role);

-- Does this item have an option value with this id (in any axis)?
create or replace function public.item_has_option_value(p_item uuid, p_id text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.items i,
      jsonb_array_elements(case when jsonb_typeof(i.option_axes) = 'array' then i.option_axes else '[]'::jsonb end) as a(e),
      jsonb_array_elements(case when jsonb_typeof(a.e -> 'values') = 'array' then a.e -> 'values' else '[]'::jsonb end) as v(e)
    where i.id = p_item and v.e ->> 'id' = p_id)
$$;
-- public_items calls it as the reader, so anon needs it. It only says whether an option value id exists on an item.
revoke all on function public.item_has_option_value(uuid, text) from public;
grant execute on function public.item_has_option_value(uuid, text) to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------------------------------------------------
-- 2. Files: bucket, path rules, uploads, garbage collection
-- ---------------------------------------------------------------------------------------------------------------------

update storage.buckets
   set allowed_mime_types = allowed_mime_types || array['model/gltf-binary']
 where id = 'seller-media' and allowed_mime_types is not null and not ('model/gltf-binary' = any (allowed_mime_types));
-- Only that one type is added (not application/octet-stream): the ticket tells the uploader to send contentType model/gltf-binary, and
-- seller-media3d-finalize reads the real bytes and deletes anything that is not a glTF 2 binary.

create or replace function public.is_storage_model_path(p text) returns boolean
language sql immutable as $$
  select p is not null
    and char_length(p) <= 300
    and p ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.glb$'
$$;
revoke all on function public.is_storage_model_path(text) from public, anon, authenticated;
grant execute on function public.is_storage_model_path(text) to anon, authenticated, service_role;

alter table public.media_uploads drop constraint if exists media_uploads_purpose_ck;
alter table public.media_uploads drop constraint if exists media_uploads_id_ck;
alter table public.media_uploads drop constraint if exists media_uploads_item_ck;
alter table public.media_uploads
  add constraint media_uploads_purpose_ck check (purpose in ('item_photo', 'item_video', 'item_model', 'item_poster', 'item_spin', 'logo', 'cover', 'gallery', 'staff')),
  add constraint media_uploads_id_ck check (
    case purpose when 'item_video' then public.is_storage_video_path(public_id) when 'item_model' then public.is_storage_model_path(public_id)
    else public.is_cloudinary_id(public_id) end),
  add constraint media_uploads_item_ck check ((purpose in ('item_photo', 'item_video', 'item_model', 'item_poster', 'item_spin')) = (item_id is not null));

create or replace function public.media_register_upload(p_business uuid, p_item uuid, p_purpose text, p_public_id text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if p_purpose not in ('item_photo', 'item_video', 'item_model', 'item_poster', 'item_spin', 'logo', 'cover', 'gallery', 'staff') then raise exception 'invalid_purpose'; end if;
  if p_purpose in ('item_video', 'item_model') then
    if p_item is null or not exists (select 1 from public.items i where i.id = p_item and i.business_id = p_business) then raise exception 'item_not_found'; end if;
    if not (case p_purpose when 'item_video' then public.is_storage_video_path(p_public_id) else public.is_storage_model_path(p_public_id) end)
       or p_public_id not like p_business::text || '/' || p_item::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
  else
    if not public.is_cloudinary_id(p_public_id) or p_public_id not like p_business::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
    if p_purpose in ('item_photo', 'item_poster', 'item_spin') then
      if p_item is null or not exists (select 1 from public.items i where i.id = p_item and i.business_id = p_business) then raise exception 'item_not_found'; end if;
      if p_purpose <> 'item_photo' and p_public_id not like p_business::text || '/' || p_item::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
    elsif p_item is not null then
      raise exception 'invalid_purpose';
    elsif p_purpose in ('gallery', 'staff') and p_public_id not like p_business::text || '/' || p_purpose || '/%' then
      raise exception 'path_not_owned' using errcode = '42501';
    end if;
  end if;
  insert into public.media_uploads (public_id, business_id, item_id, purpose) values (p_public_id, p_business, p_item, p_purpose);
end $$;

create or replace function public.media_gc_enqueue(p_ids text[], p_reason text) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  insert into public.media_gc (public_id, reason)
  select x, left(coalesce(p_reason, 'manual'), 60) from unnest(p_ids) as x
   where public.is_cloudinary_id(x) or public.is_storage_video_path(x) or public.is_storage_model_path(x)
  on conflict (public_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $$;

create or replace function public.media_gc_from_item_media() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if old.kind in ('image', 'spin', 'poster') and public.is_cloudinary_id(old.path) then
    insert into public.media_gc (public_id, reason) values (old.path, case old.kind when 'image' then 'photo_removed' else 'media3d_removed' end) on conflict (public_id) do nothing;
  elsif old.kind = 'video' and public.is_storage_video_path(old.path) then
    insert into public.media_gc (public_id, reason) values (old.path, 'video_removed') on conflict (public_id) do nothing;
  elsif old.kind = 'model' and public.is_storage_model_path(old.path) then
    insert into public.media_gc (public_id, reason) values (old.path, 'media3d_removed') on conflict (public_id) do nothing;
  end if;
  return null;
end $$;

-- A signed bucket ticket (video or model) lasts two hours, so those uploads get three hours before the sweep calls them abandoned.
create or replace function public.media_sweep_orphans(p_grace interval default interval '1 hour') returns integer
language plpgsql security definer set search_path = public as $$
declare queued integer;
begin
  with put as (
    insert into public.media_gc (public_id, reason)
    select u.public_id, 'unattached_upload' from public.media_uploads u
    where u.created_at < now() - (case when u.purpose in ('item_video', 'item_model') then greatest(p_grace, interval '3 hours') else p_grace end)
      and not public.media_in_use(u.public_id)
    on conflict (public_id) do nothing
    returning 1
  )
  select count(*) into queued from put;
  delete from public.media_uploads u
  where u.created_at < now() - (case when u.purpose in ('item_video', 'item_model') then greatest(p_grace, interval '3 hours') else p_grace end);
  return queued;
end $$;

-- ---------------------------------------------------------------------------------------------------------------------
-- 3. The 3D views (one per scope: the whole item, or one option value)
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.item_view3d_scopes(p_item uuid) returns table (scope text, model jsonb, frames jsonb, n integer, poster text)
language sql stable security definer set search_path = public as $$
  with m as (
    select x.kind, x.path, x.size_bytes, coalesce(x.option_ids[1], '') as scope, x.sort, x.created_at, x.id
    from public.item_media x where x.item_id = p_item and x.kind in ('model', 'spin', 'poster')
  )
  select g.scope,
    (select jsonb_build_object('path', x.path, 'size', x.size_bytes) from m x where x.scope = g.scope and x.kind = 'model' order by x.sort, x.created_at, x.id limit 1),
    (select jsonb_agg(x.path order by x.sort, x.created_at, x.id) from m x where x.scope = g.scope and x.kind = 'spin'),
    (select count(*)::integer from m x where x.scope = g.scope and x.kind = 'spin'),
    (select x.path from m x where x.scope = g.scope and x.kind = 'poster' order by x.sort, x.created_at, x.id limit 1)
  from (select distinct m.scope from m) g
$$;

-- { "": view, "<valueId>": view } for the scopes a buyer may see (poster AND (model OR 12..72 frames)).
create or replace function public.item_view3d_raw(p_item uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_object_agg(s.scope,
      jsonb_build_object('poster', s.poster)
      || case when s.model is not null then jsonb_build_object('model', s.model) else '{}'::jsonb end
      || case when s.n between 12 and 72 then jsonb_build_object('spin', jsonb_build_object('frames', s.frames, 'count', s.n)) else '{}'::jsonb end
    ) filter (where s.poster is not null and (s.model is not null or s.n between 12 and 72)), '{}'::jsonb)
  from public.item_view3d_scopes(p_item) s
$$;

create or replace function public.item_view3d_issues(p_item uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('code', q.code, 'scope', q.scope) order by q.scope nulls first, q.code), '[]'::jsonb)
  from (
    select nullif(s.scope, '') as scope, 'view3d_missing_poster' as code from public.item_view3d_scopes(p_item) s where s.poster is null and (s.model is not null or s.n > 0)
    union all select nullif(s.scope, ''), 'spin_too_few_frames' from public.item_view3d_scopes(p_item) s where s.n > 0 and s.n < 12
    union all select nullif(s.scope, ''), 'spin_too_many_frames' from public.item_view3d_scopes(p_item) s where s.n > 72
  ) q
$$;

-- For seller_check_item (wired by J01): item jsonb carries the item id; returns the list of issues.
create or replace function public.item_check_media3d(item jsonb) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if item is null or jsonb_typeof(item) <> 'object' or not public.option_uuid_ok(item -> 'id') then return '[]'::jsonb; end if;
  return public.item_view3d_issues((item ->> 'id')::uuid);
end $$;

create or replace function public.public_item_media3d(p_item uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select case when exists (select 1 from public.public_items pi where pi.id = p_item)
    then jsonb_build_object('view3d', public.item_view3d_raw(p_item) -> '', 'view3dByOption', public.item_view3d_raw(p_item) - '')
    else null end
$$;

revoke all on function public.item_view3d_scopes(uuid), public.item_view3d_raw(uuid), public.item_view3d_issues(uuid), public.item_check_media3d(jsonb) from public, anon, authenticated;
grant execute on function public.item_view3d_scopes(uuid), public.item_view3d_raw(uuid), public.item_view3d_issues(uuid), public.item_check_media3d(jsonb) to service_role;
revoke all on function public.public_item_media3d(uuid) from public, anon;
grant execute on function public.public_item_media3d(uuid) to anon, authenticated, service_role;

-- items.has_3d follows item_media (statement-level, so a 72-frame upload recomputes once per statement).
create or replace function public.item_media_refresh_3d(p_ids uuid[]) returns void
language sql security definer set search_path = public as $$
  update public.items i set has_3d = (public.item_view3d_raw(i.id) <> '{}'::jsonb)
   where i.id = any (p_ids) and i.has_3d is distinct from (public.item_view3d_raw(i.id) <> '{}'::jsonb)
$$;
revoke all on function public.item_media_refresh_3d(uuid[]) from public, anon, authenticated;
grant execute on function public.item_media_refresh_3d(uuid[]) to service_role;

create or replace function public.item_media_3d_ins() returns trigger language plpgsql security definer set search_path = public as $$
begin perform public.item_media_refresh_3d(array(select distinct n.item_id from new_rows n where n.kind in ('model', 'spin', 'poster'))); return null; end $$;
create or replace function public.item_media_3d_upd() returns trigger language plpgsql security definer set search_path = public as $$
begin perform public.item_media_refresh_3d(array(select distinct n.item_id from new_rows n where n.kind in ('model', 'spin', 'poster'))); return null; end $$;
create or replace function public.item_media_3d_del() returns trigger language plpgsql security definer set search_path = public as $$
begin perform public.item_media_refresh_3d(array(select distinct o.item_id from old_rows o where o.kind in ('model', 'spin', 'poster'))); return null; end $$;
drop trigger if exists t_item_media_3d_ins on public.item_media;
create trigger t_item_media_3d_ins after insert on public.item_media referencing new table as new_rows for each statement execute function public.item_media_3d_ins();
drop trigger if exists t_item_media_3d_upd on public.item_media;
create trigger t_item_media_3d_upd after update on public.item_media referencing new table as new_rows for each statement execute function public.item_media_3d_upd();
drop trigger if exists t_item_media_3d_del on public.item_media;
create trigger t_item_media_3d_del after delete on public.item_media referencing old table as old_rows for each statement execute function public.item_media_3d_del();

-- ---------------------------------------------------------------------------------------------------------------------
-- 4. Attaching and reading
-- ---------------------------------------------------------------------------------------------------------------------

create or replace function public.attach_item_media3d(
  p_item uuid, p_role text, p_path text, p_mime text, p_width integer, p_height integer, p_size bigint,
  p_option_ids text[] default '{}', p_position integer default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_bid uuid;
  v_kind text;
  v_scope text;
  v_sort integer;
  v_id uuid;
begin
  select i.business_id into v_bid from public.items i where i.id = p_item;
  if v_bid is null then raise exception 'item_not_found'; end if;
  v_kind := case p_role when 'spin-frame' then 'spin' when 'model-glb' then 'model' when 'poster' then 'poster' end;
  if v_kind is null then raise exception 'invalid_role'; end if;
  if p_path is null or p_path not like v_bid::text || '/' || p_item::text || '/%' then raise exception 'path_not_owned' using errcode = '42501'; end if;
  p_option_ids := coalesce(p_option_ids, '{}');
  if not public.media_option_ids_ok(p_option_ids, p_role) then raise exception 'bad_option_ids'; end if;
  if cardinality(p_option_ids) > 0 and not public.item_has_option_value(p_item, p_option_ids[1]) then raise exception 'unknown_option_value'; end if;
  if p_position is not null and p_position not between 0 and 71 then raise exception 'bad_position'; end if;
  v_scope := coalesce(p_option_ids[1], '');

  -- Same lock as media_limit_ok, so two uploads of one item cannot both pass a limit.
  perform pg_advisory_xact_lock(hashtext(v_bid::text || 'item_media'));

  if p_role = 'spin-frame' then
    if (select count(*) from public.item_media m where m.item_id = p_item and m.kind = 'spin' and coalesce(m.option_ids[1], '') = v_scope) >= 72 then
      raise exception 'limit_reached:spin_frames';
    end if;
    v_sort := coalesce(p_position, (select coalesce(max(m.sort) + 1, 0) from public.item_media m where m.item_id = p_item and m.kind = 'spin' and coalesce(m.option_ids[1], '') = v_scope));
  else
    -- One model and one poster per scope: a new one replaces the old (the old file is queued for deletion by the delete trigger).
    delete from public.item_media m where m.item_id = p_item and m.kind = v_kind and coalesce(m.option_ids[1], '') = v_scope;
    v_sort := 0;
  end if;
  if (select count(*) from public.item_media m where m.item_id = p_item and m.kind in ('model', 'spin', 'poster')) >= 500 then raise exception 'limit_reached:media3d'; end if;

  insert into public.item_media (item_id, business_id, kind, role, path, mime, sort, width, height, size_bytes, option_ids)
  values (p_item, v_bid, v_kind, p_role, p_path, p_mime, v_sort, p_width, p_height, p_size, p_option_ids)
  returning id into v_id;
  return v_id;
end $$;
revoke all on function public.attach_item_media3d(uuid, text, text, text, integer, integer, bigint, text[], integer) from public, anon, authenticated;
grant execute on function public.attach_item_media3d(uuid, text, text, text, integer, integer, bigint, text[], integer) to service_role;

create or replace function public.seller_set_media_options(p_item uuid, p_media uuid, p_option_ids text[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_kind text;
  v_ids text[] := coalesce(p_option_ids, '{}');
  x text;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id and not i.removed_by_admin) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  select m.kind into v_kind from public.item_media m where m.id = p_media and m.item_id = p_item and m.business_id = v_id;
  if v_kind is null then raise exception 'media_not_found' using errcode = 'P0001'; end if;
  -- A 3D asset chooses its scope when it is uploaded (the ticket takes optionIds); only photos and videos move afterwards.
  if v_kind not in ('image', 'video') then raise exception 'not_for_3d' using errcode = 'P0001'; end if;
  if not public.media_option_ids_ok(v_ids, v_kind) then raise exception 'bad_option_ids' using errcode = 'P0001'; end if;
  foreach x in array v_ids loop
    if not public.item_has_option_value(p_item, x) then raise exception 'unknown_option_value' using errcode = 'P0001'; end if;
  end loop;
  update public.item_media m set option_ids = v_ids where m.id = p_media;
  return jsonb_build_object('id', p_media, 'optionIds', to_jsonb(v_ids));
end $$;
revoke all on function public.seller_set_media_options(uuid, uuid, text[]) from public, anon;
grant execute on function public.seller_set_media_options(uuid, uuid, text[]) to authenticated, service_role;

-- The photo and video list is unchanged apart from role and optionIds; 3D rows have their own read below.
create or replace function public.seller_item_media(p_item uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_lim jsonb;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  select case b.plan_key when 'premium' then g.premium else g.standard end into v_lim
  from public.businesses b cross join public.global_limits g where b.id = v_id and g.id = 1;
  return jsonb_build_object(
    'media', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'path', m.path, 'kind', m.kind, 'sort', m.sort, 'duration', m.duration_sec, 'role', m.role, 'optionIds', to_jsonb(m.option_ids)) order by m.sort, m.created_at, m.id)
                       from public.item_media m where m.item_id = p_item and m.kind in ('image', 'video')), '[]'::jsonb),
    'cover', (select m.path from public.item_media m where m.item_id = p_item and m.kind = 'image' order by m.sort, m.created_at, m.id limit 1),
    'limits', jsonb_build_object(
      'photos', jsonb_build_object('used', (select count(*) from public.item_media m where m.item_id = p_item and m.kind = 'image')::integer, 'max', (v_lim ->> 'photosPerItem')::integer),
      'videos', jsonb_build_object('used', (select count(*) from public.item_media m where m.item_id = p_item and m.kind = 'video')::integer, 'max', (v_lim ->> 'videosPerItem')::integer)));
end $$;

create or replace function public.seller_item_media3d(p_item uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_id uuid := public.my_business_id();
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  return jsonb_build_object(
    'media3d', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'path', m.path, 'role', m.role, 'sort', m.sort, 'optionIds', to_jsonb(m.option_ids), 'size', m.size_bytes, 'width', m.width, 'height', m.height)
                          order by m.role, m.sort, m.created_at, m.id)
                         from public.item_media m where m.item_id = p_item and m.kind in ('model', 'spin', 'poster')), '[]'::jsonb),
    'issues', public.item_view3d_issues(p_item),
    'hasView', public.item_view3d_raw(p_item) <> '{}'::jsonb,
    'limits', jsonb_build_object('modelMaxBytes', 15728640, 'spinMinFrames', 12, 'spinMaxFrames', 72, 'maxRows', 500));
end $$;
revoke all on function public.seller_item_media3d(uuid) from public, anon;
grant execute on function public.seller_item_media3d(uuid) to authenticated, service_role;

-- Reordering photos and videos must ignore 3D rows (the list a seller sends has only photos and videos).
create or replace function public.seller_reorder_item_media(p_item uuid, p_paths text[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_have text[];
  v_n integer;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id and not i.removed_by_admin) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  if p_paths is null then raise exception 'no_items' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtext(v_id::text || 'item_media'));
  select coalesce(array_agg(m.path order by m.sort, m.created_at, m.id), '{}') into v_have
  from public.item_media m where m.item_id = p_item and m.business_id = v_id and m.kind in ('image', 'video');
  if cardinality(p_paths) <> (select count(distinct p) from unnest(p_paths) as p) then raise exception 'duplicate_path' using errcode = 'P0001'; end if;
  if exists (select 1 from unnest(p_paths) as p where p is null or p <> all (v_have)) then raise exception 'path_not_found' using errcode = 'P0001'; end if;
  if cardinality(p_paths) <> cardinality(v_have) then raise exception 'order_incomplete' using errcode = 'P0001'; end if;
  v_n := public.media_apply_order(p_item, p_paths);
  return jsonb_build_object('updated', v_n,
    'cover', (select m.path from public.item_media m where m.item_id = p_item and m.kind = 'image' order by m.sort, m.created_at, m.id limit 1));
end $$;

-- Same fix for the older photo-only reorder: its working list must not include 3D rows (their sort values are frame positions).
create or replace function public.seller_reorder_item_photos(p_item uuid, p_paths text[]) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_order text[];
  v_n integer;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  if not exists (select 1 from public.items i where i.id = p_item and i.business_id = v_id and not i.removed_by_admin) then
    raise exception 'item_not_found' using errcode = 'P0001';
  end if;
  if p_paths is null or cardinality(p_paths) = 0 or cardinality(p_paths) > 50 then raise exception 'no_items' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtext(v_id::text || 'item_media'));
  with cur as (
    select m.path, m.kind, row_number() over (order by m.sort, m.created_at, m.id) as rn
    from public.item_media m where m.item_id = p_item and m.business_id = v_id and m.kind in ('image', 'video')
  ), want as (
    select u.path, min(u.ord) as ord from unnest(p_paths) with ordinality as u(path, ord) group by u.path
  ), slots as (
    select rn, row_number() over (order by rn) as idx from cur where kind = 'image'
  ), picks as (
    select c.path, row_number() over (order by coalesce(w.ord, 2147483647), c.rn) as idx
    from cur c left join want w on w.path = c.path where c.kind = 'image'
  ), placed as (
    select c.path, c.rn as pos from cur c where c.kind <> 'image'
    union all
    select p.path, s.rn from picks p join slots s on s.idx = p.idx
  )
  select coalesce(array_agg(path order by pos), '{}') into v_order from placed;
  v_n := public.media_apply_order(p_item, v_order);
  return v_n;
end $$;

-- ---------------------------------------------------------------------------------------------------------------------
-- 5. Public payload: photos and videos only, with id, role and optionIds (ids of values that still exist)
-- ---------------------------------------------------------------------------------------------------------------------

create or replace view public.public_items with (security_barrier = true) as
select
  i.id, i.business_id, i.name, i.description, i.section, i.price, i.price_max, i.price_type, i.unit,
  i.availability, i.sort, i.created_at,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id and m.kind = 'image'), '[]'::jsonb) as image_paths,
  coalesce((select jsonb_agg(m.path order by m.sort, m.created_at, m.id) from public.item_media m where m.item_id = i.id and m.kind = 'video'), '[]'::jsonb) as video_paths,
  case when i.track_stock and i.show_stock_count and i.availability = 'limited_stock' and i.stock_count > 0 then i.stock_count end as stock_left,
  i.brand, i.short_description, i.highlights, i.specs, i.includes, i.terms, i.pack_size,
  coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'path', m.path, 'kind', m.kind, 'duration', m.duration_sec, 'role', m.role,
      'optionIds', to_jsonb(array(select u from unnest(m.option_ids) as u where public.item_has_option_value(i.id, u))))
      order by m.sort, m.created_at, m.id)
    from public.item_media m where m.item_id = i.id and m.kind in ('image', 'video')), '[]'::jsonb) as media,
  coalesce((select jsonb_agg(jsonb_build_object('id', x.e ->> 'id', 'label', x.e ->> 'label', 'price', (x.e ->> 'price')::numeric) order by x.n)
    from jsonb_array_elements(case when jsonb_typeof(i.variants) = 'array' then i.variants else '[]'::jsonb end) with ordinality as x(e, n)
    where coalesce(x.e ->> 'stock', '') <> '0'), '[]'::jsonb) as variants,
  i.price_min, i.price_high, i.has_options, i.department_id, i.product_type_id, i.has_3d
from public.items i
join public.businesses b on b.id = i.business_id
where public.business_is_visible(b) and i.visible and not i.draft and not i.hidden_by_admin and not i.removed_by_admin
  and public.item_is_listed(i.availability);
revoke all on public.public_items from public;
grant select on public.public_items to anon, authenticated, service_role;

$m_0101_media_3d$),
    ('0102_admin_spec_rows', $m_0102_admin_spec_rows$
create or replace function public.spec_condition_valid(c jsonb, keys text[], own text) returns boolean
language plpgsql immutable as $$
declare
  g text;
  e jsonb;
begin
  if jsonb_typeof(c) <> 'object' then return false; end if;
  g := case when c ? 'all' then 'all' when c ? 'any' then 'any' when c ? 'not' then 'not' end;
  if g = 'not' then return (select count(*) from jsonb_object_keys(c)) = 1 and public.spec_condition_valid(c -> 'not', keys, own); end if;
  if g is not null then
    if (select count(*) from jsonb_object_keys(c)) <> 1 or jsonb_typeof(c -> g) <> 'array' or jsonb_array_length(c -> g) = 0 then return false; end if;
    for e in select * from jsonb_array_elements(c -> g) loop
      if not public.spec_condition_valid(e, keys, own) then return false; end if;
    end loop;
    return true;
  end if;
  if jsonb_typeof(c -> 'row') <> 'string' or not ((c ->> 'row') = any (keys)) or (c ->> 'row') = own then return false; end if;
  if (select count(*) from jsonb_object_keys(c) k where k in ('equals', 'in', 'tag', 'present')) <> 1 then return false; end if;
  if c ? 'equals' and jsonb_typeof(c -> 'equals') <> 'string' then return false; end if;
  if c ? 'tag' and (jsonb_typeof(c -> 'tag') <> 'string' or btrim(c ->> 'tag') = '') then return false; end if;
  if c ? 'present' and jsonb_typeof(c -> 'present') <> 'boolean' then return false; end if;
  if c ? 'in' and (jsonb_typeof(c -> 'in') <> 'array' or jsonb_array_length(c -> 'in') = 0
      or exists (select 1 from jsonb_array_elements(c -> 'in') x where jsonb_typeof(x) <> 'string')) then return false; end if;
  return true;
end $$;

create or replace function public.spec_rows_valid(p jsonb) returns boolean
language plpgsql immutable as $$
declare
  keys text[];
  r jsonb;
begin
  if jsonb_typeof(p) <> 'array' then return false; end if;
  select coalesce(array_agg(e ->> 'key'), '{}') into keys from jsonb_array_elements(p) e;
  if cardinality(keys) <> (select count(distinct k) from unnest(keys) k) then return false; end if;
  for r in select * from jsonb_array_elements(p) loop
    if jsonb_typeof(r) <> 'object' or coalesce(r ->> 'key', '') !~ '^[a-z0-9][a-z0-9_-]*$' or btrim(coalesce(r ->> 'label', '')) = ''
       or coalesce(r ->> 'level', '') not in ('required', 'recommended', 'optional')
       or coalesce(r ->> 'input', '') not in ('text', 'number', 'choice', 'openValue', 'boolean', 'dimension') then return false; end if;
    if r ? 'labelSet' and coalesce(r ->> 'labelSet', '') not in ('condition', 'authenticity', 'fragranceState', 'chargerKind') then return false; end if;
    if r ? 'choices' and (jsonb_typeof(r -> 'choices') <> 'array' or jsonb_array_length(r -> 'choices') = 0
        or exists (select 1 from jsonb_array_elements(r -> 'choices') x where jsonb_typeof(x) <> 'string' or btrim(x #>> '{}') = '')) then return false; end if;
    if r ->> 'input' = 'choice' and not (r ? 'choices' or r ? 'labelSet') then return false; end if;
    if r ? 'requiredIf' and not public.spec_condition_valid(r -> 'requiredIf', keys, r ->> 'key') then return false; end if;
    if r ? 'showIf' and not public.spec_condition_valid(r -> 'showIf', keys, r ->> 'key') then return false; end if;
  end loop;
  return true;
end $$;

create or replace function public.admin_spec_rows_list() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.has_role(array['reviewer', 'support']) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'specRows', t.spec_rows) order by t.name)
                   from public.product_types t where t.active), '[]'::jsonb);
end $$;

create or replace function public.admin_save_spec_rows(p_id text, p_rows jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_old jsonb;
begin
  if not public.has_role(array['owner']) then raise exception 'forbidden' using errcode = '42501'; end if;
  select spec_rows into v_old from public.product_types where id = p_id for update;
  if not found then raise exception 'type_not_found' using errcode = 'P0001'; end if;
  if not public.spec_rows_valid(p_rows) then raise exception 'invalid_spec_rows' using errcode = 'P0001'; end if;
  if not public.spec_rows_required_ok(p_rows) then raise exception 'too_many_required' using errcode = 'P0001'; end if;
  update public.product_types set spec_rows = p_rows where id = p_id;
  perform public.admin_audit_action('spec_rows.update', 'product_type', p_id, jsonb_build_object('rows', jsonb_array_length(v_old)), jsonb_build_object('rows', jsonb_array_length(p_rows)), null, null);
  return p_rows;
end $$;

revoke all on function public.spec_condition_valid(jsonb, text[], text), public.spec_rows_valid(jsonb), public.admin_spec_rows_list(), public.admin_save_spec_rows(text, jsonb) from public, anon;
grant execute on function public.admin_spec_rows_list(), public.admin_save_spec_rows(text, jsonb) to authenticated, service_role;

$m_0102_admin_spec_rows$),
    ('0103_seller_size_guide', $m_0103_seller_size_guide$
-- Sellers own the size guide of their own items.
-- Until now an admin made the charts and a seller could only borrow one. Now a seller fills the size table on the item itself (columns they choose,
-- one row per size they sell, for shoes the EU/UK/US/cm conversion), and buyers see that table. An admin chart stays as a template and as the
-- fallback for items whose seller wrote no guide.
--   * items.size_guide          jsonb { unit?, columns:[text], rows:[[text]] }, null = none. Same shape rules as a size chart (1..12 columns, 1..60 rows,
--                               every row as wide as the columns, no empty cell). The first column is the size.
--   * seller_set_item_size_guide(item, guide)   the seller's own, active item only. guide null removes it. Audited.
--   * seller_item_size_guide(item)               the editor's read.
--   * item_size_chart_payload(item)              buyers: the item's own guide first ({ id: null, own: true }), else the admin chart as before.
-- Errors (P0001): item_not_found, invalid_size_guide. Idempotent; never edit once applied.

create or replace function public.size_guide_valid(p jsonb) returns boolean
language plpgsql immutable parallel safe as $$
begin
  if p is null then return true; end if;
  if jsonb_typeof(p) <> 'object' then return false; end if;
  if exists (select 1 from jsonb_object_keys(p) k where k not in ('unit', 'columns', 'rows')) then return false; end if;
  if not (p ? 'columns' and p ? 'rows') then return false; end if;
  if p ? 'unit' and jsonb_typeof(p -> 'unit') <> 'null' and (jsonb_typeof(p -> 'unit') <> 'string' or (p ->> 'unit') not in ('cm', 'in')) then return false; end if;
  return public.size_chart_columns_valid(p -> 'columns') and public.size_chart_rows_valid(p -> 'rows', jsonb_array_length(p -> 'columns'));
end $$;
revoke all on function public.size_guide_valid(jsonb) from public;
grant execute on function public.size_guide_valid(jsonb) to anon, authenticated, service_role;

alter table public.items add column if not exists size_guide jsonb;
alter table public.items drop constraint if exists items_size_guide_shape;
alter table public.items add constraint items_size_guide_shape check (public.size_guide_valid(size_guide));

create or replace function public.seller_set_item_size_guide(p_id uuid, p_guide jsonb) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_item public.items;
  v_guide jsonb := case when p_guide is null or jsonb_typeof(p_guide) = 'null' then null else p_guide end;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select * into v_item from public.items where id = p_id and business_id = v_id and not removed_by_admin for update;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  if not public.size_guide_valid(v_guide) then raise exception 'invalid_size_guide' using errcode = 'P0001'; end if;
  if v_item.size_guide is not distinct from v_guide then return true; end if; -- nothing changed: nothing to write or audit
  update public.items set size_guide = v_guide where id = p_id;
  perform public.write_audit(v_id, case when v_guide is null then 'item_size_guide_removed' else 'item_size_guide_saved' end, 'item', p_id::text,
    jsonb_build_object('rows', case when v_guide is null then 0 else jsonb_array_length(v_guide -> 'rows') end));
  return true;
end $$;

create or replace function public.seller_item_size_guide(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_id uuid := public.my_business_id();
  v_guide jsonb;
begin
  perform public.assert_seller_active();
  if v_id is null then raise exception 'not_a_seller' using errcode = '42501'; end if;
  select i.size_guide into v_guide from public.items i where i.id = p_id and i.business_id = v_id and not i.removed_by_admin;
  if not found then raise exception 'item_not_found' using errcode = 'P0001'; end if;
  return v_guide;
end $$;

revoke all on function public.seller_set_item_size_guide(uuid, jsonb), public.seller_item_size_guide(uuid) from public;
grant execute on function public.seller_set_item_size_guide(uuid, jsonb), public.seller_item_size_guide(uuid) to authenticated, service_role;

-- Buyers: the seller's own guide first, then the admin chart exactly as before.
create or replace function public.item_size_chart_payload(p_item public.items) returns jsonb
language sql stable security definer set search_path = public as $$
  select case
    when p_item.size_guide is not null and public.size_guide_valid(p_item.size_guide) then jsonb_build_object(
      'id', null, 'name', 'Size guide', 'category', null, 'unit', coalesce(p_item.size_guide ->> 'unit', 'cm'),
      'columns', p_item.size_guide -> 'columns', 'rows', p_item.size_guide -> 'rows', 'overridden', false, 'own', true)
    when c.id is null then null
    else jsonb_build_object(
      'id', c.id, 'name', c.name, 'category', c.category, 'unit', c.unit, 'columns', c.columns,
      'rows', case when p_item.size_chart_override is not null and public.size_chart_rows_valid(p_item.size_chart_override -> 'rows', jsonb_array_length(c.columns))
                   then p_item.size_chart_override -> 'rows' else c.rows end,
      'overridden', p_item.size_chart_override is not null and public.size_chart_rows_valid(p_item.size_chart_override -> 'rows', jsonb_array_length(c.columns))) end
  from (select 1) one left join public.size_charts c on c.id = p_item.size_chart_id and c.active
$$;
revoke all on function public.item_size_chart_payload(public.items) from public;
grant execute on function public.item_size_chart_payload(public.items) to service_role;

notify pgrst, 'reload schema';

$m_0103_seller_size_guide$),
    ('0104_size_guide_unit', $m_0104_size_guide_unit$
-- A seller's size guide may have no length unit at all (bottle volumes, loaf weights, bag capacity): its unit stays null instead of becoming 'cm',
-- so the buyer's cm / inches switch is never offered for a table of litres or grams. Only the buyer payload changes; idempotent.
create or replace function public.item_size_chart_payload(p_item public.items) returns jsonb
language sql stable security definer set search_path = public as $$
  select case
    when p_item.size_guide is not null and public.size_guide_valid(p_item.size_guide) then jsonb_build_object(
      'id', null, 'name', 'Size guide', 'category', null, 'unit', case when p_item.size_guide ->> 'unit' in ('cm', 'in') then p_item.size_guide -> 'unit' else null end,
      'columns', p_item.size_guide -> 'columns', 'rows', p_item.size_guide -> 'rows', 'overridden', false, 'own', true)
    when c.id is null then null
    else jsonb_build_object(
      'id', c.id, 'name', c.name, 'category', c.category, 'unit', c.unit, 'columns', c.columns,
      'rows', case when p_item.size_chart_override is not null and public.size_chart_rows_valid(p_item.size_chart_override -> 'rows', jsonb_array_length(c.columns))
                   then p_item.size_chart_override -> 'rows' else c.rows end,
      'overridden', p_item.size_chart_override is not null and public.size_chart_rows_valid(p_item.size_chart_override -> 'rows', jsonb_array_length(c.columns))) end
  from (select 1) one left join public.size_charts c on c.id = p_item.size_chart_id and c.active
$$;
revoke all on function public.item_size_chart_payload(public.items) from public;
grant execute on function public.item_size_chart_payload(public.items) to service_role;

notify pgrst, 'reload schema';

$m_0104_size_guide_unit$)
  ) as t(f, body) order by t.f loop
    if m.f >= v_first then
      v_step := v_step + 1;
      begin
        execute m.body;
        insert into catch_up_log values (v_step, m.f, 'applied');
      exception when others then
        insert into catch_up_log values (v_step, m.f, 'SKIPPED: ' || sqlerrm);
      end;
    end if;
  end loop;
end
$catchup$;

select * from catch_up_log order by step, migration;
